//! The Puppeteer's Strings: Discrete Control Actions
//!
//! Reinforcement learning agents cannot press buttons. They output floating-point tensors.
//! This module bridges the gap between the cold math of a neural network and the
//! tactile reality of an 8-bit game controller.
//!
//! By restricting the agent to a small, curated set of actions, we drastically
//! reduce the exploration space and guide the agent toward meaningful gameplay rather
//! than mashing `Start` and `Select` in a corner.

use nes_core::Button;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
/// The constrained vocabulary our AI uses to speak to the NES.
///
/// Rather than exploring all 256 mathematically possible button combinations on an NES joypad,
/// this enum curates the exact dialect needed for most side-scrolling platformers.
/// The agent points at one of these discrete thoughts, and we pull the strings on the
/// controller port.
pub enum ControlAction {
    /// The agent does nothing. The digital equivalent of a blank stare.
    Noop,
    /// Walking forward. The foundation of any side-scrolling adventure.
    Right,
    /// Moving forward while leaping. Critical for avoiding pits and stomping goombas.
    RightA,
    /// A vertical jump in place. Useful for hitting blocks directly overhead.
    A,
    /// Sprinting forward. Fast, but dangerous.
    RightB,
    /// A sprinting leap forward. Maximum momentum, maximum risk.
    RightAB,
}

impl ControlAction {
    /// Returns the total number of distinct actions in the action space.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_ai::actions::ControlAction;
    ///
    /// assert_eq!(ControlAction::action_count(), 6);
    /// ```
    #[must_use]
    pub const fn action_count() -> usize {
        6
    }

    /// Converts the abstract action into the raw 8-bit bitmask expected by the NES controller port.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_ai::actions::ControlAction;
    /// use nes_core::Button;
    ///
    /// let action = ControlAction::RightA;
    /// let expected = Button::Right.bit_mask() | Button::A.bit_mask();
    /// assert_eq!(action.controller1_bits(), expected);
    /// ```
    #[must_use]
    pub fn controller1_bits(self) -> u8 {
        match self {
            Self::Noop => 0,
            Self::Right => Button::Right.bit_mask(),
            Self::RightA => Button::Right.bit_mask() | Button::A.bit_mask(),
            Self::A => Button::A.bit_mask(),
            Self::RightB => Button::Right.bit_mask() | Button::B.bit_mask(),
            Self::RightAB => Button::Right.bit_mask() | Button::A.bit_mask() | Button::B.bit_mask(),
        }
    }
}

//! Evaluation binary for SMB control policies
//!
//! A utility to evaluate a trained model checkpoint against the environment.
//! It executes the policy and writes deterministic TAS replay artifacts.

use std::{env, fs, path::PathBuf};

use comfy_table::{Cell, Color as TableColor, Table, presets::UTF8_FULL};
use crossterm::style::{Color, Stylize};
use nes_ai::{
    config::AiProfileConfig,
    trainer::{TrainerConfig, evaluate_smb_control},
};

fn main() {
    if let Err(err) = run() {
        eprintln!("\n{err}");
        std::process::exit(1);
    }
}

fn run() -> Result<(), String> {
    let args = env::args().collect::<Vec<_>>();
    if args.iter().any(|arg| arg == "--help" || arg == "-h") {
        println!(
            "Usage: eval_smb_control <profile_toml> <checkpoint_base> [episodes] [artifact_dir]"
        );
        std::process::exit(0);
    }
    if args.len() < 3 || args.len() > 5 {
        return Err(format!(
            "{} missing or invalid number of arguments.\nUsage: eval_smb_control <profile_toml> <checkpoint_base> [episodes] [artifact_dir]",
            "Error:".with(Color::Red).bold()
        ));
    }

    let profile_path = PathBuf::from(&args[1]);
    let checkpoint_base = PathBuf::from(&args[2]);
    let episodes = args
        .get(3)
        .map(|value| value.parse::<usize>())
        .transpose()
        .map_err(|e| format!("Failed to parse episodes: {e}"))?
        .unwrap_or(2);
    let artifact_dir = args.get(4).map(PathBuf::from);

    let profile_str = fs::read_to_string(&profile_path)
        .map_err(|e| format!("Failed to read profile config: {e}"))?;
    let profile_cfg: AiProfileConfig =
        toml::from_str(&profile_str).map_err(|e| format!("Failed to parse profile config: {e}"))?;

    let trainer_cfg = TrainerConfig {
        artifact_dir: artifact_dir.clone(),
        ..TrainerConfig::smoke()
    };

    println!("{}", "Evaluating AI Profile...".with(Color::Cyan).bold());

    let summary =
        evaluate_smb_control(&profile_cfg, &trainer_cfg, episodes, Some(&checkpoint_base))
            .map_err(|e| format!("Evaluation failed: {e}"))?;

    println!(
        "\n{}",
        build_summary_table(summary.average_return, summary.artifact_paths.len())
    );

    Ok(())
}

fn build_summary_table(average_return: f32, artifact_paths_len: usize) -> Table {
    let mut table = Table::new();
    table.load_preset(UTF8_FULL);
    table.set_header(vec![
        Cell::new("Property").fg(TableColor::Cyan),
        Cell::new("Value").fg(TableColor::White),
    ]);

    table.add_row(vec![
        Cell::new("Average Return"),
        Cell::new(format!("{average_return:.2}")).fg(TableColor::Yellow),
    ]);
    table.add_row(vec![
        Cell::new("Artifacts Written"),
        Cell::new(artifact_paths_len.to_string()).fg(TableColor::Yellow),
    ]);

    table
}

#[cfg(test)]
mod tests {
    use super::build_summary_table;

    #[test]
    fn build_summary_table_formats_average_return_and_artifacts() {
        let table = build_summary_table(2.5, 3);
        let output = table.to_string();

        assert!(output.contains("Average Return"));
        assert!(output.contains("2.50"));
        assert!(output.contains("Artifacts Written"));
        assert!(output.contains('3'));
    }
}

//! Snapshot preparation binary for SMB control task
//!
//! A utility to bootstrap the reinforcement learning environment by saving
//! a snapshot state (e.g., SMB 1-1) required to train the control policy.

use std::{env, fs, path::PathBuf};

use comfy_table::{Cell, Color as TableColor, Table, presets::UTF8_FULL};
use crossterm::style::{Color, Stylize};
use nes_ai::snapshot::{sha256_hex, write_snapshot_bundle};
use nes_core::{NesCore, tas::TasMovie};

fn main() {
    if let Err(err) = run() {
        eprintln!("\n{err}");
        std::process::exit(1);
    }
}

fn format_rom_read_error(rom_path: &str, err: &std::io::Error) -> String {
    if err.kind() == std::io::ErrorKind::NotFound {
        format!(
            "{} Could not find the ROM file at '{}'.\n{} Check the path or try the bundled homebrew ROM: ./roms/homebrew/homebrew.nes or <path-to-your-rom>.nes",
            "Error:".with(Color::Red).bold(),
            rom_path.with(Color::Yellow),
            "Hint:".with(Color::Cyan).bold()
        )
    } else {
        format!(
            "{} Failed to read ROM at '{}': {}",
            "Error:".with(Color::Red).bold(),
            rom_path.with(Color::Yellow),
            err
        )
    }
}

fn run() -> Result<(), String> {
    let args = env::args().collect::<Vec<_>>();
    if args.iter().any(|arg| arg == "--help" || arg == "-h") {
        println!("Usage: prepare_smb_control <rom_path> <bootstrap_tas_json> <output_snapshot>");
        std::process::exit(0);
    }
    if args.len() != 4 {
        eprintln!("Usage: prepare_smb_control <rom_path> <bootstrap_tas_json> <output_snapshot>");
        std::process::exit(1);
    }

    let rom_path = PathBuf::from(&args[1]);
    let movie_path = PathBuf::from(&args[2]);
    let out_path = PathBuf::from(&args[3]);

    let rom =
        fs::read(&rom_path).map_err(|e| format_rom_read_error(&rom_path.to_string_lossy(), &e))?;
    let rom_hash = sha256_hex(&rom);

    let movie_json = fs::read(&movie_path).map_err(|e| format!("Failed to read TAS json: {e}"))?;
    let movie: TasMovie = serde_json::from_slice(&movie_json)
        .map_err(|e| format!("Failed to parse TAS json: {e}"))?;

    let mut core = NesCore::new();
    core.load_ines_rom(&rom)
        .map_err(|e| format!("Failed to load ROM: {e}"))?;
    movie
        .replay(&mut core)
        .map_err(|e| format!("Failed to replay TAS: {e}"))?;

    write_snapshot_bundle(&out_path, &rom_hash, "smb-control-v1", &core.save_state())
        .map_err(|e| format!("Failed to write snapshot bundle: {e}"))?;

    println!(
        "{}",
        "Prepared SMB Control Snapshot".with(Color::Cyan).bold()
    );

    println!("\n{}", build_success_table(&rom_hash, &out_path));

    Ok(())
}

fn build_success_table(rom_hash: &str, out_path: &std::path::Path) -> Table {
    let mut table = Table::new();
    table.load_preset(UTF8_FULL);
    table.set_header(vec![
        Cell::new("Property").fg(TableColor::Cyan),
        Cell::new("Value").fg(TableColor::White),
    ]);

    table.add_row(vec![
        Cell::new("ROM Hash"),
        Cell::new(rom_hash).fg(TableColor::Green),
    ]);
    table.add_row(vec![
        Cell::new("Output Path"),
        Cell::new(out_path.display().to_string()).fg(TableColor::Green),
    ]);
    table.add_row(vec![
        Cell::new("Status"),
        Cell::new("Success").fg(TableColor::Green),
    ]);

    table
}

#[cfg(test)]
mod tests {
    use super::build_success_table;
    use std::path::PathBuf;

    #[test]
    fn build_success_table_formats_hash_and_path() {
        let hash = "deadbeef";
        let path = PathBuf::from("test/path/snapshot.bin");
        let table = build_success_table(hash, &path);
        let output = table.to_string();

        assert!(output.contains("ROM Hash"));
        assert!(output.contains(hash));
        assert!(output.contains("Output Path"));
        assert!(output.contains("test/path/snapshot.bin"));
        assert!(output.contains("Status"));
        assert!(output.contains("Success"));
    }
}

//! PPO training binary for SMB control task
//!
//! A utility to train a PPO reinforcement learning agent on the Super Mario Bros
//! control task. Outputs model checkpoints and periodic evaluation replays.

use std::{env, fs, path::PathBuf};

use comfy_table::{Cell, Color as TableColor, Table, presets::UTF8_FULL};
use crossterm::style::{Color, Stylize};
use nes_ai::{
    config::AiProfileConfig,
    trainer::{TrainerConfig, train_smb_control},
};

fn main() {
    if let Err(err) = run() {
        eprintln!("\n{err}");
        std::process::exit(1);
    }
}

fn run() -> Result<(), String> {
    let args = env::args().collect::<Vec<_>>();
    if args.iter().any(|arg| arg == "--help" || arg == "-h") {
        println!(
            "Usage: train_smb_control <profile_toml> [episodes] [checkpoint_dir] [artifact_dir]"
        );
        std::process::exit(0);
    }
    if args.len() < 2 || args.len() > 5 {
        return Err(format!(
            "{} missing or invalid number of arguments.\nUsage: train_smb_control <profile_toml> [episodes] [checkpoint_dir] [artifact_dir]",
            "Error:".with(Color::Red).bold()
        ));
    }

    let profile_path = PathBuf::from(&args[1]);
    let episodes = args
        .get(2)
        .map(|value| value.parse::<usize>())
        .transpose()
        .map_err(|e| format!("Failed to parse episodes: {e}"))?
        .unwrap_or(4);
    let checkpoint_dir = args.get(3).map(PathBuf::from);
    let artifact_dir = args.get(4).map(PathBuf::from);

    let profile_str = fs::read_to_string(&profile_path)
        .map_err(|e| format!("Failed to read profile config: {e}"))?;
    let profile_cfg: AiProfileConfig =
        toml::from_str(&profile_str).map_err(|e| format!("Failed to parse profile config: {e}"))?;

    let trainer_cfg = TrainerConfig {
        checkpoint_dir: checkpoint_dir.clone(),
        artifact_dir: artifact_dir.clone(),
        ..TrainerConfig::smoke()
    };

    println!("{}", "Training AI Profile...".with(Color::Cyan).bold());

    let summary = train_smb_control(&profile_cfg, &trainer_cfg, episodes)
        .map_err(|e| format!("Training failed: {e}"))?;

    println!(
        "\n{}",
        build_summary_table(
            summary.average_return,
            summary.checkpoint_paths.len(),
            summary.artifact_paths.len()
        )
    );

    Ok(())
}

fn build_summary_table(
    average_return: f32,
    checkpoint_paths_len: usize,
    artifact_paths_len: usize,
) -> Table {
    let mut table = Table::new();
    table.load_preset(UTF8_FULL);
    table.set_header(vec![
        Cell::new("Property").fg(TableColor::Cyan),
        Cell::new("Value").fg(TableColor::White),
    ]);

    table.add_row(vec![
        Cell::new("Average Return"),
        Cell::new(format!("{average_return:.2}")).fg(TableColor::Yellow),
    ]);
    table.add_row(vec![
        Cell::new("Checkpoints Written"),
        Cell::new(checkpoint_paths_len.to_string()).fg(TableColor::Yellow),
    ]);
    table.add_row(vec![
        Cell::new("Artifacts Written"),
        Cell::new(artifact_paths_len.to_string()).fg(TableColor::Yellow),
    ]);

    table
}

#[cfg(test)]
mod tests {
    use super::build_summary_table;

    #[test]
    fn build_summary_table_formats_metrics() {
        let table = build_summary_table(2.5, 3, 4);
        let output = table.to_string();

        assert!(output.contains("Average Return"));
        assert!(output.contains("2.50"));
        assert!(output.contains("Checkpoints Written"));
        assert!(output.contains('3'));
        assert!(output.contains("Artifacts Written"));
        assert!(output.contains('4'));
    }
}

//! The Architect's Blueprints: AI Profile Configuration
//!
//! An AI doesn't just "play a game." It needs to know how fast time moves, what the world looks like,
//! and exactly how many points it loses for jumping into a bottomless pit.
//!
//! This module defines the rigid structure of those rules. These structs map directly to the
//! user-provided TOML or JSON configurations, defining the hyperparameters, filesystem paths,
//! and behavioral rules that govern the agent's existence.

use std::path::PathBuf;

use serde::{Deserialize, Deserializer, de::Error as _};

use crate::error::AiError;

/// The minimum allowed dimension (width or height) in pixels for an AI observation space.
pub const MIN_OBSERVATION_DIM: usize = 20;

/// Identifies the specific NES game being played by the AI profile.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum GameProfileId {
    /// Super Mario Bros. (1985)
    #[default]
    Smb,
}

/// The master ledger dictating the terms of an agent's existence.
///
/// An `AiProfileConfig` isn't just settings; it's the physics engine of the agent's mind.
/// It decides how fast the agent perceives time (`frame_skip`), how deep its memory is (`frame_stack`),
/// and what actions bring it joy or pain (`reward`).
#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct AiProfileConfig {
    /// The specific universe the agent will inhabit.
    #[serde(default)]
    pub game: GameProfileId,
    /// A unique name for this training run, used for cataloging checkpoints and artifacts.
    pub id: String,
    /// Where to find the cartridge (ROM) for the game.
    pub rom_path: PathBuf,
    /// Where to find the exact moment in time (`.state.json`) the agent will wake up in.
    pub snapshot_path: PathBuf,
    /// An optional seed script of inputs to fast-forward the agent through menus.
    pub bootstrap_tas_path: PathBuf,
    /// How many sequential glimpses of the world the agent holds in its mind at once.
    /// Critical for allowing a neural network to infer momentum and direction.
    #[serde(deserialize_with = "deserialize_positive_usize")]
    pub frame_stack: usize,
    /// How many frames the emulator fast-forwards between each agent decision.
    /// High skip means fast training but poor reaction time.
    #[serde(deserialize_with = "deserialize_positive_u32")]
    pub frame_skip: u32,
    /// The absolute time limit before the universe collapses and the episode resets.
    #[serde(deserialize_with = "deserialize_positive_u32")]
    pub max_episode_frames: u32,
    /// Rules for crushing the beautiful NES display down into cold, mathematical tensors.
    pub observation: ObservationConfig,
    /// The psychological carrot and stick. Defines what the agent values.
    pub reward: RewardConfig,
}

impl AiProfileConfig {
    /// Validates the delicate runtime invariants of the configuration.
    ///
    /// Deserializing from JSON catches most of these, but if you construct a profile
    /// by hand in code, you must ensure the physics engine doesn't divide by zero.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_ai::config::{AiProfileConfig, GameProfileId, ObservationConfig, RewardConfig};
    /// use std::path::PathBuf;
    ///
    /// let config = AiProfileConfig {
    ///     game: GameProfileId::Smb,
    ///     id: "my-hero".to_string(),
    ///     rom_path: PathBuf::from("dummy.nes"),
    ///     snapshot_path: PathBuf::from("dummy.state.json"),
    ///     bootstrap_tas_path: PathBuf::new(),
    ///     frame_stack: 4,
    ///     frame_skip: 4,
    ///     max_episode_frames: 1000,
    ///     observation: ObservationConfig { width: 84, height: 84 },
    ///     reward: RewardConfig { forward_progress: 1.0, alive_bonus: 0.1, stall_penalty: 0.0, death_penalty: 0.0, stall_frames: 60 },
    /// };
    ///
    /// // The universe is sound.
    /// assert!(config.validate().is_ok());
    /// ```
    ///
    /// # Errors
    ///
    /// Returns [`AiError`] if zero-values or dimensions smaller than [`MIN_OBSERVATION_DIM`] are found.
    pub fn validate(&self) -> Result<(), AiError> {
        validate_positive_usize(self.frame_stack, "frame_stack")?;
        validate_positive_u32(self.frame_skip, "frame_skip")?;
        validate_positive_u32(self.max_episode_frames, "max_episode_frames")?;
        self.observation.validate()?;
        self.reward.validate()?;
        Ok(())
    }
}

/// How the agent sees the world.
///
/// An NES renders at 256x240, but training a convolutional neural network on that many
/// pixels is computationally agonizing. This config dictates how brutally the screen
/// is squashed down before the agent sees it.
#[derive(Debug, Clone, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ObservationConfig {
    /// The target width of the downsampled tensor. Must be at least `MIN_OBSERVATION_DIM`.
    #[serde(deserialize_with = "deserialize_observation_dim")]
    pub width: usize,
    /// The target height of the downsampled tensor. Must be at least `MIN_OBSERVATION_DIM`.
    #[serde(deserialize_with = "deserialize_observation_dim")]
    pub height: usize,
}

impl ObservationConfig {
    fn validate(&self) -> Result<(), AiError> {
        validate_positive_usize(self.width, "observation width")?;
        validate_positive_usize(self.height, "observation height")?;
        validate_min_observation_dim(self.width, "observation width")?;
        validate_min_observation_dim(self.height, "observation height")?;
        Ok(())
    }
}

/// The psychological framework of the agent.
///
/// This structure defines the literal meaning of life for the AI. Tweak these numbers,
/// and you change whether the agent rushes fearlessly forward or cowers safely in a corner.
#[derive(Debug, Clone, Copy, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct RewardConfig {
    /// The carrot: Points awarded for moving in the right direction.
    pub forward_progress: f32,
    /// The heartbeat: A tiny drip of points given just for staying alive.
    pub alive_bonus: f32,
    /// The stick: Points drained when the agent stands still, forcing it out of local minima.
    pub stall_penalty: f32,
    /// The tragedy: A massive point deduction applied the moment the agent meets its end.
    pub death_penalty: f32,
    /// The patience: How many frames the agent can stand still before the `stall_penalty` kicks in.
    #[serde(deserialize_with = "deserialize_positive_u32")]
    pub stall_frames: u32,
}

impl RewardConfig {
    fn validate(&self) -> Result<(), AiError> {
        validate_positive_u32(self.stall_frames, "stall_frames")
    }
}

fn deserialize_positive_usize<'de, D>(deserializer: D) -> Result<usize, D::Error>
where
    D: Deserializer<'de>,
{
    let value = usize::deserialize(deserializer)?;
    if value == 0 {
        return Err(D::Error::custom("value must be greater than zero"));
    }
    Ok(value)
}

fn deserialize_observation_dim<'de, D>(deserializer: D) -> Result<usize, D::Error>
where
    D: Deserializer<'de>,
{
    let value = deserialize_positive_usize(deserializer)?;
    if value < MIN_OBSERVATION_DIM {
        return Err(D::Error::custom(format!(
            "value must be at least {MIN_OBSERVATION_DIM} pixels"
        )));
    }
    Ok(value)
}

fn deserialize_positive_u32<'de, D>(deserializer: D) -> Result<u32, D::Error>
where
    D: Deserializer<'de>,
{
    let value = u32::deserialize(deserializer)?;
    if value == 0 {
        return Err(D::Error::custom("value must be greater than zero"));
    }
    Ok(value)
}

fn validate_positive_usize(value: usize, field: &'static str) -> Result<(), AiError> {
    if value == 0 {
        return Err(AiError::Unsupported(match field {
            "frame_stack" => "frame_stack must be greater than zero",
            "observation width" => "observation width must be greater than zero",
            "observation height" => "observation height must be greater than zero",
            _ => "usize config value must be greater than zero",
        }));
    }
    Ok(())
}

fn validate_positive_u32(value: u32, field: &'static str) -> Result<(), AiError> {
    if value == 0 {
        return Err(AiError::Unsupported(match field {
            "frame_skip" => "frame_skip must be greater than zero",
            "max_episode_frames" => "max_episode_frames must be greater than zero",
            "stall_frames" => "stall_frames must be greater than zero",
            _ => "u32 config value must be greater than zero",
        }));
    }
    Ok(())
}

fn validate_min_observation_dim(value: usize, field: &'static str) -> Result<(), AiError> {
    if value < MIN_OBSERVATION_DIM {
        return Err(AiError::Unsupported(match field {
            "observation width" => "observation width must be at least 20 pixels",
            "observation height" => "observation height must be at least 20 pixels",
            _ => "observation dimension must be at least 20 pixels",
        }));
    }
    Ok(())
}

//! The Matrix: Simulated Environments for AI Agents
//!
//! An AI agent does not know what an "NES" is. It only knows that when it provides an
//! action, the universe replies with an observation and a reward.
//!
//! This module wraps the `NesCore` emulator inside a reinforcement learning environment.
//! It handles the dirty work of downsampling frames, managing frame-skipping, computing
//! rewards, and recording TAS movies, so the AI can focus purely on learning to win.

use std::fs;

use nes_core::{
    Command, NesCore,
    tas::{TasMovie, TasRecorder},
};

use crate::{
    actions::ControlAction,
    config::{AiProfileConfig, GameProfileId},
    episode::EpisodeMetadata,
    error::AiError,
    obs::{FrameStack, downsample_grayscale},
    profile::TaskProfile,
    profiles::smb::SmbProfile,
    reward::{RewardBreakdown, RewardFeatures, RewardModel},
    snapshot::{SnapshotBundle, load_snapshot_bundle, sha256_hex},
};

/// The universe's reply to an agent's action.
#[derive(Debug, Clone)]
pub struct StepOutput<F> {
    /// The raw, game-specific memory state (e.g., Mario's coordinates, enemy positions).
    pub features: F,
    /// The score calculated by the reward model, broken down by category.
    pub reward: RewardBreakdown,
    /// Indicates if the agent died, won, or ran out of time. If true, the simulation must be reset.
    pub done: bool,
}

/// A frozen glimpse of the world, packaged neatly for a neural network.
///
/// This snapshot flattens history (stacked frames) and reality (game features) into
/// contiguous floating-point buffers, ready to be ingested by Burn tensors.
#[derive(Debug, Clone, PartialEq)]
pub struct ObservationSnapshot {
    /// How many sequential glimpses of the world are stacked here.
    pub frame_stack: usize,
    /// The width of a single downsampled frame.
    pub width: usize,
    /// The height of a single downsampled frame.
    pub height: usize,
    /// The visual pixels, crushed into grayscale and flattened.
    pub frames: Vec<f32>,
    /// The numeric state vectors (like positions or speeds), flattened.
    pub features: Vec<f32>,
}

/// A stripped-down reply to an agent's action, useful for agnostic evaluation loops.
#[derive(Debug, Clone)]
pub struct ControlStepOutput {
    /// The score calculated by the reward model.
    pub reward: RewardBreakdown,
    /// Indicates if the simulation has reached a terminal state.
    pub done: bool,
}

/// Connects an NES emulator to a specific AI control profile, executing frames
/// and evaluating success/failure for the training feedback loop.
///
/// We need this wrapper so the AI doesn't interact directly with raw NES opcodes.
/// It creates a clean boundary: "Here are the buttons to press, and here is how
/// good you did." It maintains the `NesCore`, processes frame stacks, calculates
/// rewards, and ultimately spits out TAS (Tool-Assisted Speedrun) artifacts.
pub struct ProfileEnv<P>
where
    P: TaskProfile,
    P::Features: RewardFeatures,
{
    core: NesCore,
    profile: P,
    snapshot: SnapshotBundle,
    frame_stack: FrameStack,
    reward: RewardModel,
    recorder: TasRecorder,
    episode_frames: u32,
    episode_done: bool,
    stalled_frames: u32,
    last_features: Option<P::Features>,
}

impl<P> ProfileEnv<P>
where
    P: TaskProfile,
    P::Features: RewardFeatures,
{
    /// Constructs a new, uninitialized sandbox.
    ///
    /// The environment is born in limbo. You must call `reset()` to inject the snapshot
    /// and breathe life into the emulator before asking for observations or taking steps.
    ///
    /// ## Examples
    ///
    /// ```rust,ignore
    /// // Example ignored in tests due to the complexity of constructing a valid CoreSnapshot from scratch.
    /// use nes_ai::{env::ProfileEnv, config::AiProfileConfig, snapshot::load_snapshot_bundle};
    /// use nes_ai::profiles::smb::SmbProfile;
    ///
    /// let config = AiProfileConfig { /* ... */ };
    /// let profile = SmbProfile::new(config.clone());
    /// let snapshot = load_snapshot_bundle(&config.snapshot_path)?;
    ///
    /// // Create the environment
    /// let mut env = ProfileEnv::new(profile, snapshot);
    ///
    /// // The environment must be reset before it can be stepped!
    /// env.reset()?;
    /// ```
    #[must_use]
    pub fn new(profile: P, snapshot: SnapshotBundle) -> Self {
        let cfg = profile.config().clone();
        Self {
            core: NesCore::new(),
            profile,
            snapshot,
            frame_stack: FrameStack::new(
                cfg.frame_stack,
                cfg.observation.width * cfg.observation.height,
            ),
            reward: RewardModel::new(cfg.reward),
            recorder: TasRecorder::new(),
            episode_frames: 0,
            episode_done: false,
            stalled_frames: 0,
            last_features: None,
        }
    }

    /// Rewinds time to the beginning.
    ///
    /// Restores the exact memory snapshot provided during creation, clears the TAS recorder,
    /// flushes the frame stack, and computes the very first observation for the agent.
    ///
    /// ## Examples
    ///
    /// ```rust,no_run
    /// # use nes_ai::{env::SmbControlEnv, config::{AiProfileConfig, ObservationConfig, RewardConfig, GameProfileId}, error::AiError};
    /// # fn main() -> Result<(), AiError> {
    /// # let config = AiProfileConfig { game: GameProfileId::Smb, id: "test".to_string(), rom_path: std::path::PathBuf::new(), snapshot_path: std::path::PathBuf::new(), bootstrap_tas_path: std::path::PathBuf::new(), frame_stack: 4, frame_skip: 4, max_episode_frames: 100, observation: ObservationConfig { width: 84, height: 84 }, reward: RewardConfig { forward_progress: 1.0, alive_bonus: 0.0, stall_penalty: 0.0, death_penalty: 0.0, stall_frames: 10 } };
    /// # let mut env = SmbControlEnv::from_config(config)?;
    /// // Start a new episode.
    /// let initial_features = env.reset()?;
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// # Errors
    ///
    /// Returns [`AiError`] if the emulator core rejects the state payload.
    pub fn reset(&mut self) -> Result<P::Features, AiError> {
        self.core.load_state(&self.snapshot.snapshot);
        self.recorder = TasRecorder::new();
        self.recorder.start();
        self.episode_frames = 0;
        self.episode_done = false;
        self.stalled_frames = 0;
        self.frame_stack = FrameStack::new(
            self.profile.config().frame_stack,
            self.profile.config().observation.width * self.profile.config().observation.height,
        );

        let features = self.profile.decode_features(&self.core);
        self.last_features = Some(features.clone());

        let frame = downsample_grayscale(
            &self.core.framebuffer_rgba(),
            self.profile.config().observation.width,
            self.profile.config().observation.height,
        );
        for _ in 0..self.profile.config().frame_stack {
            self.frame_stack.push(frame.clone());
        }

        Ok(features)
    }

    /// Commits an action to the universe and fast-forwards time.
    ///
    /// The environment holds the requested joypad buttons down and advances the emulator
    /// by `frame_skip` frames. It then calculates how much progress was made and applies
    /// the psychological reward (or penalty).
    ///
    /// ## Examples
    ///
    /// ```rust,no_run
    /// # use nes_ai::{env::SmbControlEnv, actions::ControlAction, config::{AiProfileConfig, ObservationConfig, RewardConfig, GameProfileId}, error::AiError};
    /// # fn main() -> Result<(), AiError> {
    /// # let config = AiProfileConfig { game: GameProfileId::Smb, id: "test".to_string(), rom_path: std::path::PathBuf::new(), snapshot_path: std::path::PathBuf::new(), bootstrap_tas_path: std::path::PathBuf::new(), frame_stack: 4, frame_skip: 4, max_episode_frames: 100, observation: ObservationConfig { width: 84, height: 84 }, reward: RewardConfig { forward_progress: 1.0, alive_bonus: 0.0, stall_penalty: 0.0, death_penalty: 0.0, stall_frames: 10 } };
    /// # let mut env = SmbControlEnv::from_config(config)?;
    /// env.reset()?;
    ///
    /// // Move right and jump!
    /// let output = env.step(ControlAction::RightA)?;
    /// if output.done {
    ///     println!("The agent met its end.");
    /// }
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// # Errors
    ///
    /// Returns [`AiError`] if called before [`Self::reset`] or if the episode has already ended.
    pub fn step(&mut self, action: ControlAction) -> Result<StepOutput<P::Features>, AiError> {
        if self.episode_done {
            return Err(AiError::Unsupported("step after episode done"));
        }
        let prev = self
            .last_features
            .clone()
            .ok_or(AiError::Unsupported("step before reset"))?;
        let controller1_bits = action.controller1_bits();
        self.core
            .execute(Command::SetControllerState(controller1_bits))
            .map_err(|_| AiError::Unsupported("step controller"))?;

        let mut budget_done = false;
        for _ in 0..self.profile.config().frame_skip {
            if self.episode_frames >= self.profile.config().max_episode_frames {
                budget_done = true;
                break;
            }
            self.recorder.record_frame(controller1_bits);
            self.core
                .execute(Command::StepFrame)
                .map_err(|_| AiError::Unsupported("step frame"))?;
            self.episode_frames = self.episode_frames.saturating_add(1);
        }

        let frame = downsample_grayscale(
            &self.core.framebuffer_rgba(),
            self.profile.config().observation.width,
            self.profile.config().observation.height,
        );
        self.frame_stack.push(frame);

        let next = self.profile.decode_features(&self.core);
        self.stalled_frames = if next.level_progress() > prev.level_progress() {
            0
        } else {
            self.stalled_frames
                .saturating_add(self.profile.config().frame_skip)
        };
        let mut reward = self.reward.score(&prev, &next, self.stalled_frames);
        reward.done = reward.done
            || budget_done
            || self.episode_frames >= self.profile.config().max_episode_frames;
        self.last_features = Some(next.clone());
        self.episode_done = reward.done;

        Ok(StepOutput {
            done: self.episode_done,
            reward,
            features: next,
        })
    }

    /// Returns a shared reference to the underlying emulator core.
    ///
    /// This is useful for inspecting the current internal state of the NES
    /// without advancing the simulation or mutating its state.
    ///
    /// # Examples
    ///
    /// ```rust,no_run
    /// # use nes_ai::{env::SmbControlEnv, config::{AiProfileConfig, ObservationConfig, RewardConfig, GameProfileId}, error::AiError};
    /// # fn main() -> Result<(), AiError> {
    /// # let config = AiProfileConfig { game: GameProfileId::Smb, id: "test".to_string(), rom_path: std::path::PathBuf::new(), snapshot_path: std::path::PathBuf::new(), bootstrap_tas_path: std::path::PathBuf::new(), frame_stack: 4, frame_skip: 4, max_episode_frames: 100, observation: ObservationConfig { width: 84, height: 84 }, reward: RewardConfig { forward_progress: 1.0, alive_bonus: 0.0, stall_penalty: 0.0, death_penalty: 0.0, stall_frames: 10 } };
    /// # let env = SmbControlEnv::from_config(config)?;
    /// // Inspect the current state hash of the emulator.
    /// let hash = env.core().state_hash();
    /// println!("State Hash: {}", hash);
    /// # Ok(())
    /// # }
    /// ```
    #[must_use]
    pub fn core(&self) -> &NesCore {
        &self.core
    }

    /// Returns a mutable reference to the underlying emulator core.
    ///
    /// This allows direct manipulation of the emulator's state, such as
    /// injecting custom commands, modifying memory, or forcibly loading state.
    ///
    /// # Examples
    ///
    /// ```rust,no_run
    /// # use nes_ai::{env::SmbControlEnv, config::{AiProfileConfig, ObservationConfig, RewardConfig, GameProfileId}, error::AiError};
    /// # use nes_core::Command;
    /// # fn main() -> Result<(), AiError> {
    /// # let config = AiProfileConfig { game: GameProfileId::Smb, id: "test".to_string(), rom_path: std::path::PathBuf::new(), snapshot_path: std::path::PathBuf::new(), bootstrap_tas_path: std::path::PathBuf::new(), frame_stack: 4, frame_skip: 4, max_episode_frames: 100, observation: ObservationConfig { width: 84, height: 84 }, reward: RewardConfig { forward_progress: 1.0, alive_bonus: 0.0, stall_penalty: 0.0, death_penalty: 0.0, stall_frames: 10 } };
    /// # let mut env = SmbControlEnv::from_config(config)?;
    /// // Directly execute a command on the underlying core.
    /// env.core_mut().execute(Command::StepFrame).unwrap();
    /// # Ok(())
    /// # }
    /// ```
    pub fn core_mut(&mut self) -> &mut NesCore {
        &mut self.core
    }

    /// Gazes into the environment's current state.
    ///
    /// Flattens the recent history of visuals and internal game memory into a format
    /// easily digested by the agent's neural network.
    ///
    /// ## Examples
    ///
    /// ```rust,no_run
    /// # use nes_ai::{env::SmbControlEnv, actions::ControlAction, config::{AiProfileConfig, ObservationConfig, RewardConfig, GameProfileId}, error::AiError};
    /// # fn main() -> Result<(), AiError> {
    /// # let config = AiProfileConfig { game: GameProfileId::Smb, id: "test".to_string(), rom_path: std::path::PathBuf::new(), snapshot_path: std::path::PathBuf::new(), bootstrap_tas_path: std::path::PathBuf::new(), frame_stack: 4, frame_skip: 4, max_episode_frames: 100, observation: ObservationConfig { width: 84, height: 84 }, reward: RewardConfig { forward_progress: 1.0, alive_bonus: 0.0, stall_penalty: 0.0, death_penalty: 0.0, stall_frames: 10 } };
    /// # let mut env = SmbControlEnv::from_config(config)?;
    /// env.reset()?;
    ///
    /// let vision = env.observation()?;
    /// assert_eq!(vision.frames.len(), 4 * 84 * 84); // 4 frames stacked
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// # Errors
    ///
    /// Returns [`AiError::Unsupported`] if called before the environment is initialized via `reset()`.
    pub fn observation(&self) -> Result<ObservationSnapshot, AiError> {
        let features = self
            .last_features
            .as_ref()
            .ok_or(AiError::Unsupported("observation before reset"))?;

        Ok(ObservationSnapshot {
            frame_stack: self.profile.config().frame_stack,
            width: self.profile.config().observation.width,
            height: self.profile.config().observation.height,
            frames: self.frame_stack.flattened(),
            features: self.profile.encode_features(features),
        })
    }

    /// Returns the complete history of inputs from the current episode.
    ///
    /// Every twitch of the controller is recorded. When the agent does something brilliant,
    /// this TAS movie is the proof we save to disk.
    ///
    /// ## Examples
    ///
    /// ```rust,no_run
    /// # use nes_ai::{env::SmbControlEnv, actions::ControlAction, config::{AiProfileConfig, ObservationConfig, RewardConfig, GameProfileId}, error::AiError};
    /// # fn main() -> Result<(), AiError> {
    /// # let config = AiProfileConfig { game: GameProfileId::Smb, id: "test".to_string(), rom_path: std::path::PathBuf::new(), snapshot_path: std::path::PathBuf::new(), bootstrap_tas_path: std::path::PathBuf::new(), frame_stack: 4, frame_skip: 4, max_episode_frames: 100, observation: ObservationConfig { width: 84, height: 84 }, reward: RewardConfig { forward_progress: 1.0, alive_bonus: 0.0, stall_penalty: 0.0, death_penalty: 0.0, stall_frames: 10 } };
    /// # let mut env = SmbControlEnv::from_config(config)?;
    /// env.reset()?;
    /// env.step(ControlAction::RightA)?;
    ///
    /// let movie = env.recorded_movie();
    /// println!("Recorded {} frames", movie.total_frames());
    /// # Ok(())
    /// # }
    /// ```
    #[must_use]
    pub fn recorded_movie(&self) -> &nes_core::tas::TasMovie {
        self.recorder.movie()
    }

    /// Signs the death certificate.
    ///
    /// Compiles all terminal metrics (frames survived, total reward, final memory hash)
    /// into a tidy piece of metadata for telemetry and debugging.
    ///
    /// ## Examples
    ///
    /// ```rust,no_run
    /// # use nes_ai::{env::SmbControlEnv, actions::ControlAction, config::{AiProfileConfig, ObservationConfig, RewardConfig, GameProfileId}, error::AiError};
    /// # fn main() -> Result<(), AiError> {
    /// # let config = AiProfileConfig { game: GameProfileId::Smb, id: "test".to_string(), rom_path: std::path::PathBuf::new(), snapshot_path: std::path::PathBuf::new(), bootstrap_tas_path: std::path::PathBuf::new(), frame_stack: 4, frame_skip: 4, max_episode_frames: 100, observation: ObservationConfig { width: 84, height: 84 }, reward: RewardConfig { forward_progress: 1.0, alive_bonus: 0.0, stall_penalty: 0.0, death_penalty: 0.0, stall_frames: 10 } };
    /// # let mut env = SmbControlEnv::from_config(config)?;
    /// env.reset()?;
    /// let meta = env.finish_episode(42.5);
    /// println!("Agent scored: {}", meta.total_reward);
    /// # Ok(())
    /// # }
    /// ```
    #[must_use]
    pub fn finish_episode(&self, total_reward: f32) -> EpisodeMetadata {
        EpisodeMetadata {
            profile_id: self.profile.config().id.clone(),
            snapshot_id: self.snapshot.snapshot_id.clone(),
            rom_hash: self.snapshot.rom_hash.clone(),
            total_reward,
            episode_frames: u64::from(self.episode_frames),
            final_state_hash: self.core.state_hash(),
        }
    }
}

impl ProfileEnv<SmbProfile> {
    /// Builds an SMB control environment from a validated AI profile config.
    ///
    /// # Errors
    ///
    /// Returns [`AiError`] if the configured snapshot bundle cannot be loaded,
    /// the ROM cannot be read, or the ROM hash does not match the snapshot.
    pub fn from_config(cfg: AiProfileConfig) -> Result<Self, AiError> {
        if cfg.game != GameProfileId::Smb {
            return Err(AiError::Unsupported("smb env requires game = \"smb\""));
        }
        let snapshot = load_verified_snapshot(&cfg)?;
        let profile = SmbProfile::new(cfg);
        Ok(Self::new(profile, snapshot))
    }
}

/// A concrete instance of the AI control environment for Super Mario Bros.
pub type SmbControlEnv = ProfileEnv<SmbProfile>;

/// Type-erased wrapper for concrete environment specializations like SMB.
///
/// In Rust, generic types `ProfileEnv<P>` infect your entire API surface. This enum
/// exists to hide that complexity behind a single enum, making it trivial to pass
/// "some control environment" across thread bounds without dealing with `Box<dyn Any>`
/// trait object headaches.
pub enum AnyControlEnv {
    /// Environment variant specifically handling Super Mario Bros. logic.
    Smb(Box<SmbControlEnv>),
}

impl AnyControlEnv {
    /// Summons the appropriate universe based on the provided configuration.
    ///
    /// ## Examples
    ///
    /// ```rust,no_run
    /// # use nes_ai::{env::AnyControlEnv, actions::ControlAction, config::{AiProfileConfig, ObservationConfig, RewardConfig, GameProfileId}, error::AiError};
    /// # fn main() -> Result<(), AiError> {
    /// # let config = AiProfileConfig { game: GameProfileId::Smb, id: "test".to_string(), rom_path: std::path::PathBuf::new(), snapshot_path: std::path::PathBuf::new(), bootstrap_tas_path: std::path::PathBuf::new(), frame_stack: 4, frame_skip: 4, max_episode_frames: 100, observation: ObservationConfig { width: 84, height: 84 }, reward: RewardConfig { forward_progress: 1.0, alive_bonus: 0.0, stall_penalty: 0.0, death_penalty: 0.0, stall_frames: 10 } };
    /// let mut env = AnyControlEnv::from_config(config)?;
    /// env.reset()?;
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// # Errors
    ///
    /// Returns [`AiError`] if config validation, snapshot loading, or ROM validation fails.
    pub fn from_config(cfg: AiProfileConfig) -> Result<Self, AiError> {
        match cfg.game {
            GameProfileId::Smb => Ok(Self::Smb(Box::new(SmbControlEnv::from_config(cfg)?))),
        }
    }

    /// Rewinds time to the beginning for the active environment.
    ///
    /// ## Examples
    ///
    /// ```rust,no_run
    /// # use nes_ai::{env::AnyControlEnv, actions::ControlAction, config::{AiProfileConfig, ObservationConfig, RewardConfig, GameProfileId}, error::AiError};
    /// # fn main() -> Result<(), AiError> {
    /// # let config = AiProfileConfig { game: GameProfileId::Smb, id: "test".to_string(), rom_path: std::path::PathBuf::new(), snapshot_path: std::path::PathBuf::new(), bootstrap_tas_path: std::path::PathBuf::new(), frame_stack: 4, frame_skip: 4, max_episode_frames: 100, observation: ObservationConfig { width: 84, height: 84 }, reward: RewardConfig { forward_progress: 1.0, alive_bonus: 0.0, stall_penalty: 0.0, death_penalty: 0.0, stall_frames: 10 } };
    /// # let mut env = AnyControlEnv::from_config(config)?;
    /// env.reset()?; // Ready to play!
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// # Errors
    ///
    /// Returns [`AiError`] if the concrete environment cannot restore its snapshot.
    pub fn reset(&mut self) -> Result<(), AiError> {
        match self {
            Self::Smb(env) => {
                env.reset()?;
                Ok(())
            }
        }
    }

    /// Commits an action to the active universe and fast-forwards time.
    ///
    /// ## Examples
    ///
    /// ```rust,no_run
    /// # use nes_ai::{env::AnyControlEnv, actions::ControlAction, config::{AiProfileConfig, ObservationConfig, RewardConfig, GameProfileId}, error::AiError};
    /// # fn main() -> Result<(), AiError> {
    /// # let config = AiProfileConfig { game: GameProfileId::Smb, id: "test".to_string(), rom_path: std::path::PathBuf::new(), snapshot_path: std::path::PathBuf::new(), bootstrap_tas_path: std::path::PathBuf::new(), frame_stack: 4, frame_skip: 4, max_episode_frames: 100, observation: ObservationConfig { width: 84, height: 84 }, reward: RewardConfig { forward_progress: 1.0, alive_bonus: 0.0, stall_penalty: 0.0, death_penalty: 0.0, stall_frames: 10 } };
    /// # let mut env = AnyControlEnv::from_config(config)?;
    /// # env.reset()?;
    /// let step = env.step(ControlAction::RightB)?;
    /// println!("Score changed by: {}", step.reward.total);
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// # Errors
    ///
    /// Returns [`AiError`] if the concrete environment cannot step.
    pub fn step(&mut self, action: ControlAction) -> Result<ControlStepOutput, AiError> {
        match self {
            Self::Smb(env) => {
                let step = env.step(action)?;
                Ok(ControlStepOutput {
                    reward: step.reward,
                    done: step.done,
                })
            }
        }
    }

    /// Gazes into the active environment's current state.
    ///
    /// ## Examples
    ///
    /// ```rust,no_run
    /// # use nes_ai::{env::AnyControlEnv, actions::ControlAction, config::{AiProfileConfig, ObservationConfig, RewardConfig, GameProfileId}, error::AiError};
    /// # fn main() -> Result<(), AiError> {
    /// # let config = AiProfileConfig { game: GameProfileId::Smb, id: "test".to_string(), rom_path: std::path::PathBuf::new(), snapshot_path: std::path::PathBuf::new(), bootstrap_tas_path: std::path::PathBuf::new(), frame_stack: 4, frame_skip: 4, max_episode_frames: 100, observation: ObservationConfig { width: 84, height: 84 }, reward: RewardConfig { forward_progress: 1.0, alive_bonus: 0.0, stall_penalty: 0.0, death_penalty: 0.0, stall_frames: 10 } };
    /// # let mut env = AnyControlEnv::from_config(config)?;
    /// # env.reset()?;
    /// let vision = env.observation()?;
    /// # Ok(())
    /// # }
    /// ```
    ///
    /// # Errors
    ///
    /// Returns [`AiError`] if called before reset.
    pub fn observation(&self) -> Result<ObservationSnapshot, AiError> {
        match self {
            Self::Smb(env) => env.observation(),
        }
    }

    /// Extracts the recorded TAS input sequence from the active universe.
    ///
    /// ## Examples
    ///
    /// ```rust,no_run
    /// # use nes_ai::{env::AnyControlEnv, actions::ControlAction, config::{AiProfileConfig, ObservationConfig, RewardConfig, GameProfileId}, error::AiError};
    /// # fn main() -> Result<(), AiError> {
    /// # let config = AiProfileConfig { game: GameProfileId::Smb, id: "test".to_string(), rom_path: std::path::PathBuf::new(), snapshot_path: std::path::PathBuf::new(), bootstrap_tas_path: std::path::PathBuf::new(), frame_stack: 4, frame_skip: 4, max_episode_frames: 100, observation: ObservationConfig { width: 84, height: 84 }, reward: RewardConfig { forward_progress: 1.0, alive_bonus: 0.0, stall_penalty: 0.0, death_penalty: 0.0, stall_frames: 10 } };
    /// # let mut env = AnyControlEnv::from_config(config)?;
    /// # env.reset()?;
    /// let movie = env.recorded_movie();
    /// # Ok(())
    /// # }
    /// ```
    #[must_use]
    pub fn recorded_movie(&self) -> &TasMovie {
        match self {
            Self::Smb(env) => env.recorded_movie(),
        }
    }

    /// Signs the death certificate for the active universe, returning metrics.
    ///
    /// ## Examples
    ///
    /// ```rust,no_run
    /// # use nes_ai::{env::AnyControlEnv, actions::ControlAction, config::{AiProfileConfig, ObservationConfig, RewardConfig, GameProfileId}, error::AiError};
    /// # fn main() -> Result<(), AiError> {
    /// # let config = AiProfileConfig { game: GameProfileId::Smb, id: "test".to_string(), rom_path: std::path::PathBuf::new(), snapshot_path: std::path::PathBuf::new(), bootstrap_tas_path: std::path::PathBuf::new(), frame_stack: 4, frame_skip: 4, max_episode_frames: 100, observation: ObservationConfig { width: 84, height: 84 }, reward: RewardConfig { forward_progress: 1.0, alive_bonus: 0.0, stall_penalty: 0.0, death_penalty: 0.0, stall_frames: 10 } };
    /// # let mut env = AnyControlEnv::from_config(config)?;
    /// # env.reset()?;
    /// let meta = env.finish_episode(0.0);
    /// # Ok(())
    /// # }
    /// ```
    #[must_use]
    pub fn finish_episode(&self, total_reward: f32) -> EpisodeMetadata {
        match self {
            Self::Smb(env) => env.finish_episode(total_reward),
        }
    }
}

fn load_verified_snapshot(cfg: &AiProfileConfig) -> Result<SnapshotBundle, AiError> {
    cfg.validate()?;
    let snapshot = load_snapshot_bundle(&cfg.snapshot_path)?;
    let rom_hash = read_rom_hash(&cfg.rom_path)?;
    if snapshot.rom_hash != rom_hash {
        return Err(AiError::RomHashMismatch {
            expected: snapshot.rom_hash,
            found: rom_hash,
        });
    }
    Ok(snapshot)
}

fn read_rom_hash(path: &std::path::Path) -> Result<String, AiError> {
    let rom = fs::read(path).map_err(|source| AiError::RomRead {
        path: path.to_path_buf(),
        source,
    })?;
    Ok(sha256_hex(&rom))
}

//! The Scribe's Ledger: Episode Telemetry and Artifacts
//!
//! When an AI finishes an episode—whether it died valiantly on world 1-1 or miraculously
//! beat the game—we need proof. We need to save its memory, its inputs, and its final score.
//!
//! This module acts as the historian. It scoops up the TAS input sequences and performance
//! metadata from an environment and carefully etches them onto the disk for later
//! evaluation, debugging, and bragging rights.

use std::{fs, path::PathBuf};

use nes_core::tas::{TasError, TasMovie};
use serde::Serialize;

use crate::error::AiError;

/// The final epitaph of a completed training run.
///
/// This structure holds the high-level summary of an episode's events. Was it a
/// glorious success or a tragic failure? The numbers tell the story.
#[derive(Debug, Clone, Serialize)]
pub struct EpisodeMetadata {
    /// The specific training ruleset under which the agent operated.
    pub profile_id: String,
    /// The unique identifier of the save state where the agent was born.
    pub snapshot_id: String,
    /// The cryptographic fingerprint of the universe (ROM) the agent inhabited.
    pub rom_hash: String,
    /// The final score. The ultimate measure of the agent's worth.
    pub total_reward: f32,
    /// How many subjective ticks of time the agent experienced before the end.
    pub episode_frames: u64,
    /// The final state of the universe at the moment of completion or death.
    pub final_state_hash: u64,
}

/// The physical manifestations of the agent's memory, written to the local disk.
#[derive(Debug, Clone)]
pub struct EpisodeArtifactPaths {
    /// The path to the raw input sequence (`.tas.json`), used to exactly replay the run.
    pub tas_json_path: PathBuf,
    /// The path to the run's metadata (`.run.json`), detailing score and duration.
    pub run_json_path: PathBuf,
    /// The path to a human-readable transcription of the inputs (`.macro.txt`), if available.
    pub macro_txt_path: Option<PathBuf>,
}

/// The tireless historian that writes the agent's legacy to disk.
///
/// It ensures that all files related to an episode (metadata, TAS replays, macros)
/// are written atomically. If one fails, it attempts to clean up the rest, leaving
/// no corrupted half-histories behind.
#[derive(Debug, Clone)]
pub struct EpisodeArtifactWriter {
    /// The sanctuary where all records are kept.
    output_dir: PathBuf,
}

impl EpisodeArtifactWriter {
    /// Employs a new historian assigned to the specified directory.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_ai::episode::EpisodeArtifactWriter;
    /// use std::path::PathBuf;
    ///
    /// let scribe = EpisodeArtifactWriter::new(PathBuf::from("/tmp/ai_runs"));
    /// ```
    #[must_use]
    pub fn new(output_dir: PathBuf) -> Self {
        Self { output_dir }
    }

    /// Writes TAS, run metadata, and optional macro playback artifacts for one episode.
    ///
    /// # Errors
    ///
    /// Returns [`AiError`] if the prefix is invalid, the output directory cannot be
    /// created, serialization fails, or any artifact cannot be written.
    pub fn write(
        &self,
        prefix: &str,
        movie: &TasMovie,
        meta: &EpisodeMetadata,
    ) -> Result<EpisodeArtifactPaths, AiError> {
        let prefix = sanitize_prefix(prefix)?;
        fs::create_dir_all(&self.output_dir).map_err(|source| AiError::ArtifactDirCreate {
            path: self.output_dir.clone(),
            source,
        })?;

        let tas_json_path = self.output_dir.join(format!("{prefix}.tas.json"));
        let run_json_path = self.output_dir.join(format!("{prefix}.run.json"));
        let tas_json =
            serde_json::to_vec_pretty(movie).map_err(|source| AiError::ArtifactSerialize {
                kind: "tas movie",
                source,
            })?;
        let run_json =
            serde_json::to_vec_pretty(meta).map_err(|source| AiError::ArtifactSerialize {
                kind: "episode metadata",
                source,
            })?;

        let mut written_paths = Vec::<PathBuf>::new();
        write_artifact(&tas_json_path, &tas_json).map_err(|source| {
            cleanup_artifacts(&written_paths);
            AiError::ArtifactWrite {
                path: tas_json_path.clone(),
                source,
            }
        })?;
        written_paths.push(tas_json_path.clone());

        write_artifact(&run_json_path, &run_json).map_err(|source| {
            cleanup_artifacts(&written_paths);
            AiError::ArtifactWrite {
                path: run_json_path.clone(),
                source,
            }
        })?;
        written_paths.push(run_json_path.clone());

        let macro_txt_path = match movie.to_macro_script() {
            Ok(script) => {
                let path = self.output_dir.join(format!("{prefix}.macro.txt"));
                write_artifact(&path, script.as_bytes()).map_err(|source| {
                    cleanup_artifacts(&written_paths);
                    AiError::ArtifactWrite {
                        path: path.clone(),
                        source,
                    }
                })?;
                written_paths.push(path.clone());
                Some(path)
            }
            Err(TasError::Player2MacroScriptUnsupported) => None,
        };

        Ok(EpisodeArtifactPaths {
            tas_json_path,
            run_json_path,
            macro_txt_path,
        })
    }
}

fn sanitize_prefix(prefix: &str) -> Result<&str, AiError> {
    if prefix.is_empty() || prefix == "." || prefix == ".." || prefix.contains(['/', '\\', ':']) {
        return Err(AiError::ArtifactPrefixInvalid {
            prefix: prefix.to_owned(),
        });
    }

    Ok(prefix)
}

fn write_artifact(path: &PathBuf, bytes: &[u8]) -> Result<(), std::io::Error> {
    fs::write(path, bytes)
}

fn cleanup_artifacts(paths: &[PathBuf]) {
    for path in paths {
        let _ = fs::remove_file(path);
    }
}

//! The Tragedy of Errors: Handling AI Pipeline Failures
//!
//! Training an AI is a fragile endeavor. A missing ROM, a corrupted snapshot, or a
//! mathematically impossible configuration can all bring the agent's universe crashing down.
//!
//! This module categorizes every way the training pipeline can fail, ensuring that when
//! things break, the developer gets a clear story of *why* rather than a cryptic panic.

use std::path::PathBuf;

use burn_core::record::RecorderError;
use thiserror::Error;

/// The exhaustive list of tragedies that can befall an agent or its environment.
#[derive(Debug, Error)]
pub enum AiError {
    /// An operation that defies the physics of the simulation (e.g., trying to step before resetting).
    #[error("unsupported operation: {0}")]
    Unsupported(&'static str),
    /// The filesystem refused to grant a home for the agent's memories.
    #[error("failed to create snapshot directory '{path}': {source}")]
    SnapshotDirCreate {
        /// The path we begged the OS to create.
        path: PathBuf,
        /// The cold reality of the OS rejection.
        #[source]
        source: std::io::Error,
    },
    /// The agent's memory was too complex to be captured in JSON.
    #[error("failed to serialize snapshot bundle: {source}")]
    SnapshotSerialize {
        /// The serialization logic failure.
        #[source]
        source: serde_json::Error,
    },
    /// The agent's memory was serialized, but the disk refused to hold it.
    #[error("failed to write snapshot bundle '{path}': {source}")]
    SnapshotWrite {
        /// Where we tried to entomb the data.
        path: PathBuf,
        /// The physical IO failure.
        #[source]
        source: std::io::Error,
    },
    /// We tried to resurrect the agent, but the tomb was empty or sealed.
    #[error(
        "failed to read snapshot bundle '{path}': {source}\nHint: Ensure the file exists or check the profile configuration."
    )]
    SnapshotRead {
        /// Where we expected to find the memory.
        path: PathBuf,
        /// The reason the read failed.
        #[source]
        source: std::io::Error,
    },
    /// We resurrected the agent's memory, but it was corrupted madness.
    #[error("failed to parse snapshot bundle '{path}': {source}")]
    SnapshotParse {
        /// The file containing the corrupted memories.
        path: PathBuf,
        /// The parsing logic failure.
        #[source]
        source: serde_json::Error,
    },
    /// The snapshot comes from a timeline (version) we do not understand.
    #[error("unsupported snapshot bundle version: expected {expected}, found {found}")]
    SnapshotVersionMismatch {
        /// The timeline we know.
        expected: u32,
        /// The timeline the file belongs to.
        found: u32,
    },
    /// The filesystem refused to grant a directory for the agent's final legacy (artifacts).
    #[error("failed to create artifact directory '{path}': {source}")]
    ArtifactDirCreate {
        /// The intended resting place for the artifacts.
        path: PathBuf,
        /// The IO error blocking creation.
        #[source]
        source: std::io::Error,
    },
    /// We failed to translate the agent's final deeds into a readable JSON artifact.
    #[error("failed to serialize {kind}: {source}")]
    ArtifactSerialize {
        /// What we were trying to record (e.g. "tas movie", "episode metadata").
        kind: &'static str,
        /// The serialization error.
        #[source]
        source: serde_json::Error,
    },
    /// The agent's deeds were recorded, but the disk refused to accept the final file.
    #[error("failed to write artifact '{path}': {source}")]
    ArtifactWrite {
        /// The intended file path.
        path: PathBuf,
        /// The IO failure.
        #[source]
        source: std::io::Error,
    },
    /// The requested name prefix for saving checkpoints contained illegal or dangerous characters.
    #[error("invalid artifact prefix '{prefix}'")]
    ArtifactPrefixInvalid {
        /// The offending prefix string.
        prefix: String,
    },
    /// The Burn neural network framework failed to write its synaptic weights to disk.
    #[error("failed to save checkpoint '{path}': {source}")]
    CheckpointSave {
        /// Where the weights were supposed to go.
        path: PathBuf,
        /// The internal error from Burn's recorder.
        #[source]
        source: RecorderError,
    },
    /// The Burn neural network framework failed to read its synaptic weights from disk.
    #[error("failed to load checkpoint '{path}': {source}")]
    CheckpointLoad {
        /// Where we looked for the weights.
        path: PathBuf,
        /// The internal error from Burn's recorder.
        #[source]
        source: RecorderError,
    },
    /// We could not locate or open the sacred cartridge (ROM) the agent is supposed to inhabit.
    #[error(
        "failed to read ROM '{path}': {source}\nHint: Ensure the ROM file exists and is accessible."
    )]
    RomRead {
        /// The path we expected the ROM to be at.
        path: PathBuf,
        /// The IO error preventing access.
        #[source]
        source: std::io::Error,
    },
    /// The ROM loaded does not perfectly match the universe the snapshot was created in.
    /// A single mismatched byte could cause a catastrophic butterfly effect.
    #[error("ROM hash mismatch: expected {expected}, found {found}")]
    RomHashMismatch {
        /// The expected cryptographic signature.
        expected: String,
        /// The actual signature of the loaded file.
        found: String,
    },
}

