//! The Hybrid Policy-Value Network Architecture.
//!
//! This module contains the core neural network definition used by our reinforcement
//! learning agent. It is a "hybrid" network because it accepts two distinct modalities
//! of input simultaneously:
//!
//! 1. **Visual Data**: A stack of grayscale emulator frames processed by Convolutional
//!    Neural Network (CNN) layers.
//! 2. **Numeric Features**: Extracted RAM values (like player speed, coordinates)
//!    processed by dense linear layers.
//!
//! These two modalities are concatenated together into a single "trunk" representation.
//!
//! It is a "Policy-Value" network because it produces two outputs:
//!
//! 1. **Policy (Actor)**: A probability distribution across all possible controller actions.
//! 2. **Value (Critic)**: An estimate of the expected future reward from the current state.

use burn_core as burn;
use burn_core::prelude::{Backend, Config, Module, Tensor};
use burn_nn::{
    Linear, LinearConfig, Relu,
    conv::{Conv2d, Conv2dConfig},
    pool::{AdaptiveAvgPool2d, AdaptiveAvgPool2dConfig},
};

use crate::{config::MIN_OBSERVATION_DIM, env::ObservationSnapshot};

/// Configuration parameters for initializing a `HybridPolicyValueNet`.
#[derive(Config, Debug)]
pub struct HybridPolicyValueConfig {
    /// The number of sequential grayscale frames bundled into a single observation.
    pub frame_stack: usize,
    /// The length of the numeric feature vector (e.g., extracted RAM values).
    pub feature_count: usize,
    /// The total number of discrete controller actions the network can output.
    pub action_count: usize,
    /// The horizontal resolution of the downsampled grayscale input frame.
    #[config(default = "84")]
    pub observation_width: usize,
    /// The vertical resolution of the downsampled grayscale input frame.
    #[config(default = "84")]
    pub observation_height: usize,
}

impl HybridPolicyValueConfig {
    /// Creates a new configuration builder using the dimensions from a captured observation.
    #[must_use]
    pub fn from_observation(observation: &ObservationSnapshot, action_count: usize) -> Self {
        Self::new(
            observation.frame_stack,
            observation.features.len(),
            action_count,
        )
        .with_observation_width(observation.width)
        .with_observation_height(observation.height)
    }

    /// Initializes the actual neural network module on the specified backend device.
    #[must_use]
    pub fn init<B: Backend>(&self, device: &B::Device) -> HybridPolicyValueNet<B> {
        self.validate();
        HybridPolicyValueNet::new(device, self)
    }

    fn validate(&self) {
        assert!(
            self.frame_stack > 0,
            "frame_stack must be greater than zero"
        );
        assert!(
            self.feature_count > 0,
            "feature_count must be greater than zero"
        );
        assert!(
            self.action_count > 0,
            "action_count must be greater than zero"
        );
        assert!(
            self.observation_width >= MIN_OBSERVATION_DIM,
            "observation width must be at least {MIN_OBSERVATION_DIM} pixels"
        );
        assert!(
            self.observation_height >= MIN_OBSERVATION_DIM,
            "observation height must be at least {MIN_OBSERVATION_DIM} pixels"
        );
    }
}

/// A bundled batch of input data for the hybrid network.
#[derive(Debug)]
pub struct HybridObservationBatch<B: Backend> {
    /// The visual pixel data. Shape: `[batch_size, frame_stack, height, width]`.
    pub frames: Tensor<B, 4>,
    /// The numeric RAM-extracted features. Shape: `[batch_size, feature_count]`.
    pub features: Tensor<B, 2>,
}

/// The paired outputs returned from a forward pass of the hybrid network.
#[derive(Debug)]
pub struct HybridPolicyValueOutput<B: Backend> {
    /// The unnormalized action probabilities. Shape: `[batch_size, action_count]`.
    pub policy_logits: Tensor<B, 2>,
    /// The estimated future reward value. Shape: `[batch_size, 1]`.
    pub value: Tensor<B, 2>,
}

/// The core neural network architecture combining CNN vision and dense feature processing.
#[derive(Module, Debug)]
pub struct HybridPolicyValueNet<B: Backend> {
    conv1: Conv2d<B>,
    conv2: Conv2d<B>,
    pool: AdaptiveAvgPool2d,
    activation: Relu,
    feature_proj: Linear<B>,
    trunk: Linear<B>,
    policy_head: Linear<B>,
    value_head: Linear<B>,
}

impl<B: Backend> HybridPolicyValueNet<B> {
    /// Constructs the layers of the hybrid network.
    #[must_use]
    pub fn new(device: &B::Device, cfg: &HybridPolicyValueConfig) -> Self {
        let conv1 = Conv2dConfig::new([cfg.frame_stack, 16], [8, 8])
            .with_stride([4, 4])
            .init(device);
        let conv2 = Conv2dConfig::new([16, 32], [4, 4])
            .with_stride([2, 2])
            .init(device);
        let pool = AdaptiveAvgPool2dConfig::new([1, 1]).init();
        let feature_proj = LinearConfig::new(cfg.feature_count, 32).init(device);
        let trunk = LinearConfig::new(64, 64).init(device);
        let policy_head = LinearConfig::new(64, cfg.action_count).init(device);
        let value_head = LinearConfig::new(64, 1).init(device);

        Self {
            conv1,
            conv2,
            pool,
            activation: Relu::new(),
            feature_proj,
            trunk,
            policy_head,
            value_head,
        }
    }

    /// Executes a forward pass of the network, transforming an observation batch
    /// into action probabilities (policy) and a state estimate (value).
    #[must_use]
    pub fn forward(&self, batch: HybridObservationBatch<B>) -> HybridPolicyValueOutput<B> {
        let vision = self.activation.forward(self.conv1.forward(batch.frames));
        let vision = self.activation.forward(self.conv2.forward(vision));
        let vision: Tensor<B, 2> = self.pool.forward(vision).flatten(1, 3);

        let features = self
            .activation
            .forward(self.feature_proj.forward(batch.features));
        let joined = Tensor::cat(vec![vision, features], 1);
        let trunk = self.activation.forward(self.trunk.forward(joined));

        HybridPolicyValueOutput {
            policy_logits: self.policy_head.forward(trunk.clone()),
            value: self.value_head.forward(trunk),
        }
    }
}

use std::collections::VecDeque;

use nes_core::{FRAME_HEIGHT, FRAME_WIDTH};

/// Converts the NES RGBA framebuffer into a grayscale image at the requested size.
///
/// # Panics
///
/// Panics if `width` or `height` is zero, or if `rgba` does not match the
/// expected NES framebuffer size.
#[must_use]
pub fn downsample_grayscale(rgba: &[u8], width: usize, height: usize) -> Vec<f32> {
    assert!(width > 0, "downsample width must be greater than zero");
    assert!(height > 0, "downsample height must be greater than zero");

    let expected_len = FRAME_WIDTH * FRAME_HEIGHT * 4;
    assert_eq!(
        rgba.len(),
        expected_len,
        "rgba buffer must match the NES framebuffer size"
    );

    let mut out = vec![0.0; width * height];
    for y in 0..height {
        for x in 0..width {
            let src_x = x * FRAME_WIDTH / width;
            let src_y = y * FRAME_HEIGHT / height;
            let idx = (src_y * FRAME_WIDTH + src_x) * 4;
            let r = f32::from(rgba[idx]);
            let g = f32::from(rgba[idx + 1]);
            let b = f32::from(rgba[idx + 2]);
            out[y * width + x] = (0.299 * r + 0.587 * g + 0.114 * b) / 255.0;
        }
    }
    out
}

/// A sliding window of historical emulator frames.
///
/// In Reinforcement Learning, a single static frame of gameplay is often insufficient
/// to determine velocity or direction (e.g., is Mario moving left or right?).
/// By stacking multiple consecutive frames together, the network can implicitly learn motion.
#[derive(Debug, Clone)]
pub struct FrameStack {
    max_frames: usize,
    frame_len: usize,
    frames: VecDeque<Vec<f32>>,
}

impl FrameStack {
    /// Creates a bounded frame stack with a fixed per-frame element count.
    ///
    /// # Panics
    ///
    /// Panics if `max_frames` or `frame_len` is zero.
    #[must_use]
    pub fn new(max_frames: usize, frame_len: usize) -> Self {
        assert!(max_frames > 0, "frame stack must keep at least one frame");
        assert!(frame_len > 0, "frame length must be greater than zero");
        Self {
            max_frames,
            frame_len,
            frames: VecDeque::new(),
        }
    }

    /// Pushes one preprocessed frame into the stack, evicting the oldest frame if full.
    ///
    /// # Panics
    ///
    /// Panics if `frame.len()` does not match the configured frame length.
    pub fn push(&mut self, frame: Vec<f32>) {
        assert_eq!(frame.len(), self.frame_len);
        if self.frames.len() == self.max_frames {
            self.frames.pop_front();
        }
        self.frames.push_back(frame);
    }

    /// Returns references to the underlying frames in the stack.
    #[must_use]
    pub fn as_slices(&self) -> Vec<&[f32]> {
        self.frames.iter().map(Vec::as_slice).collect()
    }

    /// Copies and flattens all frames in the stack into a single contiguous vector.
    /// This is typically used to prepare the visual data for tensor creation.
    #[must_use]
    pub fn flattened(&self) -> Vec<f32> {
        let mut out = Vec::with_capacity(self.frames.len() * self.frame_len);
        for frame in &self.frames {
            out.extend_from_slice(frame);
        }
        out
    }
}

use nes_core::NesCore;

use crate::config::AiProfileConfig;

/// Defines the necessary operations for extracting and evaluating features
/// from the emulator state to power AI training loops.
///
/// We can't just feed raw 64KB memory dumps to our AI model. It would never converge.
/// By implementing `TaskProfile`, you provide a "lens" for the AI, allowing it to
/// see only the specific variables that matter for the task (like player X/Y coords).
pub trait TaskProfile {
    /// The strongly-typed intermediate representation of the extracted RAM variables.
    type Features: Clone + PartialEq + core::fmt::Debug;

    /// Returns the static training configuration profile for this task.
    fn config(&self) -> &AiProfileConfig;
    /// Inspects the emulator RAM and computes the strongly-typed feature set.
    fn decode_features(&self, core: &NesCore) -> Self::Features;
    /// Transforms the strongly-typed features into a normalized float array for network ingestion.
    fn encode_features(&self, features: &Self::Features) -> Vec<f32>;
    /// Returns the exact length of the vector produced by `encode_features`.
    fn feature_count(&self) -> usize;
}

//! Implementations of specific training tasks mapped to individual NES games.
/// Training environment and logic specifically for Super Mario Bros.
pub mod smb;

use nes_core::NesCore;

use crate::{config::AiProfileConfig, profile::TaskProfile};

/// The internal RAM variables extracted from Super Mario Bros. that are fed to the AI.
#[derive(Debug, Clone, PartialEq)]
pub struct SmbFeatures {
    /// The player's X coordinate representing horizontal progression through the level.
    pub level_progress: f32,
    /// The player's current horizontal sub-pixel speed velocity.
    pub horizontal_speed: f32,
    /// The player's current vertical sub-pixel speed velocity.
    pub vertical_speed: f32,
    /// Boolean flag indicating if Mario is currently jumping or falling.
    pub airborne: bool,
    /// The internal state machine enum value for the player (e.g. dying, entering pipe).
    pub player_state: u8,
    /// The remaining lives. Used heavily by the reward function to penalize death.
    pub lives: u8,
}

/// The implementation of `TaskProfile` specialized for training on Super Mario Bros.
#[derive(Debug, Clone)]
pub struct SmbProfile {
    config: AiProfileConfig,
}

impl SmbProfile {
    /// Creates a new profile runner for the SMB1 training task.
    #[must_use]
    pub fn new(config: AiProfileConfig) -> Self {
        Self { config }
    }
}

impl TaskProfile for SmbProfile {
    type Features = SmbFeatures;

    fn config(&self) -> &AiProfileConfig {
        &self.config
    }

    fn decode_features(&self, core: &NesCore) -> Self::Features {
        SmbFeatures {
            level_progress: f32::from(core.read_memory(0x006D)) * 256.0
                + f32::from(core.read_memory(0x0086)),
            horizontal_speed: f32::from(decode_signed_byte(core.read_memory(0x0057))),
            vertical_speed: f32::from(decode_signed_byte(core.read_memory(0x009F))),
            airborne: core.read_memory(0x001D) != 0,
            player_state: core.read_memory(0x000E),
            lives: core.read_memory(0x075A),
        }
    }

    fn encode_features(&self, features: &Self::Features) -> Vec<f32> {
        vec![
            features.level_progress / 4_096.0,
            features.horizontal_speed / 16.0,
            features.vertical_speed / 16.0,
            if features.airborne { 1.0 } else { 0.0 },
            f32::from(features.player_state) / 16.0,
            f32::from(features.lives) / 10.0,
        ]
    }

    fn feature_count(&self) -> usize {
        6
    }
}

fn decode_signed_byte(value: u8) -> i16 {
    if value < 0x80 {
        i16::from(value)
    } else {
        i16::from(value) - 0x100
    }
}

#[cfg(test)]
mod tests {
    use super::decode_signed_byte;

    #[test]
    fn decode_signed_byte_handles_twos_complement_values() {
        assert_eq!(decode_signed_byte(0x00), 0);
        assert_eq!(decode_signed_byte(0x7F), 127);
        assert_eq!(decode_signed_byte(0x80), -128);
        assert_eq!(decode_signed_byte(0xFF), -1);
    }
}

use crate::{config::RewardConfig, profiles::smb::SmbFeatures};

/// Specifies common indicators required for computing scalar AI rewards.
///
/// AI models operate on "carrots" and "sticks." This trait extracts the metrics
/// (like `level_progress`, player `lives`) we need to compute the scalar reward
/// at the end of every step.
pub trait RewardFeatures {
    /// Returns a scalar value indicating the player's progress through the current level.
    fn level_progress(&self) -> f32;
    /// Returns the player's state (e.g. alive, dying, dead).
    fn player_state(&self) -> u8;
    /// Returns the number of lives the player has remaining.
    fn lives(&self) -> u8;
}

impl RewardFeatures for SmbFeatures {
    fn level_progress(&self) -> f32 {
        self.level_progress
    }

    fn player_state(&self) -> u8 {
        self.player_state
    }

    fn lives(&self) -> u8 {
        self.lives
    }
}

/// Breakdown of the reward calculation for a single step.
#[derive(Debug, Clone, PartialEq)]
pub struct RewardBreakdown {
    /// The total computed reward for this step.
    pub total: f32,
    /// The reward or penalty associated with level progress.
    pub progress_delta: f32,
    /// The bonus reward for simply remaining alive during this step.
    pub alive_bonus: f32,
    /// The penalty applied if the player has stalled for too many frames.
    pub stall_penalty: f32,
    /// The penalty applied if the player died during this step.
    pub death_penalty: f32,
    /// Whether the episode should be considered terminal (e.g. death).
    pub done: bool,
}

/// A model for computing rewards during RL training.
///
/// The `RewardModel` takes in a [`RewardConfig`] and is responsible for calculating
/// the scalar reward value given the `prev` and `next` state features, along with
/// any frame stalling information.
///
/// ## Examples
/// ```
/// use nes_ai::reward::RewardModel;
/// use nes_ai::config::RewardConfig;
///
/// let cfg = RewardConfig {
///     forward_progress: 1.0,
///     alive_bonus: 0.1,
///     stall_frames: 600,
///     stall_penalty: -1.0,
///     death_penalty: -5.0,
/// };
/// let model = RewardModel::new(cfg);
/// ```
#[derive(Debug, Clone)]
pub struct RewardModel {
    cfg: RewardConfig,
}

impl RewardModel {
    /// Creates a new `RewardModel` with the given configuration.
    #[must_use]
    pub fn new(cfg: RewardConfig) -> Self {
        Self { cfg }
    }

    /// Computes the reward for a single simulation step.
    #[must_use]
    pub fn score<F: RewardFeatures>(
        &self,
        prev: &F,
        next: &F,
        stalled_frames: u32,
    ) -> RewardBreakdown {
        let done = matches!(next.player_state(), 0x06 | 0x0B) || next.lives() < prev.lives();
        let progress_delta = if done {
            0.0
        } else {
            (next.level_progress() - prev.level_progress()) * self.cfg.forward_progress
        };
        let alive_bonus = if done { 0.0 } else { self.cfg.alive_bonus };
        let stall_penalty = if stalled_frames >= self.cfg.stall_frames {
            self.cfg.stall_penalty
        } else {
            0.0
        };
        let death_penalty = if done { self.cfg.death_penalty } else { 0.0 };

        RewardBreakdown {
            total: progress_delta + alive_bonus + stall_penalty + death_penalty,
            progress_delta,
            alive_bonus,
            stall_penalty,
            death_penalty,
            done,
        }
    }
}

