trait TrainerEnv {
    fn reset_env(&mut self) -> Result<ObservationSnapshot, AiError>;
    fn step_env(&mut self, action: ControlAction) -> Result<TrainerStep, AiError>;
    fn finish_episode_meta(&self, total_reward: f32) -> EpisodeMetadata;
    fn recorded_movie(&self) -> &TasMovie;
}

impl<P> TrainerEnv for ProfileEnv<P>
where
    P: TaskProfile,
    P::Features: RewardFeatures,
{
    fn reset_env(&mut self) -> Result<ObservationSnapshot, AiError> {
        self.reset()?;
        self.observation()
    }

    fn step_env(&mut self, action: ControlAction) -> Result<TrainerStep, AiError> {
        let step = self.step(action)?;
        Ok(TrainerStep {
            observation: self.observation()?,
            reward_total: step.reward.total,
            done: step.done,
        })
    }

    fn finish_episode_meta(&self, total_reward: f32) -> EpisodeMetadata {
        self.finish_episode(total_reward)
    }

    fn recorded_movie(&self) -> &TasMovie {
        self.recorded_movie()
    }
}

impl TrainerEnv for AnyControlEnv {
    fn reset_env(&mut self) -> Result<ObservationSnapshot, AiError> {
        self.reset()?;
        self.observation()
    }

    fn step_env(&mut self, action: ControlAction) -> Result<TrainerStep, AiError> {
        let step = self.step(action)?;
        Ok(TrainerStep {
            observation: self.observation()?,
            reward_total: step.reward.total,
            done: step.done,
        })
    }

    fn finish_episode_meta(&self, total_reward: f32) -> EpisodeMetadata {
        AnyControlEnv::finish_episode(self, total_reward)
    }

    fn recorded_movie(&self) -> &TasMovie {
        AnyControlEnv::recorded_movie(self)
    }
}

#[derive(Debug, Clone)]
struct SmokeEnv {
    recorder: TasRecorder,
    frame_stack: FrameStack,
    episode_frames: u32,
    done: bool,
    position: f32,
    velocity: f32,
    last_gain: f32,
}

impl SmokeEnv {
    fn new() -> Self {
        Self {
            recorder: TasRecorder::new(),
            frame_stack: FrameStack::new(
                SMOKE_FRAME_STACK,
                SMOKE_OBSERVATION_WIDTH * SMOKE_OBSERVATION_HEIGHT,
            ),
            episode_frames: 0,
            done: false,
            position: 0.0,
            velocity: 0.0,
            last_gain: 0.0,
        }
    }

    fn observation(&self) -> ObservationSnapshot {
        ObservationSnapshot {
            frame_stack: SMOKE_FRAME_STACK,
            width: SMOKE_OBSERVATION_WIDTH,
            height: SMOKE_OBSERVATION_HEIGHT,
            frames: self.frame_stack.flattened(),
            features: vec![
                self.position / 64.0,
                self.velocity / 4.0,
                self.last_gain,
                u32_to_f32(self.episode_frames) / u32_to_f32(SMOKE_MAX_EPISODE_FRAMES),
                if self.done { 1.0 } else { 0.0 },
                1.0,
            ],
        }
    }

    fn push_rendered_frame(&mut self) {
        self.frame_stack.push(self.render_frame());
    }

    fn render_frame(&self) -> Vec<f32> {
        let mut frame = vec![0.0; SMOKE_OBSERVATION_WIDTH * SMOKE_OBSERVATION_HEIGHT];
        let column = quantize_to_index(self.position, SMOKE_OBSERVATION_WIDTH - 1);
        for row in 0..SMOKE_OBSERVATION_HEIGHT {
            frame[row * SMOKE_OBSERVATION_WIDTH + column] = 1.0;
        }

        let velocity_column =
            quantize_to_index(self.velocity.abs() * 8.0, SMOKE_OBSERVATION_WIDTH - 1);
        frame[(SMOKE_OBSERVATION_HEIGHT - 1) * SMOKE_OBSERVATION_WIDTH + velocity_column] = 0.5;
        frame
    }

    fn final_state_hash(&self) -> u64 {
        u64::from(self.episode_frames)
            ^ u64::from(self.position.to_bits())
            ^ (u64::from(self.velocity.to_bits()) << 1)
    }
}

impl TrainerEnv for SmokeEnv {
    fn reset_env(&mut self) -> Result<ObservationSnapshot, AiError> {
        self.recorder = TasRecorder::new();
        self.recorder.start();
        self.frame_stack = FrameStack::new(
            SMOKE_FRAME_STACK,
            SMOKE_OBSERVATION_WIDTH * SMOKE_OBSERVATION_HEIGHT,
        );
        self.episode_frames = 0;
        self.done = false;
        self.position = 0.0;
        self.velocity = 0.0;
        self.last_gain = 0.0;
        for _ in 0..SMOKE_FRAME_STACK {
            self.push_rendered_frame();
        }
        Ok(self.observation())
    }

    fn step_env(&mut self, action: ControlAction) -> Result<TrainerStep, AiError> {
        if self.done {
            return Err(AiError::Unsupported("step after episode done"));
        }

        self.recorder.record_frame(action.controller1_bits());
        self.episode_frames = self.episode_frames.saturating_add(1);
        let gain = SMOKE_ACTION_GAINS[action_index(action)];
        self.velocity = (self.velocity * 0.35) + gain;
        self.position += self.velocity;
        self.last_gain = gain;
        self.done = self.episode_frames >= SMOKE_MAX_EPISODE_FRAMES;
        self.push_rendered_frame();

        let reward = if matches!(action, ControlAction::Noop) {
            -0.15
        } else {
            gain
        };

        Ok(TrainerStep {
            observation: self.observation(),
            reward_total: reward,
            done: self.done,
        })
    }

    fn finish_episode_meta(&self, total_reward: f32) -> EpisodeMetadata {
        EpisodeMetadata {
            profile_id: "smoke-control".to_owned(),
            snapshot_id: "smoke-v1".to_owned(),
            rom_hash: "mock".to_owned(),
            total_reward,
            episode_frames: u64::from(self.episode_frames),
            final_state_hash: self.final_state_hash(),
        }
    }

    fn recorded_movie(&self) -> &TasMovie {
        self.recorder.movie()
    }
}

/// Evaluates a uniform random policy against the smoke environment.
///
/// # Errors
///
/// Returns [`AiError::Unsupported`] when `episodes` is zero or the trainer
/// configuration is internally inconsistent.
pub fn evaluate_random_policy(
    cfg: &TrainerConfig,
    episodes: usize,
) -> Result<EvalSummary, AiError> {
    validate_request(cfg, episodes)?;
    evaluate_random_with_factory(cfg, episodes, || Ok(SmokeEnv::new()))
}

/// Runs PPO training against the deterministic smoke environment.
///
/// # Errors
///
/// Returns [`AiError`] if the trainer configuration is invalid, checkpoint
/// writing fails, or evaluation artifacts cannot be emitted.
pub fn run_mock_ppo_smoke(cfg: &TrainerConfig, episodes: usize) -> Result<TrainSummary, AiError> {
    validate_request(cfg, episodes)?;
    train_with_factory(cfg, episodes, || Ok(SmokeEnv::new()))
}

/// Runs PPO training against the SMB control profile.
///
/// # Errors
///
/// Returns [`AiError`] if the profile cannot be loaded, training fails, or
/// checkpoint/artifact emission fails.
pub fn train_control_profile(
    profile_cfg: &AiProfileConfig,
    cfg: &TrainerConfig,
    episodes: usize,
) -> Result<TrainSummary, AiError> {
    validate_request(cfg, episodes)?;
    let profile_cfg = profile_cfg.clone();
    train_with_factory(cfg, episodes, move || {
        AnyControlEnv::from_config(profile_cfg.clone())
    })
}

/// Runs PPO training against the SMB control profile.
///
/// # Errors
///
/// Returns [`AiError`] if `profile_cfg` is not an SMB profile, the profile
/// cannot be loaded, training fails, or checkpoint/artifact emission fails.
pub fn train_smb_control(
    profile_cfg: &AiProfileConfig,
    cfg: &TrainerConfig,
    episodes: usize,
) -> Result<TrainSummary, AiError> {
    if profile_cfg.game != GameProfileId::Smb {
        return Err(AiError::Unsupported(
            "train_smb_control requires game = \"smb\"",
        ));
    }
    train_control_profile(profile_cfg, cfg, episodes)
}

/// Evaluates a configured control profile either from a saved checkpoint or with a random baseline.
///
/// # Errors
///
/// Returns [`AiError`] if the profile cannot be loaded, the checkpoint cannot be
/// loaded, or evaluation artifacts cannot be emitted.
pub fn evaluate_control_profile(
    profile_cfg: &AiProfileConfig,
    cfg: &TrainerConfig,
    episodes: usize,
    checkpoint_base: Option<&Path>,
) -> Result<EvalSummary, AiError> {
    validate_request(cfg, episodes)?;
    let profile_cfg_for_eval = profile_cfg.clone();
    let make_env = move || AnyControlEnv::from_config(profile_cfg_for_eval.clone());

    match checkpoint_base {
        Some(checkpoint_base) => {
            let mut env = make_env()?;
            let observation = env.reset_env()?;
            let model_cfg = HybridPolicyValueConfig::from_observation(
                &observation,
                ControlAction::action_count(),
            );
            let device = <InferBackend as Backend>::Device::default();
            let recorder = DefaultRecorder::new();
            let checkpoint_base = checkpoint_base_path(checkpoint_base);
            let model = model_cfg
                .init::<InferBackend>(&device)
                .load_file(checkpoint_base.clone(), &recorder, &device)
                .map_err(|source| AiError::CheckpointLoad {
                    path: checkpoint_file_path(&checkpoint_base),
                    source,
                })?;
            evaluate_model_with_factory(cfg, episodes, &model, make_env)
        }
        None => evaluate_random_with_factory(cfg, episodes, make_env),
    }
}

/// Evaluates SMB control either from a saved checkpoint or with a random baseline.
///
/// # Errors
///
/// Returns [`AiError`] if `profile_cfg` is not an SMB profile, the profile
/// cannot be loaded, the checkpoint cannot be loaded, or evaluation artifacts
/// cannot be emitted.
pub fn evaluate_smb_control(
    profile_cfg: &AiProfileConfig,
    cfg: &TrainerConfig,
    episodes: usize,
    checkpoint_base: Option<&Path>,
) -> Result<EvalSummary, AiError> {
    if profile_cfg.game != GameProfileId::Smb {
        return Err(AiError::Unsupported(
            "evaluate_smb_control requires game = \"smb\"",
        ));
    }
    evaluate_control_profile(profile_cfg, cfg, episodes, checkpoint_base)
}

/// Parses a CLI action label into the discrete control action space.
///
/// # Errors
///
/// Returns [`AiError::Unsupported`] when `value` does not map to a known
/// control action label.
pub fn action_from_arg(value: &str) -> Result<ControlAction, AiError> {
    match value {
        "noop" => Ok(ControlAction::Noop),
        "right" => Ok(ControlAction::Right),
        "right-a" => Ok(ControlAction::RightA),
        "a" => Ok(ControlAction::A),
        "right-b" => Ok(ControlAction::RightB),
        "right-a-b" => Ok(ControlAction::RightAB),
        _ => Err(AiError::Unsupported("unknown action")),
    }
}

fn train_with_factory<E, F>(
    cfg: &TrainerConfig,
    episodes: usize,
    make_env: F,
) -> Result<TrainSummary, AiError>
where
    E: TrainerEnv,
    F: Fn() -> Result<E, AiError>,
{
    let device = <TrainBackend as Backend>::Device::default();
    TrainBackend::seed(&device, cfg.seed);
    let mut rng = StdRng::seed_from_u64(cfg.seed);
    let mut env = make_env()?;
    let initial_observation = env.reset_env()?;
    let model_cfg = HybridPolicyValueConfig::from_observation(
        &initial_observation,
        ControlAction::action_count(),
    );
    let mut model = model_cfg.init::<TrainBackend>(&device);
    let mut checkpoint_paths = Vec::new();

    for update in 0..cfg.training_updates {
        let rollout = collect_rollout(cfg, &mut env, &model, &mut rng)?;
        model = ppo_update(cfg, model, &rollout, &mut rng);

        if cfg
            .checkpoint_dir
            .as_ref()
            .is_some_and(|_| (update + 1) % cfg.checkpoint_interval == 0)
        {
            checkpoint_paths.push(save_checkpoint(&model, cfg, update + 1)?);
        }
    }

    let infer_model = model.valid();
    let evaluation = evaluate_model_with_factory(cfg, episodes, &infer_model, make_env)?;

    Ok(TrainSummary {
        average_return: evaluation.average_return,
        checkpoint_paths,
        artifact_paths: evaluation.artifact_paths,
    })
}

fn evaluate_random_with_factory<E, F>(
    cfg: &TrainerConfig,
    episodes: usize,
    make_env: F,
) -> Result<EvalSummary, AiError>
where
    E: TrainerEnv,
    F: Fn() -> Result<E, AiError>,
{
    let mut rng = StdRng::seed_from_u64(cfg.seed ^ 0x5EED_F00D);
    let writer = cfg.artifact_dir.clone().map(EpisodeArtifactWriter::new);
    let mut env = make_env()?;
    let mut returns = Vec::with_capacity(episodes);
    let mut artifact_paths = Vec::new();

    for episode_index in 0..episodes {
        let mut total_reward = 0.0;
        let _ = env.reset_env()?;
        loop {
            let action = action_from_index(rng.gen_range(0..ControlAction::action_count()));
            let step = env.step_env(action)?;
            total_reward += step.reward_total;
            if step.done {
                break;
            }
        }

        returns.push(total_reward);
        if let Some(writer) = &writer {
            let prefix = format!("eval-ep{episode_index:04}");
            let meta = env.finish_episode_meta(total_reward);
            artifact_paths.push(writer.write(&prefix, env.recorded_movie(), &meta)?);
        }
    }

    Ok(EvalSummary {
        average_return: mean_f32(&returns),
        artifact_paths,
    })
}

fn evaluate_model_with_factory<E, F>(
    cfg: &TrainerConfig,
    episodes: usize,
    model: &HybridPolicyValueNet<InferBackend>,
    make_env: F,
) -> Result<EvalSummary, AiError>
where
    E: TrainerEnv,
    F: Fn() -> Result<E, AiError>,
{
    let writer = cfg.artifact_dir.clone().map(EpisodeArtifactWriter::new);
    let mut env = make_env()?;
    let mut returns = Vec::with_capacity(episodes);
    let mut artifact_paths = Vec::new();

    for episode_index in 0..episodes {
        let mut total_reward = 0.0;
        let mut observation = env.reset_env()?;
        loop {
            let decision = greedy_policy_decision(model, &observation);
            let step = env.step_env(action_from_index(decision.action_index))?;
            total_reward += step.reward_total;
            if step.done {
                break;
            }
            observation = step.observation;
        }

        returns.push(total_reward);
        if let Some(writer) = &writer {
            let prefix = format!("eval-ep{episode_index:04}");
            let meta = env.finish_episode_meta(total_reward);
            artifact_paths.push(writer.write(&prefix, env.recorded_movie(), &meta)?);
        }
    }

    Ok(EvalSummary {
        average_return: mean_f32(&returns),
        artifact_paths,
    })
}

fn collect_rollout<E: TrainerEnv>(
    cfg: &TrainerConfig,
    env: &mut E,
    model: &HybridPolicyValueNet<TrainBackend>,
    rng: &mut StdRng,
) -> Result<Vec<PpoSample>, AiError> {
    let infer_model = model.valid();
    let mut observation = env.reset_env()?;
    let mut transitions = Vec::with_capacity(cfg.rollout_steps);

    for _ in 0..cfg.rollout_steps {
        let decision = sampled_policy_decision(&infer_model, &observation, rng);
        let step = env.step_env(action_from_index(decision.action_index))?;
        transitions.push(RolloutTransition {
            observation: observation.clone(),
            action_index: decision.action_index,
            reward: step.reward_total,
            done: step.done,
            value: decision.value,
            log_prob: decision.log_prob,
        });

        observation = if step.done {
            env.reset_env()?
        } else {
            step.observation
        };
    }

    let bootstrap_value = transitions.last().map_or(0.0, |transition| {
        if transition.done {
            0.0
        } else {
            greedy_policy_decision(&infer_model, &observation).value
        }
    });

    let (advantages, returns) = compute_gae(
        &transitions,
        bootstrap_value,
        cfg.discount_gamma,
        cfg.gae_lambda,
    );
    let mut samples = transitions
        .into_iter()
        .zip(advantages)
        .zip(returns)
        .map(|((transition, advantage), return_estimate)| PpoSample {
            observation: transition.observation,
            action_index: transition.action_index,
            old_log_prob: transition.log_prob,
            advantage,
            return_estimate,
        })
        .collect::<Vec<_>>();
    normalize_advantages(&mut samples);

    Ok(samples)
}

fn compute_gae(
    transitions: &[RolloutTransition],
    bootstrap_value: f32,
    gamma: f32,
    lambda: f32,
) -> (Vec<f32>, Vec<f32>) {
    let mut advantages = vec![0.0; transitions.len()];
    let mut returns = vec![0.0; transitions.len()];
    let mut gae = 0.0;

    for index in (0..transitions.len()).rev() {
        let non_terminal = if transitions[index].done { 0.0 } else { 1.0 };
        let next_value = if index + 1 == transitions.len() {
            bootstrap_value
        } else {
            transitions[index + 1].value
        };
        let delta = transitions[index].reward + gamma * next_value * non_terminal
            - transitions[index].value;
        gae = delta + gamma * lambda * non_terminal * gae;
        advantages[index] = gae;
        returns[index] = gae + transitions[index].value;
    }

    (advantages, returns)
}

fn normalize_advantages(samples: &mut [PpoSample]) {
    if samples.is_empty() {
        return;
    }

    let count = usize_to_f32(samples.len());
    let mean = samples.iter().map(|sample| sample.advantage).sum::<f32>() / count;
    let variance = samples
        .iter()
        .map(|sample| {
            let centered = sample.advantage - mean;
            centered * centered
        })
        .sum::<f32>()
        / count;
    let stddev = variance.sqrt();
    if stddev <= f32::EPSILON {
        return;
    }

    for sample in samples {
        sample.advantage = (sample.advantage - mean) / stddev;
    }
}

fn ppo_update(
    cfg: &TrainerConfig,
    mut model: HybridPolicyValueNet<TrainBackend>,
    samples: &[PpoSample],
    rng: &mut StdRng,
) -> HybridPolicyValueNet<TrainBackend> {
    let device = <TrainBackend as Backend>::Device::default();
    let mut indices = (0..samples.len()).collect::<Vec<_>>();

    for _ in 0..cfg.epochs {
        indices.shuffle(rng);
        for chunk in indices.chunks(cfg.minibatch_size) {
            let batch = build_train_batch(samples, chunk, &device);
            let output = model.forward(batch.observations);
            let log_probs = log_softmax(output.policy_logits, 1);
            let selected_log_probs = log_probs.clone().gather(1, batch.action_indices);
            let ratios = (selected_log_probs - batch.old_log_probs).exp();
            let unclipped = ratios.clone() * batch.advantages.clone();
            let clipped =
                ratios.clamp(1.0 - cfg.clip_epsilon, 1.0 + cfg.clip_epsilon) * batch.advantages;
            let policy_loss = unclipped.min_pair(clipped).mean().mul_scalar(-1.0);
            let value_loss = (output.value - batch.returns).powf_scalar(2.0).mean();
            let entropy = (log_probs.clone().exp() * log_probs)
                .sum_dim(1)
                .mean()
                .mul_scalar(-1.0);
            let loss = policy_loss + value_loss.mul_scalar(cfg.value_loss_coefficient)
                - entropy.mul_scalar(cfg.entropy_coefficient);
            let mut grads = loss.backward();
            let mut optimizer = SgdStep {
                grads: &mut grads,
                learning_rate: cfg.learning_rate,
            };
            model = model.map(&mut optimizer);
        }
    }

    model
}

fn build_train_batch<B: Backend>(
    samples: &[PpoSample],
    indices: &[usize],
    device: &B::Device,
) -> TrainBatch<B> {
    let first = &samples[indices[0]].observation;
    let mut frames =
        Vec::with_capacity(indices.len() * first.frame_stack * first.width * first.height);
    let mut features = Vec::with_capacity(indices.len() * first.features.len());
    let mut action_indices = Vec::with_capacity(indices.len());
    let mut old_log_probs = Vec::with_capacity(indices.len());
    let mut advantages = Vec::with_capacity(indices.len());
    let mut returns = Vec::with_capacity(indices.len());

    for &index in indices {
        let sample = &samples[index];
        frames.extend_from_slice(&sample.observation.frames);
        features.extend_from_slice(&sample.observation.features);
        action_indices.push(i64::try_from(sample.action_index).unwrap_or(0));
        old_log_probs.push(sample.old_log_prob);
        advantages.push(sample.advantage);
        returns.push(sample.return_estimate);
    }

    let batch_size = indices.len();
    TrainBatch {
        observations: HybridObservationBatch {
            frames: Tensor::<B, 4>::from_data(
                TensorData::new(
                    frames,
                    [batch_size, first.frame_stack, first.height, first.width],
                ),
                device,
            ),
            features: Tensor::<B, 2>::from_data(
                TensorData::new(features, [batch_size, first.features.len()]),
                device,
            ),
        },
        action_indices: Tensor::<B, 2, Int>::from_data(
            TensorData::new(action_indices, [batch_size, 1]),
            device,
        ),
        old_log_probs: Tensor::<B, 2>::from_data(
            TensorData::new(old_log_probs, [batch_size, 1]),
            device,
        ),
        advantages: Tensor::<B, 2>::from_data(TensorData::new(advantages, [batch_size, 1]), device),
        returns: Tensor::<B, 2>::from_data(TensorData::new(returns, [batch_size, 1]), device),
    }
}

fn save_checkpoint(
    model: &HybridPolicyValueNet<TrainBackend>,
    cfg: &TrainerConfig,
    update_index: usize,
) -> Result<PathBuf, AiError> {
    let Some(checkpoint_dir) = &cfg.checkpoint_dir else {
        return Err(AiError::Unsupported("checkpoint dir missing"));
    };

    let base_path = checkpoint_dir.join(format!("policy-update-{update_index:04}"));
    let recorder = DefaultRecorder::new();
    model
        .valid()
        .save_file(base_path.clone(), &recorder)
        .map_err(|source| AiError::CheckpointSave {
            path: checkpoint_file_path(&base_path),
            source,
        })?;
    Ok(base_path)
}

fn checkpoint_file_path(base_path: &Path) -> PathBuf {
    let mut path = base_path.to_path_buf();
    path.set_extension(<DefaultRecorder as FileRecorder<InferBackend>>::file_extension());
    path
}

fn checkpoint_base_path(path: &Path) -> PathBuf {
    let expected_extension = <DefaultRecorder as FileRecorder<InferBackend>>::file_extension();
    if path
        .extension()
        .is_some_and(|extension| extension == expected_extension)
    {
        let mut base = path.to_path_buf();
        let _ = base.set_extension("");
        return base;
    }
    path.to_path_buf()
}

fn greedy_policy_decision(
    model: &HybridPolicyValueNet<InferBackend>,
    observation: &ObservationSnapshot,
) -> PolicyDecision {
    let (logits, value) = forward_policy(model, observation);
    let probabilities = logits_to_probabilities(&logits);
    let action_index = argmax_index(&logits);

    PolicyDecision {
        action_index,
        log_prob: probabilities[action_index].max(f32::MIN_POSITIVE).ln(),
        value,
    }
}

fn sampled_policy_decision(
    model: &HybridPolicyValueNet<InferBackend>,
    observation: &ObservationSnapshot,
    rng: &mut StdRng,
) -> PolicyDecision {
    let (logits, value) = forward_policy(model, observation);
    let probabilities = logits_to_probabilities(&logits);
    let action_index = sample_from_probabilities(&probabilities, rng);

    PolicyDecision {
        action_index,
        log_prob: probabilities[action_index].max(f32::MIN_POSITIVE).ln(),
        value,
    }
}

fn forward_policy(
    model: &HybridPolicyValueNet<InferBackend>,
    observation: &ObservationSnapshot,
) -> (Vec<f32>, f32) {
    let device = <InferBackend as Backend>::Device::default();
    let batch = HybridObservationBatch {
        frames: Tensor::<InferBackend, 4>::from_data(
            TensorData::new(
                observation.frames.clone(),
                [
                    1,
                    observation.frame_stack,
                    observation.height,
                    observation.width,
                ],
            ),
            &device,
        ),
        features: Tensor::<InferBackend, 2>::from_data(
            TensorData::new(
                observation.features.clone(),
                [1, observation.features.len()],
            ),
            &device,
        ),
    };
    let output = model.forward(batch);
    let logits = output
        .policy_logits
        .into_data()
        .as_slice::<f32>()
        .map_or_else(|_| Vec::new(), ToOwned::to_owned);
    let value = output
        .value
        .into_data()
        .as_slice::<f32>()
        .ok()
        .and_then(|values| values.first().copied())
        .unwrap_or(0.0);

    (logits, value)
}

/// **Performance optimization:** Fuses exponential probability calculation and total summation into a single pass, avoiding the `.collect::<Vec<_>>()` allocation chain and eliminating an extra O(N) iteration over the dataset.
fn logits_to_probabilities(logits: &[f32]) -> Vec<f32> {
    let max_logit = logits.iter().copied().fold(f32::NEG_INFINITY, f32::max);
    let mut probabilities = Vec::with_capacity(logits.len());
    let mut total = 0.0;
    for &logit in logits {
        let prob = (logit - max_logit).exp();
        total += prob;
        probabilities.push(prob);
    }

    if total <= f32::EPSILON {
        return vec![1.0 / usize_to_f32(logits.len()); logits.len()];
    }
    for probability in &mut probabilities {
        *probability /= total;
    }
    probabilities
}

fn sample_from_probabilities(probabilities: &[f32], rng: &mut StdRng) -> usize {
    let target = rng.gen_range(0.0..1.0);
    let mut cumulative = 0.0;
    for (index, probability) in probabilities.iter().copied().enumerate() {
        cumulative += probability;
        if target <= cumulative {
            return index;
        }
    }
    probabilities.len().saturating_sub(1)
}

fn argmax_index(values: &[f32]) -> usize {
    values
        .iter()
        .copied()
        .enumerate()
        .max_by(|(_, left), (_, right)| left.total_cmp(right))
        .map_or(0, |(index, _)| index)
}

fn action_from_index(index: usize) -> ControlAction {
    match index {
        0 => ControlAction::Noop,
        1 => ControlAction::Right,
        2 => ControlAction::RightA,
        3 => ControlAction::A,
        4 => ControlAction::RightB,
        _ => ControlAction::RightAB,
    }
}

fn action_index(action: ControlAction) -> usize {
    match action {
        ControlAction::Noop => 0,
        ControlAction::Right => 1,
        ControlAction::RightA => 2,
        ControlAction::A => 3,
        ControlAction::RightB => 4,
        ControlAction::RightAB => 5,
    }
}

fn validate_request(cfg: &TrainerConfig, episodes: usize) -> Result<(), AiError> {
    if episodes == 0 {
        return Err(AiError::Unsupported("episodes must be greater than zero"));
    }
    if cfg.rollout_steps == 0 {
        return Err(AiError::Unsupported(
            "rollout_steps must be greater than zero",
        ));
    }
    if cfg.minibatch_size == 0 {
        return Err(AiError::Unsupported(
            "minibatch_size must be greater than zero",
        ));
    }
    if cfg.epochs == 0 {
        return Err(AiError::Unsupported("epochs must be greater than zero"));
    }
    if cfg.training_updates == 0 {
        return Err(AiError::Unsupported(
            "training_updates must be greater than zero",
        ));
    }
    if cfg.learning_rate <= 0.0 {
        return Err(AiError::Unsupported(
            "learning_rate must be greater than zero",
        ));
    }
    if !(0.0 < cfg.discount_gamma && cfg.discount_gamma <= 1.0) {
        return Err(AiError::Unsupported("discount_gamma must be within (0, 1]"));
    }
    if !(0.0 < cfg.gae_lambda && cfg.gae_lambda <= 1.0) {
        return Err(AiError::Unsupported("gae_lambda must be within (0, 1]"));
    }
    if cfg.clip_epsilon <= 0.0 {
        return Err(AiError::Unsupported(
            "clip_epsilon must be greater than zero",
        ));
    }
    if cfg.entropy_coefficient < 0.0 {
        return Err(AiError::Unsupported(
            "entropy_coefficient must be non-negative",
        ));
    }
    if cfg.value_loss_coefficient < 0.0 {
        return Err(AiError::Unsupported(
            "value_loss_coefficient must be non-negative",
        ));
    }
    if cfg.checkpoint_interval == 0 {
        return Err(AiError::Unsupported(
            "checkpoint_interval must be greater than zero",
        ));
    }

    Ok(())
}

fn mean_f32(values: &[f32]) -> f32 {
    if values.is_empty() {
        0.0
    } else {
        values.iter().sum::<f32>() / usize_to_f32(values.len())
    }
}

#[allow(
    clippy::cast_possible_truncation,
    clippy::cast_precision_loss,
    clippy::cast_sign_loss
)]
fn quantize_to_index(value: f32, max_index: usize) -> usize {
    value.max(0.0).min(max_index as f32).round() as usize
}

fn usize_to_f32(value: usize) -> f32 {
    let clamped = value.min(usize::from(u16::MAX));
    let clamped = u16::try_from(clamped).unwrap_or(u16::MAX);

    f32::from(clamped)
}

fn u32_to_f32(value: u32) -> f32 {
    let clamped = u16::try_from(value).unwrap_or(u16::MAX);

    f32::from(clamped)
}

struct SgdStep<'a, B: AutodiffBackend> {
    grads: &'a mut B::Gradients,
    learning_rate: f32,
}

impl<B: AutodiffBackend> ModuleMapper<B> for SgdStep<'_, B> {
    fn map_float<const D: usize>(&mut self, param: Param<Tensor<B, D>>) -> Param<Tensor<B, D>> {
        let Some(grad) = param.grad_remove(self.grads) else {
            return param;
        };
        let (id, tensor, mapper) = param.consume();
        let requires_grad = tensor.is_require_grad();
        let updated =
            Tensor::<B, D>::from_inner(tensor.inner() - grad.mul_scalar(self.learning_rate))
                .set_require_grad(requires_grad);

        Param::from_mapped_value(id, updated, mapper)
    }
}

//! Configuration loading and deserialization for the NES emulator workspace.
//!
//! This crate parses `nes.toml` files and CLI overrides into a strongly-typed [`NesConfig`] struct.

use std::fs;
use std::path::{Path, PathBuf};

use serde::Deserialize;

/// Default path to the configuration file.
pub const DEFAULT_CONFIG_PATH: &str = "nes.toml";

const DEFAULT_CPU_STEPS_PER_FRAME: u32 = 10_000;
const DEFAULT_WINDOW_SCALE: u32 = 3;
const DEFAULT_AUDIO_ENABLED: bool = true;
const DEFAULT_METRICS_ENABLED: bool = false;
const DEFAULT_METRICS_EVERY_FRAMES: u64 = 60;
const DEFAULT_TRACE_EVERY_FRAMES: u64 = 0;
const DEFAULT_CAPTURE_EVERY_FRAMES: u64 = 1;
const DEFAULT_NETPLAY_ENABLED: bool = false;
const DEFAULT_NETPLAY_RELAY_ADDR: &str = "127.0.0.1:4545";
const DEFAULT_NETPLAY_ROOM: &str = "default";
const DEFAULT_NETPLAY_PLAYER: u8 = 1;
const DEFAULT_NETPLAY_INPUT_DELAY_FRAMES: u32 = 2;
const DEFAULT_NETPLAY_MAX_ROLLBACK_FRAMES: u32 = 240;
const DEFAULT_NETPLAY_HASH_CHECK_EVERY_FRAMES: u64 = 120;

/// Execution granularity for the emulator loop.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize, Default)]
#[serde(rename_all = "snake_case")]
pub enum StepModeConfig {
    /// Step the emulator one CPU instruction at a time.
    Cpu,
    /// Step the emulator one full PPU frame at a time.
    #[default]
    Frame,
}

/// Runtime configuration for desktop and windowing features.
#[derive(Debug, Clone, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct DesktopConfig {
    /// Path to the ROM file to load on startup.
    pub rom_path: Option<String>,
    /// Multiplier for the native NES resolution.
    pub window_scale: u32,
    /// Emulator step granularity.
    pub step_mode: StepModeConfig,
    /// Fixed number of CPU steps to execute per frame when not syncing to PPU.
    pub cpu_steps_per_frame: u32,
    /// Toggles audio synthesis and playback.
    pub audio_enabled: bool,
    /// Interval (in frames) to emit CPU execution traces.
    pub trace_every_frames: u64,
    /// Toggles performance metrics collection.
    pub metrics_enabled: bool,
    /// Interval (in frames) to log metrics.
    pub metrics_every_frames: u64,
    /// Path template for saving audio captures.
    pub capture_path_template: Option<String>,
    /// Interval (in frames) for audio captures.
    pub capture_every_frames: u64,
}

impl Default for DesktopConfig {
    fn default() -> Self {
        Self {
            rom_path: None,
            window_scale: DEFAULT_WINDOW_SCALE,
            step_mode: StepModeConfig::Frame,
            cpu_steps_per_frame: DEFAULT_CPU_STEPS_PER_FRAME,
            audio_enabled: DEFAULT_AUDIO_ENABLED,
            trace_every_frames: DEFAULT_TRACE_EVERY_FRAMES,
            metrics_enabled: DEFAULT_METRICS_ENABLED,
            metrics_every_frames: DEFAULT_METRICS_EVERY_FRAMES,
            capture_path_template: None,
            capture_every_frames: DEFAULT_CAPTURE_EVERY_FRAMES,
        }
    }
}

/// File paths to ROM files used for testing and validation.
#[derive(Debug, Clone, Default, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct RomPathsConfig {
    /// Path to Super Mario Bros ROM.
    pub smb: Option<String>,
    /// Path to nestest ROM.
    pub nestest: Option<String>,
    /// Path to blargg CPU test ROM.
    pub blargg_cpu: Option<String>,
    /// Directory containing bbbradsmith audio suite ROMs.
    pub bbbradsmith_audio_suite_dir: Option<String>,
    /// Directory containing bbbradsmith audio suite golden references.
    pub bbbradsmith_audio_golden_dir: Option<String>,
}

/// Settings for rollback netcode and online multiplayer.
#[derive(Debug, Clone, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct NetplayConfig {
    /// Toggles netplay rollback engine.
    pub enabled: bool,
    /// Address of the netplay relay server.
    pub relay_addr: String,
    /// Netplay room name.
    pub room: String,
    /// Player index (1 or 2).
    pub player: u8,
    /// Fixed input delay added before executing local inputs.
    pub input_delay_frames: u32,
    /// Maximum allowed rollback window size.
    pub max_rollback_frames: u32,
    /// Interval (in frames) to perform state hash checks.
    pub hash_check_every_frames: u64,
}

impl Default for NetplayConfig {
    fn default() -> Self {
        Self {
            enabled: DEFAULT_NETPLAY_ENABLED,
            relay_addr: DEFAULT_NETPLAY_RELAY_ADDR.to_owned(),
            room: DEFAULT_NETPLAY_ROOM.to_owned(),
            player: DEFAULT_NETPLAY_PLAYER,
            input_delay_frames: DEFAULT_NETPLAY_INPUT_DELAY_FRAMES,
            max_rollback_frames: DEFAULT_NETPLAY_MAX_ROLLBACK_FRAMES,
            hash_check_every_frames: DEFAULT_NETPLAY_HASH_CHECK_EVERY_FRAMES,
        }
    }
}

/// Settings for the rewind and state history engine.
#[derive(Debug, Clone, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct TimeMachineConfig {
    /// Toggles time machine functionality.
    pub enabled: bool,
    /// Maximum history size in seconds.
    pub max_history_seconds: u32,
    /// Frames between full state keyframes.
    pub keyframe_base_interval: u64,
    /// Size threshold in bytes to force a keyframe instead of a delta.
    pub delta_spike_threshold: u32,
}

impl Default for TimeMachineConfig {
    fn default() -> Self {
        Self {
            enabled: true,
            max_history_seconds: 30,
            keyframe_base_interval: 60,
            delta_spike_threshold: 2048,
        }
    }
}

/// The root configuration object combining all sub-sections.
#[derive(Debug, Clone, Default, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct NesConfig {
    /// Desktop configuration.
    pub desktop: DesktopConfig,
    /// ROM paths configuration.
    pub roms: RomPathsConfig,
    /// Netplay configuration.
    pub netplay: NetplayConfig,
    /// Time machine configuration.
    pub time_machine: TimeMachineConfig,
}

impl NesConfig {
    /// Loads and parses a TOML configuration from the specified file path.
    ///
    /// # Examples
    /// ```no_run
    /// use nes_config::NesConfig;
    /// use std::path::Path;
    /// let config = NesConfig::load(Path::new("my_nes.toml")).unwrap();
    /// ```
    pub fn load(path: &Path) -> Result<Self, String> {
        let bytes = fs::read_to_string(path).map_err(|err| {
            if err.kind() == std::io::ErrorKind::NotFound {
                format!(
                    "failed to read config '{}': file not found. Hint: copy the example profile (e.g. cp nes.example.toml nes.toml)",
                    path.display()
                )
            } else {
                format!("failed to read config '{}': {err}", path.display())
            }
        })?;
        toml::from_str::<Self>(&bytes)
            .map_err(|err| format!("failed to parse config '{}': {err}", path.display()))
    }
    /// Loads a configuration from the given path if present, otherwise attempts to load from the default path or returns a default configuration.
    ///
    /// # Examples
    /// ```no_run
    /// use nes_config::NesConfig;
    /// let config = NesConfig::load_or_default(None).unwrap();
    /// ```
    pub fn load_or_default(path: Option<&Path>) -> Result<Self, String> {
        if let Some(config_path) = path {
            Self::load(config_path)
        } else {
            let default_path = Path::new(DEFAULT_CONFIG_PATH);
            if default_path.exists() {
                Self::load(default_path)
            } else {
                Ok(Self::default())
            }
        }
    }
}

/// Returns the value if it is non-zero, otherwise returns the fallback.
pub fn normalize_nonzero_u32(value: u32, fallback: u32) -> u32 {
    if value == 0 { fallback } else { value }
}

/// Returns the value if it is non-zero, otherwise returns the fallback.
pub fn normalize_nonzero_u64(value: u64, fallback: u64) -> u64 {
    if value == 0 { fallback } else { value }
}

/// Extracts the `--config` argument from a list of command-line arguments, returning the parsed path and the remaining arguments.
pub fn parse_config_path_arg(args: &[String]) -> Result<(Option<PathBuf>, Vec<String>), String> {
    let mut config_path = None::<PathBuf>;
    let mut pass_through = Vec::new();
    let mut idx = 0_usize;
    while idx < args.len() {
        let arg = &args[idx];
        if parse_arg(args, &mut idx, "--config", |value| {
            if value.starts_with("--") {
                return Err("missing value after --config".to_owned());
            }
            config_path = Some(PathBuf::from(value));
            Ok(())
        })? {
            continue;
        }
        pass_through.push(arg.clone());
        idx += 1;
    }
    Ok((config_path, pass_through))
}

fn parse_arg<F>(args: &[String], idx: &mut usize, flag: &str, mut apply: F) -> Result<bool, String>
where
    F: FnMut(&str) -> Result<(), String>,
{
    let arg = &args[*idx];
    if arg == flag {
        let Some(value) = args.get(*idx + 1) else {
            return Err(format!("missing value after {flag}"));
        };
        apply(value)?;
        *idx += 2;
        Ok(true)
    } else if let Some(value) = arg.strip_prefix(flag).and_then(|s| s.strip_prefix('=')) {
        if value.is_empty() {
            return Err(format!("missing value after {flag}="));
        }
        apply(value)?;
        *idx += 1;
        Ok(true)
    } else {
        Ok(false)
    }
}

#[cfg(test)]
mod tests {
    use std::fs;
    use std::path::PathBuf;

    use super::{NesConfig, normalize_nonzero_u32, normalize_nonzero_u64, parse_config_path_arg};

    fn temp_config_path(stem: &str) -> PathBuf {
        let nonce = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .expect("system clock should be after epoch")
            .as_nanos();
        std::env::temp_dir().join(format!("nes-config-{stem}-{nonce}.toml"))
    }

    fn write_temp_config(contents: &str, stem: &str) -> PathBuf {
        let path = temp_config_path(stem);
        fs::write(&path, contents).expect("should write temp config");
        path
    }

    fn remove_if_exists(path: &PathBuf) {
        if path.exists() {
            fs::remove_file(path).expect("should remove temp file");
        }
    }

    #[test]
    fn time_machine_config_has_sane_defaults() {
        let config = NesConfig::default();
        assert!(config.time_machine.enabled);
        assert_eq!(config.time_machine.max_history_seconds, 30);
        assert_eq!(config.time_machine.keyframe_base_interval, 60);
        assert_eq!(config.time_machine.delta_spike_threshold, 2048);
    }

    #[test]
    fn load_reads_non_default_values_from_file() {
        let path = write_temp_config(
            r#"
[desktop]
window_scale = 7
audio_enabled = false

[netplay]
enabled = true
room = "arena"
"#,
            "load-non-defaults",
        );
        let loaded = NesConfig::load(&path).expect("load should succeed");
        remove_if_exists(&path);

        assert_eq!(loaded.desktop.window_scale, 7);
        assert!(!loaded.desktop.audio_enabled);
        assert!(loaded.netplay.enabled);
        assert_eq!(loaded.netplay.room, "arena");
    }

    #[test]
    fn load_returns_error_for_missing_file() {
        let path = temp_config_path("missing");
        let err = NesConfig::load(&path).expect_err("missing config should fail");
        assert!(err.contains("failed to read config"));
        assert!(err.contains("Hint: copy the example profile"));
    }

    #[test]
    fn load_returns_underlying_error_for_non_not_found_io_errors() {
        let path = std::path::Path::new("."); // Reading a directory should cause IsADirectory or similar OS error
        let err = NesConfig::load(path).expect_err("loading a directory should fail");
        assert!(err.contains("failed to read config"));
        assert!(!err.contains("Hint: copy the example profile"));
    }

    #[test]
    fn load_or_default_uses_provided_path_when_present() {
        let path = write_temp_config(
            r#"
[desktop]
window_scale = 9
"#,
            "load-or-default-path",
        );
        let loaded = NesConfig::load_or_default(Some(&path)).expect("load_or_default should load");
        remove_if_exists(&path);

        assert_eq!(loaded.desktop.window_scale, 9);
    }

    #[test]
    fn normalize_nonzero_helpers_use_fallback_only_for_zero() {
        assert_eq!(normalize_nonzero_u32(0, 77), 77);
        assert_eq!(normalize_nonzero_u32(5, 77), 5);
        assert_eq!(normalize_nonzero_u64(0, 99), 99);
        assert_eq!(normalize_nonzero_u64(42, 99), 42);
    }

    #[test]
    fn parse_config_path_arg_supports_split_flag() {
        let args = vec![
            "--config".to_owned(),
            "custom.toml".to_owned(),
            "rom.nes".to_owned(),
        ];
        let (config, rest) = parse_config_path_arg(&args).expect("parse should succeed");
        assert_eq!(
            config.as_deref().and_then(|p| p.to_str()),
            Some("custom.toml")
        );
        assert_eq!(rest, vec!["rom.nes".to_owned()]);
    }

    #[test]
    fn parse_config_path_arg_supports_equals_flag() {
        let args = vec!["--config=custom.toml".to_owned(), "rom.nes".to_owned()];
        let (config, rest) = parse_config_path_arg(&args).expect("parse should succeed");
        assert_eq!(
            config.as_deref().and_then(|p| p.to_str()),
            Some("custom.toml")
        );
        assert_eq!(rest, vec!["rom.nes".to_owned()]);
    }

    #[test]
    fn parse_config_path_arg_rejects_missing_value() {
        let args = vec!["--config".to_owned()];
        let err = parse_config_path_arg(&args).expect_err("parse should fail");
        assert!(err.contains("missing value"));
    }

    #[test]
    fn parse_config_path_arg_rejects_flag_as_split_value() {
        let args = vec!["--config".to_owned(), "--netplay".to_owned()];
        let err = parse_config_path_arg(&args).expect_err("parse should fail");
        assert!(err.contains("missing value"));
    }

    #[test]
    fn parse_config_path_arg_rejects_empty_equals_value() {
        let args = vec!["--config=".to_owned()];
        let err = parse_config_path_arg(&args).expect_err("parse should fail");
        assert!(err.contains("missing value"));
    }

    #[test]
    fn parse_config_path_arg_last_flag_wins_and_preserves_other_args() {
        let args = vec![
            "--config=first.toml".to_owned(),
            "rom.nes".to_owned(),
            "--config".to_owned(),
            "second.toml".to_owned(),
            "--fullscreen".to_owned(),
        ];
        let (config, rest) = parse_config_path_arg(&args).expect("parse should succeed");
        assert_eq!(
            config.as_deref(),
            Some(PathBuf::from("second.toml").as_path())
        );
        assert_eq!(rest, vec!["rom.nes".to_owned(), "--fullscreen".to_owned()]);
    }

    #[test]
    fn parse_config_path_loop_terminates() {
        let args = vec![
            "--config".to_owned(),
            "dummy.toml".to_owned(),
            "extra".to_owned(),
        ];

        let start_idx = 0;
        let mut idx = start_idx;
        let res = super::parse_arg(&args, &mut idx, "--config", |_| Ok(()));
        assert_eq!(res, Ok(true));
        assert_eq!(idx, start_idx + 2); // Ensure it increments by 2

        let mut idx = 0;
        let args2 = vec!["--config=dummy.toml".to_owned(), "extra".to_owned()];
        let res2 = super::parse_arg(&args2, &mut idx, "--config", |_| Ok(()));
        assert_eq!(res2, Ok(true));
        assert_eq!(idx, 1); // Ensure it increments by 1

        let mut idx = 0;
        let args3 = vec!["extra".to_owned()];
        let res3 = super::parse_arg(&args3, &mut idx, "--config", |_| Ok(()));
        assert_eq!(res3, Ok(false));
        assert_eq!(idx, 0); // Unchanged when not matched
    }

    #[test]
    fn load_rejects_unknown_top_level_field() {
        let path = write_temp_config(
            r#"
unknown_top_level = true
"#,
            "load-unknown-top-level",
        );
        let err = NesConfig::load(&path).expect_err("unknown top-level field should fail");
        remove_if_exists(&path);

        assert!(err.contains("unknown field"));
        assert!(err.contains("unknown_top_level"));
    }

    #[test]
    fn load_rejects_unknown_nested_field() {
        let path = write_temp_config(
            r#"
[desktop]
window_scale = 4
window_scal = 7
"#,
            "load-unknown-nested",
        );
        let err = NesConfig::load(&path).expect_err("unknown nested field should fail");
        remove_if_exists(&path);

        assert!(err.contains("unknown field"));
        assert!(err.contains("window_scal"));
    }
}

/// Baseline throughput benchmarks for nes-core hot paths.
///
/// Covers three granularities of emulation stepping:
///   - `step_frame`     : ~89,341 CPU cycles (one full PPU frame)
///   - `step_scanline`  : 341 PPU dots (one scanline)
///   - `step_cpu`       : one 6502 instruction (2-8 cycles)
///
/// Run with:
///   cargo bench -p nes-core
///
/// Compare before/after an optimization with:
///   cargo bench -p nes-core -- --save-baseline before
///   # (make changes)
///   cargo bench -p nes-core -- --baseline before
use nes_core::{Command, NesCore};

fn main() {
    divan::main();
}

/// NOP ; JMP $C000 — infinite NOP loop.
/// Exercises the full emulation pipeline (CPU decode, PPU dots, APU ticks)
/// without any ROM data dependency.
const NOP_LOOP: &[u8] = &[0xEA, 0x4C, 0x00, 0xC0];

fn make_nop_core() -> NesCore {
    let mut core = NesCore::new();
    core.load_cpu_bytes(0xC000, NOP_LOOP);
    core
}

fn make_nop_core_no_trace() -> NesCore {
    let mut core = make_nop_core();
    core.set_trace_enabled(false);
    core
}

/// Single-frame throughput — how fast can we emulate one PPU frame?
///
/// Cold: fresh NesCore each sample (first-frame cost).
/// Warm: same core accumulating frames (steady-state throughput).
#[divan::bench]
fn step_frame_cold(bencher: divan::Bencher) {
    bencher.with_inputs(make_nop_core).bench_values(|mut core| {
        core.execute(Command::StepFrame).unwrap();
        core
    });
}

#[divan::bench]
fn step_frame_warm(bencher: divan::Bencher) {
    let mut core = make_nop_core();
    bencher.bench_local(|| {
        core.execute(Command::StepFrame).unwrap();
    });
}

/// Scanline throughput — one 341-dot scanline.
///
/// Isolates per-scanline work (sprite evaluation, overflow check)
/// from per-frame and per-instruction overhead.
#[divan::bench]
fn step_scanline_warm(bencher: divan::Bencher) {
    let mut core = make_nop_core();
    bencher.bench_local(|| {
        core.execute(Command::StepScanline).unwrap();
    });
}

/// CPU instruction throughput — one 6502 NOP (2 CPU cycles, 6 PPU dots).
///
/// Measures raw cost of `advance_hardware_cycles(2)` plus dispatch overhead.
#[divan::bench]
fn step_cpu_nop(bencher: divan::Bencher) {
    let mut core = make_nop_core();
    bencher.bench_local(|| {
        core.execute(Command::StepCpu).unwrap();
    });
}

/// Sixty-frame burst — equivalent to 1 second at 60 Hz.
///
/// Exposes steady-state throughput and amortized frame-boundary costs
/// (odd-frame skip, VBlank NMI dispatch).
#[divan::bench]
fn sixty_frames_burst(bencher: divan::Bencher) {
    let mut core = make_nop_core();
    bencher.bench_local(|| {
        for _ in 0..60 {
            core.execute(Command::StepFrame).unwrap();
        }
    });
}

/// Same benchmarks with trace explicitly forced off.
///
/// In release builds this matches the default (trace is off by default via
/// `cfg!(debug_assertions)`). Kept as an explicit ceiling measurement.
mod no_trace {
    use super::*;

    #[divan::bench]
    fn step_frame_warm(bencher: divan::Bencher) {
        let mut core = make_nop_core_no_trace();
        bencher.bench_local(|| {
            core.execute(Command::StepFrame).unwrap();
        });
    }

    #[divan::bench]
    fn step_cpu_nop(bencher: divan::Bencher) {
        let mut core = make_nop_core_no_trace();
        bencher.bench_local(|| {
            core.execute(Command::StepCpu).unwrap();
        });
    }

    #[divan::bench]
    fn sixty_frames_burst(bencher: divan::Bencher) {
        let mut core = make_nop_core_no_trace();
        bencher.bench_local(|| {
            for _ in 0..60 {
                core.execute(Command::StepFrame).unwrap();
            }
        });
    }
}

//! The core emulator API surface.
//
//! This module provides the primary interface for controlling the NES emulator,
//! injecting inputs, and querying its state. The [`NesCore`] struct is the
//! main entry point for host applications.

