    pub sp: u8,
    /// Raw status flags.
    pub status: u8,
    /// 2KB NES work RAM ($0000–$07FF).
    #[serde(
        serialize_with = "crate::serde_array::serialize_u8_array",
        deserialize_with = "crate::serde_array::deserialize_u8_array"
    )]
    pub work_ram: [u8; 2048],
