    #[test]
    fn format_trace_covers_padding_paths() {
        let snapshot = TraceSnapshot {
            pc: 0x8000,
            a: 0x01,
            x: 0x02,
            y: 0x03,
            p: 0x24,
            sp: 0xFD,
        };

        // Short mnemonic to test padding loop
        let out = format_trace(snapshot, &[0xEA], format_args!("NOP"));
        assert!(out.contains("8000"));
        assert!(out.contains("NOP"));

