//! 6502 CPU implementation and status register helpers.

mod engine;
/// Processor status register (`P`) helper type.
pub mod status;

pub use engine::{
    Cpu, CpuBusAccess, CpuBusAccessKind, CpuError, CpuMmioRead, CpuPrgWrite, CpuSnapshot, CpuWrite,
};

//! CPU status register (P) abstraction.
//!
//! The 6502 CPU has a processor status register that holds condition flags
//! updated by various operations. This module provides a safe interface
//! for manipulating these flags without manual bitwise logic.

/// Represents the CPU status flags.
///
/// Handles setting, clearing, and testing the various bits used by the 6502
/// (Carry, Zero, Interrupt Disable, Decimal, Overflow, Negative). It also
/// correctly manages the somewhat complicated "Break" and "Unused" flag
/// behavior when pushing/pulling to/from the stack.
///
/// ## Panics
///
/// The methods on this struct do not panic.
///
/// ## Examples
///
/// ```
/// use nes_core::cpu::status::Status;
///
/// let mut status = Status::default();
/// assert!(!status.carry());
///
/// status.set_carry(true);
/// assert!(status.carry());
///
/// status.update_zn(0x00); // Setting value to 0 updates Zero and Negative flags
/// assert!(status.zero());
/// assert!(!status.negative());
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Status {
    bits: u8,
}

impl Status {
    const CARRY_BIT: u8 = 0b0000_0001;
    const ZERO_BIT: u8 = 0b0000_0010;
    const INTERRUPT_DISABLE_BIT: u8 = 0b0000_0100;
    const DECIMAL_BIT: u8 = 0b0000_1000;
    const BREAK_BIT: u8 = 0b0001_0000;
    const UNUSED_BIT: u8 = 0b0010_0000;
    const OVERFLOW_BIT: u8 = 0b0100_0000;
    const NEGATIVE_BIT: u8 = 0b1000_0000;

    /// Constructs status from raw bits.
    #[must_use]
    pub const fn with_bits(bits: u8) -> Self {
        Self { bits }
    }

    /// Returns raw status bits.
    #[must_use]
    pub const fn bits(self) -> u8 {
        self.bits
    }

    /// Carry flag (`C`).
    #[must_use]
    pub fn carry(&self) -> bool {
        self.bits & Self::CARRY_BIT != 0
    }

    /// Zero flag (`Z`).
    #[must_use]
    pub fn zero(&self) -> bool {
        self.bits & Self::ZERO_BIT != 0
    }

    /// Interrupt disable flag (`I`).
    #[must_use]
    pub fn interrupt_disable(&self) -> bool {
        self.bits & Self::INTERRUPT_DISABLE_BIT != 0
    }

    /// Overflow flag (`V`).
    #[must_use]
    pub fn overflow(&self) -> bool {
        self.bits & Self::OVERFLOW_BIT != 0
    }

    /// Negative flag (`N`).
    #[must_use]
    pub fn negative(&self) -> bool {
        self.bits & Self::NEGATIVE_BIT != 0
    }

    /// Sets or clears carry flag (`C`).
    pub fn set_carry(&mut self, enabled: bool) {
        self.set_flag(Self::CARRY_BIT, enabled);
    }

    /// Sets or clears interrupt-disable flag (`I`).
    pub fn set_interrupt_disable(&mut self, enabled: bool) {
        self.set_flag(Self::INTERRUPT_DISABLE_BIT, enabled);
    }

    /// Sets or clears decimal flag (`D`).
    pub fn set_decimal(&mut self, enabled: bool) {
        self.set_flag(Self::DECIMAL_BIT, enabled);
    }

    /// Sets or clears break flag (`B`).
    pub fn set_break(&mut self, enabled: bool) {
        self.set_flag(Self::BREAK_BIT, enabled);
    }

    /// Sets or clears overflow flag (`V`).
    pub fn set_overflow(&mut self, enabled: bool) {
        self.set_flag(Self::OVERFLOW_BIT, enabled);
    }

    /// Sets or clears negative flag (`N`).
    pub fn set_negative(&mut self, enabled: bool) {
        self.set_flag(Self::NEGATIVE_BIT, enabled);
    }

    /// Updates zero and negative flags from a result value.
    pub fn update_zn(&mut self, value: u8) {
        self.set_flag(Self::ZERO_BIT, value == 0);
        self.set_flag(Self::NEGATIVE_BIT, value & Self::NEGATIVE_BIT != 0);
    }

    /// Updates compare flags as if `lhs - rhs` were executed.
    pub fn update_compare(&mut self, lhs: u8, rhs: u8) {
        let result = lhs.wrapping_sub(rhs);
        self.set_carry(lhs >= rhs);
        self.update_zn(result);
    }

    /// Updates flags for `BIT` instruction semantics.
    pub fn update_bit_test(&mut self, lhs: u8, rhs: u8) {
        self.set_flag(Self::ZERO_BIT, lhs & rhs == 0);
        self.set_overflow(rhs & Self::OVERFLOW_BIT != 0);
        self.set_negative(rhs & Self::NEGATIVE_BIT != 0);
    }

    /// Restores status from stack pull (`PLP`/interrupt return semantics).
    pub fn restore_from_stack(&mut self, bits: u8) {
        self.bits = (bits | Self::UNUSED_BIT) & !Self::BREAK_BIT;
    }

    /// Encodes status bits for interrupt/BRK stack push.
    #[must_use]
    pub fn bits_for_stack_push(self) -> u8 {
        (self.bits | Self::UNUSED_BIT) & !Self::BREAK_BIT
    }

    /// Encodes status bits for `PHP` stack push.
    #[must_use]
    pub fn bits_for_php(self) -> u8 {
        self.bits | Self::UNUSED_BIT | Self::BREAK_BIT
    }

    fn set_flag(&mut self, mask: u8, enabled: bool) {
        if enabled {
            self.bits |= mask;
        } else {
            self.bits &= !mask;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_status_is_empty() {
        let status = Status::default();
        assert_eq!(status.bits(), 0);
        assert!(!status.carry());
        assert!(!status.zero());
        assert!(!status.interrupt_disable());
        assert!(!status.overflow());
        assert!(!status.negative());
    }

    #[test]
    fn construct_with_bits_retains_value() {
        let status = Status::with_bits(0b1100_0101);
        assert_eq!(status.bits(), 0b1100_0101);
        assert!(status.carry());
        assert!(status.interrupt_disable());
        assert!(status.overflow());
        assert!(status.negative());
        assert!(!status.zero());
    }

    #[test]
    fn individual_flags_can_be_set_and_cleared() {
        let mut status = Status::default();

        status.set_carry(true);
        assert!(status.carry());
        assert_eq!(status.bits(), Status::CARRY_BIT);
        status.set_carry(false);
        assert!(!status.carry());

        status.set_interrupt_disable(true);
        assert!(status.interrupt_disable());
        assert_eq!(status.bits(), Status::INTERRUPT_DISABLE_BIT);
        status.set_interrupt_disable(false);
        assert!(!status.interrupt_disable());

        status.set_decimal(true);
        assert_eq!(status.bits(), Status::DECIMAL_BIT);
        status.set_decimal(false);
        assert_eq!(status.bits(), 0);

        status.set_break(true);
        assert_eq!(status.bits(), Status::BREAK_BIT);
        status.set_break(false);
        assert_eq!(status.bits(), 0);

        status.set_overflow(true);
        assert!(status.overflow());
        assert_eq!(status.bits(), Status::OVERFLOW_BIT);
        status.set_overflow(false);
        assert!(!status.overflow());

        status.set_negative(true);
        assert!(status.negative());
        assert_eq!(status.bits(), Status::NEGATIVE_BIT);
        status.set_negative(false);
        assert!(!status.negative());
    }

    #[test]
    fn update_zn_sets_flags_based_on_value() {
        let mut status = Status::default();

        status.update_zn(0x00);
        assert!(status.zero());
        assert!(!status.negative());

        status.update_zn(0x7F);
        assert!(!status.zero());
        assert!(!status.negative());

        status.update_zn(0x80);
        assert!(!status.zero());
        assert!(status.negative());

        status.update_zn(0xFF);
        assert!(!status.zero());
        assert!(status.negative());
    }

    #[test]
    fn update_compare_sets_flags_correctly() {
        let cases = [
            // lhs, rhs, carry, zero, negative
            (0x05, 0x05, true, true, false),  // Equal
            (0x05, 0x03, true, false, false), // Greater than
            (0x03, 0x05, false, false, true), // Less than (negative result 0xFE)
            (0x80, 0x01, true, false, false), // Greater than (positive result 0x7F)
            (0x01, 0x80, false, false, true), // Less than (negative result 0x81)
            (0x7F, 0x80, false, false, true), // Less than (negative result 0xFF)
            (0x80, 0x7F, true, false, false), // Greater than (positive result 0x01)
        ];

        for (lhs, rhs, expected_c, expected_z, expected_n) in cases {
            let mut status = Status::default();
            status.update_compare(lhs, rhs);
            assert_eq!(
                status.carry(),
                expected_c,
                "carry failed for {} >= {}",
                lhs,
                rhs
            );
            assert_eq!(
                status.zero(),
                expected_z,
                "zero failed for {} - {}",
                lhs,
                rhs
            );
            assert_eq!(
                status.negative(),
                expected_n,
                "negative failed for {} - {}",
                lhs,
                rhs
            );
        }
    }

    #[test]
    fn update_bit_test_sets_flags_correctly() {
        let mut status = Status::default();

        // BIT uses mask, and sets N/V from memory value
        let lhs = 0b0000_1111;
        let rhs = 0b1100_0000;

        status.update_bit_test(lhs, rhs);
        assert!(status.zero()); // 0x0F & 0xC0 == 0
        assert!(status.overflow()); // bit 6 of rhs is 1
        assert!(status.negative()); // bit 7 of rhs is 1

        let lhs = 0b1111_1111;
        let rhs = 0b0011_1111;

        status.update_bit_test(lhs, rhs);
        assert!(!status.zero()); // 0xFF & 0x3F != 0
        assert!(!status.overflow()); // bit 6 of rhs is 0
        assert!(!status.negative()); // bit 7 of rhs is 0
    }

    #[test]
    fn stack_push_pull_semantics() {
        let mut status = Status::default();
        status.set_carry(true);
        status.set_negative(true);

        // Push via BRK/IRQ pushes with B clear, U set
        let irq_push = status.bits_for_stack_push();
        assert_eq!(irq_push & Status::BREAK_BIT, 0);
        assert_ne!(irq_push & Status::UNUSED_BIT, 0);

        // Push via PHP pushes with B set, U set
        let php_push = status.bits_for_php();
        assert_ne!(php_push & Status::BREAK_BIT, 0);
        assert_ne!(php_push & Status::UNUSED_BIT, 0);

        // Pull via PLP/RTI restores flags, ignores B and U
        let mut restored = Status::default();
        // Simulate pulling a byte with all bits set
        restored.restore_from_stack(0xFF);
        assert!(restored.carry());
        assert!(restored.negative());
        assert!(restored.overflow());
        assert_eq!(restored.bits() & Status::BREAK_BIT, 0); // B flag should be cleared on restore
        assert_ne!(restored.bits() & Status::UNUSED_BIT, 0); // U flag is always forced set
    }

    #[test]
    fn bits_for_stack_push_preserves_other_flags_and_forces_unused_set_and_break_clear() {
        // Test with a base state where U is 0 and B is 0
        let status = Status::with_bits(Status::CARRY_BIT | Status::NEGATIVE_BIT);
        let push_bits = status.bits_for_stack_push();
        assert_eq!(
            push_bits,
            Status::CARRY_BIT | Status::NEGATIVE_BIT | Status::UNUSED_BIT
        );

        // Test with a base state where U is 1 and B is 1
        let status2 = Status::with_bits(
            Status::CARRY_BIT | Status::NEGATIVE_BIT | Status::UNUSED_BIT | Status::BREAK_BIT,
        );
        let push_bits2 = status2.bits_for_stack_push();
        assert_eq!(
            push_bits2,
            Status::CARRY_BIT | Status::NEGATIVE_BIT | Status::UNUSED_BIT
        );
    }

    #[test]
    fn bits_for_php_preserves_other_flags_and_forces_unused_and_break_set() {
        // Test with a base state where U is 0 and B is 0
        let status = Status::with_bits(Status::OVERFLOW_BIT | Status::DECIMAL_BIT);
        let push_bits = status.bits_for_php();
        assert_eq!(
            push_bits,
            Status::OVERFLOW_BIT | Status::DECIMAL_BIT | Status::UNUSED_BIT | Status::BREAK_BIT
        );

        // Test with a base state where U is 1 and B is 1
        let status2 = Status::with_bits(
            Status::OVERFLOW_BIT | Status::DECIMAL_BIT | Status::UNUSED_BIT | Status::BREAK_BIT,
        );
        let push_bits2 = status2.bits_for_php();
        assert_eq!(
            push_bits2,
            Status::OVERFLOW_BIT | Status::DECIMAL_BIT | Status::UNUSED_BIT | Status::BREAK_BIT
        );

        // Test with a base state where U is 0 and B is 1
        let status3 =
            Status::with_bits(Status::OVERFLOW_BIT | Status::DECIMAL_BIT | Status::BREAK_BIT);
        let push_bits3 = status3.bits_for_php();
        assert_eq!(
            push_bits3,
            Status::OVERFLOW_BIT | Status::DECIMAL_BIT | Status::UNUSED_BIT | Status::BREAK_BIT
        );

        // Test with a base state where U is 1 and B is 0
        let status4 =
            Status::with_bits(Status::OVERFLOW_BIT | Status::DECIMAL_BIT | Status::UNUSED_BIT);
        let push_bits4 = status4.bits_for_php();
        assert_eq!(
            push_bits4,
            Status::OVERFLOW_BIT | Status::DECIMAL_BIT | Status::UNUSED_BIT | Status::BREAK_BIT
        );
    }
}

//! Experimental tools for exporting raw NES audio into standard media formats.
//!
//! This module provides the `WavExporter` utility, allowing developers or players
//! to easily capture the emulator's audio output and save it as a standard `.wav` file.
//! This is particularly useful for extracting chiptunes, sound effects, or recording
//! the audio of a complete TAS run.

#[cfg(feature = "nova")]
use crate::constants::AUDIO_SAMPLE_RATE;

/// A utility for recording 16-bit PCM samples and exporting them as a RIFF `.wav` file.
///
/// `WavExporter` acts as an audio sink. You push chunks of samples into it during
/// emulation, and when finished, you can generate a complete `.wav` file in memory
/// ready to be written to disk.
#[cfg(feature = "nova")]
#[derive(Debug, Clone)]
pub struct WavExporter {
    sample_rate: u32,
    samples: Vec<i16>,
}

#[cfg(feature = "nova")]
impl Default for WavExporter {
    fn default() -> Self {
        Self::new(AUDIO_SAMPLE_RATE)
    }
}

#[cfg(feature = "nova")]
impl WavExporter {
    /// Creates a new, empty `WavExporter` with the specified sample rate.
    pub fn new(sample_rate: u32) -> Self {
        Self {
            sample_rate,
            samples: Vec::new(),
        }
    }

    /// Appends a chunk of 16-bit mono PCM samples to the exporter.
    pub fn push_samples(&mut self, new_samples: &[i16]) {
        self.samples.extend_from_slice(new_samples);
    }

    /// Clears all recorded samples, resetting the exporter.
    pub fn clear(&mut self) {
        self.samples.clear();
    }

    /// Generates a complete RIFF `.wav` file from the recorded samples.
    ///
    /// The resulting byte vector includes the standard 44-byte WAV header followed
    /// by the raw PCM data. It can be written directly to a `.wav` file on disk.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_core::experimental::audio_exporter::WavExporter;
    ///
    /// let mut exporter = WavExporter::new(44100);
    /// exporter.push_samples(&[0, 100, 200, 100, 0, -100, -200, -100]);
    ///
    /// let wav_bytes = exporter.export();
    /// assert_eq!(&wav_bytes[0..4], b"RIFF");
    /// assert_eq!(&wav_bytes[8..12], b"WAVE");
    /// ```
    pub fn export(&self) -> Vec<u8> {
        let num_samples = self.samples.len() as u32;
        let data_size = num_samples * 2; // 2 bytes per i16 sample
        let file_size = 36 + data_size; // 36 bytes for header after the RIFF size

        let mut out = Vec::with_capacity(44 + data_size as usize);

        // RIFF header
        out.extend_from_slice(b"RIFF");
        out.extend_from_slice(&file_size.to_le_bytes());
        out.extend_from_slice(b"WAVE");

        // fmt chunk
        out.extend_from_slice(b"fmt ");
        out.extend_from_slice(&16u32.to_le_bytes()); // Chunk size
        out.extend_from_slice(&1u16.to_le_bytes()); // Audio format (1 = PCM)
        out.extend_from_slice(&1u16.to_le_bytes()); // Num channels (1 = Mono)
        out.extend_from_slice(&self.sample_rate.to_le_bytes()); // Sample rate

        let byte_rate = self.sample_rate * 2; // sample_rate * num_channels * bytes_per_sample
        out.extend_from_slice(&byte_rate.to_le_bytes()); // Byte rate

        let block_align = 2u16; // num_channels * bytes_per_sample
        out.extend_from_slice(&block_align.to_le_bytes()); // Block align

        let bits_per_sample = 16u16;
        out.extend_from_slice(&bits_per_sample.to_le_bytes()); // Bits per sample

        // data chunk
        out.extend_from_slice(b"data");
        out.extend_from_slice(&data_size.to_le_bytes());

        // sample data
        for &sample in &self.samples {
            out.extend_from_slice(&sample.to_le_bytes());
        }

        out
    }
}

#[cfg(all(test, feature = "nova"))]
mod tests {
    use super::*;

    #[test]
    fn can_export_wav_file() {
        let mut exporter = WavExporter::new(44100);
        exporter.push_samples(&[100, -100, 200, -200]);

        let wav = exporter.export();

        // Check header length
        assert_eq!(wav.len(), 44 + 8);

        // Check RIFF magic
        assert_eq!(&wav[0..4], b"RIFF");
        // Check WAVE format
        assert_eq!(&wav[8..12], b"WAVE");
        // Check fmt chunk
        assert_eq!(&wav[12..16], b"fmt ");
        // Check data chunk
        assert_eq!(&wav[36..40], b"data");

        // Verify data size (4 samples * 2 bytes = 8)
        let data_size = u32::from_le_bytes(wav[40..44].try_into().unwrap());
        assert_eq!(data_size, 8);

        // Verify sample values
        let sample0 = i16::from_le_bytes(wav[44..46].try_into().unwrap());
        let sample1 = i16::from_le_bytes(wav[46..48].try_into().unwrap());
        assert_eq!(sample0, 100);
        assert_eq!(sample1, -100);
    }

    #[test]
    fn can_clear_samples() {
        let mut exporter = WavExporter::default();
        exporter.push_samples(&[1, 2, 3]);
        assert_eq!(exporter.samples.len(), 3);
        exporter.clear();
        assert_eq!(exporter.samples.len(), 0);
    }
}

//! Experimental memory scanner for discovering cheat codes and game state values.
//!
//! The cheat finder implements a standard "successive approximation" search, similar
//! to tools found in classic emulators or cheat engines like Game Genie code finders.
//!
//! # The Process
//! 1. **Initialize:** The search begins by snapshotting the entire RAM space (`0x0000` to `0x07FF`).
//!    Every address is a potential candidate.
//! 2. **Play:** The user plays the game to change the state (e.g., losing a life, collecting a coin).
//! 3. **Filter:** The user applies a filter based on what happened (e.g., "value decreased",
//!    "value equals 5"). The finder eliminates addresses that don't match this criteria.
//! 4. **Repeat:** Steps 2 and 3 are repeated until only a handful of candidate addresses remain.
//!    These final addresses are highly likely to be the memory locations controlling the desired state.

#[cfg(feature = "nova")]
use crate::NesCore;

#[cfg(feature = "nova")]
#[derive(Debug, Clone, PartialEq, Eq)]
/// Represents a possible memory location that might hold the target cheat value.
///
/// Each candidate tracks both its physical address and the last known value at that address.
/// By storing the `last_value`, subsequent filter operations (like "has changed") can
/// accurately compare the new state against the historical state without needing to
/// buffer the entire RAM.
pub struct MemoryCandidate {
    /// The physical memory address in the NES RAM (typically `0x0000` through `0x07FF`).
    pub addr: u16,
    /// The byte value read at this address during the last filtering pass or initial reset.
    pub last_value: u8,
}

#[cfg(feature = "nova")]
#[derive(Debug, Default, Clone)]
/// The engine for discovering memory locations by repeatedly applying constraints.
///
/// `CheatFinder` maintains an internal list of [`MemoryCandidate`]s. As you filter
/// the candidates against the current state of a [`NesCore`], the list shrinks
/// until only the desired memory address remains.
pub struct CheatFinder {
    candidates: Vec<MemoryCandidate>,
}

#[cfg(feature = "nova")]
impl CheatFinder {
    /// Creates a new, empty `CheatFinder`.
    ///
    /// By default, there are no candidates to search through. You must call
    /// [`CheatFinder::reset_search`] to initialize the candidate list before
    /// performing any filtering operations.
    ///
    /// ## Examples
    ///
    /// ```
    /// # use nes_core::experimental::cheat_finder::CheatFinder;
    /// let finder = CheatFinder::new();
    /// assert_eq!(finder.candidates().len(), 0);
    /// ```
    pub fn new() -> Self {
        Self {
            candidates: Vec::new(),
        }
    }

    /// Populates the initial pool of memory candidates using the core's current state.
    ///
    /// The finder loops over the entire base RAM (`0x0000` to `0x07FF`, a total of
    /// 2,048 addresses) and records the current byte values. Any subsequent filtering
    /// applies against this initial historical baseline until updated.
    ///
    /// ## Examples
    ///
    /// ```
    /// # use nes_core::NesCore;
    /// # use nes_core::experimental::cheat_finder::CheatFinder;
    /// let core = NesCore::new();
    /// let mut finder = CheatFinder::new();
    ///
    /// // Initialize with 2048 candidates
    /// finder.reset_search(&core);
    /// assert_eq!(finder.candidates().len(), 2048);
    /// ```
    pub fn reset_search(&mut self, core: &NesCore) {
        self.candidates.clear();
        for addr in 0x0000..=0x07FF {
            self.candidates.push(MemoryCandidate {
                addr,
                last_value: core.read_memory(addr),
            });
        }
    }

    /// Keeps only candidates whose current memory value matches the exact `value` provided.
    ///
    /// After filtering, the historical `last_value` of the remaining candidates is updated.
    ///
    /// ## Examples
    ///
    /// ```
    /// # use nes_core::NesCore;
    /// # use nes_core::experimental::cheat_finder::CheatFinder;
    /// let mut core = NesCore::new();
    /// let mut finder = CheatFinder::new();
    /// finder.reset_search(&core);
    ///
    /// // Simulate changing a value at a specific address
    /// core.load_cpu_bytes(0x0123, &[42]);
    ///
    /// // Find the address that now holds the value 42
    /// finder.filter_eq(&core, 42);
    /// assert_eq!(finder.candidates()[0].addr, 0x0123);
    /// ```
    pub fn filter_eq(&mut self, core: &NesCore, value: u8) {
        self.candidates
            .retain(|c| core.read_memory(c.addr) == value);
        self.update_candidates(core);
    }

    /// Keeps only candidates whose current memory value does NOT match the `value` provided.
    ///
    /// After filtering, the historical `last_value` of the remaining candidates is updated.
    ///
    /// ## Examples
    ///
    /// ```
    /// # use nes_core::NesCore;
    /// # use nes_core::experimental::cheat_finder::CheatFinder;
    /// let core = NesCore::new();
    /// let mut finder = CheatFinder::new();
    /// finder.reset_search(&core);
    ///
    /// // Initially all values are 0, so filtering out 0 leaves nothing.
    /// finder.filter_neq(&core, 0);
    /// assert_eq!(finder.candidates().len(), 0);
    /// ```
    pub fn filter_neq(&mut self, core: &NesCore, value: u8) {
        self.candidates
            .retain(|c| core.read_memory(c.addr) != value);
        self.update_candidates(core);
    }

    /// Keeps only candidates whose memory value has changed since the last filtering operation.
    ///
    /// This is useful when you know a state has changed (e.g., your character moved, took damage)
    /// but you don't know the exact numeric value of that state in memory.
    ///
    /// After filtering, the historical `last_value` of the remaining candidates is updated.
    ///
    /// ## Examples
    ///
    /// ```
    /// # use nes_core::NesCore;
    /// # use nes_core::experimental::cheat_finder::CheatFinder;
    /// let mut core = NesCore::new();
    /// let mut finder = CheatFinder::new();
    /// finder.reset_search(&core);
    ///
    /// // Simulate an unknown change
    /// core.load_cpu_bytes(0x0200, &[99]);
    ///
    /// // Find all values that changed from their original baseline
    /// finder.filter_changed(&core);
    /// assert_eq!(finder.candidates().len(), 1);
    /// assert_eq!(finder.candidates()[0].addr, 0x0200);
    /// ```
    pub fn filter_changed(&mut self, core: &NesCore) {
        self.candidates
            .retain(|c| core.read_memory(c.addr) != c.last_value);
        self.update_candidates(core);
    }

    /// Keeps only candidates whose memory value has NOT changed since the last filtering operation.
    ///
    /// This is an extremely useful "pruning" mechanism. If your character stands still,
    /// and you filter by `filter_unchanged`, you eliminate memory values related to timers,
    /// enemy movement, rendering counters, and sound generation.
    ///
    /// After filtering, the historical `last_value` of the remaining candidates is updated.
    ///
    /// ## Examples
    ///
    /// ```
    /// # use nes_core::NesCore;
    /// # use nes_core::experimental::cheat_finder::CheatFinder;
    /// let mut core = NesCore::new();
    /// let mut finder = CheatFinder::new();
    /// finder.reset_search(&core);
    ///
    /// // Simulate time passing (e.g., a frame counter increasing)
    /// core.load_cpu_bytes(0x0111, &[10]);
    ///
    /// // Find values that remained the same (pruning the frame counter)
    /// finder.filter_unchanged(&core);
    /// assert_eq!(finder.candidates().len(), 2047);
    /// ```
    pub fn filter_unchanged(&mut self, core: &NesCore) {
        self.candidates
            .retain(|c| core.read_memory(c.addr) == c.last_value);
        self.update_candidates(core);
    }

    fn update_candidates(&mut self, core: &NesCore) {
        for candidate in &mut self.candidates {
            candidate.last_value = core.read_memory(candidate.addr);
        }
    }

    /// Returns an immutable slice of the currently surviving memory candidates.
    ///
    /// This list shrinks as you apply more filters. The cheat-finding process is typically
    /// considered "complete" when this list reduces down to 1-3 distinct memory locations.
    pub fn candidates(&self) -> &[MemoryCandidate] {
        &self.candidates
    }
}

#[cfg(all(test, feature = "nova"))]
mod tests {
    use super::*;
    use crate::NesCore;

    #[test]
    fn test_cheat_finder() {
        let mut core = NesCore::new();
        // Set some dummy memory values in RAM space (0x0000 - 0x07FF)
        core.load_cpu_bytes(0x0000, &[0x00, 0x05, 0x0A, 0x05]);

        let mut finder = CheatFinder::new();
        finder.reset_search(&core);
        assert_eq!(finder.candidates().len(), 2048);

        // Filter by exact value 5
        finder.filter_eq(&core, 5);

        // Addresses 0x0001 and 0x0003 should be the only ones remaining
        let candidates = finder.candidates();
        assert_eq!(candidates.len(), 2);
        assert_eq!(candidates[0].addr, 0x0001);
        assert_eq!(candidates[1].addr, 0x0003);

        // Change memory
        core.load_cpu_bytes(0x0001, &[0x04]);

        // Filter by changed value
        finder.filter_changed(&core);

        // Only 0x0001 changed
        let candidates = finder.candidates();
        assert_eq!(candidates.len(), 1);
        assert_eq!(candidates[0].addr, 0x0001);
    }

    #[test]
    fn test_cheat_finder_neq_and_unchanged() {
        let mut core = NesCore::new();
        core.load_cpu_bytes(0x0000, &[0x01, 0x02, 0x03, 0x04]);

        let mut finder = CheatFinder::new();
        finder.reset_search(&core);

        // Filter not equal to 0
        finder.filter_neq(&core, 0);

        // Addresses 0x0000, 0x0001, 0x0002, 0x0003 should remain
        assert_eq!(finder.candidates().len(), 4);

        // Change memory
        core.load_cpu_bytes(0x0001, &[0xFF]);

        // Filter unchanged
        finder.filter_unchanged(&core);

        // Addresses 0x0000, 0x0002, 0x0003 should remain
        let candidates = finder.candidates();
        assert_eq!(candidates.len(), 3);
        assert_eq!(candidates[0].addr, 0x0000);
        assert_eq!(candidates[1].addr, 0x0002);
        assert_eq!(candidates[2].addr, 0x0003);
    }
}

//! Experimental memory event tracking to trigger callbacks when specific conditions occur.
//!
//! This module allows users to define custom triggers (e.g., when a memory address changes or reaches a certain value)
//! and records the events.

#[cfg(feature = "nova")]
use crate::NesCore;

#[cfg(feature = "nova")]
#[derive(Debug, Clone)]
/// Represents a recorded occurrence of a tracked memory condition.
///
/// An `Event` is generated when the CPU memory matches a condition defined by a [`Trigger`].
/// This allows external analysis tools (like speedrun verifiers or AI) to know exactly what
/// values were seen at specific addresses without continuously polling the emulator memory themselves.
pub struct Event {
    /// The memory address that triggered this event.
    pub addr: u16,
    /// The specific byte value that was read at the triggered address.
    pub value: u8,
}

#[cfg(feature = "nova")]
#[derive(Debug, Clone)]
/// A condition defining what memory state should generate an [`Event`].
///
/// Triggers are registered with the [`EventTracker`] to specify which memory addresses
/// to monitor and what values indicate a notable event has occurred.
pub struct Trigger {
    /// The memory address to monitor.
    pub addr: u16,
    /// The byte value that, when present at `addr`, will fire the trigger.
    pub expected_value: u8,
}

#[cfg(feature = "nova")]
#[derive(Debug, Default, Clone)]
/// Monitors emulator memory to generate discrete [`Event`]s based on registered [`Trigger`]s.
///
/// `EventTracker` exists to bridge the gap between continuous emulator state and discrete
/// actions, enabling features like auto-splitters, achievement tracking, or debugging
/// watchpoints by recording when specific memory addresses attain specific values.
pub struct EventTracker {
    triggers: Vec<Trigger>,
    events: Vec<Event>,
}

#[cfg(feature = "nova")]
impl EventTracker {
    /// Creates a new, empty [`EventTracker`].
    ///
    /// The tracker initializes with no active triggers and an empty event log.
    /// You must add triggers using [`add_trigger`](EventTracker::add_trigger) before calling [`track`](EventTracker::track).
    ///
    /// ## Examples
    ///
    /// ```
    /// # use nes_core::experimental::event_tracker::EventTracker;
    /// let tracker = EventTracker::new();
    /// assert!(tracker.events().is_empty());
    /// ```
    pub fn new() -> Self {
        Self {
            triggers: Vec::new(),
            events: Vec::new(),
        }
    }

    /// Adds a new condition to monitor memory values.
    ///
    /// When [`track`](EventTracker::track) is called, it will check if the memory at `addr` matches `expected_value`.
    /// If it does, a new [`Event`] is pushed into the tracker's event log.
    ///
    /// ## Examples
    ///
    /// ```
    /// # use nes_core::experimental::event_tracker::EventTracker;
    /// let mut tracker = EventTracker::new();
    /// tracker.add_trigger(0x0200, 42); // Monitor address 0x0200 for the value 42
    /// ```
    pub fn add_trigger(&mut self, addr: u16, expected_value: u8) {
        self.triggers.push(Trigger {
            addr,
            expected_value,
        });
    }

    /// Evaluates all registered triggers against the current memory state of the provided [`NesCore`].
    ///
    /// For every trigger that matches, an [`Event`] is generated and appended to the event log.
    /// This is typically called once per frame or immediately after specific CPU execution steps.
    ///
    /// ## Examples
    ///
    /// ```
    /// # use nes_core::experimental::event_tracker::EventTracker;
    /// # use nes_core::NesCore;
    /// let mut core = NesCore::new();
    /// let mut tracker = EventTracker::new();
    /// tracker.add_trigger(0x0200, 42);
    ///
    /// // ... after some execution that sets 0x0200 to 42 ...
    /// core.load_cpu_bytes(0x0200, &[42]);
    /// tracker.track(&core);
    /// assert_eq!(tracker.events().len(), 1);
    /// ```
    pub fn track(&mut self, core: &NesCore) {
        for trigger in &self.triggers {
            let value = core.read_memory(trigger.addr);
            if value == trigger.expected_value {
                self.events.push(Event {
                    addr: trigger.addr,
                    value,
                });
            }
        }
    }

    /// Returns a slice of all recorded memory [`Event`]s.
    ///
    /// The log grows indefinitely as [`track`](EventTracker::track) is called and triggers are met.
    ///
    /// ## Examples
    ///
    /// ```
    /// # use nes_core::experimental::event_tracker::EventTracker;
    /// let tracker = EventTracker::new();
    /// assert_eq!(tracker.events().len(), 0);
    /// ```
    pub fn events(&self) -> &[Event] {
        &self.events
    }
}

#[cfg(all(test, feature = "nova"))]
mod tests {
    use super::*;
    use crate::Command;
    use crate::NesCore;

    #[test]
    fn test_event_tracker() {
        let mut core = NesCore::new();
        let mut tracker = EventTracker::new();

        // Track a specific memory address change
        tracker.add_trigger(0x0200, 42);

        core.load_cpu_bytes(0x0200, &[42]);
        let _ = core.execute(Command::StepFrame);

        tracker.track(&core);

        assert_eq!(tracker.events().len(), 1);
        assert_eq!(tracker.events()[0].addr, 0x0200);
        assert_eq!(tracker.events()[0].value, 42);
    }
}

//! Experimental CPU execution graph generator.
//!
//! Tracks the sequence of Program Counter (PC) values to build a directed graph of
//! CPU execution flow. It can export this flow to Graphviz DOT format, making it
//! incredibly useful for reverse engineering NES game loops or debugging AI agents.

#[cfg(feature = "nova")]
use crate::NesCore;
#[cfg(feature = "nova")]
use std::collections::{HashMap, HashSet};
#[cfg(feature = "nova")]
use std::fmt::Write;

#[cfg(feature = "nova")]
#[derive(Debug, Default, Clone)]
/// Records the flow of CPU execution by tracking Program Counter (PC) transitions.
///
/// `ExecutionGraph` builds a directed graph representing the paths the CPU takes during
/// execution. This is invaluable for reverse engineering ROMs, discovering hidden game
/// loops, or visualizing where an AI agent spends its time.
///
/// ## Examples
///
/// ```
/// # use nes_core::NesCore;
/// # use nes_core::experimental::execution_graph::ExecutionGraph;
/// let mut core = NesCore::new();
/// let mut graph = ExecutionGraph::new();
///
/// // Simulate stepping the CPU and recording the transition
/// graph.record_step(&core);
/// let _ = core.execute(nes_core::Command::StepCpu);
/// graph.record_step(&core);
///
/// // Export the recorded path to Graphviz DOT format
/// let dot_data = graph.to_dot();
/// assert!(dot_data.contains("digraph ExecutionFlow {"));
/// ```
pub struct ExecutionGraph {
    /// Maps a source PC to a set of destination PCs.
    transitions: HashMap<u16, HashSet<u16>>,
    last_pc: Option<u16>,
}

#[cfg(feature = "nova")]
impl ExecutionGraph {
    /// Creates a new, empty execution graph.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Records the current PC from the core, creating a transition from the last recorded PC.
    /// This should be called after each CPU step.
    pub fn record_step(&mut self, core: &NesCore) {
        let current_pc = core.cpu_pc();
        if let Some(last) = self.last_pc {
            // Only record jumps/branches or sequential execution
            self.transitions.entry(last).or_default().insert(current_pc);
        }
        self.last_pc = Some(current_pc);
    }

    /// Exports the recorded transitions to a Graphviz DOT string.
    #[must_use]
    pub fn to_dot(&self) -> String {
        let mut dot = String::from("digraph ExecutionFlow {\n");
        // Sort keys to ensure deterministic output for testing/version control
        let mut srcs: Vec<_> = self.transitions.keys().copied().collect();
        srcs.sort_unstable();

        for src in srcs {
            let mut dests: Vec<_> = self.transitions[&src].iter().copied().collect();
            dests.sort_unstable();
            for dest in dests {
                // ⚡ **Bolt Optimization:** Avoids allocating a new intermediate `String`
                // on the heap for every graph transition.
                let _ = writeln!(dot, "    \"{:04X}\" -> \"{:04X}\";", src, dest);
            }
        }
        dot.push_str("}\n");
        dot
    }
}

#[cfg(all(test, feature = "nova"))]
mod tests {
    use super::*;

    #[test]
    fn should_record_transitions_and_export_dot() {
        let mut core = NesCore::new();
        // Force the PC to start at 0xC000
        core.load_cpu_bytes(0xC000, &[0xEA, 0xEA, 0x4C, 0x00, 0xC0]); // NOP, NOP, JMP $C000

        let mut graph = ExecutionGraph::new();

        // Initial PC
        graph.record_step(&core);

        // Execute NOP
        let _ = core.execute(crate::Command::StepCpu);
        graph.record_step(&core);

        // Execute NOP
        let _ = core.execute(crate::Command::StepCpu);
        graph.record_step(&core);

        // Execute JMP
        let _ = core.execute(crate::Command::StepCpu);
        graph.record_step(&core);

        let dot = graph.to_dot();

        assert!(dot.contains("\"C000\" -> \"C001\""));
        assert!(dot.contains("\"C001\" -> \"C002\""));
        assert!(dot.contains("\"C002\" -> \"C000\""));
        assert!(dot.starts_with("digraph ExecutionFlow {"));
        assert!(dot.ends_with("}\n"));
    }

    #[test]
    fn should_export_exact_dot_format() {
        let mut core = NesCore::new();
        core.load_cpu_bytes(0xC000, &[0xEA, 0xEA, 0x4C, 0x00, 0xC0]);

        let mut graph = ExecutionGraph::new();
        graph.record_step(&core);
        let _ = core.execute(crate::Command::StepCpu);
        graph.record_step(&core);

        let dot = graph.to_dot();
        assert_eq!(
            dot,
            "digraph ExecutionFlow {\n    \"C000\" -> \"C001\";\n}\n"
        );
    }
}

//! Experimental visualizer for drawing sprite hitboxes on the framebuffer.

#[cfg(feature = "nova")]
use crate::NesCore;
#[cfg(feature = "nova")]
use crate::constants::{FRAME_HEIGHT, FRAME_WIDTH};
#[cfg(feature = "nova")]
use crate::experimental::oam_spatial_query::OamSprite;

#[cfg(feature = "nova")]
/// A visualizer that draws 8x8 bounding boxes around active OAM sprites.
///
/// `HitboxVisualizer` reads the emulator's Object Attribute Memory (OAM),
/// decodes the sprites, and draws hollow neon rectangles directly onto the
/// raw RGBA framebuffer. This helps developers and speedrunners visually
/// verify object positions and collisions without relying on external tools.
pub struct HitboxVisualizer;

#[cfg(feature = "nova")]
impl HitboxVisualizer {
    /// Draws hitboxes for all valid sprites on the provided RGBA framebuffer.
    ///
    /// The `frame` must be a valid RGBA framebuffer slice of length `FRAME_WIDTH * FRAME_HEIGHT * 4`.
    pub fn draw_hitboxes(core: &NesCore, frame: &mut [u8]) {
        // Extract the 256-byte OAM memory
        let mut oam = [0_u8; 256];
        for i in 0..=255 {
            oam[usize::from(i)] = core.ppu_oam_byte(i);
        }

        // Iterate over up to 64 sprites (4 bytes each)
        for i in 0..64 {
            let sprite = OamSprite::from_oam(i, &oam);

            // Hide sprites off-screen (Y >= 240 is usually off-screen or hidden)
            if sprite.y >= FRAME_HEIGHT as u8 {
                continue;
            }

            // Draw an 8x8 hollow rectangle
            // A sprite is 8 pixels wide and 8 pixels tall by default.
            // (8x16 mode is not handled specifically here yet, Phase 1 only uses 8x8)
            Self::draw_rect(
                frame,
                sprite.x as usize,
                sprite.y as usize,
                8,
                8,
                [0, 255, 0, 255],
            );
        }
    }

    /// Draws a hollow rectangle directly on an RGBA framebuffer.
    fn draw_rect(frame: &mut [u8], x: usize, y: usize, w: usize, h: usize, color: [u8; 4]) {
        let max_x = x + w;
        let max_y = y + h;

        for current_y in y..max_y {
            if current_y >= FRAME_HEIGHT {
                continue;
            }
            for current_x in x..max_x {
                if current_x >= FRAME_WIDTH {
                    continue;
                }

                // Only draw border (hollow rectangle)
                if current_x == x
                    || current_x == max_x - 1
                    || current_y == y
                    || current_y == max_y - 1
                {
                    let base_idx = (current_y * FRAME_WIDTH + current_x) * 4;
                    // Safety check against buffer overflow
                    if base_idx + 3 < frame.len() {
                        frame[base_idx] = color[0]; // R
                        frame[base_idx + 1] = color[1]; // G
                        frame[base_idx + 2] = color[2]; // B
                        frame[base_idx + 3] = color[3]; // A
                    }
                }
            }
        }
    }
}

