}

//! Experimental tools for intentionally corrupting NES ROM data.
//!
//! This module provides the [`RomCorruptor`], an experimental utility that applies
//! deterministic chaos to PRG or CHR ROM data. It uses a lightweight Linear Congruential
//! Generator (LCG) to ensure reproducible corruptions without pulling in external `rand`
//! dependencies.

#[cfg(feature = "nova")]
/// A deterministic glitch generator for NES ROM data.
///
/// `RomCorruptor` mutates ROM byte slices by either flipping random bits or
/// scrambling random bytes. This is useful for chaos engineering, speedrun
/// "glitch modes", or simply generating cursed visual aesthetics.
pub struct RomCorruptor {
    state: u32,
}

#[cfg(feature = "nova")]
impl RomCorruptor {
    /// Creates a new `RomCorruptor` seeded with a specific value.
    ///
    /// ## Examples
    ///
    /// ```
    /// # use nes_core::experimental::rom_corruptor::RomCorruptor;
    /// let mut corruptor = RomCorruptor::new(1337);
    /// ```
    #[must_use]
    pub fn new(seed: u32) -> Self {
        Self {
            // Prevent a 0 seed from locking the state if we used a multiplicative generator,
            // though our LCG constants prevent this anyway.
            state: if seed == 0 { 0xDEAD_BEEF } else { seed },
        }
    }

    /// Advances the internal LCG state and returns a pseudo-random `u32`.
    fn next_u32(&mut self) -> u32 {
        // Simple LCG (Numerical Recipes constants)
        self.state = self.state.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
        self.state
    }

    /// Returns a pseudo-random number in `[0, range)`.
    fn next_range(&mut self, range: u32) -> u32 {
        if range == 0 {
            return 0;
        }
        self.next_u32() % range
    }

    /// Randomly corrupts the given PRG ROM data by randomizing bytes.
    ///
    /// `intensity_permille` determines the likelihood of any given byte being corrupted.
    /// For example, an intensity of `10` means roughly 1% of the data will be scrambled.
    ///
    /// ## Examples
    ///
    /// ```
    /// # use nes_core::experimental::rom_corruptor::RomCorruptor;
    /// let mut corruptor = RomCorruptor::new(42);
    /// let mut prg = vec![0xEA; 100]; // 100 NOPs
    /// corruptor.corrupt_prg(&mut prg, 50); // 5% corruption
    /// assert!(prg.iter().any(|&b| b != 0xEA));
    /// ```
    pub fn corrupt_prg(&mut self, prg: &mut [u8], intensity_permille: u16) {
        if intensity_permille == 0 || prg.is_empty() {
            return;
        }

        let intensity = u32::from(intensity_permille).min(1000);
        for byte in prg.iter_mut() {
            if self.next_range(1000) < intensity {
                // Completely scramble the instruction/data
                *byte = (self.next_u32() & 0xFF) as u8;
            }
        }
    }

    /// Randomly corrupts the given CHR ROM data by flipping bits.
    ///
    /// Flipping bits in CHR RAM tends to create interesting "static" or
    /// scrambled sprite visual artifacts rather than crashing the emulator.
    ///
    /// `intensity_permille` determines the likelihood of a single byte having
    /// a random bit flipped.
    pub fn corrupt_chr(&mut self, chr: &mut [u8], intensity_permille: u16) {
        if intensity_permille == 0 || chr.is_empty() {
            return;
        }

        let intensity = u32::from(intensity_permille).min(1000);
        for byte in chr.iter_mut() {
            if self.next_range(1000) < intensity {
                // Flip a random bit (0-7)
                let bit = self.next_range(8) as u8;
                *byte ^= 1 << bit;
            }
        }
    }
}

#[cfg(all(test, feature = "nova"))]
mod tests {
    use super::*;

    #[test]
    fn corruptor_modifies_prg_deterministically() {
        let mut prg1 = vec![0x00; 1024];
        let mut prg2 = vec![0x00; 1024];

        let mut corruptor1 = RomCorruptor::new(12345);
        corruptor1.corrupt_prg(&mut prg1, 100);

        let mut corruptor2 = RomCorruptor::new(12345);
        corruptor2.corrupt_prg(&mut prg2, 100);

        // They should be identical due to same seed
        assert_eq!(prg1, prg2);

        // They should be modified from the original
        let modified_count = prg1.iter().filter(|&&b| b != 0x00).count();
        assert!(modified_count > 0);
        // Should be roughly 10% (100 permille)
        assert!((50..150).contains(&modified_count));
    }

    #[test]
    fn corruptor_modifies_chr_with_bit_flips() {
        let mut chr = vec![0xFF; 256];
        let mut corruptor = RomCorruptor::new(999);

        // 50% corruption
        corruptor.corrupt_chr(&mut chr, 500);

        let mut flipped_bits = 0;
        for &byte in &chr {
            if byte != 0xFF {
                // It should only have 1 bit flipped per affected byte
                assert_eq!(byte.count_ones(), 7);
                flipped_bits += 1;
            }
        }

        assert!(flipped_bits > 0);
    }

    #[test]
    fn zero_intensity_does_nothing() {
        let mut data = vec![0xAA; 100];
        let mut corruptor = RomCorruptor::new(1);
        corruptor.corrupt_prg(&mut data, 0);
        assert!(data.iter().all(|&b| b == 0xAA));

        corruptor.corrupt_chr(&mut data, 0);
        assert!(data.iter().all(|&b| b == 0xAA));
    }

    #[test]
    fn lcg_avoids_zero_state_lock() {
        let mut corruptor = RomCorruptor::new(0);
        assert_ne!(corruptor.next_u32(), 0);
    }
}

//! Experimental spatial bot that maps zone events to controller commands.
//!
//! The spatial bot uses `ZoneTracker` events to trigger automated inputs.

#[cfg(feature = "nova")]
use crate::Button;
#[cfg(feature = "nova")]
use crate::Command;
#[cfg(feature = "nova")]
use crate::experimental::zone_tracker::ZoneTracker;

#[cfg(feature = "nova")]
#[derive(Debug, Clone)]
pub struct BotRule {
    pub zone_id: usize,
    pub button: Button,
    pub duration_frames: u32,
}

#[cfg(feature = "nova")]
#[derive(Debug, Default, Clone)]
pub struct SpatialBot {
    rules: Vec<BotRule>,
    active_presses: std::collections::HashMap<Button, u32>,
}

#[cfg(feature = "nova")]
impl SpatialBot {
    #[must_use]
    pub fn new() -> Self {
        Self {
            rules: Vec::new(),
            active_presses: std::collections::HashMap::new(),
        }
    }

    /// Adds a new reaction rule to the bot.
    ///
    /// When the bot detects an event in the specified `zone_id`, it will press the given `button`
    /// and hold it for `duration_frames`. If the event triggers while the button is already being
    /// held, the duration is refreshed.
    ///
    /// # Examples
    ///
    /// ```
    /// # use nes_core::experimental::spatial_bot::SpatialBot;
    /// # use nes_core::Button;
    /// let mut bot = SpatialBot::new();
    /// // When an entity enters zone 1, hold the A button for 10 frames.
    /// bot.add_rule(1, Button::A, 10);
    /// ```
    pub fn add_rule(&mut self, zone_id: usize, button: Button, duration_frames: u32) {
        self.rules.push(BotRule {
            zone_id,
            button,
            duration_frames,
        });
    }

    /// Evaluates the current zone events and generates corresponding controller commands.
    ///
    /// This method checks the provided `ZoneTracker` for any active events. If an event
    /// matches a configured rule, the corresponding button is pressed, and its hold
    /// duration is updated. Buttons whose hold duration has expired are released.
    ///
    /// # Examples
    ///
    /// ```
    /// # use nes_core::experimental::spatial_bot::SpatialBot;
    /// # use nes_core::experimental::zone_tracker::ZoneTracker;
    /// # use nes_core::{Button, Command};
    /// let mut bot = SpatialBot::new();
    /// bot.add_rule(1, Button::A, 2);
    ///
    /// let mut tracker = ZoneTracker::new();
    /// // Simulate an event occurring in zone 1
    /// tracker.add_zone(1, 0, 0, 10, 10);
    /// // In reality, you'd run `tracker.track(&core)` here.
    ///
    /// // Without any actual events, evaluate will return nothing
    /// let commands = bot.evaluate(&tracker);
    /// ```
    pub fn evaluate(&mut self, tracker: &ZoneTracker) -> Vec<Command> {
        let mut commands = Vec::new();

        // 1. Process new events from the tracker
        for event in tracker.events() {
            for rule in &self.rules {
                if event.zone_id == rule.zone_id {
                    // Only issue a PressButton if we aren't already holding it
                    if !self.active_presses.contains_key(&rule.button) {
                        commands.push(Command::PressButton(rule.button));
                    }
                    // Update or insert the duration
                    self.active_presses
                        .insert(rule.button, rule.duration_frames);
                }
            }
        }

        // 2. Decrement active presses and release if 0
        // We use retain to modify the map in-place and keep only those > 0
        let mut expired = Vec::new();
        self.active_presses.retain(|button, frames_left| {
            if *frames_left > 0 {
                *frames_left -= 1;
            }
            if *frames_left == 0 {
                expired.push(*button);
                false
            } else {
                true
            }
        });

        for button in expired {
            commands.push(Command::ReleaseButton(button));
        }

        commands
    }
}

#[cfg(all(test, feature = "nova"))]
mod tests {
    use super::*;
    use crate::Command;
    use crate::NesCore;
    use crate::experimental::zone_tracker::ZoneTracker;

    #[test]
    fn test_spatial_bot_evaluation() {
        let mut core = NesCore::new();
        let mut tracker = ZoneTracker::new();
        let mut bot = SpatialBot::new();

        // Add a zone and a bot rule. Duration 2 means it is held for 2 evaluations *after* the initial event.
        tracker.add_zone(1, 100, 100, 50, 50);
        bot.add_rule(1, Button::A, 2);

        // Put a sprite inside the zone
        let mut dummy_page = [0xff; 256];
        dummy_page[0] = 120; // Y
        dummy_page[3] = 120; // X
        core.load_cpu_bytes(0x0200, &dummy_page);
        core.write_cpu_bus(0x4014, 0x02); // OAM DMA
        for _ in 0..180 {
            let _ = core.execute(Command::StepCpu);
        }

        tracker.track(&core);

        // Frame 1: Bot should press A and set duration to 2. Then duration decrements to 1.
        let cmds1 = bot.evaluate(&tracker);
        assert_eq!(cmds1.len(), 1);
        assert!(matches!(cmds1[0], Command::PressButton(Button::A)));

        // Frame 2: Bot should hold A (no new commands). Duration decrements to 0. Release happens immediately?
        // Wait, in my evaluate, decrement happens AFTER inserting.
        // Frame 1: insert 2. Decrement -> 1. Keep. (no release)
        // Frame 2: evaluate with empty_tracker. Decrement -> 0. Release.
        // Wait, the assertion failed on frame 2: left: 1, right: 0. Which means cmds2 had 1 command.

        let empty_tracker = ZoneTracker::new();
        let cmds2 = bot.evaluate(&empty_tracker);
        assert_eq!(cmds2.len(), 1);
        assert!(matches!(cmds2[0], Command::ReleaseButton(Button::A)));

        // Frame 3: Nothing.
        let cmds3 = bot.evaluate(&empty_tracker);
        assert_eq!(cmds3.len(), 0);
    }
}

//! Experimental tools for extracting sprite and tile data directly from the emulator's memory.
//!
//! This module provides utilities like [`crate::experimental::sprite_extractor::SpriteExtractor`] to parse CHR-RAM data and convert it
//! into recognizable image formats (such as BMP files). It is primarily useful for debugging,
//! automated sprite sheet generation, or external visualization tools that need to inspect
//! graphics state without manually reading individual bytes.

#[cfg(feature = "nova")]
use crate::NesCore;
#[cfg(feature = "nova")]
use crate::bmp::encode_bmp;

/// A utility for extracting CHR-RAM data from an NES core and converting it into image formats.
///
/// `SpriteExtractor` is an experimental feature that reads raw pattern tables from the PPU's memory
/// and maps the 2-bit NES color indices to a standard grayscale palette, allowing developers
/// to visualize the current tile set in standard formats like BMP.
#[cfg(feature = "nova")]
pub struct SpriteExtractor;

#[cfg(feature = "nova")]
impl SpriteExtractor {
    /// Extracts the entire CHR-RAM memory (pattern tables) and encodes it as a BMP image.
    ///
    /// This function converts the 8x8 pixel tiles stored in the NES core into a 128x256 pixel image.
    /// It is extremely useful for debugging the PPU memory visually. The 2-bit color indices
    /// are mapped to grayscale values (0, 85, 170, 255).
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_core::NesCore;
    /// use nes_core::experimental::sprite_extractor::SpriteExtractor;
    ///
    /// let core = NesCore::new();
    /// // Extract the current sprite sheet from CHR-RAM
    /// let bmp_bytes = SpriteExtractor::extract_chr_ram_bmp(&core).unwrap();
    ///
    /// // The resulting bytes contain a valid BMP file starting with the "BM" magic bytes
    /// assert_eq!(&bmp_bytes[0..2], b"BM");
    /// ```
    pub fn extract_chr_ram_bmp(core: &NesCore) -> Result<Vec<u8>, String> {
        let snapshot = core.save_state();
        let chr = snapshot.ppu.chr;

        let width = 128; // 16 tiles across
        let height = 256; // 32 tiles down

        let mut rgba = vec![0u8; width * height * 4];

        for tile_y in 0..32 {
            for tile_x in 0..16 {
                let tile_idx = tile_y * 16 + tile_x;
                let tile_addr = tile_idx * 16;

                for row in 0..8 {
                    let plane0 = chr[tile_addr + row];
                    let plane1 = chr[tile_addr + row + 8];

                    for col in 0..8 {
                        let bit0 = (plane0 >> (7 - col)) & 1;
                        let bit1 = (plane1 >> (7 - col)) & 1;
                        let color_idx = (bit1 << 1) | bit0;

                        let base_x = tile_x * 8 + col;
                        let base_y = tile_y * 8 + row;

                        let pixel_idx = (base_y * width + base_x) * 4;

                        // Simple grayscale palette mapping for raw CHR
                        let color_val = match color_idx {
                            0 => 0,
                            1 => 85,
                            2 => 170,
                            3 => 255,
                            _ => unreachable!(),
                        };

                        rgba[pixel_idx] = color_val;
                        rgba[pixel_idx + 1] = color_val;
                        rgba[pixel_idx + 2] = color_val;
                        rgba[pixel_idx + 3] = 255;
                    }
                }
            }
        }

        encode_bmp(width, height, &rgba)
    }
}

#[cfg(all(test, feature = "nova"))]
mod tests {
    use super::*;
    use crate::NesCore;

    #[test]
    fn can_extract_sprite_sheet() {
        let core = NesCore::new();
        let bmp_data = SpriteExtractor::extract_chr_ram_bmp(&core).unwrap();
        // Check BMP header magic
        assert_eq!(&bmp_data[0..2], b"BM");
    }
}

//! Experimental post-processing filters for the NES framebuffer.
//!
//! This module provides a way to apply visual themes to the raw RGBA output
//! of the PPU without modifying the core rendering logic or emulator accuracy.

#[cfg(feature = "nova")]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
/// Available visual themes that can be applied to the framebuffer.
pub enum Theme {
    /// Standard luminosity-based grayscale conversion.
    Grayscale,
    /// Classic pea-green 4-shade LCD aesthetic.
    Gameboy,
    /// Warm, vintage photograph effect.
    Sepia,
    /// High-contrast red-only display, reminiscent of the Virtual Boy.
    VirtualBoy,
}

#[cfg(feature = "nova")]
/// A stateless filter that modifies an RGBA framebuffer in place.
pub struct ThemeFilter;

#[cfg(feature = "nova")]
impl ThemeFilter {
    /// Applies a visual [`Theme`] to a raw RGBA framebuffer.
    ///
    /// The input buffer should be in `RGBA8` format (4 bytes per pixel).
    /// The alpha channel is preserved.
    ///
    /// ## Examples
    ///
    /// ```
    /// # use nes_core::experimental::theme_filter::{ThemeFilter, Theme};
    /// let mut framebuffer = vec![255, 100, 50, 255]; // Reddish pixel
    /// ThemeFilter::apply_theme(&mut framebuffer, Theme::Grayscale);
    /// assert_eq!(framebuffer[0], framebuffer[1]); // R == G
    /// assert_eq!(framebuffer[1], framebuffer[2]); // G == B
    /// ```
    pub fn apply_theme(framebuffer: &mut [u8], theme: Theme) {
        // Ensure the buffer is a valid RGBA buffer
        #[allow(clippy::manual_is_multiple_of)]
        if framebuffer.len() % 4 != 0 {
            return;
        }

        match theme {
            Theme::Grayscale => {
                for pixel in framebuffer.chunks_exact_mut(4) {
                    let r = u32::from(pixel[0]);
                    let g = u32::from(pixel[1]);
                    let b = u32::from(pixel[2]);

                    // Standard luminosity (Luma = 0.299R + 0.587G + 0.114B)
                    // Approximated with integer math: (77*R + 150*G + 29*B) >> 8
                    let luma = (r * 77 + g * 150 + b * 29) >> 8;
                    let luma = luma as u8;

                    pixel[0] = luma;
                    pixel[1] = luma;
                    pixel[2] = luma;
                }
            }
            Theme::Gameboy => {
                // Gameboy greens:
                // Darkest:  (15, 56, 15)
                // Dark:     (48, 98, 48)
                // Light:    (139, 172, 15)
                // Lightest: (155, 188, 15)
                for pixel in framebuffer.chunks_exact_mut(4) {
                    let r = u32::from(pixel[0]);
                    let g = u32::from(pixel[1]);
                    let b = u32::from(pixel[2]);

                    let luma = (r * 77 + g * 150 + b * 29) >> 8;

                    let (out_r, out_g, out_b) = if luma < 64 {
                        (15, 56, 15)
                    } else if luma < 128 {
                        (48, 98, 48)
                    } else if luma < 192 {
                        (139, 172, 15)
                    } else {
                        (155, 188, 15)
                    };

                    pixel[0] = out_r;
                    pixel[1] = out_g;
                    pixel[2] = out_b;
                }
            }
            Theme::Sepia => {
                for pixel in framebuffer.chunks_exact_mut(4) {
                    let r = f32::from(pixel[0]);
                    let g = f32::from(pixel[1]);
                    let b = f32::from(pixel[2]);

                    let tr = (r * 0.393) + (g * 0.769) + (b * 0.189);
                    let tg = (r * 0.349) + (g * 0.686) + (b * 0.168);
                    let tb = (r * 0.272) + (g * 0.534) + (b * 0.131);

                    pixel[0] = tr.min(255.0) as u8;
                    pixel[1] = tg.min(255.0) as u8;
                    pixel[2] = tb.min(255.0) as u8;
                }
            }
            Theme::VirtualBoy => {
                for pixel in framebuffer.chunks_exact_mut(4) {
                    let r = u32::from(pixel[0]);
                    let g = u32::from(pixel[1]);
                    let b = u32::from(pixel[2]);

                    let luma = (r * 77 + g * 150 + b * 29) >> 8;

                    // Virtual Boy has pure red with varying intensity
                    pixel[0] = luma.min(255) as u8;
                    pixel[1] = 0;
                    pixel[2] = 0;
                }
            }
        }
    }
}

#[cfg(all(test, feature = "nova"))]
mod tests {
    use super::*;

    #[test]
    fn grayscale_theme_converts_rgb_to_equal_values() {
        let mut frame = vec![255, 0, 0, 255, 0, 255, 0, 255];
        ThemeFilter::apply_theme(&mut frame, Theme::Grayscale);

        // Pixel 1: Pure Red
        assert_eq!(frame[0], frame[1]);
        assert_eq!(frame[1], frame[2]);
        assert_eq!(frame[3], 255); // Alpha preserved

        // Pixel 2: Pure Green
        assert_eq!(frame[4], frame[5]);
        assert_eq!(frame[5], frame[6]);
        assert_eq!(frame[7], 255); // Alpha preserved
    }

    #[test]
    fn gameboy_theme_uses_specific_palette() {
        let mut frame = vec![0, 0, 0, 255, 255, 255, 255, 255];
        ThemeFilter::apply_theme(&mut frame, Theme::Gameboy);

        // Pixel 1: Black -> Darkest Green
        assert_eq!(frame[0], 15);
        assert_eq!(frame[1], 56);
        assert_eq!(frame[2], 15);

        // Pixel 2: White -> Lightest Green
        assert_eq!(frame[4], 155);
        assert_eq!(frame[5], 188);
        assert_eq!(frame[6], 15);
    }

    #[test]
    fn virtualboy_theme_leaves_only_red_channel() {
        let mut frame = vec![100, 150, 200, 255];
        ThemeFilter::apply_theme(&mut frame, Theme::VirtualBoy);

        assert!(frame[0] > 0); // Luma applied to red
        assert_eq!(frame[1], 0); // Green cleared
        assert_eq!(frame[2], 0); // Blue cleared
    }

    #[test]
    fn sepia_theme_modifies_colors() {
        let mut frame = vec![100, 150, 200, 255];
        ThemeFilter::apply_theme(&mut frame, Theme::Sepia);

        // Ensure some color transformation happened
        assert!(frame[0] != 100 || frame[1] != 150 || frame[2] != 200);
        assert_eq!(frame[3], 255);
    }

    #[test]
    fn ignores_invalid_framebuffer() {
        let mut frame = vec![255, 255, 255]; // Missing alpha, len 3
        ThemeFilter::apply_theme(&mut frame, Theme::Grayscale);

        // Should not panic and should leave buffer unchanged
        assert_eq!(frame, vec![255, 255, 255]);
    }
}

//! Experimental spatial zone tracking for NES sprites.
//!
//! This module allows users to define rectangular "zones" on the screen and track
//! when sprites enter those zones. It builds upon `OamSpatialQuery` to monitor
//! sprite movement over time, generating events when a sprite triggers a zone.

#[cfg(feature = "nova")]
use crate::NesCore;
#[cfg(feature = "nova")]
use crate::experimental::oam_spatial_query::{OamSpatialQuery, OamSprite};

#[cfg(feature = "nova")]
#[derive(Debug, Clone, PartialEq, Eq)]
/// An event triggered when a sprite enters a defined zone.
pub struct ZoneEvent {
    /// The ID of the zone that was triggered.
    pub zone_id: usize,
    /// The sprite that entered the zone.
    pub sprite: OamSprite,
}

#[cfg(feature = "nova")]
#[derive(Debug, Clone)]
/// A defined rectangular area on the screen to monitor.
pub struct Zone {
    /// The unique identifier for this zone.
    pub id: usize,
    /// The left X coordinate of the zone bounding box.
    pub x: u8,
    /// The top Y coordinate of the zone bounding box.
    pub y: u8,
    /// The width of the zone in pixels.
    pub w: u8,
    /// The height of the zone in pixels.
    pub h: u8,
}

#[cfg(feature = "nova")]
#[derive(Debug, Default, Clone)]
/// Tracks sprites entering defined screen zones.
pub struct ZoneTracker {
    zones: Vec<Zone>,
    events: Vec<ZoneEvent>,
    /// Keeps track of which sprites were in which zones last frame to trigger only on entry.
    /// Maps zone_id to a list of sprite indices.
    active_sprites: std::collections::HashMap<usize, Vec<u8>>,
}

#[cfg(feature = "nova")]
impl ZoneTracker {
    /// Creates a new, empty `ZoneTracker`.
    #[must_use]
    pub fn new() -> Self {
        Self {
            zones: Vec::new(),
            events: Vec::new(),
            active_sprites: std::collections::HashMap::new(),
        }
    }

    /// Adds a new rectangular zone to monitor.
    pub fn add_zone(&mut self, id: usize, x: u8, y: u8, w: u8, h: u8) {
        self.zones.push(Zone { id, x, y, w, h });
        self.active_sprites.insert(id, Vec::new());
    }

    /// Evaluates the current frame's OAM against registered zones.
    ///
    /// Generates `ZoneEvent`s for any sprites that have newly entered a zone.
    pub fn track(&mut self, core: &NesCore) {
        let oam_query = OamSpatialQuery::new(core);

        for zone in &self.zones {
            let overlapping_sprites = oam_query.query_rect(zone.x, zone.y, zone.w, zone.h);

            let mut current_sprite_indices = Vec::with_capacity(overlapping_sprites.len());
            let previously_active = self.active_sprites.get(&zone.id);

            for sprite in overlapping_sprites {
                current_sprite_indices.push(sprite.index);

                // If the sprite wasn't in the zone last frame, it's a new entry event
                if previously_active.is_none_or(|prev| !prev.contains(&sprite.index)) {
                    self.events.push(ZoneEvent {
                        zone_id: zone.id,
                        sprite,
                    });
                }
            }

            // Update active sprites for this zone for the next frame
            self.active_sprites.insert(zone.id, current_sprite_indices);
        }
    }

    /// Returns a slice of all recorded `ZoneEvent`s.
    #[must_use]
    pub fn events(&self) -> &[ZoneEvent] {
        &self.events
    }
}

#[cfg(all(test, feature = "nova"))]
mod tests {
    use super::*;
    use crate::Command;

    #[test]
    fn test_zone_tracker_entry_events() {
        let mut core = NesCore::new();
        let mut tracker = ZoneTracker::new();

        // Add a zone in the middle of the screen
        tracker.add_zone(1, 100, 100, 50, 50);

        // Put a sprite outside the zone
        let mut dummy_page = [0xff; 256];
        dummy_page[0] = 50; // Y
        dummy_page[3] = 50; // X
        core.load_cpu_bytes(0x0200, &dummy_page);
        core.write_cpu_bus(0x4014, 0x02); // OAM DMA
        for _ in 0..180 {
            let _ = core.execute(Command::StepCpu);
        }

        tracker.track(&core);
        assert_eq!(
            tracker.events().len(),
            0,
            "No event should be triggered when sprite is outside"
        );

        // Move sprite into the zone
        dummy_page[0] = 120; // Y
        dummy_page[3] = 120; // X
        core.load_cpu_bytes(0x0200, &dummy_page);
        core.write_cpu_bus(0x4014, 0x02); // OAM DMA
        for _ in 0..180 {
            let _ = core.execute(Command::StepCpu);
        }

        tracker.track(&core);
        assert_eq!(
            tracker.events().len(),
            1,
            "Event should be triggered on entry"
        );
        assert_eq!(tracker.events()[0].zone_id, 1);
        assert_eq!(tracker.events()[0].sprite.index, 0);

        // Keep sprite in the zone
        core.write_cpu_bus(0x4014, 0x02); // OAM DMA
        for _ in 0..180 {
            let _ = core.execute(Command::StepCpu);
        }

        tracker.track(&core);
        assert_eq!(
            tracker.events().len(),
            1,
            "No new event should be triggered if already inside"
        );

        // Move sprite out, then back in
        dummy_page[0] = 50; // Y
        dummy_page[3] = 50; // X
        core.load_cpu_bytes(0x0200, &dummy_page);
        core.write_cpu_bus(0x4014, 0x02); // OAM DMA
        for _ in 0..180 {
            let _ = core.execute(Command::StepCpu);
        }
        tracker.track(&core); // Out

        dummy_page[0] = 120; // Y
        dummy_page[3] = 120; // X
        core.load_cpu_bytes(0x0200, &dummy_page);
        core.write_cpu_bus(0x4014, 0x02); // OAM DMA
        for _ in 0..180 {
            let _ = core.execute(Command::StepCpu);
        }
        tracker.track(&core); // In

        assert_eq!(
            tracker.events().len(),
            2,
            "Second event should be triggered on re-entry"
        );
    }
}

