use crate::rom::NametableMirroring;
use serde::{Deserialize, Serialize};

use super::Mapper;

const PRG_BANK_32K: usize = 32 * 1024;

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
/// Mapper 7 (AxROM): switchable 32KB PRG bank with one-screen mirroring control.
pub struct Axrom {
    bank_count: u8,
    selected_bank: u8,
    selected_nametable_bank: u8,
    prg_rom: Vec<u8>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub(crate) struct AxromState {
    pub selected_bank: u8,
    pub selected_nametable_bank: u8,
}

impl Axrom {
    /// Builds AxROM from raw PRG ROM bytes.
    ///
    /// If fewer than 32KB are provided, the bank is zero-padded so reads stay
    /// in-bounds across the full `$8000..=$FFFF` PRG window.
    #[must_use]
    pub fn from_prg_rom(mut prg_rom: Vec<u8>) -> Self {
        if prg_rom.len() < PRG_BANK_32K {
            prg_rom.resize(PRG_BANK_32K, 0);
        }
        let bank_count = (prg_rom.len() / PRG_BANK_32K) as u8;
        Self {
            bank_count: bank_count.max(1),
            selected_bank: 0,
            selected_nametable_bank: 0,
            prg_rom,
        }
    }

    /// Returns the currently selected 32KB PRG bank.
    #[must_use]
    pub fn selected_bank(&self) -> u8 {
        self.selected_bank
    }

    /// Returns the selected nametable page for one-screen mirroring.
    ///
    /// `0` maps all nametables to the first page, `1` to the second.
    #[must_use]
    pub fn selected_nametable_bank(&self) -> u8 {
        self.selected_nametable_bank
    }

    #[must_use]
    pub(crate) fn state(&self) -> AxromState {
        AxromState {
            selected_bank: self.selected_bank,
            selected_nametable_bank: self.selected_nametable_bank,
        }
    }

    pub(crate) fn restore_state(&mut self, state: AxromState) {
        self.selected_bank = state.selected_bank % self.bank_count;
        self.selected_nametable_bank = state.selected_nametable_bank & 0x01;
    }

    /// Returns the active one-screen nametable mirroring mode.
    #[must_use]
    pub fn mirroring(&self) -> NametableMirroring {
        if self.selected_nametable_bank == 0 {
            NametableMirroring::OneScreenLower
        } else {
            NametableMirroring::OneScreenUpper
        }
    }

    /// Reads PRG byte through current AxROM 32KB mapping.
    #[must_use]
    pub fn read_prg(&self, addr: u16) -> u8 {
        <Self as Mapper>::read_prg(self, addr)
    }
    /// Applies AxROM bank/mirroring register writes.
    pub fn write_prg(&mut self, addr: u16, value: u8) {
        <Self as Mapper>::write_prg(self, addr, value);
    }

    fn bank_offset(&self, bank: u8) -> usize {
        usize::from(bank) * PRG_BANK_32K
    }
}

impl Mapper for Axrom {
    fn read_prg(&self, addr: u16) -> u8 {
        let within_bank = usize::from(addr) & 0x7FFF;
        let offset = self.bank_offset(self.selected_bank) + within_bank;
        self.prg_rom[offset]
    }

    fn write_prg(&mut self, _addr: u16, value: u8) {
        self.selected_bank = (value & 0x07) % self.bank_count;
        self.selected_nametable_bank = (value >> 4) & 0x01;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn axrom_state_can_be_restored() {
        let prg = vec![0_u8; 64 * 1024];
        let mut mapper = Axrom::from_prg_rom(prg);

        mapper.write_prg(0x8000, 0x11);

        let state = mapper.state();

        let mut mapper_restored = Axrom::from_prg_rom(vec![0_u8; 64 * 1024]);
        mapper_restored.restore_state(state);

        assert_eq!(mapper.selected_bank(), mapper_restored.selected_bank());
        assert_eq!(
            mapper.selected_nametable_bank(),
            mapper_restored.selected_nametable_bank()
        );
    }

    #[test]
    fn axrom_mirroring_reflects_selected_nametable_bank() {
        let mut mapper = Axrom::from_prg_rom(vec![0_u8; 32 * 1024]);

        mapper.write_prg(0x8000, 0x00);
        assert_eq!(mapper.mirroring(), NametableMirroring::OneScreenLower);

        mapper.write_prg(0x8000, 0x10);
        assert_eq!(mapper.mirroring(), NametableMirroring::OneScreenUpper);
    }
}

use super::Mapper;
use serde::{Deserialize, Serialize};

const CHR_WINDOW_BYTES: usize = 8 * 1024;

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
/// Mapper 3 (CNROM): fixed PRG mapping with switchable 8KB CHR banks.
pub struct Cnrom {
    selected_chr_bank: u8,
    chr_bank_count: usize,
    prg_rom: Vec<u8>,
    chr_data: Vec<u8>,
    chr_writable: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub(crate) struct CnromState {
    pub selected_chr_bank: u8,
}

impl Cnrom {
    /// Builds CNROM from raw PRG/CHR data.
    ///
    /// Empty CHR initializes one writable 8KB CHR-RAM window.
    ///
    /// Inputs are normalized to avoid panics in mapper operations:
    /// - Empty PRG is treated as a single zero byte.
    /// - CHR length is padded to a full 8KB window when needed.
    #[must_use]
    pub fn from_prg_chr(mut prg_rom: Vec<u8>, chr_rom: Vec<u8>) -> Self {
        if prg_rom.is_empty() {
            prg_rom.push(0);
        }

        let (mut chr_data, chr_writable) = if chr_rom.is_empty() {
            (vec![0_u8; CHR_WINDOW_BYTES], true)
        } else {
            (chr_rom, false)
        };
        let remainder = chr_data.len() % CHR_WINDOW_BYTES;
        if remainder != 0 {
            chr_data.resize(chr_data.len() + (CHR_WINDOW_BYTES - remainder), 0);
        }
        let chr_bank_count = (chr_data.len() / CHR_WINDOW_BYTES).max(1);
        Self {
            selected_chr_bank: 0,
            chr_bank_count,
            prg_rom,
            chr_data,
            chr_writable,
        }
    }

    /// Returns the currently selected CHR bank.
    #[must_use]
    pub fn selected_chr_bank(&self) -> u8 {
        self.selected_chr_bank
    }

    #[must_use]
    pub(crate) fn state(&self) -> CnromState {
        CnromState {
            selected_chr_bank: self.selected_chr_bank,
        }
    }

    pub(crate) fn restore_state(&mut self, state: CnromState) {
        self.selected_chr_bank = (usize::from(state.selected_chr_bank) % self.chr_bank_count) as u8;
    }

    /// Returns the currently mapped 8KB CHR window.
    #[must_use]
    pub fn chr_window(&self) -> [u8; CHR_WINDOW_BYTES] {
        let mut window = [0_u8; CHR_WINDOW_BYTES];
        let start = usize::from(self.selected_chr_bank) * CHR_WINDOW_BYTES;
        let end = start + CHR_WINDOW_BYTES;
        if let Some(mapped_window) = self.chr_data.get(start..end) {
            window.copy_from_slice(mapped_window);
        }
        window
    }

    /// Returns `true` when CHR should be writable by the PPU.
    #[must_use]
    pub fn chr_writable(&self) -> bool {
        self.chr_writable
    }

    /// Synchronizes writable CHR-RAM from the current PPU window.
    pub fn sync_chr_ram_from_ppu_window(&mut self, window: &[u8; CHR_WINDOW_BYTES]) {
        if !self.chr_writable {
            return;
        }

        let start = usize::from(self.selected_chr_bank) * CHR_WINDOW_BYTES;
        let end = start + CHR_WINDOW_BYTES;
        self.chr_data[start..end].copy_from_slice(window);
    }

    /// Reads PRG using fixed CNROM PRG mapping.
    #[must_use]
    pub fn read_prg(&self, addr: u16) -> u8 {
        <Self as Mapper>::read_prg(self, addr)
    }

    /// Applies PRG-space write as CHR bank select.
    pub fn write_prg(&mut self, addr: u16, value: u8) {
        <Self as Mapper>::write_prg(self, addr, value);
    }

    fn prg_offset_for(&self, addr: u16) -> usize {
        if self.prg_rom.is_empty() {
            return 0;
        }
        let base = addr.saturating_sub(0x8000) as usize;
        base % self.prg_rom.len()
    }
}

impl Mapper for Cnrom {
    fn read_prg(&self, addr: u16) -> u8 {
        self.prg_rom[self.prg_offset_for(addr)]
    }

    fn write_prg(&mut self, _addr: u16, value: u8) {
        self.selected_chr_bank = (usize::from(value) % self.chr_bank_count) as u8;
    }
}

