//! Hardware audio abstraction and playback pipeline.
//!
//! This module acts as the bridge between the raw audio samples generated by `nes-core`
//! and the host operating system's audio hardware. It handles queuing, buffering, and
//! backpressure to ensure smooth audio playback without stuttering or overwhelming the
//! audio device.
//!
//! The core of the module is the [`crate::audio::AudioOutput`] struct, which manages the audio stream
//! and sink. It uses a trait-based approach ([`crate::audio::AudioSinkControl`]) to allow decoupling
//! the underlying audio library (`rodio`) for testing purposes.

use nes_core::AUDIO_SAMPLE_RATE;
use rodio::buffer::SamplesBuffer;
use rodio::{OutputStream, Sink};

/// The maximum number of audio chunks that can be queued before applying backpressure.
///
/// If the queue is full, further audio samples will be dropped to maintain low latency.
pub const MAX_AUDIO_QUEUE_CHUNKS: usize = 8;

/// The number of audio channels used by the NES (mono output).
pub const AUDIO_CHANNELS: u16 = 1;

/// Defines the required operations for interacting with an audio sink.
///
/// This trait exists primarily to decouple the `nes-desktop` audio pipeline
/// from the underlying `rodio::Sink` implementation. By defining a trait,
/// we can mock the audio sink in tests (e.g., `FakeAudioSink`), ensuring
/// the queue logic and backpressure can be tested without needing actual
/// audio hardware or generating noise during test runs.
pub trait AudioSinkControl {
    /// Returns the number of unplayed audio chunks currently queued.
    fn queue_len(&self) -> usize;

    /// Appends a new chunk of 16-bit PCM samples to the playback queue.
    fn append_i16(&self, samples: Vec<i16>);

    /// Clears all queued audio chunks.
    fn clear(&self);

    /// Stops playback and mutes the output.
    fn stop(&self);
}

/// A concrete implementation of [`crate::audio::AudioSinkControl`] that wraps a `rodio::Sink`.
///
/// This struct adapts the standard `rodio` sink interface into our application's
/// required trait, allowing it to be used dynamically via dynamic dispatch (`Box<dyn AudioSinkControl>`).
pub struct RodioSinkAdapter {
    inner: Sink,
}

impl AudioSinkControl for RodioSinkAdapter {
    fn queue_len(&self) -> usize {
        self.inner.len()
    }

    fn append_i16(&self, samples: Vec<i16>) {
        self.inner.append(SamplesBuffer::new(
            AUDIO_CHANNELS,
            AUDIO_SAMPLE_RATE,
            samples,
        ));
    }

    fn clear(&self) {
        self.inner.clear();
    }

    fn stop(&self) {
        self.inner.stop();
    }
}

/// Manages the playback of NES audio samples to the host system's audio device.
///
/// `AudioOutput` queues PCM chunks generated by the emulator core. To prevent memory
/// exhaustion and maintain low latency between the emulator state and heard audio,
/// it limits the queue to [`MAX_AUDIO_QUEUE_CHUNKS`]. When the queue is full,
/// backpressure is applied and further samples are dropped until space frees up.
///
/// ## Examples
/// ```no_run
/// use nes_desktop::audio::AudioOutput;
///
/// // Initialize the audio system.
/// let mut audio = AudioOutput::try_new().expect("Failed to open audio device");
///
/// // Queue a chunk of 16-bit PCM data generated by the APU.
/// let pcm_data = vec![0i16; 1024]; // Silence
/// audio.queue_samples(pcm_data);
/// ```
pub struct AudioOutput {
    sink: Box<dyn AudioSinkControl>,
    _stream: Option<OutputStream>,
}

impl AudioOutput {
    /// Creates a new `AudioOutput` with a provided sink and an optional stream.
    ///
    /// This is primarily used for dependency injection during testing (e.g., passing a
    /// mock sink). For normal usage, prefer [`try_new`](Self::try_new).
    pub fn new_with_sink(sink: Box<dyn AudioSinkControl>, stream: Option<OutputStream>) -> Self {
        Self {
            sink,
            _stream: stream,
        }
    }

    /// Attempts to initialize the host OS audio output.
    ///
    /// ## Errors
    /// Returns an error message if the default audio output device cannot be found
    /// or if the `rodio` sink fails to initialize (e.g., if the host environment
    /// has no audio hardware or permissions).
    pub fn try_new() -> Result<Self, String> {
        let (stream, handle) = OutputStream::try_default()
            .map_err(|err| format!("Audio output init failed: {err}"))?;
        let sink =
            Sink::try_new(&handle).map_err(|err| format!("Audio sink init failed: {err}"))?;
        let sink_adapter = RodioSinkAdapter { inner: sink };
        Ok(Self::new_with_sink(Box::new(sink_adapter), Some(stream)))
    }

    /// Queues a chunk of PCM audio samples for playback.
    ///
    /// If the internal sink queue has reached [`MAX_AUDIO_QUEUE_CHUNKS`], backpressure
    /// occurs: the incoming `samples` are immediately discarded and `false` is returned.
    /// This prevents unbounded memory growth and keeps the audio latency tight.
    ///
    /// ## Examples
    /// ```rust
    /// use nes_desktop::audio::{AudioOutput, AudioSinkControl};
    ///
    /// struct DummySink;
    /// impl AudioSinkControl for DummySink {
    ///     fn queue_len(&self) -> usize { 0 }
    ///     fn append_i16(&self, _samples: Vec<i16>) {}
    ///     fn clear(&self) {}
    ///     fn stop(&self) {}
    /// }
    ///
    /// let audio = AudioOutput::new_with_sink(Box::new(DummySink), None);
    ///
    /// // Queuing samples succeeds as the queue is empty
    /// let samples = vec![0_i16; 100];
    /// assert!(audio.queue_samples(samples));
    /// ```
    pub fn queue_samples(&self, samples: Vec<i16>) -> bool {
        if self.sink.queue_len() >= MAX_AUDIO_QUEUE_CHUNKS {
            return false;
        }
        self.sink.append_i16(samples);
        true
    }

    /// Returns the number of unplayed audio chunks currently queued.
    ///
    /// The maximum length is determined by [`MAX_AUDIO_QUEUE_CHUNKS`].
    pub fn queue_len(&self) -> usize {
        self.sink.queue_len()
    }

    /// Abruptly clears the entire playback queue.
    ///
    /// The audio device will stop playing the current buffer and silence will follow until
    /// more samples are queued. This is useful for stopping output instantly or resynchronizing
    /// the emulator with the audio stream.
    pub fn clear(&self) {
        self.sink.clear();
    }
}

impl Drop for AudioOutput {
    fn drop(&mut self) {
        // Ensure sink teardown happens while the stream backend is still alive.
        self.sink.stop();
    }
}

#[cfg(test)]
pub(crate) mod tests {
    use super::*;
    use std::sync::{Arc, Mutex};

    #[derive(Default)]
    pub struct FakeAudioState {
        pub queue_len: usize,
        pub append_calls: usize,
        pub appended_sample_count: usize,
        pub clear_calls: usize,
        pub stop_calls: usize,
    }

    /// A mock implementation of [`crate::audio::AudioSinkControl`] for unit testing without audio hardware.
    ///
    /// The `FakeAudioSink` captures all interactions (queueing samples, clearing, stopping)
    /// into a shared `FakeAudioState`. This allows tests to assert that the `AudioOutput`
    /// correctly forwards commands or applies backpressure without needing a real `rodio::Sink`.
    pub struct FakeAudioSink {
        pub state: Arc<Mutex<FakeAudioState>>,
    }

    impl FakeAudioSink {
        /// Creates a new `FakeAudioSink` with a starting queue length and returns
        /// a shared handle to its state.
        ///
        /// The `initial_len` parameter is typically used to simulate a full queue
        /// to test backpressure logic.
        pub fn with_len(initial_len: usize) -> (Self, Arc<Mutex<FakeAudioState>>) {
            let state = Arc::new(Mutex::new(FakeAudioState {
                queue_len: initial_len,
                ..Default::default()
            }));
            (
                Self {
                    state: Arc::clone(&state),
                },
                state,
            )
        }
    }

    impl AudioSinkControl for FakeAudioSink {
        fn queue_len(&self) -> usize {
            self.state
                .lock()
                .expect("fake audio state lock should not poison")
                .queue_len
        }

        fn append_i16(&self, samples: Vec<i16>) {
            let mut state = self
                .state
                .lock()
                .expect("fake audio state lock should not poison");
            state.append_calls = state.append_calls.saturating_add(1);
            state.appended_sample_count = state.appended_sample_count.saturating_add(samples.len());
            state.queue_len = state.queue_len.saturating_add(1);
        }

        fn stop(&self) {
            let mut state = self
                .state
                .lock()
                .expect("fake audio state lock should not poison");
            state.stop_calls = state.stop_calls.saturating_add(1);
        }

        fn clear(&self) {
            let mut state = self
                .state
                .lock()
                .expect("fake audio state lock should not poison");
            state.clear_calls = state.clear_calls.saturating_add(1);
            state.queue_len = 0;
        }
    }

    #[test]
    fn audio_output_queue_and_drop_behave_with_fake_sink() {
        let (fake_sink, shared_state) = FakeAudioSink::with_len(MAX_AUDIO_QUEUE_CHUNKS - 1);
        let output = AudioOutput::new_with_sink(Box::new(fake_sink), None);

        assert!(output.queue_samples(vec![1_i16, 2, 3]));
        assert_eq!(output.queue_len(), MAX_AUDIO_QUEUE_CHUNKS);

        let state_after_queue = shared_state
            .lock()
            .expect("fake audio state lock should not poison");
        assert_eq!(state_after_queue.append_calls, 1);
        assert_eq!(state_after_queue.appended_sample_count, 3);
        drop(state_after_queue);

        drop(output);
        let state_after_drop = shared_state
            .lock()
            .expect("fake audio state lock should not poison");
        assert_eq!(state_after_drop.stop_calls, 1);
    }

    #[test]
    fn audio_output_rejects_samples_when_queue_is_full() {
        let (fake_sink, shared_state) = FakeAudioSink::with_len(MAX_AUDIO_QUEUE_CHUNKS);
        let output = AudioOutput::new_with_sink(Box::new(fake_sink), None);

        assert!(!output.queue_samples(vec![1_i16, 2, 3]));
        assert_eq!(output.queue_len(), MAX_AUDIO_QUEUE_CHUNKS);

        let state = shared_state
            .lock()
            .expect("fake audio state lock should not poison");
        assert_eq!(state.append_calls, 0);
    }

    #[test]
    fn audio_output_clear_forwards_to_sink_and_empties_queue() {
        let (fake_sink, shared_state) = FakeAudioSink::with_len(3);
        let output = AudioOutput::new_with_sink(Box::new(fake_sink), None);

        output.clear();

        let state = shared_state
            .lock()
            .expect("fake audio state lock should not poison");
        assert_eq!(state.clear_calls, 1);
        assert_eq!(state.queue_len, 0);
    }

    #[test]
    fn rodio_sink_adapter_forwards_append_and_queue_len() {
        let (sink, _queue_rx) = Sink::new_idle();
        let adapter = RodioSinkAdapter { inner: sink };

        assert_eq!(adapter.queue_len(), 0);
        adapter.append_i16(vec![1_i16, 2, 3, 4]);
        assert_eq!(adapter.queue_len(), 1);
        adapter.append_i16(vec![5_i16, 6, 7, 8]);
        assert_eq!(adapter.queue_len(), 2);
    }

    #[test]
    fn rodio_sink_adapter_stop_mutes_idle_queue_output() {
        let (sink, mut queue_rx) = Sink::new_idle();
        let adapter = RodioSinkAdapter { inner: sink };

        adapter.append_i16(vec![i16::MAX; 5_000]);
        assert_eq!(
            queue_rx.next(),
            Some(0.999_969_5),
            "i16::MAX should map to a non-zero sample before stop"
        );

        adapter.stop();

        let saw_silence = (0..600).any(|_| queue_rx.next() == Some(0.0));
        assert!(saw_silence, "stop should silence the queued source");
    }
}

#[cfg(feature = "nova")]
use nes_core::{Button, Command, NesCore};
#[cfg(feature = "nova")]
use rand::Rng;

/// A simplistic, automated player that periodically injects random inputs into the emulator.
///
/// This is used primarily in experimental/nova builds to generate chaos or background activity
/// without requiring human interaction.
///
/// ## Examples
///
/// ```
/// use nes_core::NesCore;
/// use nes_desktop::auto_player::AutoPlayer;
///
/// let mut core = NesCore::new();
/// let mut auto_player = AutoPlayer::new();
///
/// // Step the emulator and allow the auto player to generate inputs
/// auto_player.step(&mut core);
/// ```
#[cfg(feature = "nova")]
pub struct AutoPlayer {
    frame_counter: u64,
    current_buttons: u8,
}

#[cfg(feature = "nova")]
impl AutoPlayer {
    /// Creates a new `AutoPlayer` with internal frame counters reset.
    pub fn new() -> Self {
        Self {
            frame_counter: 0,
            current_buttons: 0,
        }
    }

    /// Updates the auto player's internal state and injects input commands into the `NesCore`
    /// if an input interval has elapsed.
    pub fn step(&mut self, core: &mut NesCore) {
        self.frame_counter = self.frame_counter.wrapping_add(1);

        // Update inputs every 10 frames
        #[allow(clippy::manual_is_multiple_of)]
        if self.frame_counter % 10 == 0 {
            let mut rng = rand::thread_rng();
            let new_buttons: u8 = rng.r#gen(); // Randomly press any buttons

            // Compare new_buttons with current_buttons to send Press/Release commands
            for button in [
                Button::A,
                Button::B,
                Button::Select,
                Button::Start,
                Button::Up,
                Button::Down,
                Button::Left,
                Button::Right,
            ] {
                let mask = button.bit_mask();
                let was_pressed = (self.current_buttons & mask) != 0;
                let is_pressed = (new_buttons & mask) != 0;

                if is_pressed && !was_pressed {
                    let _ = core.execute(Command::PressButton(button));
                } else if !is_pressed && was_pressed {
                    let _ = core.execute(Command::ReleaseButton(button));
                }
            }

            self.current_buttons = new_buttons;
        }
    }
}

#[cfg(all(test, feature = "nova"))]
mod tests {
    use super::*;

    #[test]
    fn auto_player_injects_inputs() {
        let mut core = NesCore::new();
        let mut auto_player = AutoPlayer::new();

        let initial_buttons = core.controller_bits();
        assert_eq!(initial_buttons, 0);

        // Step auto player multiple times to trigger an input generation
        for _ in 0..10 {
            auto_player.step(&mut core);
        }

        // Auto player uses random inputs, so it could technically generate 0,
        // but it's highly likely to generate a non-zero input over a few 10-frame intervals.
        // We'll run it a bit more to ensure an input is generated.
        let mut buttons_pressed = core.controller_bits();
        for _ in 0..100 {
            auto_player.step(&mut core);
            buttons_pressed |= core.controller_bits();
        }

        // At least one button should have been pressed over 11 input cycles
        assert!(buttons_pressed != 0);
    }
}

use std::env;
use std::path::PathBuf;

use nes_config::{
    DEFAULT_CONFIG_PATH, NesConfig, StepModeConfig, normalize_nonzero_u32, normalize_nonzero_u64,
    parse_config_path_arg,
};

use crate::netplay::NetplayRuntimeConfig;
use nes_desktop::args::parse_runtime_args;
use nes_desktop::rta::{DEFAULT_RTA_PROFILES_DIR, DEFAULT_RTA_RUNS_DIR, RtaRuntimeConfig};

pub const DEFAULT_CPU_STEPS_PER_FRAME: u32 = 10_000;
pub const DEFAULT_WINDOW_SCALE: u32 = 3;
pub const DEFAULT_TRACE_EVERY_FRAMES: u64 = 0;
pub const DEFAULT_CAPTURE_EVERY_FRAMES: u64 = 1;

pub(crate) struct RuntimeConfig {
    pub(crate) rom_path: String,
    pub(crate) cheat_codes: Vec<String>,
    pub(crate) window_scale: u32,
    pub(crate) step_mode: StepMode,
    pub(crate) audio_enabled: bool,
    pub(crate) trace_every_frames: u64,
    pub(crate) metrics_enabled: bool,
    pub(crate) metrics_every_frames: u64,
    pub(crate) capture: Option<CaptureConfig>,
    pub(crate) loaded_config_path: Option<PathBuf>,
    pub(crate) mcp_enabled: bool,
    pub(crate) mcp_bind_addr: String,
    pub(crate) netplay: Option<NetplayRuntimeConfig>,
    pub(crate) rta: Option<RtaRuntimeConfig>,
    #[cfg(feature = "nova")]
    pub(crate) auto_player_enabled: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum StepMode {
    CpuBudget(u32),
    Frame,
}

#[derive(Debug, Clone)]
pub(crate) struct CaptureConfig {
    pub(crate) path_template: String,
    pub(crate) every_n_frames: u64,
}

pub(crate) fn netplay_feature_enabled(runtime_flag: bool, config_flag: bool) -> bool {
    runtime_flag || config_flag
}

pub(crate) fn capture_config_from_parts(
    path_template: Option<String>,
    every_n_frames: u64,
) -> Option<CaptureConfig> {
    let template = path_template?;
    if template.trim().is_empty() {
        return None;
    }
    Some(CaptureConfig {
        path_template: template,
        every_n_frames: normalize_nonzero_u64(every_n_frames, DEFAULT_CAPTURE_EVERY_FRAMES),
    })
}

pub(crate) fn resolve_runtime_config() -> Result<RuntimeConfig, String> {
    let raw_args: Vec<String> = env::args().skip(1).collect();
    let (config_path, pass_through) = parse_config_path_arg(&raw_args)?;
    let runtime_args = parse_runtime_args(&pass_through)?;

    let loaded_config_path = config_path.clone().or_else(|| {
        let default_path = PathBuf::from(DEFAULT_CONFIG_PATH);
        if default_path.exists() {
            Some(default_path)
        } else {
            None
        }
    });
    let config = NesConfig::load_or_default(config_path.as_deref())?;

    let rom_path = runtime_args
        .rom_path
        .or_else(|| config.desktop.rom_path.clone())
        .or_else(|| config.roms.smb.clone())
        .ok_or_else(|| {
            use crossterm::style::Stylize;
            format!(
                "{} ROM path not configured.\n{} Provide a positional ROM argument or set `desktop.rom_path`/`roms.smb` in {DEFAULT_CONFIG_PATH}.",
                "Error:".with(crossterm::style::Color::Red).bold(),
                "Hint:".with(crossterm::style::Color::Cyan).bold()
            )
        })?;
    let window_scale = normalize_nonzero_u32(config.desktop.window_scale, DEFAULT_WINDOW_SCALE);
    let cpu_steps_per_frame = normalize_nonzero_u32(
        config.desktop.cpu_steps_per_frame,
        DEFAULT_CPU_STEPS_PER_FRAME,
    );
    let trace_every_frames = normalize_nonzero_u64(
        config.desktop.trace_every_frames,
        DEFAULT_TRACE_EVERY_FRAMES,
    );
    let metrics_every_frames = normalize_nonzero_u64(config.desktop.metrics_every_frames, 60);
    let capture = capture_config_from_parts(
        config.desktop.capture_path_template,
        config.desktop.capture_every_frames,
    );
    let netplay_enabled =
        netplay_feature_enabled(runtime_args.netplay_enabled, config.netplay.enabled);
    let step_mode = if netplay_enabled {
        StepMode::Frame
    } else {
        match config.desktop.step_mode {
            StepModeConfig::Frame => StepMode::Frame,
            StepModeConfig::Cpu => StepMode::CpuBudget(cpu_steps_per_frame),
        }
    };

    let netplay = if netplay_enabled {
        let relay_addr = runtime_args
            .netplay_relay_addr
            .or_else(|| Some(config.netplay.relay_addr.clone()))
            .unwrap_or_default();
        let room = runtime_args
            .netplay_room
            .or_else(|| Some(config.netplay.room.clone()))
            .unwrap_or_default();
        let player = runtime_args.netplay_player.unwrap_or(config.netplay.player);
        let input_delay_frames = runtime_args
            .netplay_input_delay_frames
            .unwrap_or(config.netplay.input_delay_frames);
        let max_rollback_frames = runtime_args
            .netplay_max_rollback_frames
            .unwrap_or(config.netplay.max_rollback_frames);
        let hash_check_every_frames = runtime_args
            .netplay_hash_check_every_frames
            .unwrap_or(config.netplay.hash_check_every_frames);
        if room.trim().is_empty() {
            return Err("netplay room cannot be empty".to_owned());
        }
        Some(NetplayRuntimeConfig {
            relay_addr,
            room,
            player,
            input_delay_frames,
            max_rollback_frames,
            hash_check_every_frames,
        })
    } else {
        None
    };
    let rta_enabled = runtime_args.rta_enabled
        || runtime_args.rta_profile_id.is_some()
        || runtime_args.rta_profiles_dir.is_some()
        || runtime_args.rta_runs_dir.is_some()
        || runtime_args.rta_calibrate;
    let rta = if rta_enabled {
        Some(RtaRuntimeConfig {
            profile_id_override: runtime_args.rta_profile_id.clone(),
            profiles_dir: PathBuf::from(
                runtime_args
                    .rta_profiles_dir
                    .clone()
                    .unwrap_or_else(|| DEFAULT_RTA_PROFILES_DIR.to_owned()),
            ),
            runs_dir: PathBuf::from(
                runtime_args
                    .rta_runs_dir
                    .clone()
                    .unwrap_or_else(|| DEFAULT_RTA_RUNS_DIR.to_owned()),
            ),
            calibrate: runtime_args.rta_calibrate,
        })
    } else {
        None
    };

    Ok(RuntimeConfig {
        rom_path,
        cheat_codes: runtime_args.cheat_codes,
        window_scale,
        step_mode,
        audio_enabled: config.desktop.audio_enabled,
        trace_every_frames,
        metrics_enabled: config.desktop.metrics_enabled,
        metrics_every_frames,
        capture,
        loaded_config_path,
        mcp_enabled: runtime_args.mcp_enabled,
        mcp_bind_addr: runtime_args.mcp_bind_addr,
        netplay,
        rta,
        #[cfg(feature = "nova")]
        auto_player_enabled: runtime_args.auto_player_enabled,
    })
}

use gilrs::GamepadId;
use nes_core::{Button, Command};

pub const GAMEPAD_AXIS_THRESHOLD: f32 = 0.5;

pub const CONTROLLER_BUTTONS: [Button; 8] = [
    Button::A,
    Button::B,
    Button::Select,
    Button::Start,
    Button::Up,
    Button::Down,
    Button::Left,
    Button::Right,
];

#[derive(Debug, Clone, Copy, Default)]
pub struct GamepadSnapshot {
    pub connected: bool,
    pub south_pressed: bool,
    pub east_pressed: bool,
    pub west_pressed: bool,
    pub north_pressed: bool,
    pub select_pressed: bool,
    pub start_pressed: bool,
    pub dpad_up_pressed: bool,
    pub dpad_down_pressed: bool,
    pub dpad_left_pressed: bool,
    pub dpad_right_pressed: bool,
    pub left_x: f32,
    pub left_y: f32,
}

/// Filters a list of gamepads to return only those that are currently connected.
///
/// This is a convenience helper used when polling gamepads from `gilrs` to
/// easily collect the IDs of active controllers.
///
/// # Examples
/// ```
/// use gilrs::GamepadId;
/// use nes_desktop::gamepad::connected_gamepad_ids;
///
/// // Unsafe is used here only to mock Gilrs' opaque `GamepadId` for the doctest.
/// let id0 = unsafe { std::mem::transmute::<usize, GamepadId>(0) };
/// let id1 = unsafe { std::mem::transmute::<usize, GamepadId>(1) };
/// let id2 = unsafe { std::mem::transmute::<usize, GamepadId>(2) };
///
/// let gamepads = vec![(id0, true), (id1, false), (id2, true)];
/// let connected = connected_gamepad_ids(gamepads);
///
/// assert_eq!(connected.len(), 2);
/// assert!(connected.contains(&id0));
/// assert!(connected.contains(&id2));
/// ```
pub fn connected_gamepad_ids(
    gamepads: impl IntoIterator<Item = (GamepadId, bool)>,
) -> Vec<GamepadId> {
    gamepads
        .into_iter()
        .filter_map(|(id, connected)| connected.then_some(id))
        .collect()
}

/// Selects up to two active gamepads to assign to Player 1 and Player 2.
///
/// This function prioritizes keeping currently assigned gamepads in their
/// respective slots if they are still connected. If a slot is empty and
/// there are unassigned connected gamepads available, it will fill the slot.
///
/// # Examples
/// ```
/// use gilrs::GamepadId;
/// use nes_desktop::gamepad::select_active_gamepad_ids;
///
/// let id0 = unsafe { std::mem::transmute::<usize, GamepadId>(0) };
/// let id1 = unsafe { std::mem::transmute::<usize, GamepadId>(1) };
///
/// let connected = vec![id0, id1];
/// // Currently, no controllers are assigned.
/// let current = [None, None];
///
/// let next = select_active_gamepad_ids(&connected, current);
/// assert_eq!(next[0], Some(id0));
/// assert_eq!(next[1], Some(id1));
/// ```
pub fn select_active_gamepad_ids(
    connected: &[GamepadId],
    current: [Option<GamepadId>; 2],
) -> [Option<GamepadId>; 2] {
    let mut next = [None::<GamepadId>; 2];

    for player in 0..next.len() {
        if let Some(gamepad_id) = current[player]
            && connected.contains(&gamepad_id)
            && !next.contains(&Some(gamepad_id))
        {
            next[player] = Some(gamepad_id);
        }
    }

    for &gamepad_id in connected {
        if next.iter().all(|slot| *slot != Some(gamepad_id))
            && let Some(slot) = next.iter_mut().find(|slot| slot.is_none())
        {
            *slot = Some(gamepad_id);
        }
    }

    next
}

/// Converts a raw `GamepadSnapshot` into an 8-bit NES button mask.
///
/// This mapping translates modern controller inputs (like analog sticks and face buttons)
/// into the standard 8 buttons recognized by the NES: A, B, Select, Start, Up, Down, Left, Right.
///
/// It correctly handles mapping both South/East to A and West/North to B, accommodating both
/// Xbox-style and Switch-style layouts. Stick thresholds are also applied for d-pad behavior.
///
/// # Examples
/// ```
/// use nes_core::Button;
/// use nes_desktop::gamepad::{GamepadSnapshot, gamepad_snapshot_to_bits};
///
/// let mut snapshot = GamepadSnapshot::default();
/// snapshot.connected = true;
/// snapshot.south_pressed = true; // Typically 'A' or 'B' depending on layout, mapped to NES 'A'
/// snapshot.start_pressed = true;
///
/// let bits = gamepad_snapshot_to_bits(snapshot);
///
/// // Assert the correct NES bit masks are set
/// assert_ne!(bits & Button::A.bit_mask(), 0);
/// assert_ne!(bits & Button::Start.bit_mask(), 0);
/// assert_eq!(bits & Button::B.bit_mask(), 0);
/// ```
pub fn gamepad_snapshot_to_bits(snapshot: GamepadSnapshot) -> u8 {
    if !snapshot.connected {
        return 0;
    }

    let mut bits = 0_u8;
    // Keep both common face layouts usable across Xbox/Switch-style controllers.
    if snapshot.south_pressed || snapshot.east_pressed {
        bits |= Button::A.bit_mask();
    }
    if snapshot.west_pressed || snapshot.north_pressed {
        bits |= Button::B.bit_mask();
    }
    if snapshot.select_pressed {
        bits |= Button::Select.bit_mask();
    }
    if snapshot.start_pressed {
        bits |= Button::Start.bit_mask();
    }

    if snapshot.dpad_up_pressed || snapshot.left_y <= -GAMEPAD_AXIS_THRESHOLD {
        bits |= Button::Up.bit_mask();
    }
    if snapshot.dpad_down_pressed || snapshot.left_y >= GAMEPAD_AXIS_THRESHOLD {
        bits |= Button::Down.bit_mask();
    }
    if snapshot.dpad_left_pressed || snapshot.left_x <= -GAMEPAD_AXIS_THRESHOLD {
        bits |= Button::Left.bit_mask();
    }
    if snapshot.dpad_right_pressed || snapshot.left_x >= GAMEPAD_AXIS_THRESHOLD {
        bits |= Button::Right.bit_mask();
    }

    bits
}

/// **Performance optimization:** Returns an `impl Iterator` instead of `Vec<Command>`
/// to eliminate a per-frame heap allocation when processing small, bounded state changes
/// for the NES controllers.
pub fn controller_state_delta_for_player(
    previous: u8,
    current: u8,
    player: nes_core::Player,
) -> impl Iterator<Item = Command> {
    CONTROLLER_BUTTONS.into_iter().filter_map(move |button| {
        let mask = button.bit_mask();
        match (previous & mask != 0, current & mask != 0) {
            (false, true) => Some(match player {
                nes_core::Player::One => Command::PressButton(button),
                nes_core::Player::Two => Command::PressButton2(button),
            }),
            (true, false) => Some(match player {
                nes_core::Player::One => Command::ReleaseButton(button),
                nes_core::Player::Two => Command::ReleaseButton2(button),
            }),
            _ => None,
        }
    })
}

use nes_core::Command;
use nes_desktop::app::{map_key_event_to_button_bit, map_key_event_to_command};
use std::time::{Duration, Instant};
use winit::event::{ElementState, VirtualKeyCode, WindowEvent};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum WindowEventDecision {
    CloseRequested,
    KeyboardInput {
        key: Option<VirtualKeyCode>,
        pressed: bool,
    },
    Resized {
        width: u32,
        height: u32,
    },
    ScaleFactorChanged {
        width: u32,
        height: u32,
    },
    Ignore,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum KeyboardDecision {
    ToggleOverlay,
    ManualSaveState,
    ManualLoadState,
    SetRewindHeld(bool),
    RtaManualSplit,
    RtaFinish,
    UpdateKeyboardBits { mask: u8, pressed: bool },
    ExecuteCore(Command),
    Noop,
}

#[derive(Debug, Clone, Copy)]
pub(crate) enum FrameDecision {
    WaitUntil(Instant),
    Step {
        missed_deadline: bool,
        next_deadline: Instant,
    },
}

#[derive(Debug, Clone, Copy)]
pub struct KeyboardInputMode {
    pub rollback_enabled: bool,
    pub rta_enabled: bool,
    pub rta_calibrate: bool,
}

#[must_use]
pub(crate) fn classify_window_event(event: &WindowEvent<'_>) -> WindowEventDecision {
    match event {
        WindowEvent::CloseRequested => WindowEventDecision::CloseRequested,
        WindowEvent::KeyboardInput { input, .. } => WindowEventDecision::KeyboardInput {
            key: input.virtual_keycode,
            pressed: element_state_pressed(input.state),
        },
        WindowEvent::Resized(size) => WindowEventDecision::Resized {
            width: size.width,
            height: size.height,
        },
        WindowEvent::ScaleFactorChanged { new_inner_size, .. } => {
            WindowEventDecision::ScaleFactorChanged {
                width: new_inner_size.width,
                height: new_inner_size.height,
            }
        }
        _ => WindowEventDecision::Ignore,
    }
}

pub(crate) fn map_virtual_keycode(key: VirtualKeyCode) -> Option<&'static str> {
    match key {
        VirtualKeyCode::Up => Some("ArrowUp"),
        VirtualKeyCode::Down => Some("ArrowDown"),
        VirtualKeyCode::Left => Some("ArrowLeft"),
        VirtualKeyCode::Right => Some("ArrowRight"),
        VirtualKeyCode::Z => Some("KeyZ"),
        VirtualKeyCode::X => Some("KeyX"),
        VirtualKeyCode::S => Some("KeyS"),
        VirtualKeyCode::A => Some("KeyA"),
        VirtualKeyCode::Return => Some("Enter"),
        VirtualKeyCode::RShift => Some("ShiftRight"),
        _ => None,
    }
}

#[must_use]
pub(crate) fn classify_keyboard_input(
    key: VirtualKeyCode,
    pressed: bool,
    mode: KeyboardInputMode,
) -> KeyboardDecision {
    if key == VirtualKeyCode::Escape && pressed {
        return KeyboardDecision::ToggleOverlay;
    }
    if pressed && key == VirtualKeyCode::F5 {
        return KeyboardDecision::ManualSaveState;
    }
    if pressed && key == VirtualKeyCode::F8 {
        return KeyboardDecision::ManualLoadState;
    }
    if key == VirtualKeyCode::R {
        return KeyboardDecision::SetRewindHeld(pressed);
    }
    if mode.rta_enabled && pressed && key == VirtualKeyCode::F9 {
        return KeyboardDecision::RtaManualSplit;
    }
    if mode.rta_enabled && mode.rta_calibrate && pressed && key == VirtualKeyCode::F10 {
        return KeyboardDecision::RtaFinish;
    }

    let Some(key_code) = map_virtual_keycode(key) else {
        return KeyboardDecision::Noop;
    };

    if mode.rollback_enabled {
        let Some(mask) = map_key_event_to_button_bit(key_code) else {
            return KeyboardDecision::Noop;
        };
        KeyboardDecision::UpdateKeyboardBits { mask, pressed }
    } else {
        let Some(mapped) = map_key_event_to_command(key_code, pressed) else {
            return KeyboardDecision::Noop;
        };
        KeyboardDecision::ExecuteCore(mapped.core)
    }
}

#[must_use]
pub(crate) fn evaluate_frame_deadline(
    now: Instant,
    next_frame_deadline: Instant,
    target_frame_time: Duration,
) -> FrameDecision {
    if now < next_frame_deadline {
        FrameDecision::WaitUntil(next_frame_deadline)
    } else {
        FrameDecision::Step {
            missed_deadline: now > next_frame_deadline,
            next_deadline: now + target_frame_time,
        }
    }
}

#[must_use]
pub(crate) fn element_state_pressed(state: ElementState) -> bool {
    state == ElementState::Pressed
}

