        assert_eq!(metrics.audio_queue_peak, 0);
        assert_eq!(metrics.audio_queue_drops, 0);
        assert_eq!(metrics.netplay_rollbacks, 0);
        assert_eq!(metrics.netplay_max_rollback_distance, 0);
