use std::io::{BufRead, BufReader, Write};
use std::net::TcpStream;
use std::sync::mpsc::{self, Receiver, Sender, TryRecvError};
use std::thread;
use std::time::Duration;

use nes_netplay::{ClientMessage, ServerMessage};

/// Configuration settings to launch a netplay session.
///
/// This tells the `NetplayClient` which relay server to connect to,
/// the room ID, the local player index, and how to handle rollback mechanics.
///
/// ## Examples
///
/// ```
/// use nes_desktop::netplay::NetplayRuntimeConfig;
///
/// let config = NetplayRuntimeConfig {
///     relay_addr: "127.0.0.1:3555".to_string(),
///     room: "room_123".to_string(),
///     player: 1,
///     input_delay_frames: 2,
///     max_rollback_frames: 60,
///     hash_check_every_frames: 60,
/// };
/// ```
#[derive(Debug, Clone)]
pub struct NetplayRuntimeConfig {
    pub relay_addr: String,
    pub room: String,
    pub player: u8,
    pub input_delay_frames: u32,
    pub max_rollback_frames: u32,
    pub hash_check_every_frames: u64,
}

/// An asynchronous TCP client that bridges local emulation with the `nes-relay` server.
///
/// Emulation is a synchronous, cycle-accurate beast. Networks are asynchronous and
/// chaotic. `NetplayClient` solves this by spinning up an I/O thread. It exposes
/// simple, non-blocking MPSC channels so the main emulator loop can shove inputs
/// into the ether and pull down remote inputs without ever dropping a frame.
///
/// ## Examples
///
/// ```no_run
/// use nes_desktop::netplay::{NetplayClient, NetplayRuntimeConfig};
///
/// let config = NetplayRuntimeConfig {
///     relay_addr: "127.0.0.1:3555".to_string(),
///     room: "match_xyz".to_string(),
///     player: 1,
///     input_delay_frames: 2,
///     max_rollback_frames: 60,
///     hash_check_every_frames: 60,
/// };
/// let client = NetplayClient::connect(&config).unwrap();
/// client.send_ping(1234).unwrap();
/// ```
pub struct NetplayClient {
    tx: Sender<ClientMessage>,
    rx: Receiver<ServerMessage>,
    err_rx: Receiver<String>,
}

impl NetplayClient {
    /// Attempts to establish a connection to the configured `nes-relay` server.
    ///
    /// Why do we spawn a background thread? Emulation loops are incredibly sensitive to
    /// timing. If we blocked the main thread waiting for a TCP response, the emulator
    /// would stutter and drop audio. By spinning up a background I/O thread, we can
    /// shove inputs over the network asynchronously while keeping the 60 FPS dream alive.
    ///
    /// ## Examples
    ///
    /// ```no_run
    /// use nes_desktop::netplay::{NetplayClient, NetplayRuntimeConfig};
    ///
    /// let config = NetplayRuntimeConfig {
    ///     relay_addr: "127.0.0.1:4545".to_string(),
    ///     room: "my_room".to_string(),
    ///     player: 1,
    ///     input_delay_frames: 2,
    ///     max_rollback_frames: 30,
    ///     hash_check_every_frames: 60,
    /// };
    ///
    /// let client = NetplayClient::connect(&config).expect("Relay is down!");
    /// ```
    ///
    /// ## Panics
    ///
    /// This function does not panic, but it returns an error if the relay server is unreachable.
    pub fn connect(config: &NetplayRuntimeConfig) -> Result<Self, String> {
        if !matches!(config.player, 1 | 2) {
            return Err(format!(
                "netplay player must be 1 or 2, got {}",
                config.player
            ));
        }

        let stream = TcpStream::connect(&config.relay_addr)
            .map_err(|err| format!("failed to connect to relay {}: {err}", config.relay_addr))?;
        stream
            .set_nodelay(true)
            .map_err(|err| format!("failed to configure relay socket: {err}"))?;
        let writer_stream = stream
            .try_clone()
            .map_err(|err| format!("failed to clone relay socket writer: {err}"))?;
        let reader_stream = stream
            .try_clone()
            .map_err(|err| format!("failed to clone relay socket reader: {err}"))?;

        let (tx, write_rx) = mpsc::channel::<ClientMessage>();
        let (read_tx, rx) = mpsc::channel::<ServerMessage>();
        let (err_tx, err_rx) = mpsc::channel::<String>();

        let join_room = config.room.clone();
        let join_player = config.player;
        let writer_err_tx = err_tx.clone();
        thread::spawn(move || {
            if let Err(err) = writer_loop(writer_stream, write_rx, join_room, join_player) {
                let _ = writer_err_tx.send(err);
            }
        });

        let reader_err_tx = err_tx.clone();
        thread::spawn(move || {
            if let Err(err) = reader_loop(reader_stream, read_tx) {
                let _ = reader_err_tx.send(err);
            }
        });

        Ok(Self { tx, rx, err_rx })
    }

    /// Queues an input event to be sent to the remote peer via the relay.
    ///
    /// This is the lifeblood of netplay. We send our local `frame` and controller `bits`
    /// to the server, which then forwards them to Player 2. If we don't send this,
    /// Player 2's emulator will eventually guess wrong and trigger a massive rollback.
    ///
    /// ## Examples
    ///
    /// ```no_run
    /// # use nes_desktop::netplay::{NetplayClient, NetplayRuntimeConfig};
    /// # let config = NetplayRuntimeConfig {
    /// #     relay_addr: "127.0.0.1:4545".to_string(), room: "room".to_string(), player: 1,
    /// #     input_delay_frames: 2, max_rollback_frames: 30, hash_check_every_frames: 60,
    /// # };
    /// # let client = NetplayClient::connect(&config).unwrap();
    /// // Frame 120, holding 'Right' (0x01)
    /// client.send_input(120, 0x01).unwrap();
    /// ```
    ///
    /// ## Errors
    ///
    /// Returns an error if the underlying network channel has been disconnected or broken.
    pub fn send_input(&self, frame: u64, bits: u8) -> Result<(), String> {
        self.tx
            .send(ClientMessage::Input { frame, bits })
            .map_err(|err| format!("failed to queue netplay input: {err}"))
    }

    /// Sends a local emulator state hash to the remote peer to verify sync.
    ///
    /// Rollback netcode is an illusion of perfection. Occasionally, the emulators diverge
    /// due to a bug or bad guess. By periodically sending a snapshot hash, we can
    /// detect desyncs early before the players notice they are playing two entirely
    /// different realities.
    ///
    /// ## Examples
    ///
    /// ```no_run
    /// # use nes_desktop::netplay::{NetplayClient, NetplayRuntimeConfig};
    /// # let config = NetplayRuntimeConfig {
    /// #     relay_addr: "127.0.0.1:4545".to_string(), room: "room".to_string(), player: 1,
    /// #     input_delay_frames: 2, max_rollback_frames: 30, hash_check_every_frames: 60,
    /// # };
    /// # let client = NetplayClient::connect(&config).unwrap();
    /// // Frame 60, computed state hash
    /// client.send_hash(60, 0x1A2B3C4D).unwrap();
    /// ```
    pub fn send_hash(&self, frame: u64, state_hash: u64) -> Result<(), String> {
        self.tx
            .send(ClientMessage::Hash { frame, state_hash })
            .map_err(|err| format!("failed to queue netplay hash: {err}"))
    }

    /// Sends a ping to measure Round-Trip Time (RTT) to the relay.
    ///
    /// Why do we ping? Because the internet is a series of tubes, and sometimes those tubes
    /// get clogged. Measuring RTT allows the emulator to dynamically adjust the
    /// `input_delay_frames` to keep the gameplay smooth under high latency.
    ///
    /// ## Examples
    ///
    /// ```no_run
    /// # use nes_desktop::netplay::{NetplayClient, NetplayRuntimeConfig};
    /// # let config = NetplayRuntimeConfig {
    /// #     relay_addr: "127.0.0.1:4545".to_string(), room: "room".to_string(), player: 1,
    /// #     input_delay_frames: 2, max_rollback_frames: 30, hash_check_every_frames: 60,
    /// # };
    /// # let client = NetplayClient::connect(&config).unwrap();
    /// // Send ping #1
    /// client.send_ping(1).unwrap();
    /// ```
    pub fn send_ping(&self, nonce: u64) -> Result<(), String> {
        self.tx
            .send(ClientMessage::Ping { nonce })
            .map_err(|err| format!("failed to queue netplay ping: {err}"))
    }

    /// Non-blockingly drains the next available message from the relay server.
    ///
    /// This is called exactly once per emulation frame. It grabs any queued inputs
    /// from the background thread. If we used a blocking read here, the game would
    /// literally stop and wait for the network.
    ///
    /// ## Examples
    ///
    /// ```no_run
    /// # use nes_desktop::netplay::{NetplayClient, NetplayRuntimeConfig};
    /// # let config = NetplayRuntimeConfig {
    /// #     relay_addr: "127.0.0.1:4545".to_string(), room: "room".to_string(), player: 1,
    /// #     input_delay_frames: 2, max_rollback_frames: 30, hash_check_every_frames: 60,
    /// # };
    /// # let client = NetplayClient::connect(&config).unwrap();
    /// if let Ok(Some(msg)) = client.try_recv() {
    ///     println!("Got message from relay!");
    /// }
    /// ```
    pub fn try_recv(&self) -> Result<Option<ServerMessage>, String> {
        if let Some(err) = self.take_error() {
            return Err(err);
        }
        match self.rx.try_recv() {
            Ok(message) => Ok(Some(message)),
            Err(TryRecvError::Empty) => Ok(None),
            Err(TryRecvError::Disconnected) => Err("netplay relay reader disconnected".to_owned()),
        }
    }

    fn take_error(&self) -> Option<String> {
        self.err_rx.try_recv().ok()
    }
}

fn writer_loop(
    mut stream: TcpStream,
    rx: Receiver<ClientMessage>,
    room: String,
    player: u8,
) -> Result<(), String> {
    write_message(&mut stream, &ClientMessage::Join { room, player })?;

    loop {
        match rx.recv_timeout(Duration::from_millis(10)) {
            Ok(message) => write_message(&mut stream, &message)?,
            Err(mpsc::RecvTimeoutError::Timeout) => continue,
            Err(mpsc::RecvTimeoutError::Disconnected) => break,
        }
    }
    Ok(())
}

fn reader_loop(stream: TcpStream, tx: Sender<ServerMessage>) -> Result<(), String> {
    let mut reader = BufReader::new(stream);
    let mut line = String::new();
    loop {
        line.clear();
        let bytes = reader
            .read_line(&mut line)
            .map_err(|err| format!("failed to read relay message: {err}"))?;
        if bytes == 0 {
            return Err("relay closed connection".to_owned());
        }
        let message = serde_json::from_str::<ServerMessage>(line.trim())
            .map_err(|err| format!("failed to decode relay message: {err}"))?;
        tx.send(message)
            .map_err(|err| format!("failed to deliver relay message to main loop: {err}"))?;
    }
}

fn write_message(stream: &mut TcpStream, message: &ClientMessage) -> Result<(), String> {
    let line = serde_json::to_string(message)
        .map_err(|err| format!("failed to encode relay message: {err}"))?;
    stream
        .write_all(line.as_bytes())
        .and_then(|_| stream.write_all(b"\n"))
        .and_then(|_| stream.flush())
        .map_err(|err| format!("failed to write relay message: {err}"))
}

/// Tracks the health of a live rollback netplay session.
///
/// The goal of netplay is the illusion of local multiplayer. This struct acts as the
/// pulse monitor, recording how often the illusion breaks (rollbacks), how far time
/// had to rewind (`max_rollback_distance`), and how much the network is struggling (`rtt_ms`, `jitter_ms`).
/// These metrics are vital for dynamically tuning `input_delay_frames` mid-game to hide latency.
pub struct NetplayRuntimeStats {
    pub latest_rtt_ms: Option<f64>,
    pub jitter_ms: f64,
    pub rollback_count: u64,
    pub max_rollback_distance: u64,
    pub desync_count: u64,
    pub input_delay_frames: u32,
}

impl NetplayRuntimeStats {
    /// Initializes tracking metrics, seeding the initial `input_delay_frames`.
    pub fn new(input_delay_frames: u32) -> Self {
        Self {
            latest_rtt_ms: None,
            jitter_ms: 0.0,
            rollback_count: 0,
            max_rollback_distance: 0,
            desync_count: 0,
            input_delay_frames,
        }
    }

    /// Records an observed Round-Trip Time sample to calculate average latency and jitter.
    pub fn observe_rtt_ms(&mut self, rtt_ms: f64) {
        if let Some(previous) = self.latest_rtt_ms {
            let delta = (rtt_ms - previous).abs();
            if self.jitter_ms <= f64::EPSILON {
                self.jitter_ms = delta;
            } else {
                // RFC3550-style EWMA jitter estimator.
                self.jitter_ms += (delta - self.jitter_ms) * 0.125;
            }
        }
        self.latest_rtt_ms = Some(rtt_ms);
    }

    /// Logs that a rollback occurred and updates the maximum rollback distance seen.
    pub fn observe_rollback(&mut self, distance: u64) {
        if distance == 0 {
            return;
        }
        self.rollback_count = self.rollback_count.saturating_add(1);
        self.max_rollback_distance = self.max_rollback_distance.max(distance);
    }

    /// Tallies a catastrophic timeline divergence.
    ///
    /// Desyncs happen when Player 1 and Player 2 calculate different state hashes for the same frame.
    /// It means the emulators have disagreed on reality. We track this to alert the players
    /// that they are no longer playing the same game.
    pub fn observe_desync(&mut self) {
        self.desync_count = self.desync_count.saturating_add(1);
    }

    /// Computes the last known round-trip time, defaulting to zero if unknown.
    ///
    /// We use this zero fallback to keep the dynamic delay logic mathematically
    /// safe during the initial connection handshake before the first ping returns.
    pub fn latest_rtt_ms_or_zero(&self) -> f64 {
        self.latest_rtt_ms.unwrap_or(0.0)
    }
}

/// Identifies which player's gamepad state belongs to the local user.
pub fn compute_local_netplay_bits(gamepad_bits: [u8; 2], local_player: u8) -> u8 {
    let local_slot = usize::from(local_player.saturating_sub(1));
    gamepad_bits.get(local_slot).copied().unwrap_or_else(|| {
        gamepad_bits
            .iter()
            .copied()
            .find(|bits| *bits != 0)
            .unwrap_or(0)
    })
}

/// Determines whether it is time to transmit a state hash based on the interval.
pub fn should_send_netplay_hash(hash_check_every: u64, frame: u64) -> bool {
    hash_check_every != 0 && frame != 0 && frame.is_multiple_of(hash_check_every)
}

/// Evaluates if enough time has passed to send another network ping to the relay.
pub fn schedule_netplay_ping(
    now: std::time::Instant,
    next_ping_at: &mut std::time::Instant,
    ping_nonce: &mut u64,
    pending_pings: &mut std::collections::BTreeMap<u64, std::time::Instant>,
    ping_interval: Duration,
    max_pending: usize,
) -> Option<u64> {
    if now < *next_ping_at {
        return None;
    }

    let nonce = *ping_nonce;
    *ping_nonce = ping_nonce.wrapping_add(1);
    pending_pings.insert(nonce, now);
    while pending_pings.len() > max_pending {
        pending_pings.pop_first();
    }
    *next_ping_at = now + ping_interval;
    Some(nonce)
}

/// Processes an incoming message from the `nes-relay` server, updating rollback state and metrics.
pub fn handle_netplay_server_message(
    message: ServerMessage,
    rollback_engine: &mut nes_netplay::RollbackEngine,
    netplay_local_player: u8,
    netplay_stats: &mut Option<NetplayRuntimeStats>,
    netplay_pending_pings: &mut std::collections::BTreeMap<u64, std::time::Instant>,
) -> Result<(), String> {
    match message {
        ServerMessage::PeerInput {
            player,
            frame,
            bits,
        } => {
            if player != netplay_local_player {
                let ingest = rollback_engine.ingest_remote_input(frame, bits);
                if ingest.rollback_queued {
                    eprintln!(
                        "[netplay] queued rollback from frame {} due to late remote input",
                        frame
                    );
                }
            }
        }
        ServerMessage::PeerHash {
            player,
            frame,
            state_hash,
        } => {
            if player != netplay_local_player {
                match rollback_engine.compare_remote_hash(frame, state_hash) {
                    nes_netplay::HashComparison::Match => {}
                    nes_netplay::HashComparison::Mismatch => {
                        eprintln!(
                            "[netplay] desync detected at frame {} (remote hash {:016X})",
                            frame, state_hash
                        );
                        if let Some(stats) = netplay_stats.as_mut() {
                            stats.observe_desync();
                        }
                    }
                    nes_netplay::HashComparison::PendingLocalFrame => {}
                }
            }
        }
        ServerMessage::Joined {
            room,
            player,
            peer_present,
        } => {
            println!(
                "[netplay] joined room '{}' as P{} (peer_present={})",
                room, player, peer_present
            );
        }
        ServerMessage::PeerJoined { player } => {
            println!("[netplay] peer joined as P{}", player);
        }
        ServerMessage::PeerLeft { player } => {
            println!("[netplay] peer left (P{})", player);
        }
        ServerMessage::Error { message } => {
            return Err(format!("[netplay] relay error: {message}"));
        }
        ServerMessage::Pong { nonce } => {
            if let Some(sent_at) = netplay_pending_pings.remove(&nonce) {
                let rtt_ms = sent_at.elapsed().as_secs_f64() * 1_000.0;
                if let Some(stats) = netplay_stats.as_mut() {
                    stats.observe_rtt_ms(rtt_ms);
                }
            }
        }
    }
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::net::TcpListener;
    use std::sync::mpsc;
    use std::time::Duration;

    #[test]
    fn writer_loop_survives_idle_timeout_and_sends_late_message() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind listener");
        let addr = listener.local_addr().expect("listener addr");
        let client_stream = TcpStream::connect(addr).expect("connect client");
        let (server_stream, _) = listener.accept().expect("accept server stream");
        server_stream
            .set_read_timeout(Some(Duration::from_millis(500)))
            .expect("set read timeout");
        let mut server_reader = BufReader::new(server_stream);

        let (tx, rx) = mpsc::channel::<ClientMessage>();
        let writer_thread =
            thread::spawn(move || writer_loop(client_stream, rx, "test-room".to_owned(), 1));

        let mut join_line = String::new();
        server_reader
            .read_line(&mut join_line)
            .expect("read join line");
        let join = serde_json::from_str::<ClientMessage>(join_line.trim()).expect("parse join");
        assert_eq!(
            join,
            ClientMessage::Join {
                room: "test-room".to_owned(),
                player: 1
            }
        );

        thread::sleep(Duration::from_millis(30));
        tx.send(ClientMessage::Input {
            frame: 99,
            bits: 0x81,
        })
        .expect("writer thread still alive after idle timeout");

        let mut input_line = String::new();
        server_reader
            .read_line(&mut input_line)
            .expect("read input line");
        let input = serde_json::from_str::<ClientMessage>(input_line.trim()).expect("parse input");
        assert_eq!(
            input,
            ClientMessage::Input {
                frame: 99,
                bits: 0x81
            }
        );

        drop(tx);
        let result = writer_thread.join().expect("join writer thread");
        assert!(result.is_ok(), "writer loop should exit cleanly");
    }

    #[test]
    fn connect_rejects_invalid_player_before_attempting_socket_connect() {
        let config = NetplayRuntimeConfig {
            relay_addr: "127.0.0.1:1".to_owned(),
            room: "test-room".to_owned(),
            player: 3,
            input_delay_frames: 2,
            max_rollback_frames: 16,
            hash_check_every_frames: 60,
        };
        let err = NetplayClient::connect(&config)
            .err()
            .expect("invalid player should fail fast");
        assert!(err.contains("player must be 1 or 2"));
    }

    #[test]
    fn send_methods_report_channel_disconnect_errors() {
        let (tx, rx) = mpsc::channel::<ClientMessage>();
        drop(rx);
        let (_server_tx, server_rx) = mpsc::channel::<ServerMessage>();
        let (_err_tx, err_rx) = mpsc::channel::<String>();
        let client = NetplayClient {
            tx,
            rx: server_rx,
            err_rx,
        };

        let input_err = client
            .send_input(10, 0x12)
            .expect_err("send_input should report disconnected writer");
        assert!(input_err.contains("failed to queue netplay input"));

        let hash_err = client
            .send_hash(20, 0xDEADBEEF)
            .expect_err("send_hash should report disconnected writer");
        assert!(hash_err.contains("failed to queue netplay hash"));

        let ping_err = client
            .send_ping(42)
            .expect_err("send_ping should report disconnected writer");
        assert!(ping_err.contains("failed to queue netplay ping"));
    }

    #[test]
    fn try_recv_returns_messages_and_prioritizes_error_channel() {
        let (tx, _write_rx) = mpsc::channel::<ClientMessage>();
        let (server_tx, server_rx) = mpsc::channel::<ServerMessage>();
        let (_err_tx, err_rx) = mpsc::channel::<String>();
        let client = NetplayClient {
            tx,
            rx: server_rx,
            err_rx,
        };

        server_tx
            .send(ServerMessage::Pong { nonce: 7 })
            .expect("sending pong should succeed");
        assert_eq!(
            client.try_recv().expect("try_recv should read message"),
            Some(ServerMessage::Pong { nonce: 7 })
        );
        assert_eq!(
            client.try_recv().expect("empty queue should return none"),
            None
        );
        drop(server_tx);
        let disconnected = client
            .try_recv()
            .expect_err("disconnected queue should propagate error");
        assert!(disconnected.contains("reader disconnected"));

        let (tx2, _write_rx2) = mpsc::channel::<ClientMessage>();
        let (_server_tx2, server_rx2) = mpsc::channel::<ServerMessage>();
        let (err_tx2, err_rx2) = mpsc::channel::<String>();
        err_tx2
            .send("relay-side failure".to_owned())
            .expect("error send should succeed");
        let client_with_err = NetplayClient {
            tx: tx2,
            rx: server_rx2,
            err_rx: err_rx2,
        };
        let err = client_with_err
            .try_recv()
            .expect_err("queued relay error should take precedence");
        assert_eq!(err, "relay-side failure");
        assert_eq!(client_with_err.take_error(), None);
    }

    #[test]
    fn reader_loop_forwards_messages_and_reports_relay_close() {
        let listener = TcpListener::bind("127.0.0.1:0").expect("bind listener");
        let addr = listener.local_addr().expect("listener addr");
        let client_stream = TcpStream::connect(addr).expect("connect client");
        let (mut server_stream, _) = listener.accept().expect("accept server stream");
        let (tx, rx) = mpsc::channel::<ServerMessage>();

        let reader_thread = thread::spawn(move || reader_loop(client_stream, tx));

        let payload =
            serde_json::to_string(&ServerMessage::Pong { nonce: 99 }).expect("serialize message");
        server_stream
            .write_all(payload.as_bytes())
            .and_then(|_| server_stream.write_all(b"\n"))
            .expect("write framed relay line");
        server_stream.flush().expect("flush relay line");
        drop(server_stream);

        let received = rx
            .recv_timeout(Duration::from_millis(250))
            .expect("reader should forward server message");
        assert_eq!(received, ServerMessage::Pong { nonce: 99 });

        let close_err = reader_thread
            .join()
            .expect("join reader thread")
            .expect_err("reader loop should report EOF as an error");
        assert!(close_err.contains("relay closed connection"));
    }

    fn sample_ines(mapper: u8, prg_banks: u8) -> Vec<u8> {
        let mut rom = vec![0; 16 + (prg_banks as usize) * 16384];
        rom[0..4].copy_from_slice(b"NES\x1A");
        rom[4] = prg_banks;
        rom[5] = 0; // 0 CHR banks (uses CHR RAM)
        rom[6] = (mapper << 4) & 0xF0;
        rom[7] = mapper & 0xF0;
        rom
    }

    use super::{
        NetplayRuntimeStats, compute_local_netplay_bits, handle_netplay_server_message,
        schedule_netplay_ping, should_send_netplay_hash,
    };

    #[test]
    fn netplay_helper_functions_choose_local_bits_and_hash_schedule() {
        assert_eq!(compute_local_netplay_bits([0x12, 0x34], 1), 0x12);
        assert_eq!(compute_local_netplay_bits([0x12, 0x34], 2), 0x34);
        assert_eq!(compute_local_netplay_bits([0x12, 0x34], 3), 0x12);
        assert_eq!(compute_local_netplay_bits([0, 0], 9), 0);

        assert!(!should_send_netplay_hash(0, 120));
        assert!(!should_send_netplay_hash(60, 0));
        assert!(should_send_netplay_hash(60, 120));
        assert!(!should_send_netplay_hash(60, 121));
    }

    #[test]
    fn schedule_netplay_ping_enforces_deadline_nonce_and_pending_cap() {
        let now = std::time::Instant::now();
        let mut next_ping_at = now + Duration::from_millis(10);
        let mut nonce = 5_u64;
        let mut pending = std::collections::BTreeMap::<u64, std::time::Instant>::new();
        pending.insert(1, now - Duration::from_millis(20));
        pending.insert(2, now - Duration::from_millis(10));

        assert_eq!(
            schedule_netplay_ping(
                now,
                &mut next_ping_at,
                &mut nonce,
                &mut pending,
                Duration::from_millis(500),
                2
            ),
            None
        );
        assert_eq!(nonce, 5);
        assert_eq!(pending.len(), 2);

        let due_now = now + Duration::from_millis(10);
        let scheduled = schedule_netplay_ping(
            due_now,
            &mut next_ping_at,
            &mut nonce,
            &mut pending,
            Duration::from_millis(500),
            2,
        );
        assert_eq!(scheduled, Some(5));
        assert_eq!(nonce, 6);
        assert_eq!(next_ping_at, due_now + Duration::from_millis(500));
        assert_eq!(pending.len(), 2, "pending set should be capped to max");
        assert!(
            !pending.contains_key(&1),
            "oldest nonce should be evicted first"
        );
        assert!(pending.contains_key(&5), "new nonce should be tracked");
    }

    #[test]
    fn handle_netplay_server_message_updates_stats_and_errors() {
        let mut core = nes_core::NesCore::new();
        let mut rom = sample_ines(0, 1);
        let prg_start = 16;
        rom[prg_start + 0x3FFC] = 0x00;
        rom[prg_start + 0x3FFD] = 0x80;
        core.load_ines_rom(&rom).expect("sample rom should load");

        let mut rollback_engine = nes_netplay::RollbackEngine::new(nes_netplay::RollbackConfig {
            local_player: 1,
            input_delay_frames: 2,
            max_rollback_frames: 16,
        })
        .expect("rollback config should be valid");
        let first_step = rollback_engine
            .advance_frame(&mut core)
            .expect("initial rollback step should succeed");

        let mut stats = Some(NetplayRuntimeStats::new(2));
        let mut pending = std::collections::BTreeMap::<u64, std::time::Instant>::new();
        pending.insert(7, std::time::Instant::now() - Duration::from_millis(10));

        handle_netplay_server_message(
            ServerMessage::Pong { nonce: 7 },
            &mut rollback_engine,
            1,
            &mut stats,
            &mut pending,
        )
        .expect("pong message should process");
        assert!(pending.is_empty());
        let rtt_ms = stats.as_ref().and_then(|s| s.latest_rtt_ms).unwrap_or(0.0);
        assert!(
            (1.0..=500.0).contains(&rtt_ms),
            "expected plausible RTT ms value, got {rtt_ms}"
        );

        handle_netplay_server_message(
            ServerMessage::PeerInput {
                player: 2,
                frame: first_step.frame,
                bits: 0x01,
            },
            &mut rollback_engine,
            1,
            &mut stats,
            &mut pending,
        )
        .expect("peer input should process");
        let rollback_step = rollback_engine
            .advance_frame(&mut core)
            .expect("post-input rollback step should succeed");
        assert!(
            rollback_step.rollback_distance > 0,
            "late remote input should queue rollback"
        );

        handle_netplay_server_message(
            ServerMessage::PeerHash {
                player: 2,
                frame: rollback_step.frame,
                state_hash: rollback_step.state_hash.wrapping_add(1),
            },
            &mut rollback_engine,
            1,
            &mut stats,
            &mut pending,
        )
        .expect("peer hash should process");
        assert_eq!(stats.as_ref().map_or(0, |s| s.desync_count), 1);

        let err = handle_netplay_server_message(
            ServerMessage::Error {
                message: "boom".to_owned(),
            },
            &mut rollback_engine,
            1,
            &mut stats,
            &mut pending,
        )
        .expect_err("relay errors should propagate");
        assert!(err.contains("relay error"));
    }
}

//! Modal pause overlay model and bitmap renderer for `nes-desktop`.

use font8x8::{BASIC_FONTS, UnicodeFonts};
use std::borrow::Cow;
use winit::event::VirtualKeyCode;

use crate::actions::AppAction;

const GLYPH_SIZE: usize = 8;
const GLYPH_SPACING: usize = 1;
const LINE_HEIGHT: usize = 10;
const PANEL_MARGIN: usize = 16;
const PANEL_PADDING: usize = 12;
const CHEAT_CODE_MAX_LEN: usize = 8;

const COLOR_BACKDROP: [u8; 4] = [0, 0, 0, 255];
const COLOR_PANEL: [u8; 4] = [28, 30, 36, 255];
const COLOR_PANEL_BORDER: [u8; 4] = [94, 104, 124, 255];
const COLOR_TEXT: [u8; 4] = [235, 239, 247, 255];
const COLOR_SUBTEXT: [u8; 4] = [170, 178, 194, 255];
const COLOR_HIGHLIGHT: [u8; 4] = [74, 122, 197, 255];
const COLOR_STATUS: [u8; 4] = [207, 173, 91, 255];

/// Which overlay screen is currently visible.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OverlayPanel {
    MainMenu,
    Cheats,
}

/// Selectable entries in the main pause menu.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum MainMenuSelection {
    Resume,
    OpenRom,
    OpenCheats,
    SaveSlot(u8),
    LoadSlot(u8),
    Reset,
    Quit,
}

/// Selectable entries in the cheats panel.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CheatsSelection {
    AddCode,
    Cheat(usize),
}

/// Unified selection state for the active overlay panel.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum OverlaySelection {
    Main(MainMenuSelection),
    Cheats(CheatsSelection),
}

/// Commands emitted from the overlay state machine.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum OverlayCommand {
    AppAction(AppAction),
    ToggleCheat(usize),
    RemoveCheat(usize),
    SubmitCheatCode(String),
}

/// Lightweight slot summary used by the overlay renderer.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OverlaySlotSummary {
    pub slot: u8,
    pub status_label: &'static str,
    pub modified_unix_secs: Option<u64>,
}

impl OverlaySlotSummary {
    /// Returns a human-readable suffix for rendering beside slot actions.
    pub fn render_suffix(&self, out: &mut String) {
        use std::fmt::Write;
        if let Some(secs) = self.modified_unix_secs {
            let _ = write!(out, "{} ({secs})", self.status_label);
        } else {
            out.push_str(self.status_label);
        }
    }
}

/// Lightweight cheat summary used by the overlay renderer.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OverlayCheatSummary<'a> {
    pub raw_code: &'a str,
    pub enabled: bool,
}

/// Modal pause overlay state.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OverlayModel {
    open: bool,
    panel: OverlayPanel,
    selected_slot: u8,
    main_selection_index: usize,
    cheats_selection_index: usize,
    add_cheat_input: Option<String>,
    main_entries: Vec<MainMenuSelection>,
    status_message: Option<Cow<'static, str>>,
}

impl OverlayModel {
    /// Creates a new overlay model with entries for the given slot count.
    #[must_use]
    pub fn new(slot_count: u8) -> Self {
        let capped_slot_count = slot_count.max(1);
        let mut main_entries = Vec::with_capacity(usize::from(capped_slot_count) * 2 + 5);
        main_entries.push(MainMenuSelection::Resume);
        main_entries.push(MainMenuSelection::OpenRom);
        main_entries.push(MainMenuSelection::OpenCheats);
        for slot in 1..=capped_slot_count {
            main_entries.push(MainMenuSelection::SaveSlot(slot));
        }
        for slot in 1..=capped_slot_count {
            main_entries.push(MainMenuSelection::LoadSlot(slot));
        }
        main_entries.push(MainMenuSelection::Reset);
        main_entries.push(MainMenuSelection::Quit);

        Self {
            open: false,
            panel: OverlayPanel::MainMenu,
            selected_slot: 1,
            main_selection_index: 0,
            cheats_selection_index: 0,
            add_cheat_input: None,
            main_entries,
            status_message: None,
        }
    }

    /// Returns whether the overlay is currently open.
    #[must_use]
    pub const fn is_open(&self) -> bool {
        self.open
    }

    /// Returns the currently visible overlay panel.
    #[must_use]
    pub const fn panel(&self) -> OverlayPanel {
        self.panel
    }

    /// Opens the overlay.
    pub fn open(&mut self) {
        self.open = true;
    }

    /// Closes the overlay and resets transient UI state.
    pub fn close(&mut self) {
        self.open = false;
        self.panel = OverlayPanel::MainMenu;
        self.add_cheat_input = None;
    }

    /// Opens the cheats panel and keeps the overlay visible.
    pub fn open_cheats_panel(&mut self) {
        self.open = true;
        self.panel = OverlayPanel::Cheats;
        self.add_cheat_input = None;
    }

    /// Returns whether the add-cheat modal is active.
    #[must_use]
    pub fn is_add_cheat_modal_open(&self) -> bool {
        self.add_cheat_input.is_some()
    }

    /// Closes the add-cheat modal without changing the active panel.
    pub fn close_add_cheat_modal(&mut self) {
        self.add_cheat_input = None;
    }

    /// Returns the current input buffer when the add-cheat modal is active.
    #[must_use]
    pub fn cheat_input_buffer(&self) -> Option<&str> {
        self.add_cheat_input.as_deref()
    }

    /// Returns the currently selected entry for the active panel.
    #[must_use]
    pub fn selection(&self, cheat_count: usize) -> OverlaySelection {
        match self.panel {
            OverlayPanel::MainMenu => {
                OverlaySelection::Main(self.main_entries[self.main_selection_index])
            }
            OverlayPanel::Cheats => OverlaySelection::Cheats(self.cheats_selection(cheat_count)),
        }
    }

    /// Moves selection to the previous entry, wrapping at the top.
    pub fn move_prev(&mut self, cheat_count: usize) {
        match self.panel {
            OverlayPanel::MainMenu => {
                if self.main_selection_index == 0 {
                    self.main_selection_index = self.main_entries.len().saturating_sub(1);
                } else {
                    self.main_selection_index -= 1;
                }
                self.sync_selected_slot_with_main_selection();
            }
            OverlayPanel::Cheats => {
                let entry_count = cheat_count.saturating_add(1);
                if self.cheats_selection_index == 0 {
                    self.cheats_selection_index = entry_count.saturating_sub(1);
                } else {
                    self.cheats_selection_index -= 1;
                }
            }
        }
    }

    /// Moves selection to the next entry, wrapping at the bottom.
    pub fn move_next(&mut self, cheat_count: usize) {
        match self.panel {
            OverlayPanel::MainMenu => {
                self.main_selection_index =
                    (self.main_selection_index + 1) % self.main_entries.len();
                self.sync_selected_slot_with_main_selection();
            }
            OverlayPanel::Cheats => {
                let entry_count = cheat_count.saturating_add(1);
                self.cheats_selection_index =
                    (self.cheats_selection_index + 1) % entry_count.max(1);
            }
        }
    }

    /// Handles one overlay key press and emits a high-level command when needed.
    #[must_use]
    pub fn handle_key(
        &mut self,
        key: VirtualKeyCode,
        pressed: bool,
        cheat_count: usize,
    ) -> Option<OverlayCommand> {
        if !self.open || !pressed {
            return None;
        }
        if self.is_add_cheat_modal_open() {
            return self.handle_add_cheat_modal_key(key);
        }

        match self.panel {
            OverlayPanel::MainMenu => self.handle_main_menu_key(key),
            OverlayPanel::Cheats => self.handle_cheats_panel_key(key, cheat_count),
        }
    }

    /// Returns the slot most recently chosen through main menu slot actions.
    #[must_use]
    pub const fn selected_slot(&self) -> u8 {
        self.selected_slot
    }

    /// Repositions the main-menu selection to the first entry for the given slot.
    pub fn focus_slot(&mut self, slot: u8, save_action: bool) {
        if let Some(index) = self
            .main_entries
            .iter()
            .position(|entry| match (save_action, entry) {
                (true, MainMenuSelection::SaveSlot(candidate)) => *candidate == slot,
                (false, MainMenuSelection::LoadSlot(candidate)) => *candidate == slot,
                _ => false,
            })
        {
            self.main_selection_index = index;
            self.sync_selected_slot_with_main_selection();
        }
    }

    /// Selects the given cheat row in the cheats panel.
    pub fn focus_cheat(&mut self, cheat_index: usize) {
        self.cheats_selection_index = cheat_index.saturating_add(1);
    }

    /// Sets a user-facing status message shown at the bottom of the overlay.
    pub fn set_status_message(&mut self, message: impl Into<Cow<'static, str>>) {
        self.status_message = Some(message.into());
    }

    /// Clears any existing status message.
    pub fn clear_status_message(&mut self) {
        self.status_message = None;
    }

    /// Returns the current status message, if any.
    #[must_use]
    pub fn status_message(&self) -> Option<&str> {
        self.status_message.as_deref()
    }

    fn handle_add_cheat_modal_key(&mut self, key: VirtualKeyCode) -> Option<OverlayCommand> {
        match key {
            VirtualKeyCode::Escape => {
                self.add_cheat_input = None;
                None
            }
            VirtualKeyCode::Back => {
                if let Some(buffer) = self.add_cheat_input.as_mut() {
                    buffer.pop();
                }
                None
            }
            VirtualKeyCode::Return => {
                let buffer = self.add_cheat_input.as_ref()?;
                if buffer.is_empty() {
                    return None;
                }
                Some(OverlayCommand::SubmitCheatCode(buffer.clone()))
            }
            _ => {
                if let Some(ch) = key_to_cheat_char(key)
                    && let Some(buffer) = self.add_cheat_input.as_mut()
                    && buffer.len() < CHEAT_CODE_MAX_LEN
                {
                    buffer.push(ch);
                }
                None
            }
        }
    }

    fn handle_main_menu_key(&mut self, key: VirtualKeyCode) -> Option<OverlayCommand> {
        match key {
            VirtualKeyCode::Escape => Some(OverlayCommand::AppAction(AppAction::Resume)),
            VirtualKeyCode::Up => {
                self.move_prev(0);
                None
            }
            VirtualKeyCode::Down => {
                self.move_next(0);
                None
            }
            VirtualKeyCode::Return => Some(OverlayCommand::AppAction(self.main_action())),
            VirtualKeyCode::F5 => Some(OverlayCommand::AppAction(AppAction::SaveSlot(
                self.selected_slot,
            ))),
            VirtualKeyCode::F8 => Some(OverlayCommand::AppAction(AppAction::LoadSlot(
                self.selected_slot,
            ))),
            _ => None,
        }
    }

    fn handle_cheats_panel_key(
        &mut self,
        key: VirtualKeyCode,
        cheat_count: usize,
    ) -> Option<OverlayCommand> {
        match key {
            VirtualKeyCode::Escape => {
                self.panel = OverlayPanel::MainMenu;
                None
            }
            VirtualKeyCode::Up => {
                self.move_prev(cheat_count);
                None
            }
            VirtualKeyCode::Down => {
                self.move_next(cheat_count);
                None
            }
            VirtualKeyCode::Return => {
                if matches!(self.cheats_selection(cheat_count), CheatsSelection::AddCode) {
                    self.add_cheat_input = Some(String::new());
                }
                None
            }
            VirtualKeyCode::Space => match self.cheats_selection(cheat_count) {
                CheatsSelection::AddCode => None,
                CheatsSelection::Cheat(index) => Some(OverlayCommand::ToggleCheat(index)),
            },
            VirtualKeyCode::Delete => match self.cheats_selection(cheat_count) {
                CheatsSelection::AddCode => None,
                CheatsSelection::Cheat(index) => Some(OverlayCommand::RemoveCheat(index)),
            },
            _ => None,
        }
    }

    fn main_action(&self) -> AppAction {
        match self.main_entries[self.main_selection_index] {
            MainMenuSelection::Resume => AppAction::Resume,
            MainMenuSelection::OpenRom => AppAction::OpenRom,
            MainMenuSelection::OpenCheats => AppAction::OpenCheats,
            MainMenuSelection::SaveSlot(slot) => AppAction::SaveSlot(slot),
            MainMenuSelection::LoadSlot(slot) => AppAction::LoadSlot(slot),
            MainMenuSelection::Reset => AppAction::Reset,
            MainMenuSelection::Quit => AppAction::Quit,
        }
    }

    fn cheats_selection(&self, cheat_count: usize) -> CheatsSelection {
        let max_index = cheat_count;
        let bounded_index = self.cheats_selection_index.min(max_index);
        if bounded_index == 0 {
            CheatsSelection::AddCode
        } else {
            CheatsSelection::Cheat(bounded_index - 1)
        }
    }

    fn sync_selected_slot_with_main_selection(&mut self) {
        match self.main_entries[self.main_selection_index] {
            MainMenuSelection::SaveSlot(slot) | MainMenuSelection::LoadSlot(slot) => {
                self.selected_slot = slot;
            }
            MainMenuSelection::Resume
            | MainMenuSelection::OpenRom
            | MainMenuSelection::OpenCheats
            | MainMenuSelection::Reset
            | MainMenuSelection::Quit => {}
        }
    }
}

/// Draws a filled rectangle into an RGBA buffer.
pub fn fill_rect(
    frame: &mut [u8],
    frame_width: usize,
    x: usize,
    y: usize,
    width: usize,
    height: usize,
    color: [u8; 4],
) {
    if frame_width == 0 || width == 0 || height == 0 {
        return;
    }
    let frame_height = frame.len() / 4 / frame_width;
    let x_end = x.saturating_add(width).min(frame_width);
    let y_end = y.saturating_add(height).min(frame_height);
    for row in y..y_end {
        for col in x..x_end {
            set_pixel(frame, frame_width, col, row, color);
        }
    }
}

/// Draws bitmap text into an RGBA buffer.
pub fn draw_text(
    frame: &mut [u8],
    frame_width: usize,
    x: usize,
    y: usize,
    text: &str,
    color: [u8; 4],
) {
    let mut cursor_x = x;
    let mut cursor_y = y;
    for ch in text.chars() {
        if ch == '\n' {
            cursor_x = x;
            cursor_y = cursor_y.saturating_add(LINE_HEIGHT);
            continue;
        }
        draw_char(frame, frame_width, cursor_x, cursor_y, ch, color);
        cursor_x = cursor_x.saturating_add(GLYPH_SIZE + GLYPH_SPACING);
    }
}

/// Draws the full modal overlay on top of the existing frame.
///
/// **Bolt Optimization:** The `slot_summaries` and `cheat_summaries` arguments use
/// lazy iterators instead of collecting into `Vec` slices. This eliminates repeated heap
/// allocations and mappings for the UI list states on every redraw tick.
pub fn draw_overlay<'a>(
    frame: &mut [u8],
    frame_width: usize,
    frame_height: usize,
    model: &OverlayModel,
    slot_summaries: impl Iterator<Item = OverlaySlotSummary> + Clone,
    mut cheat_summaries: impl Iterator<Item = OverlayCheatSummary<'a>>,
    cheat_count: usize,
) {
    if !model.is_open() || frame_width == 0 || frame_height == 0 {
        return;
    }

    dim_frame(frame);

    let panel_x = PANEL_MARGIN.min(frame_width);
    let panel_y = PANEL_MARGIN.min(frame_height);
    let panel_width = frame_width.saturating_sub(panel_x * 2);
    let panel_height = frame_height.saturating_sub(panel_y * 2);
    fill_rect(
        frame,
        frame_width,
        panel_x,
        panel_y,
        panel_width,
        panel_height,
        COLOR_PANEL,
    );
    draw_frame_border(
        frame,
        frame_width,
        panel_x,
        panel_y,
        panel_width,
        panel_height,
    );

    let text_x = panel_x.saturating_add(PANEL_PADDING);
    let mut text_y = panel_y.saturating_add(PANEL_PADDING);

    let mut text_buffer = String::with_capacity(64);

    match model.panel() {
        OverlayPanel::MainMenu => {
            draw_text(frame, frame_width, text_x, text_y, "PAUSED", COLOR_TEXT);
            text_y = text_y.saturating_add(LINE_HEIGHT + 2);
            draw_text(
                frame,
                frame_width,
                text_x,
                text_y,
                "Resume | Open ROM | Cheats | Save/Load Slots | Reset | Quit",
                COLOR_SUBTEXT,
            );
            text_y = text_y.saturating_add(LINE_HEIGHT + 6);

            for (index, entry) in model.main_entries.iter().enumerate() {
                let is_selected = index == model.main_selection_index;
                let line_top = text_y.saturating_sub(2);
                if is_selected {
                    fill_rect(
                        frame,
                        frame_width,
                        text_x.saturating_sub(4),
                        line_top,
                        panel_width
                            .saturating_sub(PANEL_PADDING * 2)
                            .min(frame_width),
                        LINE_HEIGHT,
                        COLOR_HIGHLIGHT,
                    );
                }

                text_buffer.clear();
                main_entry_label(*entry, slot_summaries.clone(), &mut text_buffer);
                draw_text(
                    frame,
                    frame_width,
                    text_x,
                    text_y,
                    &text_buffer,
                    if is_selected {
                        COLOR_TEXT
                    } else {
                        COLOR_SUBTEXT
                    },
                );
                text_y = text_y.saturating_add(LINE_HEIGHT);
            }
        }
        OverlayPanel::Cheats => {
            draw_text(frame, frame_width, text_x, text_y, "CHEATS", COLOR_TEXT);
            text_y = text_y.saturating_add(LINE_HEIGHT + 2);
            draw_text(
                frame,
                frame_width,
                text_x,
                text_y,
                "Enter=Add | Space=Toggle | Del=Remove | Esc=Back",
                COLOR_SUBTEXT,
            );
            text_y = text_y.saturating_add(LINE_HEIGHT + 6);

            for index in 0..cheat_count.saturating_add(1) {
                let is_selected = index == model.cheats_selection_index.min(cheat_count);
                let line_top = text_y.saturating_sub(2);
                if is_selected {
                    fill_rect(
                        frame,
                        frame_width,
                        text_x.saturating_sub(4),
                        line_top,
                        panel_width
                            .saturating_sub(PANEL_PADDING * 2)
                            .min(frame_width),
                        LINE_HEIGHT,
                        COLOR_HIGHLIGHT,
                    );
                }

                text_buffer.clear();
                if index == 0 {
                    text_buffer.push_str("Add Code");
                } else if let Some(summary) = cheat_summaries.next() {
                    cheat_label(&summary, &mut text_buffer);
                }
                draw_text(
                    frame,
                    frame_width,
                    text_x,
                    text_y,
                    &text_buffer,
                    if is_selected {
                        COLOR_TEXT
                    } else {
                        COLOR_SUBTEXT
                    },
                );
                text_y = text_y.saturating_add(LINE_HEIGHT);
            }
        }
    }

    if let Some(message) = model.status_message() {
        let footer_y = panel_y
            .saturating_add(panel_height)
            .saturating_sub(PANEL_PADDING + LINE_HEIGHT);
        draw_text(frame, frame_width, text_x, footer_y, message, COLOR_STATUS);
    }

    if let Some(buffer) = model.cheat_input_buffer() {
        draw_add_cheat_modal(frame, frame_width, frame_height, buffer);
    }
}

fn draw_add_cheat_modal(frame: &mut [u8], frame_width: usize, frame_height: usize, buffer: &str) {
    let modal_width = 200.min(frame_width.saturating_sub(PANEL_MARGIN));
    let modal_height = 54.min(frame_height.saturating_sub(PANEL_MARGIN));
    let modal_x = (frame_width.saturating_sub(modal_width)) / 2;
    let modal_y = (frame_height.saturating_sub(modal_height)) / 2;
    fill_rect(
        frame,
        frame_width,
        modal_x,
        modal_y,
        modal_width,
        modal_height,
        COLOR_PANEL,
    );
    draw_frame_border(
        frame,
        frame_width,
        modal_x,
        modal_y,
        modal_width,
        modal_height,
    );
    let text_x = modal_x.saturating_add(PANEL_PADDING);
    let text_y = modal_y.saturating_add(PANEL_PADDING);
    draw_text(
        frame,
        frame_width,
        text_x,
        text_y,
        "Enter cheat code:",
        COLOR_TEXT,
    );

    // ⚡ Bolt Optimization:
    // Eliminates a per-frame `String` heap allocation (from `format!("{}_", buffer)`)
    // by drawing the input text and the cursor separately.
    let input_y = text_y.saturating_add(LINE_HEIGHT + 4);
    draw_text(frame, frame_width, text_x, input_y, buffer, COLOR_STATUS);
    let cursor_x = text_x.saturating_add(buffer.chars().count() * (GLYPH_SIZE + GLYPH_SPACING));
    draw_text(frame, frame_width, cursor_x, input_y, "_", COLOR_STATUS);
}

fn draw_frame_border(
    frame: &mut [u8],
    frame_width: usize,
    x: usize,
    y: usize,
    width: usize,
    height: usize,
) {
    fill_rect(frame, frame_width, x, y, width, 1, COLOR_PANEL_BORDER);
    fill_rect(
        frame,
        frame_width,
        x,
        y.saturating_add(height.saturating_sub(1)),
        width,
        1,
        COLOR_PANEL_BORDER,
    );
    fill_rect(frame, frame_width, x, y, 1, height, COLOR_PANEL_BORDER);
    fill_rect(
        frame,
        frame_width,
        x.saturating_add(width.saturating_sub(1)),
        y,
        1,
        height,
        COLOR_PANEL_BORDER,
    );
}

fn dim_frame(frame: &mut [u8]) {
    for pixel in frame.chunks_exact_mut(4) {
        pixel[0] = pixel[0] / 3 + COLOR_BACKDROP[0] / 4;
        pixel[1] = pixel[1] / 3 + COLOR_BACKDROP[1] / 4;
        pixel[2] = pixel[2] / 3 + COLOR_BACKDROP[2] / 4;
        pixel[3] = 255;
    }
}

fn draw_char(frame: &mut [u8], frame_width: usize, x: usize, y: usize, ch: char, color: [u8; 4]) {
    let glyph = BASIC_FONTS
        .get(ch)
        .or_else(|| BASIC_FONTS.get('?'))
        .unwrap_or([0; GLYPH_SIZE]);
    for (row_idx, row_bits) in glyph.iter().copied().enumerate() {
        for col_idx in 0..GLYPH_SIZE {
            if (row_bits >> col_idx) & 1 == 1 {
                set_pixel(
                    frame,
                    frame_width,
                    x.saturating_add(col_idx),
                    y.saturating_add(row_idx),
                    color,
                );
            }
        }
    }
}

fn set_pixel(frame: &mut [u8], frame_width: usize, x: usize, y: usize, color: [u8; 4]) {
    if frame_width == 0 {
        return;
    }
    let frame_height = frame.len() / 4 / frame_width;
    if x >= frame_width || y >= frame_height {
        return;
    }
    let offset = (y * frame_width + x) * 4;
    if let Some(pixel) = frame.get_mut(offset..offset + 4) {
        pixel.copy_from_slice(&color);
    }
}

/// ⚡ Bolt Optimization:
/// Eliminates intermediate `String` heap allocations per frame while the overlay is open
/// by writing directly to a reusable `String` buffer via `std::fmt::Write`.
fn main_entry_label(
    entry: MainMenuSelection,
    mut slot_summaries: impl Iterator<Item = OverlaySlotSummary>,
    out: &mut String,
) {
    use std::fmt::Write;
    match entry {
        MainMenuSelection::Resume => out.push_str("Resume"),
        MainMenuSelection::OpenRom => out.push_str("Open ROM..."),
        MainMenuSelection::OpenCheats => out.push_str("Cheats..."),
        MainMenuSelection::SaveSlot(slot) => {
            let _ = write!(out, "Save Slot {slot}: ");
            slot_suffix(slot, &mut slot_summaries, out);
        }
        MainMenuSelection::LoadSlot(slot) => {
            let _ = write!(out, "Load Slot {slot}: ");
            slot_suffix(slot, &mut slot_summaries, out);
        }
        MainMenuSelection::Reset => out.push_str("Reset"),
        MainMenuSelection::Quit => out.push_str("Quit"),
    }
}

fn cheat_label(summary: &OverlayCheatSummary, out: &mut String) {
    use std::fmt::Write;
    let _ = write!(
        out,
        "{} {}",
        if summary.enabled { "ON " } else { "OFF" },
        summary.raw_code
    );
}

fn slot_suffix(
    slot: u8,
    slot_summaries: &mut impl Iterator<Item = OverlaySlotSummary>,
    out: &mut String,
) {
    if let Some(summary) = slot_summaries.find(|summary| summary.slot == slot) {
        summary.render_suffix(out);
    } else {
        out.push_str("Unknown");
    }
}

fn key_to_cheat_char(key: VirtualKeyCode) -> Option<char> {
    match key {
        VirtualKeyCode::A => Some('A'),
        VirtualKeyCode::E => Some('E'),
        VirtualKeyCode::G => Some('G'),
        VirtualKeyCode::I => Some('I'),
        VirtualKeyCode::K => Some('K'),
        VirtualKeyCode::L => Some('L'),
        VirtualKeyCode::N => Some('N'),
        VirtualKeyCode::O => Some('O'),
        VirtualKeyCode::P => Some('P'),
        VirtualKeyCode::S => Some('S'),
        VirtualKeyCode::T => Some('T'),
        VirtualKeyCode::U => Some('U'),
        VirtualKeyCode::V => Some('V'),
        VirtualKeyCode::X => Some('X'),
        VirtualKeyCode::Y => Some('Y'),
        VirtualKeyCode::Z => Some('Z'),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::{
        CheatsSelection, MainMenuSelection, OverlayCheatSummary, OverlayCommand, OverlayModel,
        OverlayPanel, OverlaySelection, OverlaySlotSummary, draw_overlay, draw_text,
    };
    use crate::actions::AppAction;
    use winit::event::VirtualKeyCode;

    #[test]
    fn main_menu_navigation_wraps_and_tracks_selected_slot() {
        let mut overlay = OverlayModel::new(3);
        assert_eq!(
            overlay.selection(0),
            OverlaySelection::Main(MainMenuSelection::Resume)
        );

        overlay.move_prev(0);
        assert_eq!(
            overlay.selection(0),
            OverlaySelection::Main(MainMenuSelection::Quit)
        );

        overlay.move_next(0);
        assert_eq!(
            overlay.selection(0),
            OverlaySelection::Main(MainMenuSelection::Resume)
        );

        overlay.move_next(0);
        overlay.move_next(0);
        overlay.move_next(0);
        assert_eq!(
            overlay.selection(0),
            OverlaySelection::Main(MainMenuSelection::SaveSlot(1))
        );

        assert_eq!(overlay.selected_slot(), 1);
    }

    #[test]
    fn moving_main_menu_slot_selection_updates_selected_slot() {
        let mut overlay = OverlayModel::new(3);

        overlay.move_next(0);
        overlay.move_next(0);
        overlay.move_next(0);
        overlay.move_next(0);
        assert_eq!(
            overlay.selection(0),
            OverlaySelection::Main(MainMenuSelection::SaveSlot(2))
        );
        assert_eq!(overlay.selected_slot(), 2);

        overlay.move_next(0);
        overlay.move_next(0);
        assert_eq!(
            overlay.selection(0),
            OverlaySelection::Main(MainMenuSelection::LoadSlot(1))
        );
        assert_eq!(overlay.selected_slot(), 1);
    }

    #[test]
    fn draw_text_marks_pixels_inside_target_buffer() {
        let mut frame = vec![0_u8; 64 * 64 * 4];
        draw_text(&mut frame, 64, 2, 2, "NES", [255, 255, 255, 255]);
        assert!(frame.iter().any(|component| *component != 0));
    }

    #[test]
    fn draw_overlay_renders_main_panel_selection_and_status_message() {
        let mut frame = vec![16_u8; 128 * 96 * 4];
        let mut overlay = OverlayModel::new(2);
        overlay.open();
        overlay.move_next(0);
        overlay.set_status_message("Slot 1 loaded");
        let slots = vec![
            OverlaySlotSummary {
                slot: 1,
                status_label: "Saved",
                modified_unix_secs: Some(1_700_000_000),
            },
            OverlaySlotSummary {
                slot: 2,
                status_label: "Empty",
                modified_unix_secs: None,
            },
        ];

        draw_overlay(
            &mut frame,
            128,
            96,
            &overlay,
            slots.into_iter(),
            std::iter::empty(),
            0,
        );

        assert!(
            frame.iter().any(|component| *component != 16),
            "overlay draw should mutate the frame"
        );
    }

    #[test]
