//! The player's runtime toolbox for bending the rules of the NES universe.
//!
//! This module maintains a local inventory of active and inactive Game Genie
//! codes during a single play session. Instead of forcing users to delete codes
//! they temporarily want to bypass, this manager tracks a discrete `enabled` flag
//! for each entry. When codes are sent to the core emulator, only the activated
//! subset is applied.
//!
//! Because `SessionCheats` validates raw code strings through the core `CheatCode`
//! parser immediately upon addition, it guarantees that its inventory never holds
//! syntactically malformed Game Genie commands.

use nes_core::{CheatCode, CheatCodeError};

/// One session-local cheat entry managed by the desktop frontend.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SessionCheat {
    /// The normalized Game Genie string (e.g., "GOSSIP").
    pub raw_code: String,
    /// Whether this cheat is currently active in the core.
    pub enabled: bool,
}

/// Errors raised while mutating the session cheat list.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SessionCheatError {
    /// The cheat code string was not a valid Game Genie sequence.
    InvalidCode(CheatCodeError),
    /// An operation was attempted on an index that does not exist in the session list.
    MissingIndex {
        /// The requested index.
        index: usize,
        /// The total number of entries.
        len: usize,
    },
}

impl std::fmt::Display for SessionCheatError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::InvalidCode(err) => write!(f, "{err}"),
            Self::MissingIndex { index, len } => {
                write!(
                    f,
                    "cheat entry index {index} is out of bounds for {len} entries"
                )
            }
        }
    }
}

impl std::error::Error for SessionCheatError {}

impl From<CheatCodeError> for SessionCheatError {
    fn from(value: CheatCodeError) -> Self {
        Self::InvalidCode(value)
    }
}

/// Ordered current-session cheat list for the active ROM.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct SessionCheats {
    entries: Vec<SessionCheat>,
}

impl SessionCheats {
    /// Creates an empty session cheat list.
    ///
    /// ## Examples
    ///
    /// ```
    /// use nes_desktop::session_cheats::SessionCheats;
    /// let cheats = SessionCheats::new();
    /// assert!(cheats.is_empty());
    /// ```
    #[must_use]
    pub const fn new() -> Self {
        Self {
            entries: Vec::new(),
        }
    }

    /// Parses and initializes a session cheat list from multiple raw Game Genie strings.
    ///
    /// ## Examples
    ///
    /// ```
    /// use nes_desktop::session_cheats::SessionCheats;
    /// let codes = vec!["GOSSIP".to_owned()];
    /// let cheats = SessionCheats::from_raw_codes(&codes).unwrap();
    /// assert_eq!(cheats.len(), 1);
    /// ```
    pub fn from_raw_codes(raw_codes: &[String]) -> Result<Self, SessionCheatError> {
        let mut cheats = Self::new();
        for raw_code in raw_codes {
            cheats.add(raw_code)?;
        }
        Ok(cheats)
    }

    /// Validates, normalizes, and adds a new cheat code to the session, enabling it by default.
    ///
    /// ## Examples
    ///
    /// ```
    /// use nes_desktop::session_cheats::SessionCheats;
    /// let mut cheats = SessionCheats::new();
    /// cheats.add("GOSSIP").unwrap();
    /// assert_eq!(cheats.entries()[0].raw_code, "GOSSIP");
    /// ```
    pub fn add(&mut self, raw_code: &str) -> Result<(), SessionCheatError> {
        let normalized = normalize_cheat_code(raw_code)?;
        self.entries.push(SessionCheat {
            raw_code: normalized,
            enabled: true,
        });
        Ok(())
    }

    /// Toggles the enabled state of the cheat code at the specified index.
    ///
    /// ## Examples
    ///
    /// ```
    /// use nes_desktop::session_cheats::SessionCheats;
    /// let mut cheats = SessionCheats::new();
    /// cheats.add("GOSSIP").unwrap();
    /// cheats.toggle(0).unwrap();
    /// assert_eq!(cheats.entries()[0].enabled, false);
    /// ```
    pub fn toggle(&mut self, index: usize) -> Result<(), SessionCheatError> {
        let len = self.entries.len();
        let entry = self
            .entries
            .get_mut(index)
            .ok_or(SessionCheatError::MissingIndex { index, len })?;
        entry.enabled = !entry.enabled;
        Ok(())
    }

    /// Removes and returns the cheat code at the specified index.
    ///
    /// ## Examples
    ///
    /// ```
    /// use nes_desktop::session_cheats::SessionCheats;
    /// let mut cheats = SessionCheats::new();
    /// cheats.add("GOSSIP").unwrap();
    /// let removed = cheats.remove(0).unwrap();
    /// assert_eq!(removed.raw_code, "GOSSIP");
    /// ```
    pub fn remove(&mut self, index: usize) -> Result<SessionCheat, SessionCheatError> {
        if index >= self.entries.len() {
            return Err(SessionCheatError::MissingIndex {
                index,
                len: self.entries.len(),
            });
        }
        Ok(self.entries.remove(index))
    }

    /// Evicts all stored codes, wiping the slate clean for the next playthrough.
    ///
    /// ## Examples
    ///
    /// ```
    /// use nes_desktop::session_cheats::SessionCheats;
    /// let mut cheats = SessionCheats::new();
    /// cheats.add("GOSSIP").unwrap();
    /// cheats.clear();
    /// assert!(cheats.is_empty());
    /// ```
    pub fn clear(&mut self) {
        self.entries.clear();
    }

    /// Exposes the immutable ledger of every active and inactive code in the session.
    ///
    /// ## Examples
    ///
    /// ```
    /// use nes_desktop::session_cheats::SessionCheats;
    /// let mut cheats = SessionCheats::new();
    /// cheats.add("GOSSIP").unwrap();
    /// assert_eq!(cheats.entries()[0].raw_code, "GOSSIP");
    /// ```
    #[must_use]
    pub fn entries(&self) -> &[SessionCheat] {
        &self.entries
    }

    /// Extracts an iterator of just the raw Game Genie strings that are currently switched on.
    ///
    /// This output is ideal for directly feeding into the core emulator configuration.
    ///
    /// **⚡ Bolt Optimization:** Returns an `impl Iterator<Item = &str>` instead of allocating
    /// and returning a `Vec<String>`. This achieves zero-cost abstraction and eliminates
    /// `.clone()` overhead on memory allocations.
    ///
    /// ## Examples
    ///
    /// ```
    /// use nes_desktop::session_cheats::SessionCheats;
    /// let mut cheats = SessionCheats::new();
    /// cheats.add("GOSSIP").unwrap();
    /// cheats.add("ZEXPYGLA").unwrap();
    /// cheats.toggle(1).unwrap(); // disable the second code
    /// let codes: Vec<_> = cheats.enabled_codes().collect();
    /// assert_eq!(codes, vec!["GOSSIP"]);
    /// ```
    pub fn enabled_codes(&self) -> impl Iterator<Item = &str> {
        self.entries
            .iter()
            .filter(|entry| entry.enabled)
            .map(|entry| entry.raw_code.as_str())
    }

    /// Counts how many distinct cheat codes are being tracked, regardless of active status.
    ///
    /// ## Examples
    ///
    /// ```
    /// use nes_desktop::session_cheats::SessionCheats;
    /// let mut cheats = SessionCheats::new();
    /// cheats.add("GOSSIP").unwrap();
    /// assert_eq!(cheats.len(), 1);
    /// ```
    #[must_use]
    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// Verifies if the inventory is entirely empty.
    ///
    /// ## Examples
    ///
    /// ```
    /// use nes_desktop::session_cheats::SessionCheats;
    /// let cheats = SessionCheats::new();
    /// assert!(cheats.is_empty());
    /// ```
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }
}

fn normalize_cheat_code(raw_code: &str) -> Result<String, SessionCheatError> {
    let normalized = raw_code.trim().to_ascii_uppercase();
    let _: CheatCode = normalized.parse()?;
    Ok(normalized)
}

#[cfg(test)]
mod tests {
    use super::{SessionCheatError, SessionCheats};

    #[test]
    fn add_normalizes_lowercase_codes() {
        let mut cheats = SessionCheats::new();

        cheats.add("gossip").expect("valid code should add");

        assert_eq!(cheats.entries()[0].raw_code, "GOSSIP");
        assert!(cheats.entries()[0].enabled);
    }

    #[test]
    fn from_raw_codes_preserves_duplicate_order() {
        let cheats = SessionCheats::from_raw_codes(&[
            "GOSSIP".to_owned(),
            "ZEXPYGLA".to_owned(),
            "GOSSIP".to_owned(),
        ])
        .expect("seeded codes should validate");

        assert_eq!(cheats.len(), 3);
        let enabled: Vec<_> = cheats.enabled_codes().collect();
        assert_eq!(enabled, vec!["GOSSIP", "ZEXPYGLA", "GOSSIP"]);
    }

    #[test]
    fn toggle_and_remove_mutate_expected_entries() {
        let mut cheats =
            SessionCheats::from_raw_codes(&["GOSSIP".to_owned(), "ZEXPYGLA".to_owned()])
                .expect("seeded codes should validate");

        cheats.toggle(0).expect("toggle should succeed");
        assert!(!cheats.entries()[0].enabled);
        let enabled: Vec<_> = cheats.enabled_codes().collect();
        assert_eq!(enabled, vec!["ZEXPYGLA"]);

        let removed = cheats.remove(1).expect("remove should succeed");
        assert_eq!(removed.raw_code, "ZEXPYGLA");
        assert_eq!(cheats.len(), 1);
    }

    #[test]
    fn invalid_codes_are_rejected_before_mutation() {
        let mut cheats = SessionCheats::new();

        let err = cheats.add("BLAH").expect_err("invalid code should fail");

        assert!(matches!(err, SessionCheatError::InvalidCode(_)));
        assert!(cheats.is_empty());
    }

    #[test]
    fn missing_indices_report_bounds_errors() {
        let mut cheats = SessionCheats::new();
        let err = cheats.toggle(0).expect_err("missing entry should fail");
        assert_eq!(err, SessionCheatError::MissingIndex { index: 0, len: 0 });
    }

    #[test]
    fn clear_removes_all_entries() {
        let mut cheats =
            SessionCheats::from_raw_codes(&["GOSSIP".to_owned(), "ZEXPYGLA".to_owned()])
                .expect("seeded codes should validate");
        assert_eq!(cheats.len(), 2);
        cheats.clear();
        assert_eq!(cheats.len(), 0);
    }

    #[test]
    fn is_empty_returns_true_for_empty_list() {
        let mut cheats = SessionCheats::new();
        assert!(cheats.is_empty());
        cheats.add("GOSSIP").expect("code should add successfully");
        assert!(!cheats.is_empty());
        cheats.clear();
        assert!(cheats.is_empty());
    }

    #[test]
    fn session_cheat_error_fmt() {
        use nes_core::CheatCodeError;
        let missing_index = SessionCheatError::MissingIndex { index: 5, len: 3 };
        assert_eq!(
            missing_index.to_string(),
            "cheat entry index 5 is out of bounds for 3 entries"
        );

        let invalid_code = SessionCheatError::InvalidCode(CheatCodeError::InvalidLength(4));
        assert_eq!(
            invalid_code.to_string(),
            CheatCodeError::InvalidLength(4).to_string()
        );
    }

    #[test]
    fn doc_examples_combinations_work_without_panics() {
        // Combinations of code operations to test unwrap cases
        let mut cheats = SessionCheats::new();
        cheats.add("GOSSIP").expect("add gossip");
        cheats.add("ZEXPYGLA").expect("add zexpygla");
        cheats.toggle(0).expect("toggle index 0");
        let removed = cheats.remove(0).expect("remove index 0");
        assert_eq!(removed.raw_code, "GOSSIP");
        cheats.clear();
        assert!(cheats.is_empty());
        let codes = vec!["GOSSIP".to_owned(), "ZEXPYGLA".to_owned()];
        let cheats2 = SessionCheats::from_raw_codes(&codes).expect("from codes");
        assert_eq!(cheats2.len(), 2);
    }
}

use std::collections::BTreeMap;
use crate::ast::{AddressingMode, Expr, Fixup, FixupKind, OperandSyntax, VectorExprs};
use crate::parser::{
    decode_string_literal, is_quoted_string, parse_const_assignment, parse_expr,
    parse_operand_syntax, split_csv, split_head, split_leading_label, strip_comments,
    normalize_symbol, validate_symbol,
};
use crate::opcode::opcode_for;
use crate::{AssembleConfig, AssembledProgram, DslError};

pub(crate) fn unknown_or_mode_error(line: usize, mnemonic: &str, mode: AddressingMode) -> DslError {
    if has_mnemonic(mnemonic) {
        DslError::UnsupportedAddressing {
            line,
            mnemonic: mnemonic.to_owned(),
            mode: mode_name(mode).to_owned(),
        }
    } else {
        DslError::UnknownMnemonic {
            line,
            mnemonic: mnemonic.to_owned(),
        }
    }
}

pub(crate) fn has_mnemonic(mnemonic: &str) -> bool {
    let modes = [
        AddressingMode::Implied,
        AddressingMode::Accumulator,
        AddressingMode::Immediate,
        AddressingMode::ZeroPage,
        AddressingMode::ZeroPageX,
        AddressingMode::ZeroPageY,
        AddressingMode::Absolute,
        AddressingMode::AbsoluteX,
        AddressingMode::AbsoluteY,
        AddressingMode::Indirect,
        AddressingMode::IndirectX,
        AddressingMode::IndirectY,
        AddressingMode::Relative,
    ];
    modes.iter().any(|&m| opcode_for(mnemonic, m).is_some())
}

pub(crate) fn mode_name(mode: AddressingMode) -> &'static str {
    match mode {
        AddressingMode::Implied => "implied",
        AddressingMode::Accumulator => "accumulator",
        AddressingMode::Immediate => "immediate",
        AddressingMode::ZeroPage => "zeropage",
        AddressingMode::ZeroPageX => "zeropage,X",
        AddressingMode::ZeroPageY => "zeropage,Y",
        AddressingMode::Absolute => "absolute",
        AddressingMode::AbsoluteX => "absolute,X",
        AddressingMode::AbsoluteY => "absolute,Y",
        AddressingMode::Indirect => "indirect",
        AddressingMode::IndirectX => "(indirect,X)",
        AddressingMode::IndirectY => "(indirect),Y",
        AddressingMode::Relative => "relative",
    }
}

pub(crate) fn is_branch_mnemonic(mnemonic: &str) -> bool {
    matches!(
        mnemonic,
        "BCC" | "BCS" | "BEQ" | "BMI" | "BNE" | "BPL" | "BVC" | "BVS"
    )
}

pub(crate) fn fit_u8(value: i64, line: usize) -> Result<u8, DslError> {
    u8::try_from(value).map_err(|_| DslError::ValueOutOfRange {
        line,
        value,
        width_bits: 8,
    })
}

pub(crate) fn fit_u16(value: i64, line: usize) -> Result<u16, DslError> {
    u16::try_from(value).map_err(|_| DslError::ValueOutOfRange {
        line,
        value,
        width_bits: 16,
    })
}

#[derive(Debug, Clone)]
pub(crate) struct Assembler {
    pub(crate) config: AssembleConfig,
    pub(crate) current_addr: u16,
    pub(crate) bytes: BTreeMap<u16, u8>,
    pub(crate) labels: BTreeMap<String, u16>,
    pub(crate) constants: BTreeMap<String, i64>,
    pub(crate) fixups: Vec<Fixup>,
    pub(crate) vectors: VectorExprs,
}

impl Assembler {
    pub(crate) fn new(config: AssembleConfig) -> Self {
        Self {
            config,
            current_addr: config.default_org,
            bytes: BTreeMap::new(),
            labels: BTreeMap::new(),
            constants: BTreeMap::new(),
            fixups: Vec::new(),
            vectors: VectorExprs::default(),
        }
    }

    pub(crate) fn assemble_line(&mut self, line_no: usize, raw_line: &str) -> Result<(), DslError> {
        let stripped = strip_comments(raw_line);
        let mut line = stripped.trim();
        if line.is_empty() || line.starts_with('#') {
            return Ok(());
        }

        while let Some((label, rest)) = split_leading_label(line) {
            self.define_label(label)?;
            line = rest.trim_start();
            if line.is_empty() {
                return Ok(());
            }
        }

        if line.starts_with('.') {
            self.handle_directive(line_no, line)
        } else {
            self.handle_instruction(line_no, line)
        }
    }

    pub(crate) fn finalize(mut self) -> Result<AssembledProgram, DslError> {
        let fixups = std::mem::take(&mut self.fixups);
        for fixup in fixups {
            let value = self.resolve_expr(&fixup.expr)?;
            match fixup.kind {
                FixupKind::Byte => {
                    let byte = fit_u8(value, fixup.line)?;
                    self.bytes.insert(fixup.addr, byte);
                }
                FixupKind::Word => {
                    let word = fit_u16(value, fixup.line)?;
                    let [lo, hi] = word.to_le_bytes();
                    self.bytes.insert(fixup.addr, lo);
                    self.bytes.insert(fixup.addr.wrapping_add(1), hi);
                }
                FixupKind::Relative => {
                    let target = fit_u16(value, fixup.line)?;
                    let next_pc = fixup.addr.wrapping_add(1);
                    let delta = i32::from(target) - i32::from(next_pc);
                    if !(-128..=127).contains(&delta) {
                        return Err(DslError::BranchOutOfRange {
                            line: fixup.line,
                            from: next_pc,
                            to: target,
                        });
                    }
                    self.bytes.insert(fixup.addr, (delta as i8) as u8);
                }
            }
        }

        let reset_vector = self.resolve_vector(self.vectors.reset.as_ref(), "RESET", true)?;
        let nmi_vector = self.resolve_vector(self.vectors.nmi.as_ref(), "NMI", false)?;
        let irq_vector = self.resolve_vector(self.vectors.irq.as_ref(), "IRQ", false)?;

        Ok(AssembledProgram {
            default_org: self.config.default_org,
            bytes: self.bytes,
            labels: self.labels,
            nmi_vector,
            reset_vector,
            irq_vector,
        })
    }

    fn resolve_vector(
        &self,
        expr: Option<&Expr>,
        default_label: &str,
        required: bool,
    ) -> Result<u16, DslError> {
        if let Some(expr) = expr {
            return fit_u16(self.resolve_expr(expr)?, 0);
        }
        if let Some(addr) = self.labels.get(default_label) {
            return Ok(*addr);
        }
        if required {
            return Err(DslError::MissingResetVector);
        }
        Ok(self.config.default_org)
    }

    fn resolve_expr(&self, expr: &Expr) -> Result<i64, DslError> {
        match expr {
            Expr::Number(value) => Ok(*value),
            Expr::Symbol(name) => self
                .resolve_symbol(name)
                .ok_or_else(|| DslError::UnknownSymbol(name.clone())),
        }
    }

    fn resolve_symbol(&self, symbol: &str) -> Option<i64> {
        self.constants
            .get(symbol)
            .copied()
            .or_else(|| self.labels.get(symbol).copied().map(i64::from))
    }

    fn define_label(&mut self, name: &str) -> Result<(), DslError> {
        let normalized = normalize_symbol(name);
        validate_symbol(&normalized).map_err(|message| DslError::Parse { line: 0, message })?;
        if self.constants.contains_key(&normalized) {
            return Err(DslError::DuplicateLabel(normalized));
        }
        if self
            .labels
            .insert(normalized.clone(), self.current_addr)
            .is_some()
        {
            return Err(DslError::DuplicateLabel(normalized));
        }
        Ok(())
    }

    fn handle_directive(&mut self, line_no: usize, line: &str) -> Result<(), DslError> {
        let (name, rest) = split_head(line);
        let directive = name.to_ascii_lowercase();
        let args = rest.trim();
        match directive.as_str() {
            ".org" => {
                let expr = parse_expr(args, line_no)?;
                let value = fit_u16(self.resolve_expr(&expr)?, line_no)?;
                self.current_addr = value;
                Ok(())
            }
            ".bank" => {
                let expr = parse_expr(args, line_no)?;
                let bank = self.resolve_expr(&expr)?;
                self.current_addr = match bank {
                    0 => 0x8000,
                    1 => 0xC000,
                    _ => {
                        return Err(DslError::Parse {
                            line: line_no,
                            message: "only `.bank 0` and `.bank 1` are supported".to_owned(),
                        });
                    }
                };
                Ok(())
            }
            ".const" => self.handle_const_directive(args, line_no),
            ".byte" => self.handle_byte_directive(args, line_no),
            ".word" => self.handle_word_directive(args, line_no),
            ".text" => self.handle_text_directive(args, line_no),
            ".reset" => {
                self.vectors.reset = Some(parse_expr(args, line_no)?);
                Ok(())
            }
            ".nmi" => {
                self.vectors.nmi = Some(parse_expr(args, line_no)?);
                Ok(())
            }
            ".irq" => {
                self.vectors.irq = Some(parse_expr(args, line_no)?);
                Ok(())
            }
            _ => Err(DslError::Parse {
                line: line_no,
                message: format!("unknown directive '{directive}'"),
            }),
        }
    }

    fn handle_const_directive(&mut self, args: &str, line_no: usize) -> Result<(), DslError> {
        let (name, value_expr) = parse_const_assignment(args, line_no)?;
        let normalized = normalize_symbol(name);
        validate_symbol(&normalized).map_err(|message| DslError::Parse {
            line: line_no,
            message,
        })?;
        if self.labels.contains_key(&normalized) || self.constants.contains_key(&normalized) {
            return Err(DslError::DuplicateConst(normalized));
        }
        let value = self.resolve_expr(&parse_expr(value_expr, line_no)?)?;
        self.constants.insert(normalized, value);
        Ok(())
    }

    fn handle_byte_directive(&mut self, args: &str, line_no: usize) -> Result<(), DslError> {
        for arg in split_csv(args)? {
            if is_quoted_string(arg) {
                let bytes = decode_string_literal(arg).map_err(|message| DslError::Parse {
                    line: line_no,
                    message,
                })?;
                for byte in bytes {
                    self.emit_u8(byte)?;
                }
            } else {
                self.emit_expr_byte(parse_expr(arg, line_no)?, line_no, FixupKind::Byte)?;
            }
        }
        Ok(())
    }

    fn handle_word_directive(&mut self, args: &str, line_no: usize) -> Result<(), DslError> {
        for arg in split_csv(args)? {
            self.emit_expr_word(parse_expr(arg, line_no)?, line_no)?;
        }
        Ok(())
    }

    fn handle_text_directive(&mut self, args: &str, line_no: usize) -> Result<(), DslError> {
        let literals = split_csv(args)?;
        if literals.is_empty() {
            return Err(DslError::Parse {
                line: line_no,
                message: ".text expects at least one quoted string".to_owned(),
            });
        }
        for lit in literals {
            if !is_quoted_string(lit) {
                return Err(DslError::Parse {
                    line: line_no,
                    message: ".text accepts only quoted string literals".to_owned(),
                });
            }
            let bytes = decode_string_literal(lit).map_err(|message| DslError::Parse {
                line: line_no,
                message,
            })?;
            for byte in bytes {
                self.emit_u8(byte)?;
            }
        }
        Ok(())
    }

    fn resolve_addressing_mode(
        &self,
        mnemonic: &str,
        syntax: OperandSyntax,
    ) -> (AddressingMode, Option<FixupKind>, Option<Expr>) {
        match syntax {
            OperandSyntax::Implied => (AddressingMode::Implied, None, None),
            OperandSyntax::Accumulator => (AddressingMode::Accumulator, None, None),
            OperandSyntax::Immediate(expr) => {
                (AddressingMode::Immediate, Some(FixupKind::Byte), Some(expr))
            }
            OperandSyntax::IndirectX(expr) => {
                (AddressingMode::IndirectX, Some(FixupKind::Byte), Some(expr))
            }
            OperandSyntax::IndirectY(expr) => {
                (AddressingMode::IndirectY, Some(FixupKind::Byte), Some(expr))
            }
            OperandSyntax::Indirect(expr) => {
                (AddressingMode::Indirect, Some(FixupKind::Word), Some(expr))
            }
            OperandSyntax::AbsoluteX(expr) => {
                if self.can_use_zeropage(&expr)
                    && opcode_for(mnemonic, AddressingMode::ZeroPageX).is_some()
                {
                    (AddressingMode::ZeroPageX, Some(FixupKind::Byte), Some(expr))
                } else {
                    (AddressingMode::AbsoluteX, Some(FixupKind::Word), Some(expr))
                }
            }
            OperandSyntax::AbsoluteY(expr) => {
                if self.can_use_zeropage(&expr)
                    && opcode_for(mnemonic, AddressingMode::ZeroPageY).is_some()
                {
                    (AddressingMode::ZeroPageY, Some(FixupKind::Byte), Some(expr))
                } else {
                    (AddressingMode::AbsoluteY, Some(FixupKind::Word), Some(expr))
                }
            }
            OperandSyntax::AbsoluteOrZeroPage(expr) => {
                if self.can_use_zeropage(&expr)
                    && opcode_for(mnemonic, AddressingMode::ZeroPage).is_some()
                {
                    (AddressingMode::ZeroPage, Some(FixupKind::Byte), Some(expr))
                } else {
                    (AddressingMode::Absolute, Some(FixupKind::Word), Some(expr))
                }
            }
        }
    }

    fn handle_instruction(&mut self, line_no: usize, line: &str) -> Result<(), DslError> {
        let (head, rest) = split_head(line);
        let mnemonic = head.to_ascii_uppercase();
        let operand = rest.trim();

        if is_branch_mnemonic(&mnemonic) {
            if operand.is_empty() {
                return Err(DslError::Parse {
                    line: line_no,
                    message: format!("{mnemonic} expects a target operand"),
                });
            }
            let opcode = opcode_for(&mnemonic, AddressingMode::Relative).ok_or_else(|| {
                DslError::UnsupportedAddressing {
                    line: line_no,
                    mnemonic: mnemonic.clone(),
                    mode: "relative".to_owned(),
                }
            })?;
            self.emit_u8(opcode)?;
            self.emit_expr_byte(parse_expr(operand, line_no)?, line_no, FixupKind::Relative)?;
            return Ok(());
        }

        let syntax = parse_operand_syntax(operand, line_no)?;

        let (mode, kind, expr_opt) = self.resolve_addressing_mode(&mnemonic, syntax);

        let opcode = opcode_for(&mnemonic, mode)
            .ok_or_else(|| unknown_or_mode_error(line_no, &mnemonic, mode))?;
        self.emit_u8(opcode)?;

        if let (Some(kind), Some(expr)) = (kind, expr_opt) {
            match kind {
                FixupKind::Byte => self.emit_expr_byte(expr, line_no, FixupKind::Byte)?,
                FixupKind::Word => self.emit_expr_word(expr, line_no)?,
                FixupKind::Relative => unreachable!("relative mode handled earlier"),
            }
        }

        Ok(())
    }

    fn can_use_zeropage(&self, expr: &Expr) -> bool {
        match expr {
            Expr::Number(value) => (0..=255).contains(value),
            Expr::Symbol(symbol) => self
                .resolve_symbol(symbol)
                .is_some_and(|value| (0..=255).contains(&value)),
        }
    }

    fn emit_expr_word(&mut self, expr: Expr, line_no: usize) -> Result<(), DslError> {
        match expr {
            Expr::Number(value) => {
                let value = fit_u16(value, line_no)?;
                let [lo, hi] = value.to_le_bytes();
                self.emit_u8(lo)?;
                self.emit_u8(hi)
            }
            Expr::Symbol(symbol) => {
                if let Some(value) = self.resolve_symbol(&symbol) {
                    let value = fit_u16(value, line_no)?;
                    let [lo, hi] = value.to_le_bytes();
                    self.emit_u8(lo)?;
                    self.emit_u8(hi)?;
                } else {
                    let fixup_addr = self.current_addr;
                    self.emit_u8(0)?;
                    self.emit_u8(0)?;
                    self.fixups.push(Fixup {
                        line: line_no,
                        addr: fixup_addr,
                        expr: Expr::Symbol(symbol),
                        kind: FixupKind::Word,
                    });
                }
                Ok(())
            }
        }
    }

    pub(crate) fn emit_expr_byte(
        &mut self,
        expr: Expr,
        line_no: usize,
        kind: FixupKind,
    ) -> Result<(), DslError> {
        match (&expr, &kind) {
            (Expr::Number(value), FixupKind::Byte) => self.emit_u8(fit_u8(*value, line_no)?),
            (Expr::Number(value), FixupKind::Relative) => {
                let target = fit_u16(*value, line_no)?;
                let next_pc = self.current_addr.wrapping_add(1);
                let delta = i32::from(target) - i32::from(next_pc);
                if !(-128..=127).contains(&delta) {
                    return Err(DslError::BranchOutOfRange {
                        line: line_no,
                        from: next_pc,
                        to: target,
                    });
                }
                self.emit_u8((delta as i8) as u8)
            }
            (Expr::Symbol(symbol), FixupKind::Byte) => {
                if let Some(value) = self.resolve_symbol(symbol) {
                    self.emit_u8(fit_u8(value, line_no)?)
                } else {
                    let fixup_addr = self.current_addr;
                    self.emit_u8(0)?;
                    self.fixups.push(Fixup {
                        line: line_no,
                        addr: fixup_addr,
                        expr,
                        kind,
                    });
                    Ok(())
                }
            }
            (Expr::Symbol(_), FixupKind::Relative) => {
                let fixup_addr = self.current_addr;
                self.emit_u8(0)?;
                self.fixups.push(Fixup {
                    line: line_no,
                    addr: fixup_addr,
                    expr,
                    kind,
                });
                Ok(())
            }
            (_, FixupKind::Word) => unreachable!("word handled elsewhere"),
        }
    }

    fn emit_u8(&mut self, byte: u8) -> Result<(), DslError> {
        self.write_resolved_byte(self.current_addr, byte)?;
        self.current_addr = self.current_addr.wrapping_add(1);
        Ok(())
    }

    fn write_resolved_byte(&mut self, addr: u16, byte: u8) -> Result<(), DslError> {
        if let Some(existing) = self.bytes.get(&addr) {
            if *existing != byte {
                return Err(DslError::DuplicateAddress {
                    addr,
                    existing: *existing,
                    incoming: byte,
                });
            }
        }
        self.bytes.insert(addr, byte);
        Ok(())
    }
}

/// Assembles source with default configuration.
///
/// # Errors
///
/// Returns [`DslError`] for parse, symbol, or encoding failures.
pub fn assemble(source: &str) -> Result<AssembledProgram, DslError> {
    assemble_with_config(source, AssembleConfig::default())
}

/// Assembles source with explicit configuration.
///
/// # Errors
///
/// Returns [`DslError`] for parse, symbol, or encoding failures.
pub fn assemble_with_config(
    source: &str,
    config: AssembleConfig,
) -> Result<AssembledProgram, DslError> {
    let mut assembler = Assembler::new(config);
    for (idx, raw_line) in source.lines().enumerate() {
        assembler.assemble_line(idx + 1, raw_line)?;
    }
    assembler.finalize()
}

//! 6502-focused DSL and assembler for generating NES ROMs.
//!
//! The DSL is intentionally assembly-first. It keeps 6502 semantics visible while
//! removing hand-encoded byte work.
//!
//! Supported directives:
//!
//! - `.org <addr>`
//! - `.bank <0|1>` (`0 => $8000`, `1 => $C000`)
//! - `.const NAME = <expr>`
//! - `.byte <expr|string>, ...`
//! - `.word <expr>, ...`
//! - `.text "literal"`
//! - `.reset <expr>`
//! - `.nmi <expr>`
//! - `.irq <expr>`
//!
//! Labels are `name:` and can be referenced from instructions/directives.

mod opcode;
use opcode::opcode_for;

use std::collections::BTreeMap;
use std::fmt;

const PRG_BANK_BYTES: usize = 16 * 1024;
const CHR_BANK_BYTES: usize = 8 * 1024;
const VEC_NMI: u16 = 0xFFFA;
const VEC_RESET: u16 = 0xFFFC;
const VEC_IRQ: u16 = 0xFFFE;

/// Nametable mirroring mode for iNES output.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Mirroring {
    /// Horizontal nametable mirroring.
    Horizontal,
    /// Vertical nametable mirroring.
    Vertical,
}

/// Assembly configuration.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AssembleConfig {
    /// Initial program counter before any `.org`.
    pub default_org: u16,
}

impl Default for AssembleConfig {
    fn default() -> Self {
        Self {
            default_org: 0xC000,
        }
    }
}

/// ROM emission options.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RomBuildOptions {
    /// Cartridge nametable mirroring.
    pub mirroring: Mirroring,
    /// CHR payload. Empty means CHR RAM (`0` CHR banks in header).
    pub chr_rom: Vec<u8>,
}

impl Default for RomBuildOptions {
    fn default() -> Self {
        Self {
            mirroring: Mirroring::Horizontal,
            chr_rom: vec![0_u8; CHR_BANK_BYTES],
        }
    }
}

/// Result of assembling DSL source.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AssembledProgram {
    /// Initial origin used before directives changed it.
    pub default_org: u16,
    /// Output bytes keyed by absolute CPU address.
    pub bytes: BTreeMap<u16, u8>,
    /// Resolved labels (canonicalized to uppercase).
    pub labels: BTreeMap<String, u16>,
    /// NMI vector target.
    pub nmi_vector: u16,
    /// Reset vector target.
    pub reset_vector: u16,
    /// IRQ/BRK vector target.
    pub irq_vector: u16,
}

/// DSL parsing/assembly/ROM emission errors.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DslError {
    /// Source parse failure at a specific line.
    Parse {
        /// Line number of the error.
        line: usize,
        /// Detail message describing the parsing issue.
        message: String,
    },
    /// Duplicate label declaration.
    DuplicateLabel(String),
    /// Duplicate constant declaration.
    DuplicateConst(String),
    /// Address was written multiple times with incompatible bytes.
    DuplicateAddress {
        /// Target CPU address.
        addr: u16,
        /// Previously assembled byte value at this address.
        existing: u8,
        /// Incoming byte value trying to overwrite it.
        incoming: u8,
    },
    /// Symbol was referenced but never defined.
    UnknownSymbol(String),
    /// Value does not fit target width.
    ValueOutOfRange {
        /// Line number where the value definition failed.
        line: usize,
        /// Provided numeric value.
        value: i64,
        /// Bit-width constraint that was violated.
        width_bits: u8,
    },
    /// Relative branch cannot reach target.
    BranchOutOfRange {
        /// Line number containing the branch instruction.
        line: usize,
        /// Program counter executing the branch.
        from: u16,
        /// Target address.
        to: u16,
    },
    /// Instruction mnemonic not recognized.
    UnknownMnemonic {
        /// Line number with the unknown mnemonic.
        line: usize,
        /// The unrecognized mnemonic string.
        mnemonic: String,
    },
    /// Mnemonic exists but addressing mode is unsupported.
    UnsupportedAddressing {
        /// Line number with the unsupported syntax.
        line: usize,
        /// The mnemonic.
        mnemonic: String,
        /// The addressing mode.
        mode: String,
    },
    /// ROM layout cannot represent assembled bytes.
    InvalidRomLayout(String),
    /// Reset vector was not provided and no `RESET:` label was found.
    MissingResetVector,
}

impl fmt::Display for DslError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Parse { line, message } => write!(f, "line {line}: {message}"),
            Self::DuplicateLabel(name) => write!(f, "duplicate label '{name}'"),
            Self::DuplicateConst(name) => write!(f, "duplicate constant '{name}'"),
            Self::DuplicateAddress {
                addr,
                existing,
                incoming,
            } => write!(
                f,
                "address ${addr:04X} already written with {existing:02X}, tried to write {incoming:02X}"
            ),
            Self::UnknownSymbol(name) => write!(f, "unknown symbol '{name}'"),
            Self::ValueOutOfRange {
                line,
                value,
                width_bits,
            } => write!(
                f,
                "line {line}: value {value} does not fit in {width_bits}-bit field"
            ),
            Self::BranchOutOfRange { line, from, to } => write!(
                f,
                "line {line}: branch from ${from:04X} to ${to:04X} out of range"
            ),
            Self::UnknownMnemonic { line, mnemonic } => {
                write!(f, "line {line}: unknown mnemonic '{mnemonic}'")
            }
            Self::UnsupportedAddressing {
                line,
                mnemonic,
                mode,
            } => write!(
                f,
                "line {line}: addressing mode {mode} not supported for {mnemonic}"
            ),
            Self::InvalidRomLayout(message) => f.write_str(message),
            Self::MissingResetVector => {
                f.write_str("missing reset vector (use `.reset` or `reset:` label)")
            }
        }
    }
}

impl std::error::Error for DslError {}

#[derive(Debug, Clone, PartialEq, Eq)]
enum Expr {
    Number(i64),
    Symbol(String),
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum OperandSyntax {
    Implied,
    Accumulator,
    Immediate(Expr),
    IndirectX(Expr),
    IndirectY(Expr),
    Indirect(Expr),
    AbsoluteX(Expr),
    AbsoluteY(Expr),
    AbsoluteOrZeroPage(Expr),
}

fn parse_operand_syntax(operand: &str, line_no: usize) -> Result<OperandSyntax, DslError> {
    if operand.is_empty() {
        return Ok(OperandSyntax::Implied);
    }
    if operand.eq_ignore_ascii_case("A") {
        return Ok(OperandSyntax::Accumulator);
    }

    if let Some(raw) = operand.strip_prefix('#') {
        return Ok(OperandSyntax::Immediate(parse_expr(raw.trim(), line_no)?));
    }

    if let Some(inner) = operand.strip_prefix('(') {
        if let Some(inner) = inner.strip_suffix(",X)") {
            return Ok(OperandSyntax::IndirectX(parse_expr(inner.trim(), line_no)?));
        }

        if let Some(inner) = inner.strip_suffix("),Y") {
            return Ok(OperandSyntax::IndirectY(parse_expr(inner.trim(), line_no)?));
        }

        if let Some(inner) = inner.strip_suffix(')') {
            return Ok(OperandSyntax::Indirect(parse_expr(inner.trim(), line_no)?));
        }
    }

    if let Some(prefix) = operand.strip_suffix(",X") {
        return Ok(OperandSyntax::AbsoluteX(parse_expr(
            prefix.trim(),
            line_no,
        )?));
    }

    if let Some(prefix) = operand.strip_suffix(",Y") {
        return Ok(OperandSyntax::AbsoluteY(parse_expr(
            prefix.trim(),
            line_no,
        )?));
    }

    Ok(OperandSyntax::AbsoluteOrZeroPage(parse_expr(
        operand.trim(),
        line_no,
    )?))
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum AddressingMode {
    Implied,
    Accumulator,
    Immediate,
    ZeroPage,
    ZeroPageX,
    ZeroPageY,
    Absolute,
    AbsoluteX,
    AbsoluteY,
    Indirect,
    IndirectX,
    IndirectY,
    Relative,
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum FixupKind {
    Byte,
    Word,
    Relative,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Fixup {
    line: usize,
    addr: u16,
    expr: Expr,
    kind: FixupKind,
}

#[derive(Debug, Clone, Default, PartialEq, Eq)]
struct VectorExprs {
    nmi: Option<Expr>,
    reset: Option<Expr>,
    irq: Option<Expr>,
}

#[derive(Debug, Clone)]
struct Assembler {
    config: AssembleConfig,
    current_addr: u16,
    bytes: BTreeMap<u16, u8>,
    labels: BTreeMap<String, u16>,
    constants: BTreeMap<String, i64>,
    fixups: Vec<Fixup>,
    vectors: VectorExprs,
}

impl Assembler {
    fn new(config: AssembleConfig) -> Self {
        Self {
            config,
            current_addr: config.default_org,
            bytes: BTreeMap::new(),
            labels: BTreeMap::new(),
            constants: BTreeMap::new(),
            fixups: Vec::new(),
            vectors: VectorExprs::default(),
        }
    }

    fn assemble_line(&mut self, line_no: usize, raw_line: &str) -> Result<(), DslError> {
        let stripped = strip_comments(raw_line);
        let mut line = stripped.trim();
        if line.is_empty() || line.starts_with('#') {
            return Ok(());
        }

        while let Some((label, rest)) = split_leading_label(line) {
            self.define_label(label)?;
            line = rest.trim_start();
            if line.is_empty() {
                return Ok(());
            }
        }

        if line.starts_with('.') {
            self.handle_directive(line_no, line)
        } else {
            self.handle_instruction(line_no, line)
        }
    }

    fn finalize(mut self) -> Result<AssembledProgram, DslError> {
        let fixups = std::mem::take(&mut self.fixups);
        for fixup in fixups {
            let value = self.resolve_expr(&fixup.expr)?;
            match fixup.kind {
                FixupKind::Byte => {
                    let byte = fit_u8(value, fixup.line)?;
                    self.bytes.insert(fixup.addr, byte);
                }
                FixupKind::Word => {
                    let word = fit_u16(value, fixup.line)?;
                    let [lo, hi] = word.to_le_bytes();
                    self.bytes.insert(fixup.addr, lo);
                    self.bytes.insert(fixup.addr.wrapping_add(1), hi);
                }
                FixupKind::Relative => {
                    let target = fit_u16(value, fixup.line)?;
                    let next_pc = fixup.addr.wrapping_add(1);
                    let delta = i32::from(target) - i32::from(next_pc);
                    if !(-128..=127).contains(&delta) {
                        return Err(DslError::BranchOutOfRange {
                            line: fixup.line,
                            from: next_pc,
                            to: target,
                        });
                    }
                    self.bytes.insert(fixup.addr, (delta as i8) as u8);
                }
            }
        }

        let reset_vector = self.resolve_vector(self.vectors.reset.as_ref(), "RESET", true)?;
        let nmi_vector = self.resolve_vector(self.vectors.nmi.as_ref(), "NMI", false)?;
        let irq_vector = self.resolve_vector(self.vectors.irq.as_ref(), "IRQ", false)?;

        Ok(AssembledProgram {
            default_org: self.config.default_org,
            bytes: self.bytes,
            labels: self.labels,
            nmi_vector,
            reset_vector,
            irq_vector,
        })
    }

    fn resolve_vector(
        &self,
        expr: Option<&Expr>,
        default_label: &str,
        required: bool,
    ) -> Result<u16, DslError> {
        if let Some(expr) = expr {
            return fit_u16(self.resolve_expr(expr)?, 0);
        }
        if let Some(addr) = self.labels.get(default_label) {
            return Ok(*addr);
        }
        if required {
            return Err(DslError::MissingResetVector);
        }
        Ok(self.config.default_org)
    }

    fn resolve_expr(&self, expr: &Expr) -> Result<i64, DslError> {
        match expr {
            Expr::Number(value) => Ok(*value),
            Expr::Symbol(name) => self
                .resolve_symbol(name)
                .ok_or_else(|| DslError::UnknownSymbol(name.clone())),
        }
    }

    fn resolve_symbol(&self, symbol: &str) -> Option<i64> {
        self.constants
            .get(symbol)
            .copied()
            .or_else(|| self.labels.get(symbol).copied().map(i64::from))
    }
    fn define_label(&mut self, name: &str) -> Result<(), DslError> {
        let normalized = normalize_symbol(name);
        validate_symbol(&normalized).map_err(|message| DslError::Parse { line: 0, message })?;
        if self.constants.contains_key(&normalized) {
            return Err(DslError::DuplicateLabel(normalized));
        }
        if self
            .labels
            .insert(normalized.clone(), self.current_addr)
            .is_some()
        {
            return Err(DslError::DuplicateLabel(normalized));
        }
        Ok(())
    }

    fn handle_directive(&mut self, line_no: usize, line: &str) -> Result<(), DslError> {
        let (name, rest) = split_head(line);
        let directive = name.to_ascii_lowercase();
        let args = rest.trim();
        match directive.as_str() {
            ".org" => {
                let expr = parse_expr(args, line_no)?;
                let value = fit_u16(self.resolve_expr(&expr)?, line_no)?;
                self.current_addr = value;
                Ok(())
            }
            ".bank" => {
                let expr = parse_expr(args, line_no)?;
                let bank = self.resolve_expr(&expr)?;
                self.current_addr = match bank {
                    0 => 0x8000,
                    1 => 0xC000,
                    _ => {
                        return Err(DslError::Parse {
                            line: line_no,
                            message: "only `.bank 0` and `.bank 1` are supported".to_owned(),
                        });
                    }
                };
                Ok(())
            }
            ".const" => self.handle_const_directive(args, line_no),
            ".byte" => self.handle_byte_directive(args, line_no),
            ".word" => self.handle_word_directive(args, line_no),
            ".text" => self.handle_text_directive(args, line_no),
            ".reset" => {
                self.vectors.reset = Some(parse_expr(args, line_no)?);
                Ok(())
            }
            ".nmi" => {
                self.vectors.nmi = Some(parse_expr(args, line_no)?);
                Ok(())
            }
            ".irq" => {
                self.vectors.irq = Some(parse_expr(args, line_no)?);
                Ok(())
            }
            _ => Err(DslError::Parse {
                line: line_no,
                message: format!("unknown directive '{directive}'"),
            }),
        }
    }

    fn handle_const_directive(&mut self, args: &str, line_no: usize) -> Result<(), DslError> {
        let (name, value_expr) = parse_const_assignment(args, line_no)?;
        let normalized = normalize_symbol(name);
        validate_symbol(&normalized).map_err(|message| DslError::Parse {
            line: line_no,
            message,
        })?;
        if self.labels.contains_key(&normalized) || self.constants.contains_key(&normalized) {
            return Err(DslError::DuplicateConst(normalized));
        }
        let value = self.resolve_expr(&parse_expr(value_expr, line_no)?)?;
        self.constants.insert(normalized, value);
        Ok(())
    }

    fn handle_byte_directive(&mut self, args: &str, line_no: usize) -> Result<(), DslError> {
        for arg in split_csv(args)? {
            if is_quoted_string(arg) {
                let bytes = decode_string_literal(arg).map_err(|message| DslError::Parse {
                    line: line_no,
                    message,
                })?;
                for byte in bytes {
                    self.emit_u8(byte)?;
                }
            } else {
                self.emit_expr_byte(parse_expr(arg, line_no)?, line_no, FixupKind::Byte)?;
            }
        }
        Ok(())
    }

    fn handle_word_directive(&mut self, args: &str, line_no: usize) -> Result<(), DslError> {
        for arg in split_csv(args)? {
            self.emit_expr_word(parse_expr(arg, line_no)?, line_no)?;
        }
        Ok(())
    }

    fn handle_text_directive(&mut self, args: &str, line_no: usize) -> Result<(), DslError> {
        let literals = split_csv(args)?;
        if literals.is_empty() {
            return Err(DslError::Parse {
                line: line_no,
                message: ".text expects at least one quoted string".to_owned(),
            });
        }
        for lit in literals {
            if !is_quoted_string(lit) {
                return Err(DslError::Parse {
                    line: line_no,
                    message: ".text accepts only quoted string literals".to_owned(),
                });
            }
            let bytes = decode_string_literal(lit).map_err(|message| DslError::Parse {
                line: line_no,
                message,
            })?;
            for byte in bytes {
                self.emit_u8(byte)?;
            }
        }
        Ok(())
    }

    fn resolve_addressing_mode(
        &self,
        mnemonic: &str,
        syntax: OperandSyntax,
    ) -> (AddressingMode, Option<FixupKind>, Option<Expr>) {
        match syntax {
            OperandSyntax::Implied => (AddressingMode::Implied, None, None),
            OperandSyntax::Accumulator => (AddressingMode::Accumulator, None, None),
            OperandSyntax::Immediate(expr) => {
                (AddressingMode::Immediate, Some(FixupKind::Byte), Some(expr))
            }
            OperandSyntax::IndirectX(expr) => {
                (AddressingMode::IndirectX, Some(FixupKind::Byte), Some(expr))
            }
            OperandSyntax::IndirectY(expr) => {
                (AddressingMode::IndirectY, Some(FixupKind::Byte), Some(expr))
            }
            OperandSyntax::Indirect(expr) => {
                (AddressingMode::Indirect, Some(FixupKind::Word), Some(expr))
            }
            OperandSyntax::AbsoluteX(expr) => {
                if self.can_use_zeropage(&expr)
                    && opcode_for(mnemonic, AddressingMode::ZeroPageX).is_some()
                {
                    (AddressingMode::ZeroPageX, Some(FixupKind::Byte), Some(expr))
                } else {
                    (AddressingMode::AbsoluteX, Some(FixupKind::Word), Some(expr))
                }
            }
            OperandSyntax::AbsoluteY(expr) => {
                if self.can_use_zeropage(&expr)
                    && opcode_for(mnemonic, AddressingMode::ZeroPageY).is_some()
                {
                    (AddressingMode::ZeroPageY, Some(FixupKind::Byte), Some(expr))
                } else {
                    (AddressingMode::AbsoluteY, Some(FixupKind::Word), Some(expr))
                }
            }
            OperandSyntax::AbsoluteOrZeroPage(expr) => {
                if self.can_use_zeropage(&expr)
                    && opcode_for(mnemonic, AddressingMode::ZeroPage).is_some()
                {
                    (AddressingMode::ZeroPage, Some(FixupKind::Byte), Some(expr))
                } else {
                    (AddressingMode::Absolute, Some(FixupKind::Word), Some(expr))
                }
            }
        }
    }

    fn handle_instruction(&mut self, line_no: usize, line: &str) -> Result<(), DslError> {
        let (head, rest) = split_head(line);
        let mnemonic = head.to_ascii_uppercase();
        let operand = rest.trim();

        if is_branch_mnemonic(&mnemonic) {
            if operand.is_empty() {
                return Err(DslError::Parse {
                    line: line_no,
                    message: format!("{mnemonic} expects a target operand"),
                });
            }
            let opcode = opcode_for(&mnemonic, AddressingMode::Relative).ok_or_else(|| {
                DslError::UnsupportedAddressing {
                    line: line_no,
                    mnemonic: mnemonic.clone(),
                    mode: "relative".to_owned(),
                }
            })?;
            self.emit_u8(opcode)?;
            self.emit_expr_byte(parse_expr(operand, line_no)?, line_no, FixupKind::Relative)?;
            return Ok(());
        }

        let syntax = parse_operand_syntax(operand, line_no)?;

        let (mode, kind, expr_opt) = self.resolve_addressing_mode(&mnemonic, syntax);

        let opcode = opcode_for(&mnemonic, mode)
            .ok_or_else(|| unknown_or_mode_error(line_no, &mnemonic, mode))?;
        self.emit_u8(opcode)?;

        if let (Some(kind), Some(expr)) = (kind, expr_opt) {
            match kind {
                FixupKind::Byte => self.emit_expr_byte(expr, line_no, FixupKind::Byte)?,
                FixupKind::Word => self.emit_expr_word(expr, line_no)?,
                FixupKind::Relative => unreachable!("relative mode handled earlier"),
            }
        }

        Ok(())
    }

    fn can_use_zeropage(&self, expr: &Expr) -> bool {
        match expr {
            Expr::Number(value) => (0..=255).contains(value),
            Expr::Symbol(symbol) => self
                .resolve_symbol(symbol)
                .is_some_and(|value| (0..=255).contains(&value)),
        }
    }

    fn emit_expr_word(&mut self, expr: Expr, line_no: usize) -> Result<(), DslError> {
        match expr {
            Expr::Number(value) => {
                let value = fit_u16(value, line_no)?;
                let [lo, hi] = value.to_le_bytes();
                self.emit_u8(lo)?;
                self.emit_u8(hi)
            }
            Expr::Symbol(symbol) => {
                if let Some(value) = self.resolve_symbol(&symbol) {
                    let value = fit_u16(value, line_no)?;
                    let [lo, hi] = value.to_le_bytes();
                    self.emit_u8(lo)?;
                    self.emit_u8(hi)?;
                } else {
                    let fixup_addr = self.current_addr;
                    self.emit_u8(0)?;
                    self.emit_u8(0)?;
                    self.fixups.push(Fixup {
                        line: line_no,
                        addr: fixup_addr,
                        expr: Expr::Symbol(symbol),
                        kind: FixupKind::Word,
                    });
                }
                Ok(())
            }
        }
    }

    fn emit_expr_byte(
        &mut self,
        expr: Expr,
        line_no: usize,
        kind: FixupKind,
    ) -> Result<(), DslError> {
        match (&expr, &kind) {
            (Expr::Number(value), FixupKind::Byte) => self.emit_u8(fit_u8(*value, line_no)?),
            (Expr::Number(value), FixupKind::Relative) => {
                let target = fit_u16(*value, line_no)?;
                let next_pc = self.current_addr.wrapping_add(1);
                let delta = i32::from(target) - i32::from(next_pc);
                if !(-128..=127).contains(&delta) {
                    return Err(DslError::BranchOutOfRange {
                        line: line_no,
                        from: next_pc,
                        to: target,
                    });
                }
                self.emit_u8((delta as i8) as u8)
            }
            (Expr::Symbol(symbol), FixupKind::Byte) => {
                if let Some(value) = self.resolve_symbol(symbol) {
                    self.emit_u8(fit_u8(value, line_no)?)
                } else {
                    let fixup_addr = self.current_addr;
                    self.emit_u8(0)?;
                    self.fixups.push(Fixup {
                        line: line_no,
                        addr: fixup_addr,
                        expr,
                        kind: FixupKind::Byte,
                    });
                    Ok(())
                }
            }
            (Expr::Symbol(symbol), FixupKind::Relative) => {
                if let Some(value) = self.resolve_symbol(symbol) {
                    let target = fit_u16(value, line_no)?;
                    let next_pc = self.current_addr.wrapping_add(1);
                    let delta = i32::from(target) - i32::from(next_pc);
                    if !(-128..=127).contains(&delta) {
                        return Err(DslError::BranchOutOfRange {
                            line: line_no,
                            from: next_pc,
                            to: target,
                        });
                    }
                    self.emit_u8((delta as i8) as u8)
                } else {
                    let fixup_addr = self.current_addr;
                    self.emit_u8(0)?;
                    self.fixups.push(Fixup {
                        line: line_no,
                        addr: fixup_addr,
                        expr,
                        kind: FixupKind::Relative,
                    });
                    Ok(())
                }
            }
            (_, FixupKind::Word) => Err(DslError::Parse {
                line: line_no,
                message: "internal error: byte emitter used for word fixup".to_owned(),
            }),
        }
    }

    fn emit_u8(&mut self, byte: u8) -> Result<(), DslError> {
        self.write_resolved_byte(self.current_addr, byte)?;
        self.current_addr = self.current_addr.wrapping_add(1);
        Ok(())
    }

    fn write_resolved_byte(&mut self, addr: u16, byte: u8) -> Result<(), DslError> {
        if let Some(existing) = self.bytes.get(&addr) {
            if *existing != byte {
                return Err(DslError::DuplicateAddress {
                    addr,
                    existing: *existing,
                    incoming: byte,
                });
            }
            return Ok(());
        }
        self.bytes.insert(addr, byte);
        Ok(())
    }
}

/// Assembles source with default configuration.
///
/// # Errors
///
/// Returns [`DslError`] for parse, symbol, or encoding failures.
pub fn assemble(source: &str) -> Result<AssembledProgram, DslError> {
    assemble_with_config(source, AssembleConfig::default())
}

/// Assembles source with explicit configuration.
///
/// # Errors
///
/// Returns [`DslError`] for parse, symbol, or encoding failures.
pub fn assemble_with_config(
    source: &str,
    config: AssembleConfig,
) -> Result<AssembledProgram, DslError> {
    let mut assembler = Assembler::new(config);
    for (idx, raw_line) in source.lines().enumerate() {
        assembler.assemble_line(idx + 1, raw_line)?;
    }
    assembler.finalize()
}

/// Builds an iNES mapper-0 ROM from DSL source.
///
/// # Errors
///
/// Returns [`DslError`] if assembly fails or ROM layout is invalid.
pub fn build_ines_nrom_rom(source: &str, options: &RomBuildOptions) -> Result<Vec<u8>, DslError> {
    let program = assemble(source)?;
    emit_ines_nrom_rom(&program, options)
}

/// Emits an iNES mapper-0 ROM from an assembled program.
///
/// # Errors
///
/// Returns [`DslError`] when output cannot fit NROM layout constraints.
pub fn emit_ines_nrom_rom(
    program: &AssembledProgram,
    options: &RomBuildOptions,
) -> Result<Vec<u8>, DslError> {
    let uses_lower_bank = program.bytes.keys().any(|addr| *addr < 0xC000);
    let prg_banks = if uses_lower_bank { 2_usize } else { 1_usize };
    let prg_len = prg_banks * PRG_BANK_BYTES;

    let mut prg = vec![0_u8; prg_len];
    let mut prg_written = vec![false; prg_len];

    for (addr, byte) in &program.bytes {
        insert_mapped_byte(
            &mut prg,
            &mut prg_written,
            prg_banks,
            *addr,
            *byte,
            "program bytes",
        )?;
    }

    write_vector(
        &mut prg,
        &mut prg_written,
        prg_banks,
        VEC_NMI,
        program.nmi_vector,
        "nmi",
    )?;
    write_vector(
        &mut prg,
        &mut prg_written,
        prg_banks,
        VEC_RESET,
        program.reset_vector,
        "reset",
    )?;
    write_vector(
        &mut prg,
        &mut prg_written,
        prg_banks,
        VEC_IRQ,
        program.irq_vector,
        "irq",
    )?;

    let chr_banks = if options.chr_rom.is_empty() {
        0_usize
    } else {
        options.chr_rom.len().div_ceil(CHR_BANK_BYTES)
    };
    if chr_banks > usize::from(u8::MAX) {
        return Err(DslError::InvalidRomLayout(format!(
            "CHR bank count {} exceeds iNES header limit",
            chr_banks
        )));
    }

    let mut rom = Vec::with_capacity(16 + prg_len + chr_banks * CHR_BANK_BYTES);
    rom.extend_from_slice(b"NES\x1A");
    rom.push(prg_banks as u8);
    rom.push(chr_banks as u8);
    let mut flags6 = 0_u8;
    if options.mirroring == Mirroring::Vertical {
        flags6 |= 0x01;
    }
    rom.push(flags6);
    rom.push(0_u8);
    rom.extend_from_slice(&[0_u8; 8]);
    rom.extend_from_slice(&prg);
    if chr_banks != 0 {
        rom.extend_from_slice(&options.chr_rom);
        let pad = chr_banks * CHR_BANK_BYTES - options.chr_rom.len();
        if pad != 0 {
            rom.extend(std::iter::repeat_n(0_u8, pad));
        }
    }

    Ok(rom)
}

fn write_vector(
    prg: &mut [u8],
    written: &mut [bool],
    prg_banks: usize,
    addr: u16,
    target: u16,
    vector_name: &str,
) -> Result<(), DslError> {
    let [lo, hi] = target.to_le_bytes();
    insert_mapped_byte(
        prg,
        written,
        prg_banks,
        addr,
        lo,
        &format!("{vector_name} vector lo"),
    )?;
    insert_mapped_byte(
        prg,
        written,
        prg_banks,
        addr.wrapping_add(1),
        hi,
        &format!("{vector_name} vector hi"),
    )
}

fn insert_mapped_byte(
    prg: &mut [u8],
    written: &mut [bool],
    prg_banks: usize,
    addr: u16,
    value: u8,
    context: &str,
) -> Result<(), DslError> {
    let Some(offset) = cpu_addr_to_prg_offset(prg_banks, addr) else {
        return Err(DslError::InvalidRomLayout(format!(
            "{context}: CPU address ${addr:04X} is outside PRG ROM window ($8000-$FFFF)"
        )));
    };
    if offset >= prg.len() {
        return Err(DslError::InvalidRomLayout(format!(
            "{context}: mapped offset {offset} exceeds PRG image length {}",
            prg.len()
        )));
    }
    if written[offset] && prg[offset] != value {
        return Err(DslError::InvalidRomLayout(format!(
            "{context}: conflicting writes at CPU ${addr:04X} (existing {:02X}, incoming {value:02X})",
            prg[offset]
        )));
    }
    prg[offset] = value;
    written[offset] = true;
    Ok(())
}

fn cpu_addr_to_prg_offset(prg_banks: usize, addr: u16) -> Option<usize> {
    if addr < 0x8000 {
        return None;
    }
    let raw = usize::from(addr - 0x8000);
    match prg_banks {
        1 => Some(raw % PRG_BANK_BYTES),
        2 => Some(raw),
        _ => None,
    }
}

fn unknown_or_mode_error(line: usize, mnemonic: &str, mode: AddressingMode) -> DslError {
    if has_mnemonic(mnemonic) {
        DslError::UnsupportedAddressing {
            line,
            mnemonic: mnemonic.to_owned(),
            mode: mode_name(mode).to_owned(),
        }
    } else {
        DslError::UnknownMnemonic {
            line,
            mnemonic: mnemonic.to_owned(),
        }
    }
}

fn has_mnemonic(mnemonic: &str) -> bool {
    matches!(
        mnemonic,
        "ADC"
            | "AND"
            | "ASL"
            | "BCC"
            | "BCS"
            | "BEQ"
            | "BIT"
            | "BMI"
            | "BNE"
            | "BPL"
            | "BRK"
            | "BVC"
            | "BVS"
            | "CLC"
            | "CLD"
            | "CLI"
            | "CLV"
            | "CMP"
            | "CPX"
            | "CPY"
            | "DEC"
            | "DEX"
            | "DEY"
            | "EOR"
            | "INC"
            | "INX"
            | "INY"
            | "JMP"
            | "JSR"
            | "LDA"
            | "LDX"
            | "LDY"
            | "LSR"
            | "NOP"
            | "ORA"
            | "PHA"
            | "PHP"
            | "PLA"
            | "PLP"
            | "ROL"
            | "ROR"
            | "RTI"
            | "RTS"
            | "SBC"
            | "SEC"
            | "SED"
            | "SEI"
            | "STA"
            | "STX"
            | "STY"
            | "TAX"
            | "TAY"
            | "TSX"
            | "TXA"
            | "TXS"
            | "TYA"
    )
}

fn mode_name(mode: AddressingMode) -> &'static str {
    match mode {
        AddressingMode::Implied => "implied",
        AddressingMode::Accumulator => "accumulator",
        AddressingMode::Immediate => "immediate",
        AddressingMode::ZeroPage => "zeropage",
        AddressingMode::ZeroPageX => "zeropage,X",
        AddressingMode::ZeroPageY => "zeropage,Y",
        AddressingMode::Absolute => "absolute",
        AddressingMode::AbsoluteX => "absolute,X",
        AddressingMode::AbsoluteY => "absolute,Y",
        AddressingMode::Indirect => "indirect",
        AddressingMode::IndirectX => "(indirect,X)",
        AddressingMode::IndirectY => "(indirect),Y",
        AddressingMode::Relative => "relative",
    }
}

fn is_branch_mnemonic(mnemonic: &str) -> bool {
    matches!(
        mnemonic,
        "BCC" | "BCS" | "BEQ" | "BMI" | "BNE" | "BPL" | "BVC" | "BVS"
    )
}

fn fit_u8(value: i64, line: usize) -> Result<u8, DslError> {
    u8::try_from(value).map_err(|_| DslError::ValueOutOfRange {
        line,
        value,
        width_bits: 8,
    })
}

fn fit_u16(value: i64, line: usize) -> Result<u16, DslError> {
    u16::try_from(value).map_err(|_| DslError::ValueOutOfRange {
        line,
        value,
        width_bits: 16,
    })
}

/// **Performance optimization:** Avoids `.collect::<Vec<_>>()` by using an iterator,
/// eliminating an O(N) heap allocation per line of DSL code parsed.
fn strip_comments(line: &str) -> String {
    let mut in_string = false;
    let mut escaped = false;
    let mut out = String::with_capacity(line.len());
    let mut chars = line.chars().peekable();

    while let Some(ch) = chars.next() {
        if in_string {
            out.push(ch);
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_string = false;
            }
            continue;
        }
        if ch == '"' {
            in_string = true;
            out.push(ch);
            continue;
        }
        if ch == ';' {
            break;
        }
        if ch == '/' && chars.peek() == Some(&'/') {
            break;
        }
        out.push(ch);
    }
    out
}

fn split_leading_label(line: &str) -> Option<(&str, &str)> {
    let trimmed = line.trim_start();
    let colon = trimmed.find(':')?;
    let label = trimmed[..colon].trim();
    if label.is_empty() || label.chars().any(char::is_whitespace) {
        return None;
    }
    let rest = &trimmed[colon + 1..];
    Some((label, rest))
}

fn split_head(line: &str) -> (&str, &str) {
    let trimmed = line.trim_start();
    let Some(split) = trimmed.find(char::is_whitespace) else {
        return (trimmed, "");
    };
    let head = &trimmed[..split];
    let rest = &trimmed[split..];
    (head, rest)
}

fn parse_const_assignment(input: &str, line_no: usize) -> Result<(&str, &str), DslError> {
    let Some(eq_index) = input.find('=') else {
        return Err(DslError::Parse {
            line: line_no,
            message: ".const expects `NAME = value`".to_owned(),
        });
    };
    let name = input[..eq_index].trim();
    let value = input[eq_index + 1..].trim();
    if name.is_empty() || value.is_empty() {
        return Err(DslError::Parse {
            line: line_no,
            message: ".const expects `NAME = value`".to_owned(),
        });
    }
    Ok((name, value))
}

fn normalize_symbol(symbol: &str) -> String {
    symbol.trim().to_ascii_uppercase()
}

fn validate_symbol(symbol: &str) -> Result<(), String> {
    let mut chars = symbol.chars();
    let Some(first) = chars.next() else {
        return Err("symbol cannot be empty".to_owned());
    };
    if !(first.is_ascii_alphabetic() || first == '_') {
        return Err("symbol must start with [A-Za-z_]".to_owned());
    }
    if chars.any(|ch| !(ch.is_ascii_alphanumeric() || ch == '_')) {
        return Err("symbol must contain only [A-Za-z0-9_]".to_owned());
    }
    Ok(())
}

fn parse_expr(input: &str, line_no: usize) -> Result<Expr, DslError> {
    let token = input.trim();
    if token.is_empty() {
        return Err(DslError::Parse {
            line: line_no,
            message: "expected expression".to_owned(),
        });
    }

    let (sign, rest) = if let Some(rest) = token.strip_prefix('-') {
        (-1_i64, rest.trim())
    } else if let Some(rest) = token.strip_prefix('+') {
        (1_i64, rest.trim())
    } else {
        (1_i64, token)
    };

    let parsed = if let Some(hex) = rest.strip_prefix('$') {
        i64::from_str_radix(hex, 16).ok()
    } else if let Some(bin) = rest.strip_prefix('%') {
        i64::from_str_radix(bin, 2).ok()
    } else if let Some(hex) = rest.strip_prefix("0x").or_else(|| rest.strip_prefix("0X")) {
        i64::from_str_radix(hex, 16).ok()
    } else {
        rest.parse::<i64>().ok()
    };

    let Some(value) = parsed else {
        if sign != 1 {
            return Err(DslError::Parse {
                line: line_no,
                message: format!("invalid numeric expression '{token}'"),
            });
        }
        let symbol = normalize_symbol(rest);
        validate_symbol(&symbol).map_err(|message| DslError::Parse {
            line: line_no,
            message,
        })?;
        return Ok(Expr::Symbol(symbol));
    };

    Ok(Expr::Number(sign * value))
}

fn split_csv(input: &str) -> Result<Vec<&str>, DslError> {
    let mut out = Vec::new();
    let mut in_string = false;
    let mut escaped = false;
    let mut start_idx = 0;

    for (idx, ch) in input.char_indices() {
        if in_string {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_string = false;
            }
            continue;
        }
        match ch {
            '"' => {
                in_string = true;
            }
            ',' => {
                let item = input[start_idx..idx].trim();
                if !item.is_empty() {
                    out.push(item);
                }
                start_idx = idx + ch.len_utf8();
            }
            _ => {}
        }
    }

    if in_string {
        return Err(DslError::Parse {
            line: 0,
            message: "unterminated string literal".to_owned(),
        });
    }

    let tail = input[start_idx..].trim();
    if !tail.is_empty() {
        out.push(tail);
    }
    Ok(out)
}

fn is_quoted_string(value: &str) -> bool {
    value.len() >= 2 && value.starts_with('"') && value.ends_with('"')
}

fn decode_string_literal(literal: &str) -> Result<Vec<u8>, String> {
    if !is_quoted_string(literal) {
        return Err("expected quoted string literal".to_owned());
    }

    let inner = &literal[1..literal.len() - 1];
    let mut bytes = Vec::with_capacity(inner.len());
    let mut chars = inner.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch != '\\' {
            if (ch as u32) > 0xFF {
                return Err(format!("character '{ch}' is outside byte range"));
            }
            bytes.push(ch as u8);
            continue;
        }

        let esc = chars
            .next()
            .ok_or_else(|| "dangling escape sequence".to_owned())?;
        match esc {
            'n' => bytes.push(b'\n'),
            'r' => bytes.push(b'\r'),
            't' => bytes.push(b'\t'),
            '\\' => bytes.push(b'\\'),
            '"' => bytes.push(b'"'),
            'x' => {
                let hi = chars
                    .next()
                    .ok_or_else(|| "expected two hex digits after \\x".to_owned())?;
                let lo = chars
                    .next()
                    .ok_or_else(|| "expected two hex digits after \\x".to_owned())?;

                // **Performance optimization:** Replaced intermediate string allocation
                // during hex escape parsing with direct character parsing.
                let hi_val = hi
                    .to_digit(16)
                    .ok_or_else(|| "invalid hex escape sequence".to_owned())?;
                let lo_val = lo
                    .to_digit(16)
                    .ok_or_else(|| "invalid hex escape sequence".to_owned())?;
                bytes.push((hi_val << 4 | lo_val) as u8);
            }
            _ => return Err(format!("unsupported escape '\\{esc}'")),
        }
    }
    Ok(bytes)
}

