            ("STX", &[ZeroPage, ZeroPageY, Absolute]),
            ("STY", &[ZeroPage, ZeroPageX, Absolute]),
            ("TAX", &[Implied]),
            ("TAY", &[Implied]),
            ("TSX", &[Implied]),
            ("TXA", &[Implied]),
            ("TXS", &[Implied]),
            ("TYA", &[Implied]),
        ];

        for &(mnemonic, modes) in supported_modes {
            for &mode in modes {
                assert!(
                    opcode_for(mnemonic, mode).is_some(),
                    "expected opcode for {mnemonic} in mode {}",
                    mode_name(mode)
                );
            }
        }

        assert!(opcode_for("LDA", AddressingMode::Implied).is_none());
        assert!(opcode_for("WUT", AddressingMode::Immediate).is_none());
    }

    #[test]
    fn parser_helper_functions_enforce_expected_rules() {
        assert_eq!(
            strip_comments(r#"LDA #$01 ; trailing comment"#),
            "LDA #$01 "
        );
        assert_eq!(
            strip_comments(r#"LDA #"//" // real comment"#),
            r#"LDA #"//" "#
        );

        assert_eq!(split_leading_label("loop: NOP"), Some(("loop", " NOP")));
        assert_eq!(split_leading_label("bad label: NOP"), None);

        assert_eq!(
            parse_const_assignment("NAME = $10", 12).expect("const assignment"),
            ("NAME", "$10")
        );
        assert!(parse_const_assignment("NAME", 12).is_err());
        assert!(parse_const_assignment("= $10", 12).is_err());
        assert!(parse_const_assignment("NAME =", 12).is_err());

        assert!(validate_symbol("GOOD_NAME1").is_ok());
        assert!(validate_symbol("_good").is_ok());
        assert!(validate_symbol("").is_err());
        assert!(validate_symbol("1bad").is_err());
        assert!(validate_symbol("bad-name").is_err());

        assert_eq!(
            parse_expr("-$10", 1).expect("negative hex"),
            Expr::Number(-16)
        );
        assert_eq!(
            parse_expr("+0x20", 1).expect("positive hex"),
            Expr::Number(32)
        );
        assert_eq!(
            parse_expr("label_name", 1).expect("symbol parse"),
            Expr::Symbol("LABEL_NAME".to_owned())
        );
        assert!(parse_expr("-label_name", 1).is_err());
    }

    #[test]
    fn csv_and_string_literal_helpers_handle_escapes_and_errors() {
        let parts = split_csv(r#""A,B", $10, "C\"D""#).expect("csv parse");
        assert_eq!(parts, vec![r#""A,B""#, "$10", r#""C\"D""#]);

        let decoded = decode_string_literal(r#""A\n\r\t\\\"\x41""#).expect("string decode");
        assert_eq!(decoded, vec![b'A', b'\n', b'\r', b'\t', b'\\', b'"', 0x41]);

        let utf_err = decode_string_literal("\"\u{0100}\"").expect_err("out of byte range");
        assert!(utf_err.contains("outside byte range"));

        let dangling_escape =
            decode_string_literal("\"abc\\\"").expect_err("dangling escape should fail");
        assert!(dangling_escape.contains("dangling escape sequence"));

        let invalid_hex = decode_string_literal(r#""\xG1""#).expect_err("invalid hex escape");
        assert!(invalid_hex.contains("invalid hex escape sequence"));

        let invalid_hex2 = decode_string_literal(r#""\x1Z""#).expect_err("invalid hex escape");
        assert!(invalid_hex2.contains("invalid hex escape sequence"));
    }

    #[test]
    fn parse_expr_reports_unknown_mnemonic_with_one_based_line_numbers() {
        let err = assemble("WUT").expect_err("unknown mnemonic should fail");
        match err {
            DslError::UnknownMnemonic { line, mnemonic } => {
                assert_eq!(line, 1);
                assert_eq!(mnemonic, "WUT");
            }
            other => panic!("unexpected error: {other:?}"),
        }
    }

    #[test]
    fn branch_relative_encoding_is_correct_for_in_range_targets() {
        let mut immediate = Assembler::new(AssembleConfig::default());
        immediate.current_addr = 0xC001;
        immediate
            .emit_expr_byte(Expr::Number(0xC004), 1, FixupKind::Relative)
            .expect("immediate relative should emit");
        assert_eq!(immediate.bytes.get(&0xC001), Some(&0x02));

        let mut fixup = Assembler::new(AssembleConfig::default());
        fixup.fixups.push(Fixup {
            line: 1,
            addr: 0xC001,
            expr: Expr::Symbol("TARGET".to_owned()),
            kind: FixupKind::Relative,
        });
        fixup.labels.insert("TARGET".to_owned(), 0xC003);
        fixup.vectors.reset = Some(Expr::Number(0xC000));
        let finalized = fixup
            .finalize()
            .expect("forward relative fixup should resolve");
        assert_eq!(finalized.bytes.get(&0xC001), Some(&0x01));
    }

    #[test]
    fn emit_ines_rom_keeps_single_bank_for_upper_bank_program_bytes_only() {
        let program = assemble(
            r#"
            .bank 1
            RESET:
                LDA #$01
                NOP
            .reset RESET
        "#,
        )
        .expect("assembly should succeed");
        let rom =
            emit_ines_nrom_rom(&program, &RomBuildOptions::default()).expect("rom should emit");
        assert_eq!(
            rom[4], 1,
            "program without <$C000 bytes should stay single-bank"
        );
    }

    #[test]
    fn insert_mapped_byte_allows_vector_bytes_that_match_existing_program_data() {
        let mut bytes = BTreeMap::new();
        bytes.insert(VEC_RESET, 0x34);
        bytes.insert(VEC_RESET + 1, 0x12);
        let program = AssembledProgram {
            default_org: 0xC000,
            bytes,
            labels: BTreeMap::new(),
            nmi_vector: 0x1234,
            reset_vector: 0x1234,
            irq_vector: 0x1234,
        };
        let rom = emit_ines_nrom_rom(&program, &RomBuildOptions::default())
            .expect("matching vector bytes should not conflict");
        assert_eq!(rom[4], 1);
    }

    #[test]
    fn strip_comments_handles_string_boundaries_and_trailing_slashes() {
        assert_eq!(
            strip_comments(r#".text "a;still" ; comment"#),
            r#".text "a;still" "#
        );
        assert_eq!(strip_comments("/"), "/");
        assert_eq!(strip_comments("/x"), "/x");
        assert_eq!(strip_comments("x//comment"), "x");
    }

    #[test]
    fn quoted_string_predicate_requires_both_delimiters() {
        assert!(is_quoted_string(r#""ok""#));
        assert!(!is_quoted_string(r#""missing-end"#));
        assert!(!is_quoted_string(r#"missing-start""#));
    }

    #[test]
    fn decode_string_literal_accepts_byte_boundary_character_ff() {
        let decoded = decode_string_literal("\"\u{00FF}\"").expect("0xFF should be valid");
        assert_eq!(decoded, vec![0xFF]);
    }
}

use crate::ast::{Expr, OperandSyntax};
use crate::DslError;

/// **Performance optimization:** Avoids `.collect::<Vec<_>>()` by using an iterator,
/// eliminating an O(N) heap allocation per line of DSL code parsed.
pub(crate) fn strip_comments(line: &str) -> String {
    let mut in_string = false;
    let mut escaped = false;
    let mut out = String::with_capacity(line.len());
    let mut chars = line.chars().peekable();

    while let Some(ch) = chars.next() {
        if in_string {
            out.push(ch);
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_string = false;
            }
            continue;
        }
        if ch == '"' {
            in_string = true;
            out.push(ch);
            continue;
        }
        if ch == ';' {
            break;
        }
        if ch == '/' && chars.peek() == Some(&'/') {
            break;
        }
        out.push(ch);
    }
    out
}

pub(crate) fn split_leading_label(line: &str) -> Option<(&str, &str)> {
    let trimmed = line.trim_start();
    let colon = trimmed.find(':')?;
    let label = trimmed[..colon].trim();
    if label.is_empty() || label.chars().any(char::is_whitespace) {
        return None;
    }
    let rest = &trimmed[colon + 1..];
    Some((label, rest))
}

pub(crate) fn split_head(line: &str) -> (&str, &str) {
    let trimmed = line.trim_start();
    let Some(split) = trimmed.find(char::is_whitespace) else {
        return (trimmed, "");
    };
    let head = &trimmed[..split];
    let rest = &trimmed[split..];
    (head, rest)
}

pub(crate) fn parse_const_assignment(input: &str, line_no: usize) -> Result<(&str, &str), DslError> {
    let Some(eq_index) = input.find('=') else {
        return Err(DslError::Parse {
            line: line_no,
            message: "expected `=` in `.const` assignment".to_owned(),
        });
    };
    let name = input[..eq_index].trim();
    let value = input[eq_index + 1..].trim();
    if name.is_empty() || value.is_empty() {
        return Err(DslError::Parse {
            line: line_no,
            message: "invalid `.const` assignment syntax".to_owned(),
        });
    }
    Ok((name, value))
}

pub(crate) fn normalize_symbol(symbol: &str) -> String {
    symbol.to_ascii_uppercase()
}

pub(crate) fn validate_symbol(symbol: &str) -> Result<(), String> {
    let Some(first) = symbol.chars().next() else {
        return Err("symbol cannot be empty".to_owned());
    };
    if !first.is_ascii_alphabetic() && first != '_' {
        return Err(format!("symbol '{symbol}' must start with letter or underscore"));
    }
    if !symbol.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') {
        return Err(format!("symbol '{symbol}' contains invalid characters"));
    }
    Ok(())
}

pub(crate) fn parse_expr(input: &str, line_no: usize) -> Result<Expr, DslError> {
    if input.is_empty() {
        return Err(DslError::Parse {
            line: line_no,
            message: "expected expression but found empty operand".to_owned(),
        });
    }
    if let Some(hex) = input.strip_prefix('$') {
        let value = i64::from_str_radix(hex, 16).map_err(|_| DslError::Parse {
            line: line_no,
            message: format!("invalid hex number '${hex}'"),
        })?;
        return Ok(Expr::Number(value));
    }
    if let Some(bin) = input.strip_prefix('%') {
        let value = i64::from_str_radix(bin, 2).map_err(|_| DslError::Parse {
            line: line_no,
            message: format!("invalid binary number '%{bin}'"),
        })?;
        return Ok(Expr::Number(value));
    }
    if let Ok(value) = input.parse::<i64>() {
        return Ok(Expr::Number(value));
    }

    let normalized = normalize_symbol(input);
    validate_symbol(&normalized).map_err(|message| DslError::Parse { line: line_no, message })?;
    Ok(Expr::Symbol(normalized))
}

pub(crate) fn split_csv(input: &str) -> Result<Vec<&str>, DslError> {
    let mut parts = Vec::new();
    let mut current_start = 0;
    let mut in_string = false;
    let mut escaped = false;
    let mut chars = input.char_indices().peekable();

    while let Some((idx, ch)) = chars.next() {
        if in_string {
            if escaped {
                escaped = false;
            } else if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_string = false;
            }
            continue;
        }
        if ch == '"' {
            in_string = true;
            continue;
        }
        if ch == ',' {
            parts.push(input[current_start..idx].trim());
            current_start = idx + 1;
        }
    }

    if in_string {
        return Err(DslError::Parse {
            line: 0,
            message: "unterminated string literal in list".to_owned(),
        });
    }

    let tail = input[current_start..].trim();
    if !tail.is_empty() {
        parts.push(tail);
    } else if !parts.is_empty() {
        return Err(DslError::Parse {
            line: 0,
            message: "trailing comma in list".to_owned(),
        });
    }

    Ok(parts)
}

pub(crate) fn is_quoted_string(value: &str) -> bool {
    value.starts_with('"') && value.ends_with('"') && value.len() >= 2
}

pub(crate) fn decode_string_literal(literal: &str) -> Result<Vec<u8>, String> {
    if !is_quoted_string(literal) {
        return Err("expected quoted string literal".to_owned());
    }

    let inner = &literal[1..literal.len() - 1];
    let mut bytes = Vec::with_capacity(inner.len());
    let mut chars = inner.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch != '\\' {
            if (ch as u32) > 0xFF {
                return Err(format!("character '{ch}' is outside byte range"));
            }
            bytes.push(ch as u8);
            continue;
        }

        let esc = chars
            .next()
            .ok_or_else(|| "dangling escape sequence".to_owned())?;
        match esc {
            'n' => bytes.push(b'\n'),
            'r' => bytes.push(b'\r'),
            't' => bytes.push(b'\t'),
            '\\' => bytes.push(b'\\'),
            '"' => bytes.push(b'"'),
            'x' => {
                let hi = chars
                    .next()
                    .ok_or_else(|| "expected two hex digits after \\x".to_owned())?;
                let lo = chars
                    .next()
                    .ok_or_else(|| "expected two hex digits after \\x".to_owned())?;

                let hi_val = hi
                    .to_digit(16)
                    .ok_or_else(|| "invalid hex escape sequence".to_owned())?;
                let lo_val = lo
                    .to_digit(16)
                    .ok_or_else(|| "invalid hex escape sequence".to_owned())?;
                bytes.push((hi_val << 4 | lo_val) as u8);
            }
            _ => return Err(format!("unsupported escape '\\{esc}'")),
        }
    }
    Ok(bytes)
}


pub(crate) fn parse_operand_syntax(operand: &str, line_no: usize) -> Result<OperandSyntax, DslError> {
    if operand.is_empty() {
        return Ok(OperandSyntax::Implied);
    }
    if operand.eq_ignore_ascii_case("A") {
        return Ok(OperandSyntax::Accumulator);
    }

    if let Some(raw) = operand.strip_prefix('#') {
        return Ok(OperandSyntax::Immediate(parse_expr(raw.trim(), line_no)?));
    }

    if let Some(inner) = operand.strip_prefix('(') {
        if let Some(inner) = inner.strip_suffix(",X)") {
            return Ok(OperandSyntax::IndirectX(parse_expr(inner.trim(), line_no)?));
        }
        if let Some(inner) = inner.strip_suffix("),Y") {
            return Ok(OperandSyntax::IndirectY(parse_expr(inner.trim(), line_no)?));
        }
        if let Some(inner) = inner.strip_suffix(')') {
            return Ok(OperandSyntax::Indirect(parse_expr(inner.trim(), line_no)?));
        }
    }

    if let Some(prefix) = operand.strip_suffix(",X") {
        return Ok(OperandSyntax::AbsoluteX(parse_expr(prefix.trim(), line_no)?));
    }

    if let Some(prefix) = operand.strip_suffix(",Y") {
        return Ok(OperandSyntax::AbsoluteY(parse_expr(prefix.trim(), line_no)?));
    }

    Ok(OperandSyntax::AbsoluteOrZeroPage(parse_expr(operand.trim(), line_no)?))
}

use crate::{AssembledProgram, DslError, Mirroring, RomBuildOptions};
use crate::assembler::assemble;

pub(crate) const PRG_BANK_BYTES: usize = 16 * 1024;
pub(crate) const CHR_BANK_BYTES: usize = 8 * 1024;
const VEC_NMI: u16 = 0xFFFA;
pub(crate) const VEC_RESET: u16 = 0xFFFC;
const VEC_IRQ: u16 = 0xFFFE;

/// Builds an iNES mapper-0 ROM from DSL source.
///
/// # Errors
///
/// Returns [`DslError`] if assembly fails or ROM layout is invalid.
pub fn build_ines_nrom_rom(source: &str, options: &RomBuildOptions) -> Result<Vec<u8>, DslError> {
    let program = assemble(source)?;
    emit_ines_nrom_rom(&program, options)
}

/// Emits an iNES mapper-0 ROM from an assembled program.
///
/// # Errors
///
/// Returns [`DslError`] when output cannot fit NROM layout constraints.
pub fn emit_ines_nrom_rom(
    program: &AssembledProgram,
    options: &RomBuildOptions,
) -> Result<Vec<u8>, DslError> {
    let uses_lower_bank = program.bytes.keys().any(|addr| *addr < 0xC000);
    let prg_banks = if uses_lower_bank { 2_usize } else { 1_usize };
    let prg_len = prg_banks * PRG_BANK_BYTES;

    let mut prg = vec![0_u8; prg_len];
    let mut prg_written = vec![false; prg_len];

    for (addr, byte) in &program.bytes {
        insert_mapped_byte(
            &mut prg,
            &mut prg_written,
            prg_banks,
            *addr,
            *byte,
            "program bytes",
        )?;
    }

    write_vector(
        &mut prg,
        &mut prg_written,
        prg_banks,
        VEC_NMI,
        program.nmi_vector,
        "nmi",
    )?;
    write_vector(
        &mut prg,
        &mut prg_written,
        prg_banks,
        VEC_RESET,
        program.reset_vector,
        "reset",
    )?;
    write_vector(
        &mut prg,
        &mut prg_written,
        prg_banks,
        VEC_IRQ,
        program.irq_vector,
        "irq",
    )?;

    let chr_banks = if options.chr_rom.is_empty() {
        0_usize
    } else {
        options.chr_rom.len().div_ceil(CHR_BANK_BYTES)
    };
    if chr_banks > usize::from(u8::MAX) {
        return Err(DslError::InvalidRomLayout(format!(
            "CHR bank count {} exceeds iNES header limit",
            chr_banks
        )));
    }

    let mut out = Vec::with_capacity(16 + prg.len() + options.chr_rom.len());
    out.extend_from_slice(b"NES\x1A");
    out.push(prg_banks as u8);
    out.push(chr_banks as u8);

    let mut flags6 = 0_u8;
    if options.mirroring == Mirroring::Vertical {
        flags6 |= 0x01;
    }
    out.push(flags6);
    out.push(0_u8);
    out.extend_from_slice(&[0_u8; 8]);
    out.extend_from_slice(&prg);

    if !options.chr_rom.is_empty() {
        out.extend_from_slice(&options.chr_rom);
    }

    Ok(out)
}

fn write_vector(
    prg: &mut [u8],
    prg_written: &mut [bool],
    prg_banks: usize,
    addr: u16,
    value: u16,
    name: &str,
) -> Result<(), DslError> {
    let [lo, hi] = value.to_le_bytes();
    insert_mapped_byte(prg, prg_written, prg_banks, addr, lo, name)?;
    insert_mapped_byte(prg, prg_written, prg_banks, addr + 1, hi, name)?;
    Ok(())
}

fn insert_mapped_byte(
    prg: &mut [u8],
    prg_written: &mut [bool],
    prg_banks: usize,
    addr: u16,
    byte: u8,
    name: &str,
) -> Result<(), DslError> {
    let Some(offset) = cpu_addr_to_prg_offset(prg_banks, addr) else {
        return Err(DslError::InvalidRomLayout(format!(
            "address ${addr:04X} from {name} does not map to PRG ROM"
        )));
    };
    if prg_written[offset] && prg[offset] != byte {
        return Err(DslError::InvalidRomLayout(format!(
            "address ${addr:04X} written multiple times with different values"
        )));
    }
    prg[offset] = byte;
    prg_written[offset] = true;
    Ok(())
}

fn cpu_addr_to_prg_offset(prg_banks: usize, addr: u16) -> Option<usize> {
    if prg_banks == 1 {
        if (0xC000..=0xFFFF).contains(&addr) {
            return Some((addr - 0xC000) as usize);
        }
    } else if prg_banks == 2 {
        if (0x8000..=0xFFFF).contains(&addr) {
            return Some((addr - 0x8000) as usize);
        }
    }
    None
}

//! Standalone macro runner binary.
//!
//! Provides a command-line interface to execute `.macro.txt` scripts directly
//! against a ROM using the `nes_mcp` macro engine. Useful for debugging
//! automated tool interactions outside of an active MCP session.

use std::env;
use std::fs;
use std::path::Path;

use comfy_table::{Cell, Color as TableColor, Table, presets::UTF8_FULL};
use crossterm::style::{Color, Stylize};
use nes_core::NesCore;
use nes_mcp::macro_engine::execute_macro_script;

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.iter().any(|arg| arg == "--help" || arg == "-h") {
        println!("Usage: nes-mcp-run-macro <rom_path> <script_path>");
        std::process::exit(0);
    }
    if args.len() != 3 {
        eprintln!("Usage: nes-mcp-run-macro <rom_path> <script_path>");
        std::process::exit(1);
    }

    let rom_path = &args[1];
    let script_path = &args[2];

    if let Err(err) = run(rom_path, script_path) {
        eprintln!("\n{err}");
        std::process::exit(1);
    }
}

fn format_rom_read_error(rom_path: &str, err: &std::io::Error) -> String {
    if err.kind() == std::io::ErrorKind::NotFound {
        format!(
            "{} Could not find the ROM file at '{}'.\n{} Check the path or try the bundled homebrew ROM: ./roms/homebrew/homebrew.nes or <path-to-your-rom>.nes",
            "Error:".with(Color::Red).bold(),
            rom_path.with(Color::Yellow),
            "Hint:".with(Color::Cyan).bold()
        )
    } else {
        format!(
            "{} Failed to read ROM at '{}': {}",
            "Error:".with(Color::Red).bold(),
            rom_path.with(Color::Yellow),
            err
        )
    }
}

fn format_script_read_error(script_path: &str, err: &std::io::Error) -> String {
    if err.kind() == std::io::ErrorKind::NotFound {
        format!(
            "{} Could not find the macro script at '{}'.\n{} Check the path or create a new .txt file.",
            "Error:".with(Color::Red).bold(),
            script_path.with(Color::Yellow),
            "Hint:".with(Color::Cyan).bold()
        )
    } else {
        format!(
            "{} Failed to read script at '{}': {}",
            "Error:".with(Color::Red).bold(),
            script_path,
            err
        )
    }
}

fn run(rom_path: &str, script_path: &str) -> Result<(), String> {
    let rom_bytes = fs::read(rom_path).map_err(|err| format_rom_read_error(rom_path, &err))?;
    let script_content = fs::read_to_string(script_path)
        .map_err(|err| format_script_read_error(script_path, &err))?;

    let mut core = NesCore::new();
    let rom_info = core
        .load_ines_rom(&rom_bytes)
        .map_err(|err| format!("Failed to load ROM: {}", err))?;

    println!("{}", "Executing Macro Script...".with(Color::Cyan).bold());

    let mut callback = |current_line: usize, total_lines: usize| {
        let pct = if total_lines > 0 {
            (current_line as f64 / total_lines as f64) * 100.0
        } else {
            0.0
        };
        print!(
            "\r\x1B[2K{}",
            format!(
                "Running line {} / {} ({:.1}%)",
                current_line, total_lines, pct
            )
            .with(Color::Yellow)
        );
        let _ = std::io::Write::flush(&mut std::io::stdout());
    };

    let frames_elapsed = execute_macro_script(&mut core, &script_content, Some(&mut callback))
        .map_err(|err| format!("Macro execution failed: {}", err))?;

    println!(
        "\r\x1B[2K{}",
        "Execution Complete".with(Color::Green).bold()
    );

    let rom_name = Path::new(rom_path)
        .file_name()
        .and_then(|n| n.to_str())
        .unwrap_or(rom_path);

    let mut table = Table::new();
    table.load_preset(UTF8_FULL);
    table.set_header(vec![
        Cell::new("Property").fg(TableColor::Cyan),
        Cell::new("Value").fg(TableColor::White),
    ]);

    table.add_row(vec![
        Cell::new("ROM"),
        Cell::new(rom_name).fg(TableColor::Green),
    ]);
    table.add_row(vec![
        Cell::new("Mapper ID"),
        Cell::new(rom_info.mapper_id.to_string()),
    ]);
    table.add_row(vec![
        Cell::new("Status"),
        Cell::new("Success").fg(TableColor::Green),
    ]);
    table.add_row(vec![
        Cell::new("Frames Elapsed"),
        Cell::new(frames_elapsed.to_string()).fg(TableColor::Yellow),
    ]);
    table.add_row(vec![
        Cell::new("Total CPU Cycles"),
        Cell::new(core.total_cycles().to_string()).fg(TableColor::Yellow),
    ]);
    table.add_row(vec![
        Cell::new("Final PC"),
        Cell::new(format!("${:04X}", core.cpu_pc())).fg(TableColor::Yellow),
    ]);
    table.add_row(vec![
        Cell::new("Final Controller State"),
        Cell::new(format!("{:08b}", core.controller_bits())).fg(TableColor::Yellow),
    ]);

    println!("\n{table}");

    Ok(())
}

