            "jsonrpc": "2.0",
            "id": id,
            "method": method,
            "params": params
        })
    }

    fn call(state: &mut ServerState, request: Value) -> Value {
        let payload = serde_json::to_vec(&request).expect("request serializes");
        handle_message(state, &payload).expect("request produces response")
    }

