        );
        assert_eq!(logging["result"], json!({}));
    }

    #[test]
    fn mcp_error_formatting_and_conversions() {
        let io_err = std::io::Error::new(std::io::ErrorKind::NotFound, "file missing");
        let mcp_io: McpError = io_err.into();
        assert_eq!(mcp_io.to_string(), "IO error: file missing");

        let mcp_proto: McpError = "bad format".into();
        assert_eq!(mcp_proto.to_string(), "Protocol error: bad format");

        let mcp_proto_string: McpError = "bad format".to_owned().into();
        assert_eq!(mcp_proto_string.to_string(), "Protocol error: bad format");
    }

    #[test]
    fn read_stdio_message_handles_errors() {
        let mut reader = b"Content-Length: abc\r\n\r\n".as_slice();
        let err = read_stdio_message(&mut reader).unwrap_err();
        assert!(
            err.to_string()
                .contains("invalid Content-Length value 'abc'")
        );

        let mut reader = b"Something else\r\n\r\n".as_slice();
        let err = read_stdio_message(&mut reader).unwrap_err();
        assert!(err.to_string().contains("missing Content-Length header"));

        let mut reader = b"Content-Length: 100\r\nEOF".as_slice();
        let err = read_stdio_message(&mut reader).unwrap_err();
        assert!(
            err.to_string()
                .contains("unexpected EOF while reading MCP headers")
        );

        let mut reader = b"Content-Length: 100\r\n\r\nshort".as_slice();
        let err = read_stdio_message(&mut reader).unwrap_err();
        assert!(err.to_string().contains("failed reading payload body"));
    }
}

//! Manages shared audio and video output state for the MCP server.
//!
//! Because the emulator generates full 256x240 RGBA frames (~245KB each) and
//! audio samples 60 times a second, copying these buffers for every single JSON
//! RPC query would cause severe memory pressure. This module uses `Arc` wrapped
//! data structures to allow multiple readers to hold references to the latest
//! output chunk without needing to deep-copy the underlying arrays.

use std::cmp;
use std::sync::{Arc, Mutex, OnceLock};

use nes_core::{AUDIO_CHUNK_SAMPLES, FRAME_HEIGHT, FRAME_RGBA_BYTES, FRAME_WIDTH};

const DEFAULT_WIDTH: u32 = FRAME_WIDTH as u32;
const DEFAULT_HEIGHT: u32 = FRAME_HEIGHT as u32;
const DEFAULT_AUDIO_SAMPLE_COUNT: usize = AUDIO_CHUNK_SAMPLES;

/// Current metadata snapshot of the publisher's output state.
///
/// This metadata allows consumers to quickly check if new frames or audio
/// samples have been published by the emulator without needing to acquire locks
/// or perform deep copies of the underlying media buffers.
///
/// ## Examples
///
/// ```
/// use nes_mcp::OutputMetadata;
///
/// // Metadata is typically retrieved via `latest_output_metadata()`
/// let metadata = OutputMetadata {
///     frame_seq: 42,
///     audio_seq: 15,
///     width: 256,
///     height: 240,
/// };
///
/// if metadata.frame_seq > 0 {
///     println!("The emulator has rendered {} frames!", metadata.frame_seq);
/// }
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct OutputMetadata {
    /// Incremented each time a new frame is published.
    pub frame_seq: u64,
    /// Incremented each time a new audio chunk is published.
    pub audio_seq: u64,
    /// The width of the current published frame.
    pub width: u32,
    /// The height of the current published frame.
    pub height: u32,
}

/// A reference-counted video frame snapshot.
///
/// By utilizing `Arc<Vec<u8>>`, the MCP server can broadcast a single rendered
/// frame to multiple connected clients (or tool invocations) simultaneously.
/// This zero-copy approach prevents severe memory pressure when dealing with
/// the ~245KB RGBA payload of a standard NES frame.
///
/// ## Examples
///
/// ```
/// use std::sync::Arc;
/// use nes_mcp::FrameChunk;
///
/// // A blank, black frame ready to be shipped over JSON-RPC.
/// let chunk = FrameChunk {
///     seq: 1,
///     rgba: Arc::new(vec![0; 256 * 240 * 4]),
/// };
///
/// assert_eq!(chunk.rgba.len(), 245760);
/// ```
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FrameChunk {
    /// The sequence number of this frame.
    pub seq: u64,
    /// We use `Arc<Vec<u8>>` instead of `Vec<u8>` here to allow the MCP engine to
    /// share a single read-only view of the framebuffer across threads without
    /// performing a deep copy (approx ~245KB allocation) every time it's queried.
    pub rgba: Arc<Vec<u8>>,
}

/// A reference-counted block of audio samples.
///
/// Similar to `FrameChunk`, this structure wraps raw `i16` audio samples in
/// an `Arc`. This ensures that high-frequency audio polling from external
/// tools does not trigger expensive memory allocations on the hot path.
///
/// ## Examples
///
/// ```
/// use std::sync::Arc;
/// use nes_mcp::AudioChunk;
///
/// // A block of pure silence, perhaps from a paused emulator.
/// let chunk = AudioChunk {
///     seq: 1,
///     samples: Arc::new(vec![0; 735]),
/// };
///
/// assert_eq!(chunk.samples.len(), 735);
/// ```
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AudioChunk {
    /// The sequence number of this audio chunk.
    pub seq: u64,
    /// We use `Arc<Vec<i16>>` to share audio samples safely without incurring
    /// per-query memory allocations or deep `.clone()` operations on the hot path.
    pub samples: Arc<Vec<i16>>,
}

#[derive(Debug)]
struct OutputState {
    frame_seq: u64,
    audio_seq: u64,
    width: u32,
    height: u32,
    frame_rgba: Arc<Vec<u8>>,
    audio_samples: Arc<Vec<i16>>,
}

impl OutputState {
    fn metadata(&self) -> OutputMetadata {
        OutputMetadata {
            frame_seq: self.frame_seq,
            audio_seq: self.audio_seq,
            width: self.width,
            height: self.height,
        }
    }
}

fn output_state() -> &'static Mutex<OutputState> {
    static STATE: OnceLock<Mutex<OutputState>> = OnceLock::new();
    STATE.get_or_init(|| {
        Mutex::new(OutputState {
            frame_seq: 0,
            audio_seq: 0,
            width: DEFAULT_WIDTH,
            height: DEFAULT_HEIGHT,
            frame_rgba: Arc::new(vec![0; FRAME_RGBA_BYTES]),
            audio_samples: Arc::new(vec![0; DEFAULT_AUDIO_SAMPLE_COUNT]),
        })
    })
}

/// Returns the current metadata for available frame and audio chunks.
///
/// ## Examples
///
/// ```
/// use nes_mcp::latest_output_metadata;
///
/// let meta = latest_output_metadata();
/// assert_eq!(meta.width, 256);
/// assert_eq!(meta.height, 240);
/// ```
#[must_use]
pub fn latest_output_metadata() -> OutputMetadata {
    output_state().lock().expect("output state lock").metadata()
}

/// Updates the globally shared output state with a new video frame.
///
/// This increments the internal `frame_seq` counter and wraps the payload
/// in an `Arc` for lock-free reader access.
///
/// ## Examples
///
/// ```
/// use nes_mcp::{publish_frame, latest_output_metadata};
///
/// let empty_frame = vec![0; 256 * 240 * 4];
/// publish_frame(256, 240, empty_frame);
///
/// let meta = latest_output_metadata();
/// assert!(meta.frame_seq > 0);
/// ```
pub fn publish_frame(width: u32, height: u32, rgba: Vec<u8>) {
    let Some(expected_len) = expected_frame_len(width, height) else {
        return;
    };
    if rgba.len() != expected_len {
        return;
    }

    let mut state = output_state().lock().expect("output state lock");
    state.frame_seq = state.frame_seq.saturating_add(1);
    state.width = width;
    state.height = height;
    state.frame_rgba = Arc::new(rgba);
}

/// Updates the globally shared output state with a new video frame by modifying the existing allocation.
pub fn publish_frame_with<F>(width: u32, height: u32, f: F)
where
    F: FnOnce(&mut [u8]),
{
    let Some(expected_len) = expected_frame_len(width, height) else {
        return;
    };

    let mut state = output_state().lock().expect("output state lock");
    let buffer = Arc::make_mut(&mut state.frame_rgba);

    if buffer.len() != expected_len {
        buffer.resize(expected_len, 0);
    }

    f(buffer);

    state.frame_seq = state.frame_seq.saturating_add(1);
    state.width = width;
    state.height = height;
}

/// Updates the globally shared output state with a new audio chunk.
///
/// This increments the internal `audio_seq` counter and wraps the samples
/// in an `Arc` for lock-free reader access.
///
/// ## Examples
///
/// ```
/// use nes_mcp::{publish_audio, latest_output_metadata};
///
/// publish_audio(vec![0; 735]);
///
/// let meta = latest_output_metadata();
/// assert!(meta.audio_seq > 0);
/// ```
pub fn publish_audio(samples: Vec<i16>) {
    let mut state = output_state().lock().expect("output state lock");
    state.audio_seq = state.audio_seq.saturating_add(1);
    state.audio_samples = Arc::new(samples);
}

/// Updates the globally shared output state with a new audio chunk by modifying the existing allocation.
pub fn publish_audio_with<F>(len: usize, f: F)
where
    F: FnOnce(&mut [i16]),
{
    let mut state = output_state().lock().expect("output state lock");
    let buffer = Arc::make_mut(&mut state.audio_samples);

    if buffer.len() != len {
        buffer.resize(len, 0);
    }

    f(buffer);

    state.audio_seq = state.audio_seq.saturating_add(1);
}

/// Retrieves a reference-counted view of the requested frame sequence.
///
/// If the requested sequence is newer than the current sequence, the state
/// acts as a fast-forward and clamps to the requested sequence to prevent
/// future drift on the client side.
///
/// ## Examples
///
/// ```
/// use nes_mcp::{frame_chunk, publish_frame};
///
/// publish_frame(256, 240, vec![0; 256 * 240 * 4]);
/// let chunk = frame_chunk(1).unwrap();
/// assert_eq!(chunk.rgba.len(), 256 * 240 * 4);
/// ```
#[must_use]
pub fn frame_chunk(requested_seq: u64) -> Option<FrameChunk> {
    let mut state = output_state().lock().expect("output state lock");
    state.frame_seq = cmp::max(state.frame_seq, requested_seq);

    Some(FrameChunk {
        seq: state.frame_seq,
        rgba: state.frame_rgba.clone(),
    })
}

/// Retrieves a reference-counted view of the requested audio sequence.
///
/// If the requested sequence is newer than the current sequence, the state
/// acts as a fast-forward and clamps to the requested sequence to prevent
/// future drift on the client side.
///
/// ## Examples
///
/// ```
/// use nes_mcp::{audio_chunk, publish_audio};
///
/// publish_audio(vec![0; 735]);
/// let chunk = audio_chunk(1).unwrap();
/// assert_eq!(chunk.samples.len(), 735);
/// ```
#[must_use]
pub fn audio_chunk(requested_seq: u64) -> Option<AudioChunk> {
    let mut state = output_state().lock().expect("output state lock");
    state.audio_seq = cmp::max(state.audio_seq, requested_seq);

    Some(AudioChunk {
        seq: state.audio_seq,
        samples: state.audio_samples.clone(),
    })
}

fn expected_frame_len(width: u32, height: u32) -> Option<usize> {
    let width = usize::try_from(width).ok()?;
    let height = usize::try_from(height).ok()?;
    width.checked_mul(height)?.checked_mul(4)
}

#[cfg(test)]
pub(crate) fn reset_output_state_for_test() -> std::sync::MutexGuard<'static, ()> {
    static TEST_LOCK: OnceLock<Mutex<()>> = OnceLock::new();
    let guard = TEST_LOCK
        .get_or_init(|| Mutex::new(()))
        .lock()
        .expect("output test lock");

    let mut state = output_state().lock().expect("output state lock");
    *state = OutputState {
        frame_seq: 0,
        audio_seq: 0,
        width: DEFAULT_WIDTH,
        height: DEFAULT_HEIGHT,
        frame_rgba: Arc::new(vec![0; FRAME_RGBA_BYTES]),
        audio_samples: Arc::new(vec![0; DEFAULT_AUDIO_SAMPLE_COUNT]),
    };
    drop(state);

    guard
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn should_return_none_when_expected_frame_len_overflows() {
        let _guard = reset_output_state_for_test();
        assert_eq!(
            expected_frame_len(u32::MAX, u32::MAX),
            None,
            "Expected None due to width * height overflow"
        );
        // On 32-bit platforms, an overflow happens earlier (width * height),
        // whereas on 64-bit platforms it happens later (during * 4).
    }

    #[test]
    fn should_calculate_correct_frame_length_for_valid_dimensions() {
        let _guard = reset_output_state_for_test();
        assert_eq!(
            expected_frame_len(256, 240),
            Some(245_760),
            "Expected 256 * 240 * 4 = 245760"
        );
    }

    #[test]
    fn should_ignore_publish_frame_if_rgba_length_is_invalid() {
        let _guard = reset_output_state_for_test();
        let initial_meta = latest_output_metadata();

        // Pass an array that is definitely wrong sized (1 byte)
        publish_frame(256, 240, vec![0]);

        let final_meta = latest_output_metadata();
        assert_eq!(
            initial_meta.frame_seq, final_meta.frame_seq,
            "Frame sequence should not increment for invalid frame lengths"
        );
    }

    #[test]
    fn should_fast_forward_frame_chunk_sequence_when_requested_seq_is_newer() {
        let _guard = reset_output_state_for_test();
        let initial_meta = latest_output_metadata();
        let future_seq = initial_meta.frame_seq + 10;

        let chunk = frame_chunk(future_seq).expect("Frame chunk must exist");
        assert_eq!(
            chunk.seq, future_seq,
            "Frame chunk sequence should fast-forward to the requested future sequence"
        );

        let final_meta = latest_output_metadata();
        assert_eq!(
            final_meta.frame_seq, future_seq,
            "Global metadata frame sequence should be fast-forwarded"
        );
    }

    #[test]
    fn should_fast_forward_audio_chunk_sequence_when_requested_seq_is_newer() {
        let _guard = reset_output_state_for_test();
        let initial_meta = latest_output_metadata();
        let future_seq = initial_meta.audio_seq + 5;

        let chunk = audio_chunk(future_seq).expect("Audio chunk must exist");
        assert_eq!(
            chunk.seq, future_seq,
            "Audio chunk sequence should fast-forward to the requested future sequence"
        );

        let final_meta = latest_output_metadata();
        assert_eq!(
            final_meta.audio_seq, future_seq,
            "Global metadata audio sequence should be fast-forwarded"
        );
    }

    #[test]
    fn should_reuse_memory_when_publishing_frame_with_closure() {
        let _guard = reset_output_state_for_test();
        let initial_meta = latest_output_metadata();
        publish_frame_with(256, 240, |buf| {
            assert_eq!(buf.len(), 245_760);
            buf[0] = 99;
        });
        let meta = latest_output_metadata();
        assert_eq!(meta.frame_seq, initial_meta.frame_seq + 1);
        let chunk = frame_chunk(meta.frame_seq).unwrap();
        assert_eq!(chunk.rgba[0], 99);
    }

    #[test]
    fn should_reuse_memory_when_publishing_audio_with_closure() {
        let _guard = reset_output_state_for_test();
        let initial_meta = latest_output_metadata();
        publish_audio_with(735, |buf| {
            assert_eq!(buf.len(), 735);
            buf[0] = 42;
        });
        let meta = latest_output_metadata();
        assert_eq!(meta.audio_seq, initial_meta.audio_seq + 1);
        let chunk = audio_chunk(meta.audio_seq).unwrap();
        assert_eq!(chunk.samples[0], 42);
    }

    #[test]
    fn should_resize_memory_when_publishing_audio_with_closure_if_length_differs() {
        let _guard = reset_output_state_for_test();
        publish_audio(vec![0; 100]);
        publish_audio_with(200, |samples| {
            assert_eq!(samples.len(), 200);
        });
    }

    #[test]
    fn should_resize_memory_when_publishing_frame_with_closure_if_length_differs() {
        let _guard = reset_output_state_for_test();
        publish_frame(256, 240, vec![0; 256 * 240 * 4]);
        publish_frame_with(128, 120, |rgba| {
            assert_eq!(rgba.len(), 128 * 120 * 4);
        });
    }

    #[test]
    fn should_increment_audio_seq_and_update_samples_on_publish_audio() {
        let _guard = reset_output_state_for_test();
        let initial_meta = latest_output_metadata();

        publish_audio(vec![42; 735]);

        let final_meta = latest_output_metadata();
        assert_eq!(
            final_meta.audio_seq,
            initial_meta.audio_seq + 1,
            "Audio sequence should increment by 1"
        );

        let chunk = audio_chunk(final_meta.audio_seq).expect("Audio chunk must exist");
        assert_eq!(
            chunk.samples.len(),
            735,
            "Audio chunk should contain the newly published samples"
        );
        assert_eq!(
            chunk.samples[0], 42,
            "Sample content should match what was published"
        );
    }
}

//! JSON-RPC 2.0 protocol types for the Model Context Protocol (MCP) server.
//!
//! This module defines the core request and error structures used to communicate
//! between the MCP client (like an LLM) and the NES emulator host. The MCP
//! server expects incoming requests to conform to `RpcRequest` and formats
//! responses or failures as `RpcError`.
//!
//! Because the payload data can vary dynamically depending on the tool
//! invoked, the structures rely on `serde_json::Value` for parameter and
//! data fields.

use serde::Deserialize;
use serde_json::{Map, Value, json};

use crate::{DispatchOutput, ToolParams};

/// The fixed JSON-RPC version string required by the protocol.
pub const JSONRPC_VERSION: &str = "2.0";
/// The default MCP protocol version.
pub const DEFAULT_PROTOCOL_VERSION: &str = "2025-06-18";

/// A JSON-RPC 2.0 request sent from the MCP client.
///
/// This structure represents a single tool invocation or command. The MCP
/// server deserializes incoming JSON payloads into this type before dispatching
/// the command to the appropriate emulator core function.
///
/// ## Examples
///
/// ```
/// use nes_mcp::protocol::RpcRequest;
/// use serde_json::json;
///
/// let json_payload = r#"{
///     "jsonrpc": "2.0",
///     "id": 1,
///     "method": "tools/call",
///     "params": {
///         "name": "pause"
///     }
/// }"#;
///
/// let request: RpcRequest = serde_json::from_str(json_payload).unwrap();
/// assert_eq!(request.method, "tools/call");
/// assert_eq!(request.id, Some(json!(1)));
/// ```
#[derive(Debug, Deserialize)]
pub struct RpcRequest {
    /// The protocol version, typically exactly `"2.0"`.
    pub jsonrpc: String,
    /// The unique request identifier.
    ///
    /// This is optional in JSON-RPC (where lack of an ID implies a notification),
    /// but standard MCP tool calls will always provide one.
    #[serde(default)]
    pub id: Option<Value>,
    /// The name of the method to be invoked (e.g., `"tools/call"` or `"tools/list"`).
    pub method: String,
    /// The parameters to be passed to the method.
    ///
    /// The structure of these parameters depends entirely on the `method` being called.
    #[serde(default)]
    pub params: Option<Value>,
}

/// A JSON-RPC 2.0 error response.
///
/// This structure is used to communicate failures back to the MCP client.
/// It encapsulates the standard JSON-RPC error codes along with a human-readable
/// message and an optional data payload for extended diagnostic context.
///
/// When converting this error into a JSON value for transmission, you must use
/// the [`RpcError::into_json`] method to avoid non-exhaustive pattern compilation errors
/// that can arise from custom serialization strategies.
#[derive(Debug, Clone)]
pub struct RpcError {
    /// A Number that indicates the error type that occurred.
    ///
    /// Common codes are -32700 (Parse error) or -32600 (Invalid Request).
    pub code: i64,
    /// A String providing a short description of the error.
    pub message: String,
    /// A Primitive or Structured value that contains additional information
    /// about the error.
    pub data: Option<Value>,
}

impl RpcError {
    /// Creates a new "Parse error" (-32700) response.
    ///
    /// Use this when the incoming payload cannot be parsed as valid JSON.
    pub fn parse_error(message: impl Into<String>) -> Self {
        Self {
            code: -32700,
            message: message.into(),
            data: None,
        }
    }

    /// Creates a new "Invalid Request" (-32600) response.
    ///
    /// Use this when the JSON payload is valid, but the structure does not
    /// conform to the JSON-RPC 2.0 specification.
    pub fn invalid_request(message: impl Into<String>) -> Self {
        Self {
            code: -32600,
            message: message.into(),
            data: None,
        }
    }

    /// Creates a new "Method not found" (-32601) response.
    ///
    /// Use this when the client attempts to invoke a tool or method that
    /// the server does not expose in its catalog.
    pub fn method_not_found(message: impl Into<String>) -> Self {
        Self {
            code: -32601,
            message: message.into(),
            data: None,
        }
    }

    /// Creates a new "Invalid params" (-32602) response.
    ///
    /// Use this when the tool exists, but the provided arguments fail validation
    /// against the tool's expected schema.
    pub fn invalid_params(message: impl Into<String>) -> Self {
        Self {
            code: -32602,
            message: message.into(),
            data: None,
        }
    }

    /// Serializes the error into a valid JSON-RPC 2.0 error object.
    ///
    /// **Important:** You must use this custom `into_json()` method instead of `as_json()`
    /// when constructing the response payload. It gracefully handles the optional `data`
    /// field without generating compilation errors associated with non-exhaustive patterns.
    ///
    /// ## Examples
    ///
    /// ```
    /// use nes_mcp::protocol::RpcError;
    ///
    /// let err = RpcError::invalid_params("missing required field 'rom_path'");
    /// let json_val = err.into_json();
    ///
    /// assert_eq!(json_val["code"], -32602);
    /// assert_eq!(json_val["message"], "missing required field 'rom_path'");
    /// assert!(json_val.get("data").is_none());
    /// ```
    #[must_use]
    pub fn into_json(self) -> Value {
        let mut value = json!({
            "code": self.code,
            "message": self.message,
        });
        if let Some(data) = self.data
            && let Some(obj) = value.as_object_mut()
        {
            obj.insert("data".to_owned(), data);
        }
        value
    }

    /// Creates a new "Internal error" (-32603) response.
    ///
    /// Use this when the emulator core encounters an unexpected panic or
    /// fatal state during the execution of a valid tool command.
    pub fn internal_error(message: impl Into<String>) -> Self {
        Self {
            code: -32603,
            message: message.into(),
            data: None,
        }
    }
}

/// Maps raw JSON RPC arguments into a strongly typed `ToolParams` map.
///
/// **Performance optimization:** This function consumes an owned `Map<String, Value>`
/// rather than taking a borrowed reference `&Map`. Because the MCP dispatch
/// layer typically already has an owned arguments object, taking ownership here
/// entirely eliminates the need to allocate and `.clone()` every string key
/// and value when inserting them into the returned `ToolParams`.
#[must_use]
pub fn map_tool_arguments(arguments: Map<String, Value>) -> ToolParams {
    let mut params = ToolParams::new();
    for (key, value) in arguments {
        params.insert(key, json_arg_to_string(value));
    }
    params
}

/// Converts a JSON `Value` into a `String` without extra allocations if possible.
///
/// **Performance optimization:** Taking an owned `Value` allows us to extract
/// and return the inner `String` directly via pattern matching, avoiding
/// a heap allocation compared to calling `.to_string()` or `.clone()` on a reference.
#[must_use]
pub fn json_arg_to_string(value: Value) -> String {
    match value {
        Value::String(v) => v,
        _ => value.to_string(),
    }
}

/// Serializes the result of a tool execution into a [`serde_json::Value`].
///
/// This output value is intended to be included in the `result` field of a
/// JSON-RPC response message sent back to the MCP client.
///
/// ## Examples
///
/// ```
/// use nes_mcp::protocol::dispatch_output_value;
/// use nes_mcp::DispatchOutput;
/// use serde_json::json;
///
/// let val = dispatch_output_value(DispatchOutput::Ack);
/// assert_eq!(val, json!({ "kind": "ack" }));
/// ```
#[must_use]
pub fn dispatch_output_value(output: DispatchOutput) -> Value {
    match output {
        DispatchOutput::Ack => json!({ "kind": "ack" }),
        DispatchOutput::CpuStep { trace, cpu_cycles } => {
            json!({ "kind": "cpu_step", "trace": trace, "cpu_cycles": cpu_cycles })
        }
        DispatchOutput::CycleCount { cpu_cycles } => {
            json!({ "kind": "cycle_count", "cpu_cycles": cpu_cycles })
        }
        DispatchOutput::ControllerState { controller_bits } => {
            json!({ "kind": "controller_state", "controller_bits": controller_bits })
        }
        DispatchOutput::EmulatorState {
            paused,
            speed_permille,
            controller_bits,
        } => {
            json!({
                "kind": "emulator_state",
                "paused": paused,
                "speed_permille": speed_permille,
                "controller_bits": controller_bits
            })
        }
        DispatchOutput::Registers {
            pc,
            a,
            x,
            y,
            sp,
            status,
        } => {
            json!({
                "kind": "registers",
                "pc": pc,
                "a": a,
                "x": x,
                "y": y,
                "sp": sp,
                "status": status
            })
        }
        DispatchOutput::Memory { address, value } => {
            json!({ "kind": "memory", "address": address, "value": value })
        }
        DispatchOutput::Fps { fps_milli } => json!({ "kind": "fps", "fps_milli": fps_milli }),
        DispatchOutput::PpuFrameCounter { frame_counter } => {
            json!({ "kind": "ppu_frame_counter", "frame_counter": frame_counter })
        }
        DispatchOutput::Frame { seq, bytes } => {
            json!({ "kind": "frame", "seq": seq, "bytes": bytes })
        }
        DispatchOutput::FrameCaptured { path, bytes } => {
            json!({ "kind": "frame_captured", "path": path, "bytes": bytes })
        }
        DispatchOutput::Audio { seq, samples } => {
            json!({ "kind": "audio", "seq": seq, "samples": samples })
        }
        DispatchOutput::StateSlot { slot } => {
            json!({ "kind": "state_slot", "slot": slot })
        }
        DispatchOutput::RomLoaded {
            mapper_id,
            prg_rom_bytes,
            reset_pc,
        } => {
            json!({
                "kind": "rom_loaded",
                "mapper_id": mapper_id,
                "prg_rom_bytes": prg_rom_bytes,
                "reset_pc": reset_pc
            })
        }
        DispatchOutput::MacroExecuted {
            frames_elapsed,
            final_controller_bits,
        } => {
            json!({
                "kind": "macro_executed",
                "frames_elapsed": frames_elapsed,
                "final_controller_bits": final_controller_bits,
            })
        }
        DispatchOutput::PpuOam { oam_bytes } => {
            json!({
                "kind": "ppu_oam",
                "oam_bytes": oam_bytes,
            })
        }
        DispatchOutput::DslAssembled {
            bytes_written,
            label_count,
            nmi_vector,
            reset_vector,
            irq_vector,
        } => {
            json!({
                "kind": "dsl_assembled",
                "bytes_written": bytes_written,
                "label_count": label_count,
                "nmi_vector": nmi_vector,
                "reset_vector": reset_vector,
                "irq_vector": irq_vector,
            })
        }
        DispatchOutput::DslRomLoaded {
            mapper_id,
            prg_rom_bytes,
            reset_pc,
            rom_bytes,
        } => {
            json!({
                "kind": "dsl_rom_loaded",
                "mapper_id": mapper_id,
                "prg_rom_bytes": prg_rom_bytes,
                "reset_pc": reset_pc,
                "rom_bytes": rom_bytes,
            })
        }
        DispatchOutput::DslRomExported {
            path,
            bytes,
            mapper_id,
            prg_rom_bytes,
        } => {
            json!({
                "kind": "dsl_rom_exported",
                "path": path,
                "bytes": bytes,
                "mapper_id": mapper_id,
                "prg_rom_bytes": prg_rom_bytes,
            })
        }
        DispatchOutput::DslRomExportedBase64 {
            rom_base64,
            bytes,
            mapper_id,
            prg_rom_bytes,
        } => {
            json!({
                "kind": "dsl_rom_exported_base64",
                "rom_base64": rom_base64,
                "bytes": bytes,
                "mapper_id": mapper_id,
                "prg_rom_bytes": prg_rom_bytes,
            })
        }
    }
}

/// Returns the JSON Schema defining expected arguments for a given tool.
///
/// This schema dictates exactly what arguments an LLM must supply when invoking
/// the specified tool over the MCP protocol.
///
/// ## Examples
///
/// ```
/// use nes_mcp::protocol::tool_input_schema;
///
/// let schema = tool_input_schema("set_controller_state");
/// assert!(schema.get("properties").unwrap().get("bits").is_some());
/// ```
#[must_use]
pub fn tool_input_schema(tool_name: &str) -> Value {
    match tool_name {
        "set_controller_state" => json!({
            "type": "object",
            "properties": {
                "bits": { "type": "integer", "minimum": 0, "maximum": 255 },
                "player": { "type": "integer", "enum": [1, 2] }
            },
            "required": ["bits"],
            "additionalProperties": false
        }),
        "press_button" | "release_button" => json!({
            "type": "object",
            "properties": {
                "button": {
                    "type": "string",
                    "enum": ["A", "B", "Select", "Start", "Up", "Down", "Left", "Right"]
                },
                "player": { "type": "integer", "enum": [1, 2] }
            },
            "required": ["button"],
            "additionalProperties": false
        }),
        "set_speed" => json!({
            "type": "object",
            "properties": {
                "multiplier": { "type": "number", "exclusiveMinimum": 0.0 }
            },
            "required": ["multiplier"],
            "additionalProperties": false
        }),
        "read_memory" | "set_breakpoint" | "clear_breakpoint" | "disassemble_at" => json!({
            "type": "object",
            "properties": {
                "address": { "type": "integer", "minimum": 0, "maximum": 65535 }
            },
            "required": ["address"],
            "additionalProperties": false
        }),
        "get_frame" | "get_audio_chunk" => json!({
            "type": "object",
            "properties": {
                "seq": { "type": "integer", "minimum": 0 }
            },
            "additionalProperties": false
        }),
        "capture_frame" => json!({
            "type": "object",
            "properties": {
                "path": { "type": "string", "minLength": 1 }
            },
            "required": ["path"],
            "additionalProperties": false
        }),
        "save_state" | "load_state" => json!({
            "type": "object",
            "properties": {
                "slot": { "type": "string", "minLength": 1 }
            },
            "additionalProperties": false
        }),
        "load_rom" => json!({
            "type": "object",
            "properties": {
                "rom_path": { "type": "string", "minLength": 1 },
                "rom_hex": { "type": "string", "minLength": 2 }
            },
            "oneOf": [
                { "required": ["rom_path"] },
                { "required": ["rom_hex"] }
            ],
            "additionalProperties": false
        }),
        "assemble_6502_dsl" => json!({
            "type": "object",
            "properties": {
                "source": { "type": "string", "minLength": 1 }
            },
            "required": ["source"],
            "additionalProperties": false
        }),
        "load_6502_dsl" => json!({
            "type": "object",
            "properties": {
                "source": { "type": "string", "minLength": 1 },
                "mirroring": { "type": "string", "enum": ["horizontal", "vertical"] },
                "chr_hex": { "type": "string", "minLength": 2 }
            },
            "required": ["source"],
            "additionalProperties": false
        }),
        "export_6502_dsl_rom" => json!({
            "type": "object",
            "properties": {
                "source": { "type": "string", "minLength": 1 },
                "output_path": { "type": "string", "minLength": 1 },
                "mirroring": { "type": "string", "enum": ["horizontal", "vertical"] },
                "chr_hex": { "type": "string", "minLength": 2 }
            },
            "required": ["source", "output_path"],
            "additionalProperties": false
        }),
        "export_6502_dsl_rom_base64" => json!({
            "type": "object",
            "properties": {
                "source": { "type": "string", "minLength": 1 },
                "mirroring": { "type": "string", "enum": ["horizontal", "vertical"] },
                "chr_hex": { "type": "string", "minLength": 2 }
            },
            "required": ["source"],
            "additionalProperties": false
        }),
        _ => json!({
            "type": "object",
            "properties": {},
            "additionalProperties": false
        }),
    }
}

/// Constructs a successful JSON-RPC 2.0 response object.
///
/// Combines the original request `id` and the successful `result` into a payload
/// suitable for transmitting back to the client.
///
/// ## Examples
///
/// ```
/// use nes_mcp::protocol::jsonrpc_result;
/// use serde_json::json;
///
/// let response = jsonrpc_result(json!(42), json!({"kind": "ack"}));
/// assert_eq!(response["id"], json!(42));
/// assert_eq!(response["result"]["kind"], "ack");
/// ```
#[must_use]
pub fn jsonrpc_result(id: Value, result: Value) -> Value {
    json!({
        "jsonrpc": JSONRPC_VERSION,
        "id": id,
        "result": result
    })
}

/// Constructs an error JSON-RPC 2.0 response object.
///
/// Combines the original request `id` and the structured [`RpcError`] into a payload
/// to notify the client of a failure.
///
/// ## Examples
///
/// ```
/// use nes_mcp::protocol::{jsonrpc_error, RpcError};
/// use serde_json::json;
///
/// let err = RpcError::invalid_params("missing button");
/// let response = jsonrpc_error(json!(42), err);
/// assert_eq!(response["id"], json!(42));
/// assert!(response.get("error").is_some());
/// ```
#[must_use]
pub fn jsonrpc_error(id: Value, err: RpcError) -> Value {
    json!({
        "jsonrpc": JSONRPC_VERSION,
        "id": id,
        "error": err.into_json()
    })
}

#[cfg(test)]
mod tests {
