    fn make_snapshot() -> CoreSnapshot {
        let core = NesCore::new();
        core.save_state()
    }

    fn sample_ines(mapper_id: u8, prg_banks: u8) -> Vec<u8> {
        let mut rom = vec![0_u8; 16 + prg_banks as usize * 16 * 1024];
        rom[0] = 0x4E;
        rom[1] = 0x45;
        rom[2] = 0x53;
        rom[3] = 0x1A;
        rom[4] = prg_banks;
        rom[5] = 0;
        rom[6] = (mapper_id & 0x0F) << 4;
        rom[7] = mapper_id & 0xF0;
        rom
    }

    fn make_mmc3_snapshot() -> CoreSnapshot {
        let rom = sample_ines(4, 4);
        let mut core = NesCore::new();
        core.load_ines_rom(&rom).unwrap();
        core.save_state()
    }

    fn make_cnrom_chr_ram_snapshot() -> CoreSnapshot {
        let rom = sample_ines(3, 1);
        let mut core = NesCore::new();
        core.load_ines_rom(&rom).unwrap();
        core.save_state()
    }

    fn write_ppu_data(core: &mut NesCore, addr: u16, data: &[u8]) {
        core.write_cpu_bus(0x2006, (addr >> 8) as u8);
        core.write_cpu_bus(0x2006, addr as u8);
        for &byte in data {
            core.write_cpu_bus(0x2007, byte);
        }
    }

    #[test]
    fn identical_snapshots_all_none() {
        let snap = make_snapshot();
        let fd = FieldDelta::compute(&snap, &snap);
        assert!(fd.cpu_regs.is_none());
        assert!(fd.ppu_ctrl.is_none());
        assert!(fd.ppu_timing.is_none());
        assert!(fd.ppu_scroll.is_none());
        assert!(fd.mapper.is_none());
    }

    #[test]
    fn mapper_irq_state_roundtrip_requires_mapper_delta() {
        let before = make_mmc3_snapshot();

        let mut core = NesCore::new();
        core.load_state(&before);
        core.write_cpu_bus(0xC000, 0x03);
        core.write_cpu_bus(0xC001, 0x00);
        core.write_cpu_bus(0xE001, 0x00);
        let after = core.save_state();

        let fd = FrameDelta::compute(&before, &after);
        let mut target = before.clone();
        fd.apply(&mut target);

        assert_eq!(target, after);
    }

    #[test]
    fn chr_ram_writes_preserve_mapper_backing_without_register_change() {
        let before = make_cnrom_chr_ram_snapshot();

        let mut core = NesCore::new();
        core.load_state(&before);
        write_ppu_data(&mut core, 0x0000, &[0x5A]);
        let after = core.save_state();

        let fd = FrameDelta::compute(&before, &after);
        assert!(fd.fields.mapper.is_some());

        let mut target = before.clone();
        fd.apply(&mut target);

        let mut restored = NesCore::new();
        restored.load_state(&target);
        assert_eq!(restored.save_state().ppu.chr[0], 0x5A);
    }

    #[test]
    fn ppu_scroll_change_detected() {
        let before = make_snapshot();
        let mut after = before.clone();
        after.ppu.vram_addr = 0x1234;
        after.ppu.fine_x = 5;
        after.ppu.scroll_x = 80;

        let fd = FieldDelta::compute(&before, &after);
        assert!(fd.ppu_scroll.is_some());
        let scroll = fd.ppu_scroll.unwrap();
        assert_eq!(scroll.vram_addr, 0x1234);
        assert_eq!(scroll.fine_x, 5);
        assert_eq!(scroll.scroll_x, 80);
    }

    #[test]
    fn ppu_scroll_delta_apply_restores_scroll() {
        let before = make_snapshot();
        let mut after = before.clone();
        after.ppu.vram_addr = 0x2000;
        after.ppu.temp_addr = 0x3FFF;
        after.ppu.fine_x = 7;
        after.ppu.write_toggle = true;
        after.ppu.scroll_x = 120;
        after.ppu.scroll_y = 30;
        after.ppu.read_buffer = 0xAB;

        let fd = FieldDelta::compute(&before, &after);
        let mut target = before.clone();
        fd.apply(&mut target);

        assert_eq!(target.ppu.vram_addr, 0x2000);
        assert_eq!(target.ppu.temp_addr, 0x3FFF);
        assert_eq!(target.ppu.fine_x, 7);
        assert!(target.ppu.write_toggle);
        assert_eq!(target.ppu.scroll_x, 120);
        assert_eq!(target.ppu.scroll_y, 30);
        assert_eq!(target.ppu.read_buffer, 0xAB);
    }

    #[test]
    fn cpu_register_change_detected() {
        let before = make_snapshot();
        let mut after = before.clone();
        after.cpu.a = 0x42;
        after.cpu.pc = 0xBEEF;

        let fd = FieldDelta::compute(&before, &after);
        assert!(fd.cpu_regs.is_some());
        let cpu = fd.cpu_regs.unwrap();
        assert_eq!(cpu.a, 0x42);
        assert_eq!(cpu.pc, 0xBEEF);
    }

    #[test]
    fn ppu_ctrl_change_detected() {
        let before = make_snapshot();
        let mut after = before.clone();
        after.ppu.ctrl = 0x80;

        let fd = FieldDelta::compute(&before, &after);
        assert!(fd.ppu_ctrl.is_some());
        assert_eq!(fd.ppu_ctrl.unwrap()[0], 0x80);
    }

    #[test]
    fn ppu_timing_change_detected() {
        let before = make_snapshot();
        let mut after = before.clone();
        after.ppu.frame_counter = 999;
        after.ppu.scanline = 120;

        let fd = FieldDelta::compute(&before, &after);
        assert!(fd.ppu_timing.is_some());
        let t = fd.ppu_timing.unwrap();
        assert_eq!(t.frame_counter, 999);
        assert_eq!(t.scanline, 120);
    }

    #[test]
    fn field_delta_apply_restores_changes() {
        let before = make_snapshot();
        let mut after = before.clone();
        after.cpu.a = 0x77;
        after.ppu.ctrl = 0x88;
        after.ppu.frame_counter = 42;

        let fd = FieldDelta::compute(&before, &after);

        let mut target = before.clone();
        fd.apply(&mut target);
        assert_eq!(target.cpu.a, 0x77);
        assert_eq!(target.ppu.ctrl, 0x88);
        assert_eq!(target.ppu.frame_counter, 42);
    }

    // -----------------------------------------------------------------------
    // FrameDelta tests
    // -----------------------------------------------------------------------

    #[test]
    fn identical_snapshots_zero_compressed_size() {
        let snap = make_snapshot();
        let fd = FrameDelta::compute(&snap, &snap);
        assert_eq!(fd.compressed_size(), 0);
    }

    #[test]
    fn palette_change_tracked_in_frame_delta() {
        let before = make_snapshot();
        let mut after = before.clone();
        after.ppu.palette_ram[0] = 0x0F; // black background
        after.ppu.palette_ram[1] = 0x16; // red

        let fd = FrameDelta::compute(&before, &after);
        assert!(!fd.palette_deltas.is_empty());
    }

    #[test]
    fn palette_delta_roundtrip() {
        let before = make_snapshot();
        let mut after = before.clone();
        after.ppu.palette_ram[0] = 0x0F;
        after.ppu.palette_ram[16] = 0x30; // white sprite palette

        let fd = FrameDelta::compute(&before, &after);
        let mut target = before.clone();
        fd.apply(&mut target);

        assert_eq!(target.ppu.palette_ram[0], 0x0F);
        assert_eq!(target.ppu.palette_ram[16], 0x30);
    }

    #[test]
    fn frame_delta_roundtrip() {
        let before = make_snapshot();
        let mut after = before.clone();

        // Mutate several areas
        after.cpu.work_ram[0] = 0xAA;
        after.cpu.work_ram[1] = 0xBB;
        after.ppu.oam[10] = 0xCC;
        after.ppu.chr[500] = 0xDD;
        after.ppu.nametable_ram[100] = 0xEE;
        after.ppu.palette_ram[4] = 0x16;
        after.ppu.vram_addr = 0x1234;
        after.ppu.scroll_x = 100;
        after.cpu.a = 0x42;
        after.ppu.frame_counter = 100;

        let fd = FrameDelta::compute(&before, &after);
        assert!(fd.compressed_size() > 0);

        let mut target = before.clone();
        fd.apply(&mut target);

        assert_eq!(target.cpu.work_ram[0], 0xAA);
        assert_eq!(target.cpu.work_ram[1], 0xBB);
        assert_eq!(target.ppu.oam[10], 0xCC);
        assert_eq!(target.ppu.chr[500], 0xDD);
        assert_eq!(target.ppu.nametable_ram[100], 0xEE);
        assert_eq!(target.ppu.palette_ram[4], 0x16);
        assert_eq!(target.ppu.vram_addr, 0x1234);
        assert_eq!(target.ppu.scroll_x, 100);
        assert_eq!(target.cpu.a, 0x42);
        assert_eq!(target.ppu.frame_counter, 100);
    }

    #[test]
    fn frame_delta_frame_id_is_after_frame_counter() {
        let before = make_snapshot();
        let mut after = before.clone();
        after.ppu.frame_counter = 7;

        let fd = FrameDelta::compute(&before, &after);
        assert_eq!(fd.frame_id, 7);
    }
}

//! Time Machine: player-facing rewind with anchor+delta compression.

/// Rewind cursor for querying historical state.
pub mod cursor;
/// State delta encoding and decoding utilities.
pub mod delta;
/// Keyframe placement policy and heuristic logic.
pub mod policy;
/// Ring-buffer timeline for storing compressed historical states.
pub mod timeline;
/// Asynchronous worker orchestrating state capturing and compression.
pub mod worker;

pub use cursor::{RewindCursor, RewindSpeed};
pub use delta::{ArrayDelta, FieldDelta, FrameDelta};
pub use policy::KeyframePolicy;
pub use timeline::CompressedTimeline;
pub use worker::{TimeMachine, TimeMachineConfig, TimeMachineState};

/// Decides when to promote a full keyframe snapshot vs storing a delta.
///
/// Uses an Exponential Moving Average (EMA) of recent delta sizes to detect
/// spikes that warrant an early keyframe, plus a base interval guarantee.
#[derive(Debug, Clone)]
pub struct KeyframePolicy {
    base_interval: u64,
    spike_threshold: u32,
    frames_since_keyframe: u64,
    rolling_avg: u32,
}

impl KeyframePolicy {
    /// Creates a new `KeyframePolicy` with the given parameters.
    ///
    /// ## Arguments
    ///
    /// * `base_interval` - The guaranteed number of frames between keyframes,
    ///   assuming no delta spikes trigger an early keyframe.
    /// * `spike_threshold` - The heuristic threshold where a large frame delta
    ///   is considered complex enough to warrant a fresh keyframe immediately,
    ///   preventing expensive delta-chains.
    ///
    /// ## Examples
    ///
    /// ```
    /// use nes_rewind::policy::KeyframePolicy;
    ///
    /// let mut policy = KeyframePolicy::new(60, 4000);
    /// assert_eq!(policy.should_promote(100), false); // Still under interval
    /// assert_eq!(policy.should_promote(5000), true); // Triggered by spike
    /// ```
    pub fn new(base_interval: u64, spike_threshold: u32) -> Self {
        Self {
            base_interval,
            spike_threshold,
            frames_since_keyframe: 0,
            rolling_avg: 0,
        }
    }

    /// Returns true if a full keyframe should be stored this frame.
    ///
    /// Updates internal EMA. Resets counter on promotion.
    pub fn should_promote(&mut self, delta_size: u32) -> bool {
        self.frames_since_keyframe += 1;
        self.rolling_avg = self.ema_step(delta_size);

        if self.frames_since_keyframe >= self.base_interval {
            self.frames_since_keyframe = 0;
            return true;
        }

        if delta_size > self.spike_threshold && delta_size > self.rolling_avg * 3 {
            self.frames_since_keyframe = 0;
            return true;
        }

        false
    }

    fn ema_step(&self, new_value: u32) -> u32 {
        // alpha = 32/256 ~ 0.125 in Q8 fixed point
        const ALPHA_Q8: u32 = 32;
        let weighted_new = (new_value * ALPHA_Q8) >> 8;
        let weighted_old = (self.rolling_avg * (256 - ALPHA_Q8)) >> 8;
        weighted_new + weighted_old
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn policy() -> KeyframePolicy {
        KeyframePolicy::new(60, 2048)
    }

    #[test]
    fn forces_keyframe_at_base_interval() {
        let mut p = policy();
        for _ in 0..59 {
            assert!(!p.should_promote(100));
        }
        assert!(p.should_promote(100)); // 60th tick
    }

    #[test]
    fn resets_counter_after_promotion() {
        let mut p = policy();
        for _ in 0..60 {
            p.should_promote(100);
        }
        for _ in 0..59 {
            assert!(!p.should_promote(100));
        }
        assert!(p.should_promote(100));
    }

    #[test]
    fn spike_triggers_early_promotion() {
        let mut p = policy();
        for _ in 0..10 {
            p.should_promote(100);
        } // warm up EMA
        assert!(p.should_promote(10_000)); // massive spike
    }

    #[test]
    fn moderate_delta_does_not_false_positive() {
        let mut p = policy();
        for _ in 0..10 {
            p.should_promote(500);
        }
        assert!(!p.should_promote(1000)); // 2x avg, not 3x
    }
}

//! Anchor+delta ring buffer for the Time Machine rewind system.

use std::collections::VecDeque;

use nes_core::CoreSnapshot;

use crate::delta::FrameDelta;
use crate::policy::KeyframePolicy;

struct Keyframe {
    frame_id: u64,
    snapshot: CoreSnapshot,
}

/// Rolling history of emulator states as anchor keyframes + compressed deltas.
///
/// Stores full [`CoreSnapshot`] keyframes at adaptive intervals and
/// [`FrameDelta`]s between them. Old history is pruned automatically when
/// `max_frames` is exceeded.
pub struct CompressedTimeline {
    keyframes: VecDeque<Keyframe>,
    deltas: VecDeque<FrameDelta>,
    max_frames: u64,
    policy: KeyframePolicy,
    last_snapshot: Option<CoreSnapshot>,
    last_frame_id: Option<u64>,
}

impl CompressedTimeline {
    /// Create a new timeline with the given capacity and keyframe policy.
    pub fn new(max_frames: u64, policy: KeyframePolicy) -> Self {
        Self {
            keyframes: VecDeque::new(),
            deltas: VecDeque::new(),
            max_frames,
            policy,
            last_snapshot: None,
            last_frame_id: None,
        }
    }

    /// Push a new frame into the timeline.
    ///
    /// The first frame is always stored as a keyframe. Subsequent frames are
    /// stored as deltas unless [`KeyframePolicy`] promotes them to keyframes.
    pub fn push(&mut self, frame_id: u64, snapshot: CoreSnapshot) {
        if let Some(prev) = self.last_snapshot.take() {
            let mut delta = FrameDelta::compute(&prev, &snapshot);
            // Override with the caller-supplied frame_id — FrameDelta::compute
            // uses ppu.frame_counter which may lag behind the logical frame id.
            delta.frame_id = frame_id;
            let size = delta.compressed_size();

            if self.policy.should_promote(size) {
                self.keyframes.push_back(Keyframe {
                    frame_id,
                    snapshot: snapshot.clone(),
                });
            } else {
                self.deltas.push_back(delta);
            }
        } else {
            // First frame always anchors.
            self.keyframes.push_back(Keyframe {
                frame_id,
                snapshot: snapshot.clone(),
            });
        }

        self.last_snapshot = Some(snapshot);
        self.last_frame_id = Some(frame_id);
        self.prune();
    }

    /// Reconstruct the snapshot at `target_frame_id`.
    ///
    /// Finds the nearest keyframe at or before `target_frame_id`, then
    /// replays deltas forward. Returns `None` if the frame has been pruned,
    /// was never recorded, or is beyond the last recorded frame.
    #[must_use]
    pub fn reconstruct(&self, target_frame_id: u64) -> Option<CoreSnapshot> {
        // Reject frames we've never seen.
        if self.last_frame_id.is_none_or(|last| target_frame_id > last) {
            return None;
        }

        // Latest keyframe at or before target.
        let kf = self
            .keyframes
            .iter()
            .rev()
            .find(|kf| kf.frame_id <= target_frame_id)?;
        let mut snap = kf.snapshot.clone();

        if kf.frame_id == target_frame_id {
            return Some(snap);
        }

        // Replay deltas between keyframe and target.
        for delta in &self.deltas {
            if delta.frame_id > kf.frame_id && delta.frame_id <= target_frame_id {
                delta.apply(&mut snap);
            }
        }
        Some(snap)
    }

    /// Total number of recorded entries (keyframes + deltas).
    #[must_use]
    pub fn len(&self) -> usize {
        self.keyframes.len() + self.deltas.len()
    }

    /// Returns `true` if no frames have been recorded yet.
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.keyframes.is_empty() && self.deltas.is_empty()
    }

    fn prune(&mut self) {
        while self.len() as u64 > self.max_frames {
            // Where does the second-oldest keyframe begin?
            let next_kf_id = self
                .keyframes
                .get(1)
                .map(|kf| kf.frame_id)
                .unwrap_or(u64::MAX);

            if self.deltas.front().is_some_and(|d| d.frame_id < next_kf_id) {
                // Advance the oldest keyframe by absorbing the first delta into
                // it in-place. This removes one delta (net -1) without breaking
                // the anchor chain.
                let delta = self.deltas.pop_front().unwrap();
                if let Some(oldest) = self.keyframes.front_mut() {
                    delta.apply(&mut oldest.snapshot);
                    oldest.frame_id = delta.frame_id;
                }
            } else {
                // No deltas anchored to oldest keyframe — drop it and any
                // orphaned deltas that preceded the next keyframe.
                self.keyframes.pop_front();
                while self.deltas.front().is_some_and(|d| d.frame_id < next_kf_id) {
                    self.deltas.pop_front();
                }
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use nes_core::{Command, NesCore};

    fn make_core() -> NesCore {
        let mut core = NesCore::new();
        core.load_cpu_bytes(0xC000, &[0xEA, 0x4C, 0x00, 0xC0]);
        core
    }

    fn policy() -> KeyframePolicy {
        KeyframePolicy::new(10, 2048)
    }

    #[test]
    fn empty_timeline_returns_none() {
        let tl = CompressedTimeline::new(300, policy());
        assert!(tl.is_empty());
        assert!(tl.reconstruct(0).is_none());
    }

    #[test]
    fn first_push_is_keyframe_and_reconstructs() {
        let core = make_core();
        let snap = core.save_state();
        let mut tl = CompressedTimeline::new(300, policy());
        tl.push(0, snap.clone());

        assert_eq!(tl.len(), 1);
        let got = tl.reconstruct(0).unwrap();
        assert_eq!(got.ppu.frame_counter, snap.ppu.frame_counter);
    }

    #[test]
    fn reconstruct_unknown_frame_returns_none() {
        let core = make_core();
        let mut tl = CompressedTimeline::new(300, policy());
        tl.push(0, core.save_state());
        assert!(tl.reconstruct(999).is_none());
    }

    #[test]
    fn push_prunes_when_over_capacity() {
        let core = make_core();
        let snap = core.save_state();
        let mut tl = CompressedTimeline::new(5, policy());
        for i in 0..10u64 {
            tl.push(i, snap.clone());
        }
        assert!(tl.len() <= 5);
        // Oldest frames should be gone.
        assert!(tl.reconstruct(0).is_none());
        // Most recent should still be available.
        assert!(tl.reconstruct(9).is_some());
    }

    #[test]
    fn reconstruct_after_step_frame_restores_earlier_state() {
        let mut core = make_core();
        let mut tl = CompressedTimeline::new(300, policy());

        let snap0 = core.save_state();
        tl.push(0, snap0);

        core.execute(Command::StepFrame).unwrap();
        let snap1 = core.save_state();
        let frame1 = snap1.ppu.frame_counter;
        tl.push(frame1, snap1);

        core.execute(Command::StepFrame).unwrap();
        let snap2 = core.save_state();
        let frame2 = snap2.ppu.frame_counter;
        tl.push(frame2, snap2);

        // Reconstruct frame 0 — should have frame_counter 0.
        let restored = tl.reconstruct(0).unwrap();
        assert_eq!(restored.ppu.frame_counter, 0);
    }
}

//! TimeMachine: host-facing rewind API backed by a background worker thread.
//!
//! The main emulation thread calls [`TimeMachine::record_frame`] each frame
//! (non-blocking — drops if the channel is full) and [`TimeMachine::rewind_step`]
//! during rewind. All timeline compression and reconstruction runs on a
//! dedicated background thread so the audio/video loop is never stalled.

use std::sync::mpsc::{self, Receiver, SyncSender};
use std::thread;
use std::time::Duration;

use nes_core::{CoreSnapshot, NesCore};

use crate::cursor::{RewindCursor, RewindSpeed};
use crate::policy::KeyframePolicy;
use crate::timeline::CompressedTimeline;

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------

/// Configuration for the Time Machine rewind system.
#[derive(Debug, Clone)]
pub struct TimeMachineConfig {
    /// How many seconds of history to retain (default: 30).
    pub max_history_seconds: u32,
    /// Minimum frames between forced keyframes (default: 60).
    pub keyframe_base_interval: u64,
    /// Delta byte threshold that, combined with 3× EMA, triggers early keyframe.
    pub delta_spike_threshold: u32,
}

impl Default for TimeMachineConfig {
    fn default() -> Self {
        Self {
            max_history_seconds: 30,
            keyframe_base_interval: 60,
            delta_spike_threshold: 2048,
        }
    }
}

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------

/// Observable state of the Time Machine.
#[derive(Debug, Clone, PartialEq)]
pub enum TimeMachineState {
    /// Actively recording frames.
    Recording,
    /// Rewinding history.
    Rewinding {
        /// Approximate history time remaining (seconds from frame 0).
        seconds_remaining: f32,
    },
    /// Rewind history exhausted.
    Exhausted,
}

// ---------------------------------------------------------------------------
// Worker protocol
// ---------------------------------------------------------------------------

enum WorkerMsg {
    Record {
        frame_id: u64,
        snapshot: Box<CoreSnapshot>,
    },
    Reconstruct {
        target_frame: u64,
    },
    Shutdown,
}

enum WorkerReply {
    Reconstructed {
        frame_id: u64,
        snapshot: CoreSnapshot,
    },
}

// ---------------------------------------------------------------------------
// TimeMachine
// ---------------------------------------------------------------------------

/// Host-facing rewind controller.
///
/// # Usage
///
/// ```no_run
/// use nes_core::{Command, NesCore};
/// use nes_rewind::worker::{TimeMachine, TimeMachineConfig};
///
/// let mut core = NesCore::new();
/// let mut tm = TimeMachine::new(TimeMachineConfig::default());
///
/// // Each frame: advance then record.
/// core.execute(Command::StepFrame).unwrap();
/// tm.record_frame(&core);
///
/// // On rewind key: step backward.
/// tm.rewind_step(&mut core);
/// ```
pub struct TimeMachine {
    #[allow(dead_code)]
    config: TimeMachineConfig,
    state: TimeMachineState,
    cursor: Option<RewindCursor>,
    tx: SyncSender<WorkerMsg>,
    rx: Receiver<WorkerReply>,
    last_recorded_frame: u64,
}

impl TimeMachine {
    /// Construct a new `TimeMachine` and spawn its background worker thread.
    pub fn new(config: TimeMachineConfig) -> Self {
        let max_frames = u64::from(config.max_history_seconds) * 60;
        let policy =
            KeyframePolicy::new(config.keyframe_base_interval, config.delta_spike_threshold);

        // Channel capacities:
        //   work_tx capacity 4  — small; emulation thread drops rather than blocks.
        //   reply_tx capacity 64 — large enough for lookahead pre-fetch bursts.
        let (work_tx, work_rx) = mpsc::sync_channel::<WorkerMsg>(4);
        let (reply_tx, reply_rx) = mpsc::sync_channel::<WorkerReply>(64);

        thread::spawn(move || {
            let mut timeline = CompressedTimeline::new(max_frames, policy);
            loop {
                match work_rx.recv() {
                    Ok(WorkerMsg::Record { frame_id, snapshot }) => {
                        timeline.push(frame_id, *snapshot);
                    }
                    Ok(WorkerMsg::Reconstruct { target_frame }) => {
                        if let Some(snapshot) = timeline.reconstruct(target_frame) {
                            let _ = reply_tx.send(WorkerReply::Reconstructed {
                                frame_id: target_frame,
                                snapshot,
                            });
                        }
                    }
                    Ok(WorkerMsg::Shutdown) | Err(_) => break,
                }
            }
        });

        Self {
            config,
            state: TimeMachineState::Recording,
            cursor: None,
            tx: work_tx,
            rx: reply_rx,
            last_recorded_frame: 0,
        }
    }

    /// Record the current emulator state. Non-blocking — drops if worker is busy.
    ///
    /// Call once per frame after advancing the core, only while [`TimeMachineState::Recording`].
    pub fn record_frame(&mut self, core: &NesCore) {
        if !matches!(self.state, TimeMachineState::Recording) {
            return;
        }
        let frame_id = core.ppu_frame_counter();
        let snapshot = core.save_state();
        self.last_recorded_frame = frame_id;
        // `try_send` — never block the emulation thread.
        let _ = self.tx.try_send(WorkerMsg::Record {
            frame_id,
            snapshot: Box::new(snapshot),
        });
    }

    /// Step backward one frame. Returns `Some(frame_id)` on success, `None` when history is exhausted.
    ///
    /// Blocks up to 16 ms waiting for the worker to reconstruct the target frame.
    pub fn rewind_step(&mut self, core: &mut NesCore) -> Option<u64> {
        // Initialise the cursor on first rewind call.
        if self.cursor.is_none() {
            self.state = TimeMachineState::Rewinding {
                seconds_remaining: 0.0,
            };
            self.cursor = Some(RewindCursor::new(
                self.last_recorded_frame,
                RewindSpeed::Normal,
            ));
        }

        let cursor = self.cursor.as_mut().unwrap();
        let target = cursor.current_frame.checked_sub(1)?;

        // Request the previous frame from the worker.
        // Use blocking send here — during rewind the emulation loop is paused so
        // it is acceptable to wait briefly for a slot (worker drains quickly).
        let _ = self.tx.send(WorkerMsg::Reconstruct {
            target_frame: target,
        });

        // Wait up to one frame-budget (16 ms) for the reply.
        if let Ok(WorkerReply::Reconstructed { frame_id, snapshot }) =
            self.rx.recv_timeout(Duration::from_millis(16))
        {
            cursor.current_frame = frame_id;
            core.load_state(&snapshot);
            self.state = TimeMachineState::Rewinding {
                seconds_remaining: frame_id as f32 / 60.0,
            };
            Some(frame_id)
        } else {
            self.state = TimeMachineState::Exhausted;
            None
        }
    }

    /// Accelerate rewind (tap → Normal → Fast → Faster).
    pub fn rewind_faster(&mut self) {
        if let Some(cursor) = &mut self.cursor {
            cursor.speed = match cursor.speed {
                RewindSpeed::Single | RewindSpeed::Normal => RewindSpeed::Fast,
                RewindSpeed::Fast => RewindSpeed::Faster,
                RewindSpeed::Faster => RewindSpeed::Faster,
            };
        }
    }

    /// Resume recording from the current rewind position.
    pub fn resume(&mut self) {
        self.cursor = None;
        self.state = TimeMachineState::Recording;
    }

    /// Current observable state.
    pub fn state(&self) -> TimeMachineState {
        self.state.clone()
    }

    /// Approximate seconds of history recorded so far.
    pub fn history_seconds(&self) -> f32 {
        self.last_recorded_frame as f32 / 60.0
    }
}

impl Drop for TimeMachine {
    fn drop(&mut self) {
        // Best-effort graceful shutdown of the worker thread.
        let _ = self.tx.send(WorkerMsg::Shutdown);
    }
}

