//! Homebrew ROM builder binary
//!
//! A standalone utility used to assemble and write the custom homebrew NES ROM.
//! This allows the workspace to have a deterministic test target without needing
//! an external 6502 assembler.

use std::env;
use std::path::PathBuf;

use comfy_table::{Cell, Color as TableColor, Table, presets::UTF8_FULL};
use crossterm::style::{Color, Stylize};
use nes_test_harness::{default_homebrew_rom_path, write_homebrew_rom};

fn main() {
    if let Err(err) = run() {
        eprintln!("\n{}", err);
        std::process::exit(1);
    }
}

fn run() -> Result<(), String> {
    let mut args = env::args().skip(1);
    let mut out_path = default_homebrew_rom_path();

    while let Some(arg) = args.next() {
        match arg.as_str() {
            "--help" | "-h" => {
                println!(
                    "Usage: build_homebrew_rom [--out <path>]\nDefault output: {}",
                    out_path.display()
                );
                return Ok(());
            }
            "--out" => {
                let Some(path) = args.next() else {
                    return Err("missing value after --out".to_owned());
                };
                out_path = PathBuf::from(path);
            }
            _ => return Err(format!("unknown argument '{arg}'")),
        }
    }

    write_homebrew_rom(&out_path)?;

    println!("{}", "Building Homebrew ROM...".with(Color::Cyan).bold());

    println!("\n{}", build_success_table(&out_path));

    Ok(())
}

fn build_success_table(out_path: &std::path::Path) -> Table {
    let mut table = Table::new();
    table.load_preset(UTF8_FULL);
    table.set_header(vec![
        Cell::new("Property").fg(TableColor::Cyan),
        Cell::new("Value").fg(TableColor::White),
    ]);

    table.add_row(vec![
        Cell::new("Output Path"),
        Cell::new(out_path.display().to_string()).fg(TableColor::Green),
    ]);
    table.add_row(vec![
        Cell::new("Status"),
        Cell::new("Success").fg(TableColor::Green),
    ]);

    table
}

#[cfg(test)]
mod tests {
    use super::build_success_table;
    use std::path::PathBuf;

    #[test]
    fn build_success_table_includes_path_and_success_status() {
        let path = PathBuf::from("test/path/rom.nes");
        let table = build_success_table(&path);
        let output = table.to_string();

        assert!(output.contains("test/path/rom.nes"));
        assert!(output.contains("Output Path"));
        assert!(output.contains("Status"));
        assert!(output.contains("Success"));
    }
}

use std::fs;
use std::path::{Path, PathBuf};

#[must_use]
pub fn default_homebrew_rom_path() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .join("roms")
        .join("homebrew")
        .join("homebrew.nes")
}

/// Compiles the minimal test ROM ("homebrew.nes") using the `nes_dsl` assembler.
///
/// This ROM is used across the codebase for integration testing and serves as a reliable,
/// deterministic target that doesn't require downloading copyrighted material.
///
/// ## Examples
///
/// ```
/// use nes_test_harness::build_homebrew_rom;
///
/// let rom_bytes = build_homebrew_rom().unwrap();
/// assert!(rom_bytes.len() > 16);
/// assert_eq!(&rom_bytes[0..4], b"NES\x1A");
/// ```
pub fn build_homebrew_rom() -> Result<Vec<u8>, String> {
    let source = assemble_homebrew_program();

    let options = nes_dsl::RomBuildOptions {
        chr_rom: {
            let mut chr = vec![0_u8; 8192];
            let tile_1 = [
                0x18, 0x3C, 0x7E, 0xFF, 0xFF, 0x7E, 0x3C, 0x18, // plane 0
                0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, // plane 1
            ];
            chr[16..32].copy_from_slice(&tile_1);
            chr
        },
        ..nes_dsl::RomBuildOptions::default()
    };

    nes_dsl::build_ines_nrom_rom(&source, &options).map_err(|e| e.to_string())
}

/// Compiles and writes the minimal test ROM to the specified path on disk.
///
/// This function also creates any missing parent directories required by the target path.
///
/// ## Examples
///
/// ```no_run
/// use std::path::Path;
/// use nes_test_harness::write_homebrew_rom;
///
/// let path = Path::new("./roms/homebrew/homebrew.nes");
/// write_homebrew_rom(path).unwrap();
/// assert!(path.exists());
/// ```
pub fn write_homebrew_rom(path: &Path) -> Result<(), String> {
    let rom = build_homebrew_rom()?;
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).map_err(|err| {
            format!(
                "failed to create homebrew output directory '{}': {err}",
                parent.display()
            )
        })?;
    }
    fs::write(path, rom)
        .map_err(|err| format!("failed to write homebrew ROM '{}': {err}", path.display()))
}

fn assemble_homebrew_program() -> String {
    r#"
.bank 0
.org $C000

.const PPUCTRL = $2000
.const PPUMASK = $2001
.const PPUSTATUS = $2002
.const OAMADDR = $2003
.const PPUSCROLL = $2005
.const PPUADDR = $2006
.const PPUDATA = $2007
.const OAMDMA = $4014

.const APU_DMC = $4010
.const APU_FRAME = $4017
.const JOY1 = $4016
.const JOY2 = $4017

.const SPR_Y = $00
.const SPR_X = $01
.const OAM_Y = $0200
.const OAM_TILE = $0201
.const OAM_ATTR = $0202
.const OAM_X = $0203

reset:
    sei
    cld
    ldx #$40
    stx APU_FRAME
    ldx #$FF
    txs
    inx
    stx PPUCTRL
    stx PPUMASK
    stx APU_DMC
    jsr vblank_wait
    jsr vblank_wait

    lda #$70
    sta SPR_Y
    lda #$70
    sta SPR_X

    lda PPUSTATUS
    lda #$3F
    sta PPUADDR
    lda #$00
    sta PPUADDR

    ; BG palette 0
    lda #$21
    sta PPUDATA
    lda #$30
    sta PPUDATA
    lda #$16
    sta PPUDATA
    lda #$0F
    sta PPUDATA

    ; BG palette 1
    lda #$21
    sta PPUDATA
    lda #$01
    sta PPUDATA
    lda #$11
    sta PPUDATA
    lda #$31
    sta PPUDATA

    ; BG palette 2
    lda #$21
    sta PPUDATA
    lda #$06
    sta PPUDATA
    lda #$16
    sta PPUDATA
    lda #$26
    sta PPUDATA

    ; sprite palette 0
    lda #$21
    sta PPUDATA
    lda #$30
    sta PPUDATA
    lda #$16
    sta PPUDATA
    lda #$0F
    sta PPUDATA

    lda #$01
    sta OAM_TILE
    lda #$00
    sta OAM_ATTR
    lda SPR_Y
    sta OAM_Y
    lda SPR_X
    sta OAM_X
    lda #$02
    sta OAMDMA

    lda #%10000000
    sta PPUCTRL
    lda #%00011110
    sta PPUMASK

main_loop:
    jmp main_loop

vblank_wait:
    bit PPUSTATUS
    bpl vblank_wait
    rts

nmi:
    pha
    txa
    pha
    tya
    pha

    lda #$01
    sta JOY1
    lda #$00
    sta JOY1

    ; Skip A/B/Select/Start
    lda JOY1
    lda JOY1
    lda JOY1
    lda JOY1

    ; Up
    lda JOY1
    and #$01
    beq not_up
    dec SPR_Y
not_up:

    ; Down
    lda JOY1
    and #$01
    beq not_down
    inc SPR_Y
not_down:

    ; Left
    lda JOY1
    and #$01
    beq not_left
    dec SPR_X
not_left:

    ; Right
    lda JOY1
    and #$01
    beq not_right
    inc SPR_X
not_right:

    lda SPR_Y
    sta OAM_Y
    lda #$01
    sta OAM_TILE
    lda #$00
    sta OAM_ATTR
    lda SPR_X
    sta OAM_X
    lda #$02
    sta OAMDMA

    pla
    tay
    pla
    tax
    pla
    rti

irq:
    rti

.reset reset
.nmi nmi
.irq irq
"#
    .to_owned()
}

