fn nestest_boot_sequence_matches_expected_prefix() {
    let rom_path = nestest_rom_path();

    let bytes = fs::read(&rom_path).expect("failed to read nestest ROM");
    let mut core = NesCore::new();
    let info = core
        .load_ines_rom(&bytes)
        .expect("failed to load nestest ROM");
