    let expected = [
        "C004  78        SEI",
        "C005  D8        CLD",
        "C006  A2 FF     LDX #$FF",
        "C008  9A        TXS",
        "C009  AD 02 20  LDA $2002",
        "C00C  10 FB     BPL $C009",
    ];
    let expected_cycles = [2_u64, 4, 6, 8, 12, 15];

    for (step, expected_prefix) in expected.iter().enumerate() {
        core.execute(Command::StepCpu).unwrap_or_else(|err| {
            panic!(
                "nestest prefix step failed at pc={:04X}: {err}",
                core.cpu_pc()
