//! Terminal rendering engine for the NES emulator.
//!
//! This module provides high-performance routines for downsampling the raw `256x240` RGBA
//! framebuffer from the NES PPU into stylized text structures compatible with the `ratatui`
//! terminal UI library. It supports multiple block-character resolutions (e.g., half-block
//! and quarter-block) to approximate the display in a standard monospaced terminal.

use nes_core::{FRAME_HEIGHT, FRAME_RGBA_BYTES, FRAME_WIDTH};
use ratatui::style::{Color, Style};
use ratatui::text::{Line, Span};

/// Downsamples the raw RGBA NES framebuffer into a smaller grid of RGB tuples.
///
/// Uses nearest-neighbor sampling. Useful for building raw color maps or basic
/// single-character (space) rendering modes.
///
/// ## Panics
///
/// This function does not panic, provided the `frame_rgba` matches the expected
/// length of `nes_core::FRAME_RGBA_BYTES`. If the inputs are invalid or target
/// dimensions are zero, it returns an empty vector.
///
/// ## Examples
///
/// ```
/// use nes_core::FRAME_RGBA_BYTES;
/// use nes_tui::render::downsample_frame_rgb;
///
/// let frame = vec![0_u8; FRAME_RGBA_BYTES];
/// // Downsample to a 64x60 grid
/// let cells = downsample_frame_rgb(&frame, 64, 60);
/// assert_eq!(cells.len(), 64 * 60);
/// ```
#[must_use]
pub fn downsample_frame_rgb(
    frame_rgba: &[u8],
    target_width: u16,
    target_height: u16,
) -> Vec<(u8, u8, u8)> {
    if frame_rgba.len() != FRAME_RGBA_BYTES || target_width == 0 || target_height == 0 {
        return Vec::new();
    }

    let width = usize::from(target_width);
    let height = usize::from(target_height);
    assert!(
        width > 0 && height > 0,
        "downsample dimensions must be non-zero after guard validation"
    );
    let mut out = Vec::with_capacity(width * height);

    for y in 0..height {
        let src_y = if height == 1 {
            FRAME_HEIGHT / 2
        } else {
            y * (FRAME_HEIGHT - 1) / (height - 1)
        };
        for x in 0..width {
            let src_x = if width == 1 {
                FRAME_WIDTH / 2
            } else {
                x * (FRAME_WIDTH - 1) / (width - 1)
            };
            let idx = (src_y * FRAME_WIDTH + src_x) * 4;
            out.push((frame_rgba[idx], frame_rgba[idx + 1], frame_rgba[idx + 2]));
        }
    }

    out
}

/// Converts a flat slice of RGB tuples into a list of `ratatui` [`Line`]s using spaces.
///
/// Each cell is rendered as a single space character with the background color
/// set to the RGB tuple. This creates a low-resolution "full block" appearance.
///
/// ## Examples
///
/// ```
/// use nes_tui::render::frame_lines_from_rgb;
///
/// let cells = vec![(255, 0, 0), (0, 255, 0)];
/// let lines = frame_lines_from_rgb(&cells, 2);
/// assert_eq!(lines.len(), 1);
/// assert_eq!(lines[0].spans.len(), 2);
/// ```
#[must_use]
pub fn frame_lines_from_rgb(cells: &[(u8, u8, u8)], width: u16) -> Vec<Line<'static>> {
    if width == 0 {
        return Vec::new();
    }

    let row_width = usize::from(width);
    let mut lines = Vec::with_capacity(cells.len() / row_width);
    for row in cells.chunks(row_width) {
        let mut spans = Vec::with_capacity(row.len());
        for &(r, g, b) in row {
            spans.push(Span::styled(
                " ",
                Style::default()
                    .fg(Color::Rgb(r, g, b))
                    .bg(Color::Rgb(r, g, b)),
            ));
        }
        lines.push(Line::from(spans));
    }
    lines
}

/// Renders the NES framebuffer into `ratatui` lines using Unicode half-blocks (`▀`).
///
/// This technique doubles the vertical resolution in the terminal by using the
/// foreground color for the top half of the character cell and the background color
/// for the bottom half. It averages pixel regions to produce smooth colors.
///
/// ## Examples
///
/// ```
/// use nes_core::FRAME_RGBA_BYTES;
/// use nes_tui::render::frame_lines_half_blocks;
///
/// let frame = vec![0_u8; FRAME_RGBA_BYTES];
/// // Requesting a 64x24 terminal area
/// let lines = frame_lines_half_blocks(&frame, 64, 24);
/// assert_eq!(lines.len(), 24);
/// ```
#[must_use]
pub fn frame_lines_half_blocks(
    frame_rgba: &[u8],
    target_width: u16,
    target_height: u16,
) -> Vec<Line<'static>> {
    if frame_rgba.len() != FRAME_RGBA_BYTES || target_width == 0 || target_height == 0 {
        return Vec::new();
    }

    let width = usize::from(target_width);
    let height = usize::from(target_height);
    let virtual_rows = height.saturating_mul(2);
    let mut lines = Vec::with_capacity(height);

    for row in 0..height {
        let top_virtual_y = row.saturating_mul(2);
        let bottom_virtual_y = top_virtual_y.saturating_add(1);
        let (top_y_start, top_y_end) = bucket_bounds(top_virtual_y, virtual_rows, FRAME_HEIGHT);
        let (bottom_y_start, bottom_y_end) =
            bucket_bounds(bottom_virtual_y, virtual_rows, FRAME_HEIGHT);

        let mut spans = Vec::with_capacity(width);
        for col in 0..width {
            let (x_start, x_end) = bucket_bounds(col, width, FRAME_WIDTH);
            let top = average_region_rgb(frame_rgba, x_start, x_end, top_y_start, top_y_end);
            let bottom =
                average_region_rgb(frame_rgba, x_start, x_end, bottom_y_start, bottom_y_end);
            spans.push(Span::styled(
                "\u{2580}",
                Style::default()
                    .fg(Color::Rgb(top.0, top.1, top.2))
                    .bg(Color::Rgb(bottom.0, bottom.1, bottom.2)),
            ));
        }
        lines.push(Line::from(spans));
    }

    lines
}

/// Renders the NES framebuffer into `ratatui` lines using Unicode quarter-blocks.
///
/// This provides the highest perceived resolution in a terminal by fitting 4 "pixels"
/// (a 2x2 grid) into a single character cell, selecting an optimal foreground, background,
/// and block glyph mask for each cell.
///
/// ## Examples
///
/// ```
/// use nes_core::FRAME_RGBA_BYTES;
/// use nes_tui::render::frame_lines_quarter_blocks;
///
/// let frame = vec![0_u8; FRAME_RGBA_BYTES];
/// let lines = frame_lines_quarter_blocks(&frame, 64, 24);
/// assert_eq!(lines.len(), 24);
/// ```
#[must_use]
pub fn frame_lines_quarter_blocks(
    frame_rgba: &[u8],
    target_width: u16,
    target_height: u16,
) -> Vec<Line<'static>> {
    if frame_rgba.len() != FRAME_RGBA_BYTES || target_width == 0 || target_height == 0 {
        return Vec::new();
    }

    let width = usize::from(target_width);
    let height = usize::from(target_height);
    let virtual_cols = width.saturating_mul(2);
    let virtual_rows = height.saturating_mul(2);
    let mut lines = Vec::with_capacity(height);

    for row in 0..height {
        let top_virtual_y = row.saturating_mul(2);
        let bottom_virtual_y = top_virtual_y.saturating_add(1);
        let src_top_y = map_index(top_virtual_y, virtual_rows, FRAME_HEIGHT);
        let src_bottom_y = map_index(bottom_virtual_y, virtual_rows, FRAME_HEIGHT);

        let mut spans = Vec::with_capacity(width);
        for col in 0..width {
            let left_virtual_x = col.saturating_mul(2);
            let right_virtual_x = left_virtual_x.saturating_add(1);
            let src_left_x = map_index(left_virtual_x, virtual_cols, FRAME_WIDTH);
            let src_right_x = map_index(right_virtual_x, virtual_cols, FRAME_WIDTH);

            let samples = [
                sample_rgb(frame_rgba, src_left_x, src_top_y),
                sample_rgb(frame_rgba, src_right_x, src_top_y),
                sample_rgb(frame_rgba, src_left_x, src_bottom_y),
                sample_rgb(frame_rgba, src_right_x, src_bottom_y),
            ];
            let (mask, fg, bg) = choose_quarter_mask_and_palette(samples);
            spans.push(Span::styled(
                quarter_block_glyph(mask),
                Style::default()
                    .fg(Color::Rgb(fg.0, fg.1, fg.2))
                    .bg(Color::Rgb(bg.0, bg.1, bg.2)),
            ));
        }
        lines.push(Line::from(spans));
    }

    lines
}

/// Extracts a small sequence of color swatches directly from the center of the framebuffer.
///
/// This is used by the TUI to display a quick "color summary" or ambient theme palette
/// based on the current screen contents.
///
/// ## Examples
///
/// ```
/// use nes_core::FRAME_RGBA_BYTES;
/// use nes_tui::render::mini_palette_spans;
///
/// let frame = vec![0_u8; FRAME_RGBA_BYTES];
/// // Extract 5 color swatches
/// let spans = mini_palette_spans(&frame, 5);
/// assert_eq!(spans.len(), 5);
/// ```
#[must_use]
pub fn mini_palette_spans(frame_rgba: &[u8], swatches: usize) -> Vec<Span<'static>> {
    if frame_rgba.len() != FRAME_RGBA_BYTES || swatches == 0 {
        return Vec::new();
    }
    let mut spans = Vec::with_capacity(swatches);
    for idx in 0..swatches {
        let x = map_index(idx, swatches, FRAME_WIDTH);
        let y = FRAME_HEIGHT / 2;
        let (r, g, b) = sample_rgb(frame_rgba, x, y);
        spans.push(Span::styled(
            "  ",
            Style::default()
                .bg(Color::Rgb(r, g, b))
                .fg(Color::Rgb(r, g, b)),
        ));
    }
    spans
}

#[must_use]
fn sample_rgb(frame_rgba: &[u8], x: usize, y: usize) -> (u8, u8, u8) {
    let idx = (y * FRAME_WIDTH + x) * 4;
    (frame_rgba[idx], frame_rgba[idx + 1], frame_rgba[idx + 2])
}

#[must_use]
fn map_index(idx: usize, target_len: usize, source_len: usize) -> usize {
    if source_len <= 1 || target_len <= 1 {
        return 0;
    }
    idx.saturating_mul(source_len - 1) / (target_len - 1)
}

#[must_use]
fn bucket_bounds(idx: usize, bucket_count: usize, source_len: usize) -> (usize, usize) {
    if bucket_count == 0 || source_len == 0 {
        return (0, 0);
    }

    let start = idx.saturating_mul(source_len) / bucket_count;
    let mut end = idx.saturating_add(1).saturating_mul(source_len) / bucket_count;
    if end <= start {
        end = start.saturating_add(1);
    }

    (start.min(source_len.saturating_sub(1)), end.min(source_len))
}

#[must_use]
fn average_region_rgb(
    frame_rgba: &[u8],
    x_start: usize,
    x_end: usize,
    y_start: usize,
    y_end: usize,
) -> (u8, u8, u8) {
    let mut r_sum = 0_u32;
    let mut g_sum = 0_u32;
    let mut b_sum = 0_u32;
    let mut count = 0_u32;

    for y in y_start..y_end {
        for x in x_start..x_end {
            let idx = (y * FRAME_WIDTH + x) * 4;
            r_sum = r_sum.saturating_add(u32::from(frame_rgba[idx]));
            g_sum = g_sum.saturating_add(u32::from(frame_rgba[idx + 1]));
            b_sum = b_sum.saturating_add(u32::from(frame_rgba[idx + 2]));
            count = count.saturating_add(1);
        }
    }

    if count == 0 {
        return sample_rgb(
            frame_rgba,
            x_start.min(FRAME_WIDTH.saturating_sub(1)),
            y_start.min(FRAME_HEIGHT.saturating_sub(1)),
        );
    }

    (
        (r_sum / count) as u8,
        (g_sum / count) as u8,
        (b_sum / count) as u8,
    )
}

#[must_use]
fn choose_quarter_mask_and_palette(samples: [(u8, u8, u8); 4]) -> (u8, (u8, u8, u8), (u8, u8, u8)) {
    // **⚡ Bolt Optimization:** We use a stack-allocated fixed-size array instead of a `Vec`
    // to gather unique color candidates. This is invoked for every character cell on the screen
    // (potentially thousands of times per frame), completely eliminating heap allocations
    // on this extremely hot path.
    let mut candidates = [(0, 0, 0); 4];
    let mut candidates_len = 0;

    for sample in samples {
        let mut found = false;
        for &existing in &candidates[..candidates_len] {
            if existing == sample {
                found = true;
                break;
            }
        }
        if !found {
            candidates[candidates_len] = sample;
            candidates_len += 1;
        }
    }
    if candidates_len == 0 {
        return (0, (0, 0, 0), (0, 0, 0));
    }
    if candidates_len == 1 {
        return (15, candidates[0], candidates[0]);
    }

    let mut best_error = u32::MAX;
    let mut best = (15_u8, candidates[0], candidates[1]);

    for &fg in &candidates[..candidates_len] {
        for &bg in &candidates[..candidates_len] {
            let mut mask = 0_u8;
            let mut error = 0_u32;
            for (idx, &sample) in samples.iter().enumerate() {
                let fg_error = rgb_error_sq(sample, fg);
                let bg_error = rgb_error_sq(sample, bg);
                if fg_error <= bg_error {
                    mask |= 1_u8 << idx;
                    error = error.saturating_add(fg_error);
                } else {
                    error = error.saturating_add(bg_error);
                }
            }
            if error < best_error {
                best_error = error;
                best = (mask, fg, bg);
            }
        }
    }

    best
}

#[must_use]
fn rgb_error_sq(a: (u8, u8, u8), b: (u8, u8, u8)) -> u32 {
    let dr = i32::from(a.0) - i32::from(b.0);
    let dg = i32::from(a.1) - i32::from(b.1);
    let db = i32::from(a.2) - i32::from(b.2);
    ((dr * dr) + (dg * dg) + (db * db)) as u32
}

#[must_use]
fn quarter_block_glyph(mask: u8) -> &'static str {
    match mask {
        0 => " ",
        1 => "\u{2598}",  // TL
        2 => "\u{259D}",  // TR
        3 => "\u{2580}",  // TL + TR
        4 => "\u{2596}",  // BL
        5 => "\u{258C}",  // TL + BL
        6 => "\u{259E}",  // TR + BL
        7 => "\u{259B}",  // TL + TR + BL
        8 => "\u{2597}",  // BR
        9 => "\u{259A}",  // TL + BR
        10 => "\u{2590}", // TR + BR
        11 => "\u{259C}", // TL + TR + BR
        12 => "\u{2584}", // BL + BR
        13 => "\u{2599}", // TL + BL + BR
        14 => "\u{259F}", // TR + BL + BR
        _ => "\u{2588}",  // all quadrants
    }
}

#[cfg(test)]
mod tests {
    use super::{
        average_region_rgb, bucket_bounds, downsample_frame_rgb, frame_lines_from_rgb,
        frame_lines_half_blocks, frame_lines_quarter_blocks, map_index, mini_palette_spans,
        quarter_block_glyph, rgb_error_sq,
    };
    use nes_core::{FRAME_HEIGHT, FRAME_RGBA_BYTES, FRAME_WIDTH};
    use ratatui::style::Color;

    #[test]
    fn downsample_returns_expected_cell_count() {
        let frame = vec![0_u8; FRAME_RGBA_BYTES];
        let cells = downsample_frame_rgb(&frame, 64, 60);
        assert_eq!(cells.len(), 64 * 60);
    }

    #[test]
    fn downsample_returns_empty_for_invalid_frame_length() {
        let frame = vec![0_u8; FRAME_RGBA_BYTES - 1];
        let cells = downsample_frame_rgb(&frame, 1, 1);
        assert!(cells.is_empty());
    }

    #[test]
    fn downsample_returns_empty_when_target_dimensions_are_zero() {
        let frame = vec![0_u8; FRAME_RGBA_BYTES];
        assert!(downsample_frame_rgb(&frame, 0, 10).is_empty());
        assert!(downsample_frame_rgb(&frame, 10, 0).is_empty());
    }

    #[test]
    fn downsample_uses_nearest_pixel_mapping() {
        let mut frame = vec![0_u8; FRAME_RGBA_BYTES];
        write_px(&mut frame, 0, 0, 255, 0, 0);
        write_px(&mut frame, FRAME_WIDTH - 1, 0, 0, 255, 0);
        write_px(&mut frame, 0, FRAME_HEIGHT - 1, 0, 0, 255);
        write_px(&mut frame, FRAME_WIDTH - 1, FRAME_HEIGHT - 1, 255, 255, 0);

        let cells = downsample_frame_rgb(&frame, 2, 2);
        assert_eq!(cells[0], (255, 0, 0));
        assert_eq!(cells[1], (0, 255, 0));
        assert_eq!(cells[2], (0, 0, 255));
        assert_eq!(cells[3], (255, 255, 0));
    }

    #[test]
    fn downsample_height_one_samples_vertical_center_row() {
        let mut frame = vec![0_u8; FRAME_RGBA_BYTES];
        let center_y = FRAME_HEIGHT / 2;
        write_px(&mut frame, 0, center_y, 12, 34, 56);
        write_px(&mut frame, FRAME_WIDTH - 1, center_y, 65, 43, 21);

        let cells = downsample_frame_rgb(&frame, 2, 1);
        assert_eq!(cells, vec![(12, 34, 56), (65, 43, 21)]);
    }

    #[test]
    fn downsample_width_one_samples_horizontal_center_column() {
        let mut frame = vec![0_u8; FRAME_RGBA_BYTES];
        let center_x = FRAME_WIDTH / 2;
        write_px(&mut frame, center_x, 0, 10, 20, 30);
        write_px(&mut frame, center_x, FRAME_HEIGHT - 1, 210, 220, 230);

        let cells = downsample_frame_rgb(&frame, 1, 2);
        assert_eq!(cells, vec![(10, 20, 30), (210, 220, 230)]);
    }

    #[test]
    fn mini_palette_spans_samples_expected_pixels() {
        let mut frame = vec![0_u8; FRAME_RGBA_BYTES];
        let y = FRAME_HEIGHT / 2;
        write_px(&mut frame, 0, y, 10, 11, 12);
        write_px(&mut frame, 85, y, 20, 21, 22);
        write_px(&mut frame, 170, y, 30, 31, 32);
        write_px(&mut frame, FRAME_WIDTH - 1, y, 40, 41, 42);

        let spans = mini_palette_spans(&frame, 4);
        assert_eq!(spans.len(), 4);
        assert_eq!(spans[0].style.bg, Some(Color::Rgb(10, 11, 12)));
        assert_eq!(spans[1].style.bg, Some(Color::Rgb(20, 21, 22)));
        assert_eq!(spans[2].style.bg, Some(Color::Rgb(30, 31, 32)));
        assert_eq!(spans[3].style.bg, Some(Color::Rgb(40, 41, 42)));
    }

    #[test]
    fn mini_palette_spans_supports_single_swatch_without_panicking() {
        let mut frame = vec![0_u8; FRAME_RGBA_BYTES];
        let y = FRAME_HEIGHT / 2;
        write_px(&mut frame, 0, y, 77, 88, 99);

        let spans = mini_palette_spans(&frame, 1);
        assert_eq!(spans.len(), 1);
        assert_eq!(spans[0].style.bg, Some(Color::Rgb(77, 88, 99)));
    }

    #[test]
    fn mini_palette_spans_returns_empty_for_invalid_inputs() {
        assert!(mini_palette_spans(&vec![0_u8; FRAME_RGBA_BYTES - 1], 8).is_empty());
        assert!(mini_palette_spans(&vec![0_u8; FRAME_RGBA_BYTES], 0).is_empty());
    }

    #[test]
    fn map_index_returns_zero_for_degenerate_lengths() {
        assert_eq!(map_index(5, 1, FRAME_WIDTH), 0);
        assert_eq!(map_index(5, 10, 1), 0);
    }

    #[test]
    fn bucket_bounds_handles_zero_bucket_or_source_lengths() {
        assert_eq!(bucket_bounds(0, 0, FRAME_WIDTH), (0, 0));
        assert_eq!(bucket_bounds(0, 4, 0), (0, 0));
    }

    #[test]
    fn bucket_bounds_scales_evenly_for_regular_partitions() {
        assert_eq!(bucket_bounds(1, 4, 16), (4, 8));
        assert_eq!(bucket_bounds(3, 4, 16), (12, 16));
    }

    #[test]
    fn average_region_rgb_uses_independent_rgb_channels() {
        let mut frame = vec![0_u8; FRAME_RGBA_BYTES];
        write_px(&mut frame, 0, 0, 10, 200, 30);
        write_px(&mut frame, 1, 0, 40, 50, 60);
        assert_eq!(average_region_rgb(&frame, 0, 2, 0, 1), (25, 125, 45));
    }

    #[test]
    fn rgb_error_sq_matches_expected_distance() {
        assert_eq!(rgb_error_sq((10, 20, 30), (13, 16, 40)), 125);
        assert_eq!(rgb_error_sq((13, 16, 40), (10, 20, 30)), 125);
    }

    #[test]
    fn quarter_block_glyph_maps_all_masks_to_expected_symbols() {
        let expected = [
            " ", "\u{2598}", "\u{259D}", "\u{2580}", "\u{2596}", "\u{258C}", "\u{259E}",
            "\u{259B}", "\u{2597}", "\u{259A}", "\u{2590}", "\u{259C}", "\u{2584}", "\u{2599}",
            "\u{259F}", "\u{2588}",
        ];

        for (mask, glyph) in expected.iter().enumerate() {
            assert_eq!(quarter_block_glyph(mask as u8), *glyph);
        }
    }

    #[test]
    fn frame_lines_match_row_count() {
        let cells = vec![(0_u8, 0_u8, 0_u8); 32 * 16];
        let lines = frame_lines_from_rgb(&cells, 32);
        assert_eq!(lines.len(), 16);
    }

    #[test]
    fn half_block_lines_match_requested_height() {
        let frame = vec![0_u8; FRAME_RGBA_BYTES];
        let lines = frame_lines_half_blocks(&frame, 64, 24);
        assert_eq!(lines.len(), 24);
    }

    #[test]
    fn half_block_lines_return_empty_for_invalid_input_guards() {
        assert!(frame_lines_half_blocks(&vec![0_u8; FRAME_RGBA_BYTES - 1], 8, 8).is_empty());
        assert!(frame_lines_half_blocks(&vec![0_u8; FRAME_RGBA_BYTES], 0, 8).is_empty());
        assert!(frame_lines_half_blocks(&vec![0_u8; FRAME_RGBA_BYTES], 8, 0).is_empty());
    }

    #[test]
    fn half_block_renderer_uses_area_average_for_downsampling() {
        let mut frame = vec![0_u8; FRAME_RGBA_BYTES];
        for y in 0..FRAME_HEIGHT {
            for x in 0..FRAME_WIDTH {
                let (r, g, b) = match (x < FRAME_WIDTH / 2, y < FRAME_HEIGHT / 2) {
                    (true, true) => (255, 0, 0),     // top-left
                    (false, true) => (0, 255, 0),    // top-right
                    (true, false) => (0, 0, 255),    // bottom-left
                    (false, false) => (255, 255, 0), // bottom-right
                };
                write_px(&mut frame, x, y, r, g, b);
            }
        }

        let lines = frame_lines_half_blocks(&frame, 1, 1);
        assert_eq!(lines.len(), 1);
        assert_eq!(lines[0].spans.len(), 1);
        assert_eq!(lines[0].spans[0].content.as_ref(), "\u{2580}");
        assert_eq!(lines[0].spans[0].style.fg, Some(Color::Rgb(127, 127, 0)));
        assert_eq!(lines[0].spans[0].style.bg, Some(Color::Rgb(127, 127, 127)));
    }

    #[test]
    fn quarter_block_lines_match_requested_height() {
        let frame = vec![0_u8; FRAME_RGBA_BYTES];
        let lines = frame_lines_quarter_blocks(&frame, 64, 24);
        assert_eq!(lines.len(), 24);
    }

    #[test]
    fn quarter_block_lines_return_empty_for_invalid_input_guards() {
        assert!(frame_lines_quarter_blocks(&vec![0_u8; FRAME_RGBA_BYTES - 1], 8, 8).is_empty());
        assert!(frame_lines_quarter_blocks(&vec![0_u8; FRAME_RGBA_BYTES], 0, 8).is_empty());
        assert!(frame_lines_quarter_blocks(&vec![0_u8; FRAME_RGBA_BYTES], 8, 0).is_empty());
    }

    #[test]
    fn quarter_block_preserves_top_bottom_split() {
        let mut frame = vec![0_u8; FRAME_RGBA_BYTES];
        write_px(&mut frame, 0, 0, 255, 0, 0);
        write_px(&mut frame, FRAME_WIDTH - 1, 0, 255, 0, 0);
        write_px(&mut frame, 0, FRAME_HEIGHT - 1, 0, 0, 255);
        write_px(&mut frame, FRAME_WIDTH - 1, FRAME_HEIGHT - 1, 0, 0, 255);

        let lines = frame_lines_quarter_blocks(&frame, 1, 1);
        assert_eq!(lines.len(), 1);
        assert_eq!(lines[0].spans.len(), 1);
        assert_eq!(lines[0].spans[0].content.as_ref(), "\u{2580}");
        assert_eq!(lines[0].spans[0].style.fg, Some(Color::Rgb(255, 0, 0)));
        assert_eq!(lines[0].spans[0].style.bg, Some(Color::Rgb(0, 0, 255)));
    }

    fn write_px(frame: &mut [u8], x: usize, y: usize, r: u8, g: u8, b: u8) {
        let idx = (y * FRAME_WIDTH + x) * 4;
        frame[idx] = r;
        frame[idx + 1] = g;
        frame[idx + 2] = b;
        frame[idx + 3] = 0xFF;
    }
}

use nes_core::{Button, Command};

/// A command bridged between the DOM keyboard events and the NES emulator core.
///
/// This struct wraps a [`Command`] targeted for the core to standardize how inputs
/// are structured before being applied.
///
/// ## Examples
///
/// ```
/// use nes_core::{Button, Command};
/// use nes_web::bridge::BridgeCommand;
///
/// let cmd = BridgeCommand { core: Command::PressButton(Button::A) };
/// assert_eq!(cmd.tool_name(), "press_button");
/// ```
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BridgeCommand {
    /// The underlying emulator core command (e.g. `PressButton(`[`Button::A`]`)$).
    pub core: Command,
}

impl BridgeCommand {
    /// Returns the equivalent tool name string for this command.
    ///
    /// The tool name corresponds to the MCP tool identifiers such as `"press_button"`.
    /// Useful for logging or dispatching via standardized text interfaces.
    ///
    /// ## Examples
    ///
    /// ```
    /// use nes_core::{Button, Command};
    /// use nes_web::bridge::BridgeCommand;
    ///
    /// let cmd = BridgeCommand { core: Command::ReleaseButton(Button::Start) };
    /// assert_eq!(cmd.tool_name(), "release_button");
    /// ```
    #[must_use]
    pub fn tool_name(self) -> &'static str {
        match self.core {
            Command::PressButton(_) => "press_button",
            Command::ReleaseButton(_) => "release_button",
            _ => "unsupported",
        }
    }
}

/// Maps a standard DOM `KeyboardEvent.code` to the correct NES button natively.
///
/// Converts web frontend key codes into an actionable [`BridgeCommand`]. Returns
/// `None` if the key does not map to any NES input.
///
/// ## Examples
///
/// ```
/// use nes_core::{Button, Command};
/// use nes_web::bridge::{BridgeCommand, map_dom_key_to_command};
///
/// let cmd = map_dom_key_to_command("Enter", true).unwrap();
/// assert_eq!(cmd.core, Command::PressButton(Button::Start));
/// ```
#[must_use]
pub fn map_dom_key_to_command(key_code: &str, pressed: bool) -> Option<BridgeCommand> {
    let button = match key_code {
        "KeyZ" => Button::A,
        "KeyX" => Button::B,
        "Enter" => Button::Start,
        "ShiftRight" => Button::Select,
        "ArrowUp" => Button::Up,
        "ArrowDown" => Button::Down,
        "ArrowLeft" => Button::Left,
        "ArrowRight" => Button::Right,
        _ => return None,
    };

    let core = if pressed {
        Command::PressButton(button)
    } else {
        Command::ReleaseButton(button)
    };

    Some(BridgeCommand { core })
}

//! WebAssembly (Wasm) bindings for `nes-core`.
//!
//! This crate provides the [`NesWebEmulator`] struct, an interface tailored for JavaScript consumers.
//! It exposes the core NES emulation capabilities through the `wasm-bindgen` boundary, mapping simple
//! strings and arrays into complex emulator commands. This bridges the gap between the strict Rust
//! emulation layer and the flexible, event-driven world of the browser.
//!
//! ## Examples
//!
//! While [`NesWebEmulator`] requires a WebAssembly environment, the underlying [`WebRuntime`] can be used
//! natively for testing or alternative integrations:
//!
//! ```rust
//! use nes_web::WebRuntime;
//!
//! let mut runtime = WebRuntime::new();
//! // The runtime manages its own internal framebuffer allocation.
//! let frame_bytes = runtime.frame_rgba();
//! assert_eq!(frame_bytes.len(), 256 * 240 * 4);
//! ```

/// Web bridge layer translating JS events to core commands.
pub mod bridge;
/// Core WebAssembly runtime container for the emulator.
pub mod runtime;

pub use runtime::WebRuntime;

use wasm_bindgen::prelude::*;

/// The main WebAssembly interface for the NES emulator.
///
/// This struct holds the underlying emulation runtime and exposes methods that are
/// directly callable from JavaScript. It ensures memory safety and handles the conversion
/// of internal emulator errors into browser-friendly `JsValue` strings.
#[wasm_bindgen]
pub struct NesWebEmulator {
    runtime: WebRuntime,
}

#[wasm_bindgen]
impl NesWebEmulator {
    /// Creates a fresh instance of the web emulator.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// ```
    #[wasm_bindgen(constructor)]
    #[must_use]
    pub fn new() -> Self {
        Self {
            runtime: WebRuntime::new(),
        }
    }

    /// Loads an iNES format ROM from a byte array.
    ///
    /// This initializes the console and prepares it for execution.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// // In reality, these bytes would be parsed from an uploaded .nes file.
    /// let dummy_rom = [0; 16]; // A failing, invalid rom
    /// assert!(runtime.load_rom(&dummy_rom).is_err());
    /// ```
    pub fn load_rom(&mut self, rom_bytes: &[u8]) -> Result<(), JsValue> {
        self.runtime.load_rom(rom_bytes).map_err(to_js_error)
    }

    /// Advances the emulation by exactly one full NES frame.
    ///
    /// This is the primary workhorse method, designed to be called exactly once per
    /// `requestAnimationFrame` loop in the browser.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// // Step emulation. Without a ROM, this executes an infinite loop.
    /// runtime.step_frame().unwrap();
    /// ```
    pub fn step_frame(&mut self) -> Result<(), JsValue> {
        self.runtime.step_frame().map_err(to_js_error)
    }

    /// Advances the emulation by one PPU scanline.
    ///
    /// Useful for debugging tools that need to visualize the rendering process
    /// step-by-step rather than observing only fully composited frames.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.step_scanline().unwrap();
    /// ```
    pub fn step_scanline(&mut self) -> Result<(), JsValue> {
        self.runtime.step_scanline().map_err(to_js_error)
    }

    /// Advances the emulation by a single CPU instruction.
    ///
    /// Allows granular inspection of the console state for disassemblers and debuggers.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.step_cpu().unwrap();
    /// ```
    pub fn step_cpu(&mut self) -> Result<(), JsValue> {
        self.runtime.step_cpu().map_err(to_js_error)
    }

    /// Suspends active execution.
    ///
    /// Calling `step_frame` while paused will have no effect on the emulator's state.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.pause().unwrap();
    /// ```
    pub fn pause(&mut self) -> Result<(), JsValue> {
        self.runtime.pause().map_err(to_js_error)
    }

    /// Restores active execution after a suspension.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.resume().unwrap();
    /// ```
    pub fn resume(&mut self) -> Result<(), JsValue> {
        self.runtime.resume().map_err(to_js_error)
    }

    /// Triggers the physical NES Reset button.
    ///
    /// This jumps the CPU to the Reset Vector but preserves internal memory contents,
    /// similar to briefly pressing reset on the real hardware.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.reset().unwrap();
    /// ```
    pub fn reset(&mut self) -> Result<(), JsValue> {
        self.runtime.reset().map_err(to_js_error)
    }

    /// Simulates unplugging and reconnecting the NES power supply.
    ///
    /// This entirely clears internal RAM and re-initializes all hardware registers to zero.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.power_cycle().unwrap();
    /// ```
    pub fn power_cycle(&mut self) -> Result<(), JsValue> {
        self.runtime.power_cycle().map_err(to_js_error)
    }

    /// Adjusts the execution speed multiplier.
    ///
    /// The value is provided as a permille (1/1000) scale. Setting `1000` means normal 1.0x speed,
    /// while `2000` is double speed. This is crucial for implementing fast-forward functionality.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.set_speed(2000).unwrap(); // 2.0x speed
    /// ```
    pub fn set_speed(&mut self, speed_permille: u16) -> Result<(), JsValue> {
        self.runtime.set_speed(speed_permille).map_err(to_js_error)
    }

    /// Overwrites the exact binary bitfield for Player 1's controller.
    ///
    /// Allows the web frontend to supply pre-composed inputs rather than relying on
    /// individual button press events, which is preferred for netplay or TAS playback.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// // 0x80 usually maps to the 'A' button depending on polling implementation.
    /// runtime.set_controller_state(0x80).unwrap();
    /// ```
    pub fn set_controller_state(&mut self, bits: u8) -> Result<(), JsValue> {
        self.runtime.set_controller_state(bits).map_err(to_js_error)
    }

    /// Emulates pushing down on a specific gamepad button.
    ///
    /// Valid strings match the NES controller layout: `"A"`, `"B"`, `"Select"`, `"Start"`, `"Up"`, `"Down"`, `"Left"`, `"Right"`.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.press_button("Start").unwrap();
    /// ```
    pub fn press_button(&mut self, button: &str) -> Result<(), JsValue> {
        self.runtime.press_button(button).map_err(to_js_error)
    }

    /// Emulates letting go of a specific gamepad button.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.release_button("Start").unwrap();
    /// ```
    pub fn release_button(&mut self, button: &str) -> Result<(), JsValue> {
        self.runtime.release_button(button).map_err(to_js_error)
    }

    /// Maps a standard DOM `KeyboardEvent.code` to the correct NES button natively.
    ///
    /// This offloads key mapping logic to Rust, guaranteeing consistent controls regardless of
    /// frontend changes. It returns `true` if the key was recognized and mapped, `false` otherwise.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// let handled = runtime.dispatch_dom_key("ArrowUp", true).unwrap();
    /// assert!(handled);
    /// ```
    pub fn dispatch_dom_key(&mut self, key_code: &str, pressed: bool) -> Result<bool, JsValue> {
        self.runtime
            .dispatch_dom_key(key_code, pressed)
            .map_err(to_js_error)
    }

    /// Flushes the internal PPU rendering buffer into the RGBA memory segment.
    ///
    /// For zero-copy architectures, the frontend must manually call this before attempting
    /// to read from `frame_rgba_ptr`.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.refresh_frame_rgba();
    /// ```
    pub fn refresh_frame_rgba(&mut self) {
        let _ = self.runtime.refresh_frame_rgba();
    }

    /// Allocates and returns a distinct copy of the current video frame.
    ///
    /// Note: Creating a new vector per frame incurs overhead. For high-performance
    /// 60 FPS rendering, prefer zero-copy memory access via `frame_rgba_ptr`.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// let copy = runtime.frame_rgba();
    /// assert_eq!(copy.len(), 256 * 240 * 4);
    /// ```
    pub fn frame_rgba(&mut self) -> Vec<u8> {
        self.runtime.frame_rgba()
    }

    /// Exposes the starting memory address of the internal RGBA video buffer.
    ///
    /// The WebAssembly host can use this pointer to instantiate an `Uint8ClampedArray`
    /// directly over the shared memory region, bypassing expensive byte copies.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// let ptr = runtime.frame_rgba_ptr();
    /// assert!(!ptr.is_null());
    /// ```
    #[must_use]
    pub fn frame_rgba_ptr(&self) -> *const u8 {
        self.runtime.frame_rgba_ptr()
    }

    /// Exposes the expected byte length of the shared video buffer.
    ///
    /// Usually `256 * 240 * 4 = 245760`.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// assert_eq!(runtime.frame_rgba_len(), 245760);
    /// ```
    #[must_use]
    pub fn frame_rgba_len(&self) -> usize {
        self.runtime.frame_rgba_len()
    }

    /// Drains any synthesized audio samples into a vector.
    ///
    /// This consumes the internal audio buffer. If called sparsely, the emulator
    /// guarantees it will return all audio generated since the previous query.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.step_frame().unwrap();
    /// let chunk = runtime.audio_chunk_i16();
    /// assert!(!chunk.is_empty());
    /// ```
    pub fn audio_chunk_i16(&mut self) -> Vec<i16> {
        self.runtime.audio_chunk_i16()
    }

    /// Exposes the active instruction address of the CPU.
    ///
    /// This is an essential telemetry metric for debugging crashes or synchronization loss.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// // Without a ROM, the PC initializes to a default value like 0xC000.
    /// let pc = runtime.cpu_pc();
    /// ```
    #[must_use]
    pub fn cpu_pc(&self) -> u16 {
        self.runtime.cpu_pc()
    }

    /// Exposes the observed Frames Per Second.
    ///
    /// Represented as a permille. For instance, `60000` indicates exactly 60.000 FPS.
    /// Useful for telemetry and adjusting `requestAnimationFrame` budgets.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// let fps = runtime.fps_milli();
    /// ```
    #[must_use]
    pub fn fps_milli(&self) -> u32 {
        self.runtime.fps_milli()
    }

    /// Exposes the total number of frames rendered since initialization.
    ///
    /// This provides a stable timeline identifier for rollback states and recording.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.step_frame().unwrap();
    /// assert_eq!(runtime.ppu_frame_counter(), 1);
    /// ```
    #[must_use]
    pub fn ppu_frame_counter(&self) -> u64 {
        self.runtime.ppu_frame_counter()
    }

    /// Computes a lightweight structural hash of all internal state (RAM and Registers).
    ///
    /// This guarantees that two emulator instances with the exact same hash will simulate
    /// identical future states. Essential for verifying desyncs in peer-to-peer Netplay.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// let hash1 = runtime.state_hash();
    /// let hash2 = runtime.state_hash();
    /// assert_eq!(hash1, hash2);
    /// ```
    #[must_use]
    pub fn state_hash(&self) -> u64 {
        self.runtime.state_hash()
    }

    /// Exposes the active controller inputs as an 8-bit mask.
    ///
    /// Used by frontend UI overlays to visually demonstrate which buttons are currently
    /// held down.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.press_button("Start").unwrap();
    /// let bits = runtime.controller_bits();
    /// ```
    #[must_use]
    pub fn controller_bits(&self) -> u8 {
        self.runtime.controller_bits()
    }

    /// The exact horizontal dimension of an NES display output.
    ///
    /// Always returns `256`. Web frontends use this value to configure `<canvas>` element dimensions.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// assert_eq!(runtime.frame_width(), 256);
    /// ```
    #[must_use]
    pub fn frame_width(&self) -> u32 {
        self.runtime.frame_width()
    }

    /// The exact vertical dimension of an NES display output.
    ///
    /// Always returns `240`. Web frontends use this value to configure `<canvas>` element dimensions.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// assert_eq!(runtime.frame_height(), 240);
    /// ```
    #[must_use]
    pub fn frame_height(&self) -> u32 {
        self.runtime.frame_height()
    }

    /// The specific sample rate the audio generator expects to consume.
    ///
    /// Typically `44100`. The browser's Web Audio API context must be configured to this frequency.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// assert_eq!(runtime.audio_sample_rate(), 44100);
    /// ```
    #[must_use]
    pub fn audio_sample_rate(&self) -> u32 {
        self.runtime.audio_sample_rate()
    }

    /// The exact number of audio frames expected per execution chunk.
    ///
    /// Helps initialize `AudioBuffer` sizes in the frontend perfectly, preventing stuttering.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// let expected_samples = runtime.audio_chunk_samples();
    /// ```
    #[must_use]
    pub fn audio_chunk_samples(&self) -> u32 {
        self.runtime.audio_chunk_samples()
    }
}

impl Default for NesWebEmulator {
    fn default() -> Self {
        Self::new()
    }
}

fn to_js_error(err: String) -> JsValue {
    JsValue::from_str(&err)
}

//! The core web runtime for the NES emulator.
//!
//! This module provides [`WebRuntime`], an environment-agnostic wrapper over `NesCore`
//! tailored for web use cases (like `requestAnimationFrame` and JS event dispatching).
//!
//! It primarily handles translating string commands and allocating the proper
//! buffers for image rendering to avoid raw pointer unsafety across the JS boundary
//! when possible.
//!
//! ## Examples
//!
//! Using the runtime directly in Rust without the Wasm boundaries:
//!
//! ```rust
//! use nes_web::WebRuntime;
//!
//! let mut runtime = WebRuntime::new();
//! // runtime.load_rom(bytes).unwrap();
//! // let frame = runtime.frame_rgba(); // Vec<u8> containing RGBA
//! ```

use nes_core::{
    AUDIO_CHUNK_SAMPLES, AUDIO_SAMPLE_RATE, Button, Command, FRAME_HEIGHT, FRAME_RGBA_BYTES,
    FRAME_WIDTH, NesCore,
};

use crate::bridge::map_dom_key_to_command;

/// The environment-agnostic web execution manager.
///
/// This structure holds the underlying emulator and pre-allocates an internal framebuffer
/// (`frame_rgba`). By hiding the core behind this struct, frontend consumers do not have to
/// instantiate memory mapping objects directly in Wasm, dramatically simplifying API usability.
#[derive(Debug, Clone)]
pub struct WebRuntime {
    core: NesCore,
    frame_rgba: Vec<u8>,
}

impl WebRuntime {
    /// Bootstraps an empty, initialized NES core and allocates the shared framebuffer.
    ///
    /// The framebuffer requires exactly 245,760 bytes (256x240 pixels at 4 bytes per RGBA pixel).
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// assert_eq!(runtime.frame_rgba_len(), 256 * 240 * 4);
    /// ```
    #[must_use]
    pub fn new() -> Self {
        Self {
            core: NesCore::new(),
            frame_rgba: vec![0; FRAME_RGBA_BYTES],
        }
    }

    /// Mounts an `.nes` file binary payload directly to the core bus.
    ///
    /// Loading the ROM verifies the iNES header. It converts parsing failures directly into human-readable
    /// strings suitable for frontend toast notifications.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// let dummy_payload = vec![0x00, 0x01, 0x02];
    ///
    /// let result = runtime.load_rom(&dummy_payload);
    /// assert!(result.unwrap_err().contains("failed to load rom:"));
    /// ```
    pub fn load_rom(&mut self, rom_bytes: &[u8]) -> Result<(), String> {
        self.core
            .load_ines_rom(rom_bytes)
            .map(|_| ())
            .map_err(|err| format!("failed to load rom: {err}"))
    }

    /// Executes the console indefinitely until the PPU completes a single vertical blank.
    ///
    /// Web applications invoke this API inside of `requestAnimationFrame` loops to keep the
    /// visual framerate locked to the browser refresh rate.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.step_frame().unwrap();
    /// assert_eq!(runtime.ppu_frame_counter(), 1);
    /// ```
    pub fn step_frame(&mut self) -> Result<(), String> {
        self.execute(Command::StepFrame)
    }

    /// Executes the console until exactly one display scanline is produced.
    ///
    /// Ideal for cycle-accurate debugging tools where visualizing PPU timing behavior
    /// (such as mid-frame palette swaps) is required.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.step_scanline().unwrap();
    /// ```
    pub fn step_scanline(&mut self) -> Result<(), String> {
        self.execute(Command::StepScanline)
    }

    /// Steps the core forward by one internal 6502 processor instruction.
    ///
    /// Extremely fast micro-stepping for disassembly inspection.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.step_cpu().unwrap();
    /// ```
    pub fn step_cpu(&mut self) -> Result<(), String> {
        self.execute(Command::StepCpu)
    }

    /// Safely halts all running internal execution loops.
    ///
    /// Subsequent calls to `step_frame` become no-ops until `resume()` is triggered.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.pause().unwrap();
    /// ```
    pub fn pause(&mut self) -> Result<(), String> {
        self.execute(Command::Pause)
    }

    /// Resumes normal background execution.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.pause().unwrap();
    /// runtime.resume().unwrap();
    /// ```
    pub fn resume(&mut self) -> Result<(), String> {
        self.execute(Command::Resume)
    }

    /// Trips the physical Reset button on the emulator logic.
    ///
    /// The software vectors to the Reset address. Unlike a full reboot, RAM variables
    /// like high scores may survive if the specific game logic allows it.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.reset().unwrap();
    /// ```
    pub fn reset(&mut self) -> Result<(), String> {
        self.execute(Command::Reset)
    }

    /// Totally destroys current hardware state and boots from scratch.
    ///
    /// Equivalent to blowing on the cartridge and flipping the physical switch.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.power_cycle().unwrap();
    /// ```
    pub fn power_cycle(&mut self) -> Result<(), String> {
        self.execute(Command::PowerCycle)
    }

    /// Dynamically rescales emulator CPU cycles against the host system clock.
    ///
    /// Accepts a permille integer (e.g. `1000` = 1.0x). Passing `2000` tells the
    /// runtime to process twice as many NES cycles per tick, effectively yielding a 120Hz Fast Forward.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.set_speed(3000).unwrap(); // 3.0x speed
    /// ```
    pub fn set_speed(&mut self, speed_permille: u16) -> Result<(), String> {
        self.execute(Command::SetSpeed(speed_permille))
    }

    /// Overwrites the exact memory mask for gamepad one.
    ///
    /// Web platforms can pass an integer (`0x00`-`0xFF`) over the JS boundary far faster than
    /// parsing thousands of `"press_button"` string requests for TAS playbacks.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// // 0x80 typically triggers the A button in many mapping engines.
    /// runtime.set_controller_state(0x80).unwrap();
    /// ```
    pub fn set_controller_state(&mut self, bits: u8) -> Result<(), String> {
        self.execute(Command::SetControllerState(bits))
    }

    /// Generates a synthetic signal representing a physical gamepad push.
    ///
    /// Matches the explicit labels `"A"`, `"B"`, `"Select"`, `"Start"`, `"Up"`, `"Down"`, `"Left"`, or `"Right"`.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.press_button("Start").unwrap();
    /// assert!(runtime.press_button("JUMP").is_err());
    /// ```
    pub fn press_button(&mut self, button: &str) -> Result<(), String> {
        let parsed = parse_button(button)?;
        self.execute(Command::PressButton(parsed))
    }

    /// Generates a synthetic signal representing releasing a physical gamepad switch.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.release_button("Start").unwrap();
    /// ```
    pub fn release_button(&mut self, button: &str) -> Result<(), String> {
        let parsed = parse_button(button)?;
        self.execute(Command::ReleaseButton(parsed))
    }

    /// Intercepts native DOM `KeyboardEvent.code` values and maps them intelligently.
    ///
    /// Hardcoding mappings in Rust prevents frontend logic drift. Returns `true` if the event
    /// successfully mapped to a specific NES action, or `false` if it was ignored.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// let did_map = runtime.dispatch_dom_key("ArrowLeft", true).unwrap();
    /// assert!(did_map);
    ///
    /// let unknown = runtime.dispatch_dom_key("Escape", true).unwrap();
    /// assert!(!unknown);
    /// ```
    pub fn dispatch_dom_key(&mut self, key_code: &str, pressed: bool) -> Result<bool, String> {
        let Some(mapped) = map_dom_key_to_command(key_code, pressed) else {
            return Ok(false);
        };
        self.execute(mapped.core)?;
        Ok(true)
    }

    /// Forces a synchronization flush of the core's native PPU video buffer into the
    /// pre-allocated RGBA contiguous segment.
    ///
    /// In architectures where zero-copy memory access is used, this method *must* be invoked
    /// before reading from the internal data pointer.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.step_frame().unwrap();
    /// let frame = runtime.refresh_frame_rgba();
    /// assert_eq!(frame.len(), 256 * 240 * 4);
    /// ```
    #[must_use]
    pub fn refresh_frame_rgba(&mut self) -> &[u8] {
        self.core.fill_framebuffer_rgba(&mut self.frame_rgba);
        &self.frame_rgba
    }

    /// Clones the internal video buffer into a new `Vec<u8>`.
    ///
    /// This introduces a measurable heap allocation delay and memory copy for all 245,760 bytes.
    /// It should be avoided in 60 FPS critical paths if direct pointer mapping is available.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// let duplicate_frame = runtime.frame_rgba();
    /// assert_eq!(duplicate_frame.len(), 245760);
    /// ```
    #[must_use]
    pub fn frame_rgba(&mut self) -> Vec<u8> {
        self.refresh_frame_rgba().to_vec()
    }

    /// Generates a raw memory address spanning the composited video buffer.
    ///
    /// Exposing this address lets JavaScript utilize an `Uint8ClampedArray` to read pixels instantly
    /// from WebAssembly heap memory, unlocking 60FPS browser performance.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// let ptr = runtime.frame_rgba_ptr();
    /// assert!(!ptr.is_null());
    /// ```
    #[must_use]
    pub fn frame_rgba_ptr(&self) -> *const u8 {
        self.frame_rgba.as_ptr()
    }

    /// Verifies the absolute dimension in bytes of the exposed memory span.
    ///
    /// Guarantees that consumers understand the bounds of the returned pointer.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// assert_eq!(runtime.frame_rgba_len(), 256 * 240 * 4);
    /// ```
    #[must_use]
    pub fn frame_rgba_len(&self) -> usize {
        self.frame_rgba.len()
    }

    /// Siphons all queued audio sample fragments.
    ///
    /// Since the previous query, the internal APU queues 16-bit PCM waveform samples.
    /// These are popped off efficiently for continuous playback.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.step_frame().unwrap();
    /// let samples = runtime.audio_chunk_i16();
    /// assert!(!samples.is_empty());
    /// ```
    #[must_use]
    pub fn audio_chunk_i16(&mut self) -> Vec<i16> {
        self.core.audio_chunk_i16()
    }

    /// Retrieves the precise location the 6502 processor is evaluating within its execution.
    ///
    /// Tracking the Program Counter allows debugging crashes and finding synchronization
    /// deviation points in emulation testing.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// let pc = runtime.cpu_pc();
    /// ```
    #[must_use]
    pub fn cpu_pc(&self) -> u16 {
        self.core.cpu_pc()
    }

    /// Fetches the dynamically calculated Frames Per Second telemetry.
    ///
    /// Stored as a permille multiplier: e.g. `60000` equals 60.000 FPS. Frontends use this
    /// integer to decide if they need to increase `requestAnimationFrame` budgets or drop frames.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// let metrics = runtime.fps_milli();
    /// ```
    #[must_use]
    pub fn fps_milli(&self) -> u32 {
        self.core.fps_milli()
    }

    /// Verifies the deterministic index of the specific frame currently rendered.
    ///
    /// An invaluable metric for indexing states during peer-to-peer rollback simulation.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.step_frame().unwrap();
    /// assert_eq!(runtime.ppu_frame_counter(), 1);
    /// ```
    #[must_use]
    pub fn ppu_frame_counter(&self) -> u64 {
        self.core.ppu_frame_counter()
    }

    /// Computes a lightweight rolling hash mapping the precise internal RAM/Register state.
    ///
    /// Ensures that if an identical input trajectory was executed by two parallel clients,
    /// they remain perfectly synchronized in lockstep.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// let sync_token = runtime.state_hash();
    /// ```
    #[must_use]
    pub fn state_hash(&self) -> u64 {
        self.core.state_hash()
    }

    /// Reads the active gamepad inputs expressed as an 8-bit integer layout.
    ///
    /// Required when drawing UI elements that highlight physical button presses back to the user.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let mut runtime = WebRuntime::new();
    /// runtime.press_button("Start").unwrap();
    /// let state = runtime.controller_bits();
    /// ```
    #[must_use]
    pub fn controller_bits(&self) -> u8 {
        self.core.controller_bits()
    }

    /// Locks the output width to the standard NES spec.
    ///
    /// Exposing this guarantees the JS frontend always scales the canvas specifically to `256` pixels.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// assert_eq!(runtime.frame_width(), 256);
    /// ```
    #[must_use]
    pub fn frame_width(&self) -> u32 {
        FRAME_WIDTH as u32
    }

    /// Locks the output height to the standard NES spec.
    ///
    /// Exposing this guarantees the JS frontend always scales the canvas specifically to `240` pixels.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// assert_eq!(runtime.frame_height(), 240);
    /// ```
    #[must_use]
    pub fn frame_height(&self) -> u32 {
        FRAME_HEIGHT as u32
    }

    /// Indicates the target frequency required by the host's audio API layer.
    ///
    /// Commonly `44100` Hertz, defining how many individual samples constitute one second of audio.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// assert_eq!(runtime.audio_sample_rate(), 44100);
    /// ```
    #[must_use]
    pub fn audio_sample_rate(&self) -> u32 {
        AUDIO_SAMPLE_RATE
    }

    /// Indicates the maximum number of 16-bit PCM samples delivered per internal audio execution loop.
    ///
    /// Useful for determining accurate JS-side `AudioBuffer` allocations to eliminate clipping and drift.
    ///
    /// ## Examples
    ///
    /// ```rust
    /// use nes_web::WebRuntime;
    /// let runtime = WebRuntime::new();
    /// let len = runtime.audio_chunk_samples();
    /// ```
    #[must_use]
    pub fn audio_chunk_samples(&self) -> u32 {
        AUDIO_CHUNK_SAMPLES as u32
    }

    fn execute(&mut self, command: Command) -> Result<(), String> {
        self.core
            .execute(command)
            .map_err(|err| format!("core command failed: {err}"))
    }
}

impl Default for WebRuntime {
    fn default() -> Self {
        Self::new()
    }
}

fn parse_button(button: &str) -> Result<Button, String> {
    match button {
        "A" => Ok(Button::A),
        "B" => Ok(Button::B),
        "Select" => Ok(Button::Select),
        "Start" => Ok(Button::Start),
        "Up" => Ok(Button::Up),
        "Down" => Ok(Button::Down),
        "Left" => Ok(Button::Left),
        "Right" => Ok(Button::Right),
        _ => Err(format!(
            "unknown button '{button}'. expected one of: A, B, Select, Start, Up, Down, Left, Right"
        )),
    }
}

